void ff(int x, int y) {
	for (vector<int>::iterator i = A[x].begin(); i != A[x].end(); i ++)
		if (*i != y) ff(*i, x);
	int c = 0;
	ll S = 0;
	for (vector<int>::iterator i = A[x].begin(); i != A[x].end(); i ++)
		if (*i != y) {
			B[c++] = f[*i];
			S += f[*i];
		}
	if (c == 0) {
		f[x] = a[x];
		return;
	}
	if (S < a[x]) end();
	ll w = S-a[x];
	if (a[x] < w) end();
	sort(B, B+c);
	ll ma = S/2;
	ma = min(ma, S-B[c-1]);
	if (ma < w) end();
	f[x] = a[x]-w;
}

