bool solve() {
    ll n; cin >> n;
    vector<ll> A(n); cin >> A;
    vector<ll> cnt(n, 0);
    vector<vector<ll>> G(n);
    REP(i, n-1) {
        ll a, b; cin >> a >> b; --a, --b;
        G[a].pb(b);
        G[b].pb(a);
        cnt[a]++;
        cnt[b]++;
    }
    vector<ll> dp(n, -1);
    queue<ll> Q;
    REP(i, n) {
        if (cnt[i] <= 1) {
            Q.push(i);
        }
    }
    while ( !Q.empty() ) {
        ll v = Q.front(); Q.pop();
        ll s = 0;
        ll M = -1;
        EACH(to, G[v]) {
            if (dp[to] < 0) continue;
            s += dp[to];
            M = max(M, dp[to]);
        }
        if (G[v].size() == 1) {
            s += A[v];
            M = max(M, A[v]);
        }
        // debug(v);
        ll need = A[v]*2 - s;
        if (cnt[v] == 1) {
            if (need < 0) return false;
            dp[v] = need;
        }
        else {
            if (need != 0) return false;
        }
        M = max(M, need);
        s += need;
        if (s-M < M) return false;
        EACH(to, G[v]) {
            if (dp[to] < 0) {
                if (--cnt[to] == 1) {
                    Q.push(to);
                }
            }
        }
    }
    return true;
}
