    LL tot = 0, x1 = 0, x2 = 0, maxw = 0, sumw;
    for(int i = head[u]; ~i; i = E[i].nxt){
        int v = E[i].v;
        if(v == fa) continue;
        sumw = dfs(v, u);
        maxw = max(maxw, sumw);
        tot += sumw;
    }
    x2 = tot - A[u];
    x1 = A[u] - x2;
    if(x1 < 0 || x2 < 0 || A[u] < maxw || (x1 > 0 && fa == -1))
    {
        puts("NO");
        exit(0);
    }
    return x1;
}
