vi used;
vll A;

ll dfs(int v, bool root = true){
    used[v] = true;

    if(not root and (int)G[v].size() == 1){
        return A[v];
    }

    priority_queue<ll> q;
    ll sum = 0;
    for(auto& nv : G[v]){
        if(used[nv]) continue;
        ll cur = dfs(nv, false);
        if(cur == -1) return -1;
        sum += cur;
        q.push(cur);
    }
    if(sum < A[v]) return -1;

    ll ret = A[v];
    while(sum > ret and q.size() >= 2){
        ll a = q.top(); q.pop();
        ll b = q.top(); q.pop();

        ll diff = min(b, sum - ret);
        a -= diff;
        b -= diff;
        sum -= 2 * diff;
        ret -= diff;

        if(a > 0) q.push(a);
        if(b > 0) q.push(b);
    }
    if(ret != sum) return -1;

    return ret;
}

