int getMin(vi &data)
{
    if (data.size() == 0) return 0;
    vi s(data.size(), 0);
    s[0] = data[0];
    Rep(i, data.size()) {
        s[i] = s[i-1] + data[i];
    }
    int ret = INF;
    rep(i, s.size()) {
        ret = min(ret, abs(s.back() - s[i] * 2));
    }
    return ret;
}

int dfs(Graph &g, vi &data, int pos, int bef)
{
    if (g[pos].size() == 1) {
        return data[pos];
    }
    int yui = 0;
    vi cnt;
    for (auto i : g[pos]) {
        if (i.d != bef) {
            cnt.pb(dfs(g, data, i.d, pos));
            yui += cnt.back();
        }
    }
    sort(all(cnt));
    /*
    cout << pos << " : ";
    rep(i, cnt.size()) cout << cnt[i] << " "; cout << endl;
    */
    int kyoko = yui / 2 + yui % 2;
    if (kyoko <= data[pos] && data[pos] <= yui) {
        return data[pos] - (yui - data[pos]);
    } else {
        return INF;
    }
}

bool solve(Graph &g, vi &data, int pos)
{
    vi cnt;
    for (auto i : g[pos]) {
        cnt.pb(dfs(g, data, i.d, pos));
    }
    int yui = 0;
    rep(i, cnt.size()) yui += cnt[i];
    sort(all(cnt));
    //rep(i, cnt.size()) cout << cnt[i] << " "; cout << endl;
    return (data[pos] + data[pos] == yui && yui % 2 == 0);
}

