long long dfs(const vector<vector<int>> &G, const vector<long long> &A, int v, int prev){
  if(G[v].size() == 1 and G[v][0] == prev) return A[v];
  long long s = 0, m = -1;
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    long long t = dfs(G,A,v_,v);
    if(t < 0) return -1;
    m = max(m,t);
    s += t;
  }
  long long d = s - A[v];
  if(d >= 0 and s - 2*d >= 0 and s - m >= d) return s - 2*d;
  return -1;
}

