  }
  if(n == 2) {
    puts("YES");
    return 0;
  }
  int rt = 0;
  for(int i = 1;i <= n;++ i) {
    if(du[i] >= 2) {
      rt = i;
      break;
    }
  }
  dfs(rt , 0);
  calc(rt , 0);
  if(dp[rt]) Cannot;
  puts("YES");
}

