long long dif[N];
int a , b;
vector < int > v[N];
long long dfs(int node , int parent){
    dif[node] = arr[node];
    vector < long long > s;
    s.clear();
    long long sum = 0;
    for(int next : v[node]){
        if(next != parent){
            s.push_back(dfs(next , node));
            sum += s.back();
            dif[node] -= arr[next];
        }
    }
    if(v[node].size() == 1){
        return dif[node];
    }
    if(dif[node] > 0){
        printf("NO\n");
        exit(0);
    }
    long long val = dif[node];
    long long cur = 0;
    long long tot = 0;
    for(auto &it : s){
        long long x = min(it , cur);
        if(val < x){
            val = 0;
            sum -= val * 2;
            tot += val;
            break;
        }
        else{
            val -= x;
            sum -= 2 * x;
            cur -= x;
            it -= x;
            tot += x;
        }
        cur += it;
    }
    if(val > 0){
        printf("NO\n");
        exit(0);
    }
    dif[parent] += tot;
    return cur;
}
