bool dfs(int cur, int parent)
{
  node n = nodes[cur];
  int sum = 0;
  rep(i, n.ns.size()) {
    int next = n.ns[i];
    if(next != parent) {
      if(dfs(next, cur))
	sum += nodes[next].a;
      else
	return false;
    }
  }
  if(parent == -1) {
    node t = nodes[n.ns[0]];
    if(n.ns.size() == 1) {
      return n.a == t.a;
    } else {
      return (2 * n.a - sum == 0);
    }
  } else {
    if(sum == 0) return true;
    if(2 * n.a < sum || n.a > sum)
      return false;
    else {
      nodes[cur].a = 2 * n.a - sum;
      return true;
    }
  }
}

