using namespace std;
std::vector<int64_t> numbers;
vector<vector<int>> graph;
std::vector<bool> used;

std::pair<bool, int64_t> Dfs(int v) {
    used[v] = true;

    std::vector<int64_t> elements;
    int64_t mx = 0;
    int64_t sum = 0;
    for (const auto& el : graph[v]) {
        if (used[el]) continue;
        auto pr = Dfs(el);
        if (!pr.first) {
            return {false, 0};
        }
        elements.push_back(pr.second);
        mx = max(mx, pr.second);
        sum += pr.second;
        assert(pr.second >= 0);
    }
    if (elements.empty()) {
        return {true, numbers[v]};
    }
    int64_t mn_can = min(mx, sum / 2);
    if (mn_can + (sum - mn_can * 2) > numbers[v]) {
        return {false, 0};
    }
    if (sum < numbers[v]) {
        return {false, 0};
    }
    auto sm = sum - numbers[v];
    if (sm > mn_can) {
        return {false, 0};
    }
    sum -= 2 * sm;
    return {true, sum};
}

int main() {
    std::ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    graph.resize(n);
    used.resize(n);
    used.assign(n, 0);
