    for (int i = 0; i < n; i++) {
        if (graph[i].size() > 1) {
            v = i;
        }
    }
    auto ans = Dfs(v);
    if (ans.first == true && ans.second == 0) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

