bool solve(int N, vi& A, vi& _a, vi& _b) {
    vvi ne(N);
    rep(i,N-1) {
        int ai = _a[i]-1, bi = _b[i]-1;
        assert(IN(ai, 0, N-1));
        assert(IN(bi, 0, N-1));
        assert(ai != bi);
        ne[ai].pb(bi);
        ne[bi].pb(ai);
    }
    vi ne_c(N);
    rep(i,N) ne_c[i] = ne[i].size();

    int max_at = (int)(max_element(ALL(ne_c)) - ne_c.begin());
    int root = max_at;

    queue<int> q;
    vi visited(N, false);
    vi order; order.reserve(N);
    vi parent(N, -1);
    q.push(root);
    while (!q.empty()){
        int u = q.front(); q.pop();
        visited[u] = true;
        order.pb(u);
        for (int v: ne[u]){
            if(visited[v]) continue;
            q.push(v);
            parent[v] = u;
        }
    }
    reverse(ALL(order));
    vvi gathered(N, vi());
    for (int u: order) {
        ll upwards = 0;
        if (gathered[u].empty()) {
            upwards = A[u];
        } else {
            sort(ALL(gathered[u]));
            ll a_b = A[u];
            ll a_2b = accumulate(ALL(gathered[u]), 0LL);
            ll b = a_2b - a_b, a = a_b - b;
            if (a < 0 || b < 0) return false;
            ll largest = gathered[u].back();
            if (a_2b - largest + a < largest) return false;
            upwards = a;
        }
        int p = parent[u];
        if (p == -1) {
            return (upwards == 0);
        }
        gathered[p].pb(upwards);
    }

    return false;
}

