long long dfs ( int v,int p ) {
  long long down = 0;
  if ( tree[v] . size ( ) == 1 ) return arr[v];
  if ( p!= -1 && tree[v] . size ( ) == 2 ) {
    int u = tree[v][0] ;
    if ( u == p ) u = tree[v][1] ;
    if ( arr[v] != arr[u] ) { cout << "NO" << endl; exit ( 0 ) ; } ;
