void makeTree(int n, int p) {
    parent[n] = p;
    FORE (v, edge[n]) {
        if (v == p) continue;
        makeTree(v, n);
    }
}

ll dfs(int n) {
    ll s = 0, mx = 0;
    if (edge[n].size() == 1) return A[n];
    FORE (e, edge[n]) {
        if (parent[e] != n) continue;
        ll m = dfs(e);
        mx = max(mx, m);
        if (m == -1) return -1;
        s += m;
    }
    ll r = 2 * A[n] - s;
    if (r < 0 || r > A[n] || s - mx < (s-r)/2) r = -1;
    return r;
}

