	ll sum = 0;
	int count = 0;
	priority_queue<ll> pq;
	for (int j : g[i]) {
		if (j == p) continue;
		ll now = dfs(j, i);
		if (now == -1) return -1;
		sum += now;
		++count;
		pq.push(now);
