int rec(int idx, int par = -1)
{
  if(g[idx].size() == 1) return (A[idx]);
  priority_queue< int > que;
  que.push(0);
  int sum = 0;
  for(auto &to : g[idx]) {
    if(to == par) continue;
    auto get = rec(to, idx);
    sum += get;
    que.emplace(get);
  }
  while(que.size() > 1) {
    int p = que.top();
    que.pop();
    int q = que.top();
    que.pop();
    que.push(p - q);
  }
  int zan = (sum - que.top()) / 2;
  if(zan < A[idx] || sum - zan > A[idx]) throw 1LL;
  return (sum - (sum - A[idx]) * 2);
}

