ll dfs3(int u,int par=-1){
    if(sz(v[u])==1) return W[u];
    ll check=cnt[u]*2,sum=0;
    for(int y:v[u]){
	if(y!=par){
	    ll num=dfs3(y,u);
	    sum+=num;
	    check-=min(num,cnt[u]);
	}
    }
    if(check>0) cout<<"NO"<<endl,exit(0);
    return sum-cnt[u]*2;
}

