    long long n = scan<long long>(), root = -1;
    auto A = scan<long long>(n, 1);
    vector<vector<long long>> g(n + 1);
    vector<long long> deg(n + 1, 0), vis(n + 1, false), X(n + 1, 0);
    for (long long i = 0; i < n - 1; ++i) {
        auto [u, v] = scan<long long, 2>();
        g[u].push_back(v), g[v].push_back(u);
        deg[u] += 1, deg[v] += 1;
    }
    if(n == 2) return cout << (A[1] == A[2] ? "YES" : "NO") << "\n", 0;
    bool ok = true;
    function<long long(long long u)> dfs = [&](long long u) -> long long{
        vis[u] = true;
        long long mxchild = 0;
        if (deg[u] == 1)
            return A[u];
        for (auto v : g[u]) {
            if (!vis[v]) {
                long long t = dfs(v);
                X[u] += t; ckmax(mxchild, t);
            }
        }
        ok = ok and (A[u] <= X[u]) and (mxchild <= A[u]) and (2 * A[u] - X[u] >= 0);
        return 2 * A[u] - X[u];
    };
    for(long long i = 1; i <= n; ++i) if (deg[i] != 1) { root = i; break; }
    bool ans = (dfs(root) == 0) and (ok);
    return cout << (ans ? "YES" : "NO") << "\n", 0;
}
