    addArc(g, a, b, w);
    addArc(g, b, a, w);
}

int dfs(Graph &g, vi &data, int pos, int bef)
{
    if (g[pos].size() == 1) {
        return data[pos];
    }
    int yui = 0;
    vi cnt;
    for (auto i : g[pos]) {
        if (i.d != bef) {
            cnt.pb(dfs(g, data, i.d, pos));
            yui += cnt.back();
        }
    }
    sort(all(cnt));
    if (cnt[0] < 0) return -1;
    int kyoko = data[pos] * 2 - yui;
    if (max(cnt.back(), yui/2) >= data[pos]) {
        return -kyoko;
    } else {
        return -1;
    }
}

