inline void dfs(int node){
    if(grad[node] == 1){
        max_elem[node] = v[node];
        return ;
    }
    long long sum = 0;
    int vec, lim = graph[node].size();
    for(int i = 0; i < lim; i++){
        vec = graph[node][i];
        if(!viz[vec]){
            viz[vec] = viz[node] + 1;
            dfs(vec);
            sum += max_elem[vec];
        }
    }
    long long sure = (sum&1);
    sum -= sure; v[node] -= sure;
    long long pass = 2 * v[node] - sum;
    max_elem[node] = pass + sure;

    if(pass > sum || pass > v[node]){
        printf("NO\n");
        exit(0);
    }

    if(grad[node] == 2 && node != root && pass != v[node]){
        printf("NO\n");
        exit(0);
    }

    for(int i = 0; i < lim; i++){
        vec = graph[node][i];
        if(viz[vec] < viz[node])
            continue;
        if(max_elem[vec] - pass - sure > sum + sure - max_elem[vec]){
            printf("NO\n");
            exit(0);
        }
    }
}

