ll dfs(int v, int par){
    ll sum = (g[v].size() <= 1) ? a[v] : 0;
    ll ma = sum;
    each(u, g[v]){
        if(*u != par){
            ll cur = dfs(*u, v);
            if(cur < 0)
                return -1;
            if(ma < cur)
                ma = cur;
            sum += cur;
        }
    }
    ll lim = 2ll * a[v] - sum;
    if(lim < (ma - (sum - ma)) || lim > sum)
        return -1;
    return lim;
}

