int stone[100010];

vector<int> ed[100010];

int par[100010];

void NO(){ puts("NO"); exit(0); }

void dfs(int x){
	if(ed[x].size() == 1u) return;
	multiset<int> ss;
	ll S=0;
	for(int y:ed[x]) if(par[x]!=y){
		par[y]=x;
		dfs(y);
		ss.insert(stone[y]);
		S += stone[y];
	}
	ll a = S-stone[x];
	if(a < 0) NO();
	ll mm=0;
	if(ss.size()){
		int mv = *ss.begin();
		if(mv > 0) mv=(mv-1)/2*2;
		multiset<int> tmp;
		for(int x:ss) tmp.insert(x-mv);
		swap(tmp, ss);
	}
	while(ss.size() >= 2u){
		ll a=*--ss.end();
		ll b=*--(--ss.end());
		if(b == 0) break;
		++mm;
		ss.erase(--ss.end());
		ss.erase(--ss.end());
		ss.insert(a-1);
		ss.insert(b-1);
	}
	if(mm < a) NO();
	stone[x] = S-2*a;
}

