      if (cnt > 20) {
        puts("YES");
        exit(0);
      }
    }
  }

  if (N > 2) {
    puts("YES");
    exit(0);
  }

  assert(N == 2);
  if (A[0] == A[1]) puts("YES");
  else puts("NO");
}

