const double EPS = 1e-10;
const int MOD = 1000000007;


const int MAX_N = 100000;
int N;
int a[MAX_N], b[MAX_N];
ll A[MAX_N];

struct edge { int to, cost; };
const int MAX_V = MAX_N, INF = 10000000;

// Vの初期化を忘れない。
int V;
vector<edge> G[MAX_V];
int d[MAX_V];

void dijkstra(int s) {
  fill(d, d+V, INF);
  priority_queue<Pii, vector<Pii>, greater<Pii> > pque;
  d[s] = 0;
  pque.push(Pii(0, s));


  while (!pque.empty()) {
    Pii p = pque.top(); pque.pop();
    int v = p.second;
    if (d[v] < p.first) continue;
    for (int i = 0; i < (int)G[v].size(); ++i) {
      edge e = G[v][i];
      if (d[e.to] > d[v] + e.cost) {
        d[e.to] = d[v] + e.cost; 
        pque.push(Pii(d[v]+ e.cost, e.to));
      }
    }
  }
}

ll rec(int v) {
  if (G[v].size() == 1) return A[v];

  vector<ll> vec;
  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i].to;
    if (d[v] > d[u]) continue;
    vec.push_back(rec(u));
  }

  ll sum = 0;
  for (int i = 0; i < vec.size(); ++i) {
    if (vec[i] < 0) return -1;
    sum += vec[i];
  }

  ll res = 2*A[v] - sum;
  if (res < 0) return -1;
  vec.push_back(res);

  for (int i = 0; i < vec.size(); ++i) {
    if (vec[i] > A[v]) return -1;
  }

  return res;
}

int main() {
  cin >> N;
  rep(i, N) cin >> A[i];
  rep(i, N-1) {
    cin >> a[i] >> b[i]; a[i]--; b[i]--;
  }


  V = N;
  for (int i = 0; i < N-1; ++i) {
    G[a[i]].push_back((edge){b[i], 1});
    G[b[i]].push_back((edge){a[i], 1});
  }

  if (N == 2) {
    if (A[0] == A[1]) cout << "YES" << endl;
    else cout << "NO" << endl;
    return 0;
  }

  int root = 0;
  for (int i = 0; i < N; ++i) {
    if (G[i].size() != 1) {
      root = i; break;
    }
  }

  dijkstra(root);

  if (rec(root) != 0) {
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
  }

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
LL read(){
	LL x=0,f=1;
	char ch=getchar();
	while (!isdigit(ch)&&ch!='-')
		ch=getchar();
	if (ch=='-')
		f=-1,ch=getchar();
	while (isdigit(ch))
		x=(x<<1)+(x<<3)+(ch^48),ch=getchar();
	return x*f;
}
const int N=100005;
int n,A[N],in[N];
vector <int> e[N];
vector <LL> v[N];
LL solve(int x,int pre){
	vector <LL> &a=v[x];
	for (auto y : e[x])
		if (y!=pre)
			a.push_back(solve(y,x));
	if (a.empty())
		return A[x];
	sort(a.begin(),a.end());
	if (!~*a.begin())
		return -1;
	reverse(a.begin(),a.end());
	LL tot=0;
	for (auto y : a)
		tot+=y;
	LL mx=min((LL)A[x],min(*a.begin(),tot-*a.begin()));
	LL Need=tot-A[x];
	return Need>mx?-1:(A[x]-Need);
}
int main(){
	srand('C'+'L'+'Y'+'A'+'K');
	n=read();
	for (int i=1;i<=n;i++)
		A[i]=read();
	for (int i=1;i<=n;i++)
		e[i].clear();
	for (int i=1;i<n;i++){
		int a=read(),b=read();
		e[a].push_back(b);
		e[b].push_back(a);
		in[a]++,in[b]++;
	}
	if (n==2)
		return puts(A[1]==A[2]?"YES":"NO"),0;
	int rt=0;
	for (int i=1;(!rt||rand()%100)&&i<=n;i++)
		if (in[i]>1)
			rt=i;
	puts(solve(rt,0)==0?"YES":"NO");
	return 0;
}

