int n, a[maxn], deg[maxn];
vi gr[maxn];

int dfs(int u, int par){
	int res = 0;	
	if(gr[u].size() == 1 || gr[u][0] == par){
		return a[u];
	}
	int mx = 0;
	fora(v, gr[u]){
		if(v == par){
			continue;
		}
		int tmp = dfs(v, u);
		res += tmp;
		mx = max(mx, tmp);
	}
	if(gr[u].size() == 2 && par != -1){
		if(res != a[u]){
			cout << "NO\n"; exit(0);
		}
		return a[u];
	}
	if(mx * 2 > res && par == -1){
		cout << "NO\n"; exit(0);
	}
	if(2 * a[u] - res < 0){
		cout << "NO\n"; exit(0);
	}
	if(2 * a[u] - res > res){
		cout << "NO\n"; exit(0);
	}
	if(a[u] < mx){
		cout << "NO\n"; exit(0);
	}
	return 2 * a[u] - res;
}

void solve(){
	int i, j, k, l, r; cin >> n;
	for1(i, 1, n){
		cin >> a[i];
	}
	for0(i, 1, n){
		int u, v; cin >> u >> v;
		gr[u].pb(v); gr[v].pb(u);
		deg[u]++; deg[v]++;
	}
	if(n == 2){
		if(a[1] == a[2]){
			cout << "YES\n"; return;
		}
		else cout << "NO\n"; return;
	}
	int root = -1;
	for1(i, 1, n){
		if(deg[i] > 1){
			root = i;
		}
	}
	//cout << root << '\n';
	int now = dfs(root, -1);
	if(now == 0) cout << "YES\n";
	else cout << "NO\n";
}

