void dfs(int v,int p)
{
  int s=0,nv=0,match=0;
  for(int i=0;i<g[v].size();i++)
    if(g[v][i]!=p)
      {
	dfs(g[v][i],v);
	s+=dp[g[v][i]];
	if(2*match>=dp[g[v][i]])
	  {
	    match=(2*match+dp[g[v][i]])/2;
	    if((2*match+dp[g[v][i]])%2)
	      if(nv>0)
		{
		  match++;
		  nv=-1;
		}
	      else
		nv+=1;
	  }
	else
	  {
	    int mod=dp[g[v][i]]-2*match;
	    match*=2;
	    if(mod<=nv)
	      {
		nv-=mod;
		match+=mod;
	      }
	    else
	      {
		match+=nv;
		nv=mod-nv;
	      }
	  }
      }
  if(g[v].size()==1)
    dp[v]=A[v];
  else
    {
      //cout<<"             "<<v<<" "<<match<<endl;
      int k2=s-A[v];
      int k1=2*A[v]-s;
      if(k1<0 || k2<0 || match<k2)
	flag=true;
      dp[v]=k1;
    }
}

