ll dfs(int v, int p = -1) {
	if (g[v].size() == 1) {
		return a[v];
	}


	vector<ll> ch;
	ll r = 0;
	for (int to : g[v]) {
		if (to == p) {
			continue;
		}
		ch.pb(dfs(to, v));
		r += ch.back();
	}
	sort(ch.begin(), ch.end());

	ll already = r & 1;
	ch.back() -= r & 1;
	r -= r & 1;

	sort(ch.begin(), ch.end());


	ll bad = max(0LL, ch.back() - (r - ch.back()));
	ll diff = (r - bad) / 2;

	if (p == -1) {
		if (already || r / 2 != a[v] || ch.back() > r - ch.back()) {
			//cout << v << endl;
			//cout << ch << endl;
			cout << "NO" << endl;
			exit(0);
		}
	}


	if (!(r + already - diff <= a[v] && a[v] <= r + already)) {
		//cout << ch << endl;
		//cout << r << " " << already << " " << diff << endl;
		cout << "NO" << endl;
		exit(0);
	}

	ll need = r + already - a[v];



	return r + already - need * 2;
}

