/* ------------- Functions -------------- */

ll dfs(ll v) {
    visited[v] = true;
    ll sum = 0;
    V<ll> stone;
    for (ll sv : path[v]) {
        if (!visited[sv]) {
            ll s = dfs(sv);
            if (s < 0) {
                return -1;
            } else {
                sum += s;
                stone.pb(s);
            }
        }
    }

    if (stone.empty()) {
        return A[v];
    } else {
        GSORT(stone);
        ll mi = min(sum / 2 + sum % 2, stone[0]);
        if (A[v] < mi || A[v] > sum) {
            return -1;
        } else {
            return A[v] * 2 - sum;
        }
    }
}

