int n;
ll a[500000];
vector<int> graph[500000];
ll mark[500000];

ll dfs(int v)
{
    mark[v] = 1;
    ll leaf = 0;
    int t = 0;
    ll max_leaf = 0;
    for (auto u : graph[v])
    {
        if (mark[u] == 0)
        {
            ll x = dfs(u);
            max_leaf = max(max_leaf, x);
            leaf += x;
            t = 1;
        }
    }
    if (max_leaf * 2 > leaf)
    {
        cout << "NO";
        exit(0);
    }
    if (t == 0)
    {
        return a[v];
    }
    if (leaf < a[v])
    {
        cout << "NO";
        exit(0);
    }
    long long r = leaf - a[v];
    leaf -= 2 * r, a[v] -= r;
    if (leaf < 0)
    {
        cout << "NO";
        exit(0);
    }
    return leaf;
}

