void dp(int v, int _p) {
	if (len(g[v]) == 1) {
		return;
	}
	int before = up[v];
	up[v] *= 2;
	for (int sub : g[v]) {
		if (sub == _p) continue;
		dp(sub, v);
		up[v] -= up[sub];
	}
	int pairs = before - up[v];
	int S = 0;
	int _max = 0;
	for (int sub : g[v]) {
		if (sub == _p) continue;
		S += up[sub];
		_max = max(_max, up[sub]);
	}
	if (S - _max <= _max) {
		pairs -= S - _max;
	} else {
		pairs -= S / 2;
	}
	if (pairs > 0 || ((S - up[v]) & 1)) {
		print "NO";
		exit(0);
	}
}

