const int MAXN = 100005;
typedef long long ll;

vector <int> g[MAXN];
bool visited[MAXN];
ll f[MAXN];
ll a[MAXN];

bool dfs(int v)
{
	visited[v] = true;
	if (g[v].size() == 1)
	{
		f[v] = a[v];
		return true;
	}

	ll cnt = 0;
	for (int i = 0; i < g[v].size(); i++)
	{
		if (!visited[g[v][i]])
		{
			if (!dfs(g[v][i]))
			{
				return false;
			}
            cnt += f[g[v][i]];
		}
	}

	if (a[v] > cnt) return false;

	if (a[v] < cnt && g[v].size() == 2) return false;

	if (2*a[v] < cnt) return false;

	f[v] = a[v] - (cnt - a[v]);
	return true;
}

