ll dfs(int v, int p = -1) {
  vector < ll > now;
  ll x = a[v];
  ll y = 0;
  for (auto to : g[v]) {
    if (to != p) {
      ll tmp = dfs(to, v);
      y += tmp;
      now.pb(tmp);
    }
  }
  if (now.size() == 0) return x;
  if (x > y) {
    cout << "NO\n";
    exit(0);
  }
  ll z = y - x;
  multiset < int > st;
  for (auto i : now) st.insert(i);
  while(z > 0) {
    if (now.size() < 2) break;
    ll mn = *st.begin();
    st.erase(st.find(mn));
    ll mx = *st.rbegin();
    st.erase(st.find(mx));
    ll cur = min(z, mn);
    mn -= cur;
    mx -= cur;
    x -= cur;
    y -= cur;
    z -= cur;
    if (mn > 0) st.insert(mn);
    if (mx > 0) st.insert(mx); 
  }
  if (z > 0) {
