typedef long long ll;

const int MAXN = (int)1e5 + 5;

vector<int> adj[MAXN];

int arr[MAXN];

int n;

bool check(ll sum, int mx, int st, int p) {
	ll t = 0;     

	if (mx < p) {
		return 0;
	}

    if (mx - p > sum) {
    	return 0;
    }

    t += (mx - p);
	sum -= (mx - p);

	if (sum & 1) {
		return 0;
	}

	t += (sum >> 1);
	return st - p == t;
}

bool dfs(int v, int pr) {
	if (adj[v].size() == 1) {
		return 1;
	}

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		if (!dfs(to, v)) {
			return 0;
		}
	}

	int mx = 0;
	ll sum = 0;

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}		

		sum += arr[to];
		mx = max(mx, arr[to]);
	}    

	sum -= mx;

	for (int x = max(0ll, mx - sum); x <= (pr == -1 ? 0 : mx); ++x) {
		if (check(sum, mx, arr[v], x)) {
			arr[v] = x;
			return 1;
		}
	}

	return 0;
}

