LL xs[100010];
LL dfs(VVI& G, int u, int p){
  if(SZ(G[u]) == 1){
	return xs[u];
  }

  LL as = 0;
  vector<LL> ch;
  for(int to: G[u]){
	if(to == p) continue;
	LL tmp = dfs(G, to, u);
	if(tmp < 0) return -1;
	as += tmp;
	ch.PB(tmp);
  }
  LL res = 2*xs[u] - as;
  if(!(0 <= res && res <= xs[u])) return -1;

  SORT(ch);
  if(SZ(ch) == 1){
	return res == as? res: -1;
  }

  ch.back() -= res;
  return (xs[u]-res >= ch.back()? res: -1);
}

