const int N=1e5+10;
int n,p;
int head[N],In[N];
LL F[N],G[N],sum[N],A[N];
bool YES[N];
struct Edge {
  int to,last;
  Edge () {}
  Edge (int a,int b) :to(a),last(b) {}
}edge[N<<1];
void ADD(int a,int b) {
  edge[++p]=Edge(b,head[a]); head[a]=p;
  edge[++p]=Edge(a,head[b]); head[b]=p;
}
void DFS(int u,int f) {
  if(In[u]==1) {
    F[u]=A[u];
    return;
  }
  int g=0;
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(v!=f) {
      ++g;
      DFS(v,u);
      sum[u]+=F[v];
    }
  }
  if(g==1) {
    YES[u]=true;
    if(sum[u]!=A[u]) puts("NO"),exit(0);
  }
  if(sum[u]>=A[u]&&sum[u]<=A[u]*2) F[u]=A[u]*2-sum[u];
  else puts("NO"),exit(0);
}
void SFD(int u,int f) {
  if(In[u]==1) return;
  if((sum[u]+G[f])==A[u]*2ll) puts("YES"),exit(0);
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(v!=f) {
      if(YES[u]) {
        if(G[f]==A[u]) G[u]=G[f],SFD(v,u);
      }
      else {
        LL t=G[f]+sum[u]-F[v];
        if(t>=A[u]&&t<=A[u]*2) G[u]=A[u]*2-t,SFD(v,u);
      }
    }
  }
}
