const int N = 1e5 + 7;
const int INF = 1e18 + 239;

int smul(int a, int b) {
	if (a == 0 || b == 0) return 0;
	if (a > INF / b) return INF;
	else return min(INF, a * b);
}

int sadd(int a, int b) {
	return min(a + b, INF);
}

int a[N];
vector<int> g[N];

int dfs(int cur, int p, int pv) {
	int sm = 0;
	vector<int> sn;
	for (auto t : g[cur]) {
		if (t != p) {
			int v = dfs(t, cur, a[cur]);
			sm += v;
			sn.push_back(v);
		}
	}
	if (sn.empty()) {
		return a[cur];
	}
	int tot = 0;
	for (auto t : sn) {
		tot = sadd(tot, smul(t, sm - t));
	}
	int dl = a[cur] - pv;
	if (tot < dl || sm < 2 * dl) {
		cout << "NO\n";
		exit(0);
	} else {
		if (cur == 1) {
			// cerr << "rt " << cur << ' ' << sm - 2 * dl << endl;
			// cerr << sm << endl;
			// cerr << dl << endl;
		}
		return sm - 2 * max((int)0, dl);
	}
}

