vector<int> a;

vector<vector<int>> graph;

ll dfs(int v, int pre = -1) {
    ll sum = 0;
    vector<ll> cnts;
    for (int to: graph[v]) if (to != pre) {
        ll c = dfs(to, v);
        if (c == -1) return -1;
        sum += c;
        cnts.push_back(c);
    }

    if (cnts.size() == 0) return a[v];
    if (pre == -1) {
        if (cnts.size() == 1) return sum == a[v] ? 1 : 0;
        return sum == a[v] * 2 ? 1 : 0;
    }

    cnts.push_back(a[v] * 2 - sum);
    for (ll c: cnts) if (a[v] < c || c < 0) return -1;
    return cnts.back();
}

