#define REP(i,n) for (int i=0,_n=(int)(n); i < _n; i++)
template<class T> bool chmax(T &a, T b) { return a < b ? (a = b, true) : false; }
template<class T> bool chmin(T &a, T b) { return a > b ? (a = b, true) : false; }

typedef long long ll;

const int MAX_N = 100000 + 10;
int A[MAX_N];
vector<int> g[MAX_N];
bool ans;

ll f(int v, int p) {
  if (!ans) return 0;
  ll T = 0;
  if (p != -1 && g[v].size() == 1) {
    T = A[v];
  } else {
    ll L = 0;
    vector<ll> c;
    for (int u : g[v]) if (u != p) {
      ll ci = f(u, v);
      L += ci;
      c.push_back(ci);
    }
    T = 2 * A[v] - L;
    if (T < 0 || T > A[v]) { ans = false; }
    if ((L - T) % 2 != 0) { ans = false; }
    ll P = (L - T) / 2;
    ll Q = L/2;
    REP(i, c.size()) {
      Q = min(Q, L-c[i]);
    }
    // if (ans) {
      // cout << "v=" << v << ", Q=" << Q << ", p=" << P << endl;
    // }
    if (Q < P) { ans = false; }
  }
  if (p == -1 && g[v].size() == 1) {
    if (T != A[v]) ans = false;
  }
  return T;
}

