vector <int> L[Nmax];
int grad[Nmax],n,val[Nmax],Bad;
long long dp[Nmax];

inline void dfs(int nod, int tata)
{
    long long sum=0,cnt=0;
    for(auto it : L[nod])
    {
        if(it==tata) continue;
        dfs(it,nod);
        sum+=dp[it];
    }

    if(grad[nod]==1)
    {
        dp[nod]=val[nod]; return;
    }

    long long b = 2LL * (sum-val[nod]);
    long long a = sum-b;

    for(auto it : L[nod])
    {
        if(it==tata) continue;
        cnt+=max(0LL,dp[it]-b/2);
    }

    if(cnt>a)
    {
        Bad=1; return;
    }

    dp[nod]=a;
}

