int ans;
int can(int pos,int par){
  int sum = 0;
  for(int to:G[pos]) if(to!=par) sum += num[to];
  if(sum < num[pos]) return 0;
  if(sum == num[pos]) return 1;

  int target = num[pos];
  int a = 0;
  for(int to:G[pos]){
    if(to == par) continue;
    int b = min(abs(sum - target), min(a,num[to]) );
    target -= b;
    sum -= b * 2;
    assert(sum>=0 && target >=0);
    if(sum == target){
      num[pos] = target;
      return 1;
    }
    a = abs(a - num[to]);
  }
  return 0;
}

int check(int pos,int par){
  if(G[pos].size() == 1) return 1;

  for(int to:G[pos]){
    if(to == par) continue;
    if(check(to,pos) == 0) return ans = 0;
  }
  return ans = can(pos,par);
}
