          dfs(nex, cur);
          sum_c += C[nex];
          c_max = max(c_max, C[nex]);
        }
      }

      if (sz(E[cur]) == 1) {
        C[cur] = A[cur];
      }
      else {
        C[cur] = 2 * A[cur] - sum_c;
        if ((sum_c - C[cur]) % 2) ans = false;
        ll l = (sum_c - C[cur]) / 2;
        if (l < 0) ans = false;
        //out(cur, C[cur], c_max, sum_c, c_max-C[cur] > (sum_c-C[cur]) / 2);
        if (c_max-C[cur] > (sum_c-C[cur]) / 2) ans = false;
      }
    };
    dfs(0, -1);
  }

  return ans;
}

