ll B[SIZE];

int main()
{
    RD(N);
    RDV(A + 1, A + N + 1);
    for(int i: RG(N - 1))
    {
        int u, v;
        RD(u, v);
        adj[u].push_back(v);
        adj[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }

    if(N == 2)
    {
        WTL(A[1] == A[2]? "YES": "NO");
        return 0;
    }

    ll leaf = 0, inter = 0;
    for(int i: RG(1, N + 1))
        if(deg[i] == 1)
            leaf += A[i];
        else
            inter += A[i];

    queue<int> que;
    for(int i: RG(1, N + 1))
        if(deg[i] == 1)
            que.push(i);

    for(int z = que.size(); z > 0; z--)
    {
        int i = que.front();
        que.pop();
        for(int to: adj[i])
        {
            B[to] += A[i];
            if(--deg[to] == 1)
                que.push(to);
        }
    }

    bool ans = true;

    while(que.size() > 1)
    {
        int u = que.front();
        que.pop();

        if(A[u] * 2 < B[u] || A[u] > B[u])
        {
            ans = false;
            break;
        }
        for(int to: adj[u])
        {
            B[to] += A[u] * 2 - B[u];
            if(--deg[to] == 1)
                que.push(to);
        }
    }

    int u = que.front();

    if(A[u] * 2 != B[u])
        ans = false;
    WTL(ans? "YES": "NO");



}

