	void push(int x, int y) {
		vr[++tt] = y; nt[tt] = hd[x]; hd[x] = tt;
	}
	void dfs(int nw, int en) {
		if(nt[hd[nw]] == 0) {mn[nw] = a[nw]; return;}
		int sm, S = 0, T = 0, mx = 0, k = 0, MX = 0, SM = 0, db = 0, GD = 0, hc = 0, ZD = 0;
		for(int i = hd[nw]; i; i = nt[i]) {
			if(vr[i] == en) continue;
			dfs(vr[i], nw);
			if(mx < mn[vr[i]]) S += mx, mx = mn[vr[i]], k = vr[i];
			else S += mn[vr[i]];
		}
		if(mx > S) {
			T = mx - S;
			sm = mx;
			db = S;
		} else {
			T = (S + mx) & 1;
			sm = (S + mx) / 2 + T;
			db = (S + mx) / 2;
			k = 0;
		}
		if(sm > a[nw]) {puts("NO"); exit(0);}
		hc = a[nw] - sm;

