			if(vr[i] == en || vr[i] == k) continue;
			if(T >= (a[vr[i]] - mn[vr[i]]) * 2) T -= (a[vr[i]] - mn[vr[i]]) * 2;
			else {
				int X = (a[vr[i]] - mn[vr[i]]) * 2 - ((T >> 1) << 1);
				if(MX < X) SM += MX, MX = X;
				else SM += X;
				T = T & 1;
			}
		}

		if(MX > SM) {
			ZD = SM;
			GD = MX - SM;
		} else {
			ZD = (SM + MX) / 2;
