using P = pair<int,int>;

P merge(P a, P b) {
  int sum = a.second + b.second;
  if (a.second < b.first) return make_pair(b.first - a.second, sum);
  if (b.second < a.first) return make_pair(a.first - b.second, sum);
  return make_pair(a.first & b.first & 1, sum);
}

vector<int> g[128000];
ll A[128000];
bool visited[128000];
bool flag;

ll dfs(int v) {
  visited[v] = true;
  if (g[v].size() == 1) return A[v];
  vector<ll> vec;
  for (int i: g[v]) {
    if (visited[i]) continue;
    vec.push_back(dfs(i));
  }
  ll sum = accumulate(ALL(vec), 0LL);
  ll res = 2 * A[v] - sum;
  if (A[v] > sum || res < 0) flag = false;
  if (vec.back() * 2 > sum + res) flag = false;
  // cout << v << " " << res << endl;
  return res;
}

void solve(ll N, vector<ll> a, vector<ll> b) {
  REP(i,N-1) {
    int s = a[i] - 1, t = b[i] - 1;
    g[s].push_back(t);
    g[t].push_back(s);
  }
  int root = -1;
  REP(i,N) if (g[i].size() > 1) root = i;
  if (root == -1) { cout << (A[0] == A[1]) << endl; return; }
  flag = true;
  // cout << root << endl;
  if (dfs(root) != 0) flag = false;
  cout << flag << endl;
}

