		return 0;
	}
	memset(head, 0, sizeof head);
	for (int i = 1; i < n; ++ i)
	{
		int u = Getint(), v = Getint();
		++ d[u], ++ d[v];
		AddEdge(u, v);
		AddEdge(v, u);
	}
	int root;
	for (root = 1; d[root] == 1; ++ root);
	if (!Dfs(root, 0) || f[root]) puts("NO"); else puts("YES");
	return 0;
}

