struct tree{
	int r,p;
	vector<int> c;
	ll w = -1LL; //親との経路の使用数
};

tree T[SIZE];

void dfs(int v,int r){
	T[v].r = r;
	for(int c : G[v]) if(T[c].r == 0){
		T[c].p = v;
		T[v].c.push_back(c);
		dfs(c,r+1);
	}
}

void tdfs(int v){
	ll sum = 0LL;
	if(T[v].c.empty()){
		T[v].w = A[v];
		return;
	}
	for(int c : T[v].c) if(T[c].w == -1){
		tdfs(c);
		sum += T[c].w;
	}
	T[v].w = 2LL*A[v] - sum;
}

bool C = true;
void cdfs(int v){
	if(T[v].c.empty())return;
	ll sum = 0LL;
	ll maxc = 0LL;
	for(int c : T[v].c){
		cdfs(c);
		sum += T[c].w;
		maxc = max(maxc,T[c].w);
	}
	ll L = (sum-T[v].w)/2LL;
	ll ps = min(sum/2LL,sum-maxc);
	if(ps < L)C = false;
}

