	for (int i=0;i<g[v].size();i++)
	{
		int to=g[v][i];
		if (used[to])
			continue;
		trace(to);
		sons.push_back(to);
	}

	long long max_son=0;

	if (sons.size()==0)// leaf
	{
		goes_up[v]=am[v];
		return;
	}

	long long total_in_sons=0;
	for (int i=0;i<sons.size();i++)
	{
		int to=sons[i];
		total_in_sons+=goes_up[to];
		max_son=max(max_son,goes_up[to]);
	}

	if (total_in_sons<am[v])
	{
		ok=0;
		return ;
	}
	long long paired=total_in_sons-am[v];

	if (paired*2>total_in_sons)
	{
		ok=0;
		return ;
	}

	long long in_dif=total_in_sons-max_son;
	if (paired>in_dif)
	{
		ok=0;
		return ;
	}

	long long unpaired=total_in_sons-2*paired;
	goes_up[v]=unpaired;
}

