int solve(int cur, int parent) {
  //   cout << cur << ", " << parent << endl;

  if (g[cur].size() == 1) {
    if (parent == -1) {
      return solve(g[cur][0], cur) == as[cur] ? 0 : -1;
    }

    return as[cur];
  }

  vector<int> cs;

  for (auto &next : g[cur]) {
    if (next == parent)
      continue;
    int v = solve(next, cur);
    if (v < 0)
      return -1;

    cs.push_back(v);
  }

  int sum = 0;
  for (auto &c : cs) {
    sum += c;
  }

  int up = 2 * as[cur] - sum;

  //   cout << "**:* up " << as[cur] << ", " << sum << endl;

  if (up < 0) {
    return -1;
  }

  int conn = (sum - up) / 2;

  auto f = [&](int a, int b) {
    int t = min(a, b);
    return max(a - t, b - t);
  };

  int mi = 0, ma = 0;
  for (auto &c : cs) {
    int nmi = f(mi, c);

    nmi = min(nmi, f(ma, c));

    if (mi <= c && c <= ma) {
      int t = c;
      if (mi % 2 != t % 2) {
        t--;
      }
      if (mi <= t && t <= ma) {
        nmi = min(nmi, f(t, c));
      }
      t += 2;
      if (mi <= t && t <= ma) {
        nmi = min(nmi, f(t, c));
      }
    }

    mi = nmi;
    ma += c;
  }

  if (mi <= up && up <= ma)
    return up;

  return -1;
}

