bool check(ll sum, int mx, int st, int p) {
	ll t = 0;     

	if (mx < p) {
		return 0;
	}

    if (mx - sum > p) {
    	return 0;
    }

    t += (mx - p);
	sum -= (mx - p);

	if (sum & 1) {
		return 0;
	}

	t += (sum >> 1);
	return st - t == p;
}

bool dfs(int v, int pr) {
	if ((int)adj[v].size() - (pr != -1) == 0) {
		return 1;
	}

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		if (!dfs(to, v)) {
			return 0;
		}
	}

	int mx = 0;
