template<typename T>
WeightedGraph<T> wgraph(
  int N , int M = -1 , bool is_directed = false , bool is_1origin = true){
  WeightedGraph<T> g(N);
  if(M == -1) M = N - 1;
  for(int _ = 0 ; _ < M ; _++){
    int x , y; cin >> x >> y;
    T c; cin >> c;
    if(is_1origin) x-- , y--;
    g[x].eb(y , c);
    if(!is_directed) g[y].eb(x , c);
  }
  return g;
}

void solve(){
  ini(N);
  vl A(N); in(A);
  auto g = graph(N);


  vl L(N) , R(N);

  auto dfs = [&](auto rec,int cur,int par = -1) -> void{
    // 根からのアレを集計する    
    int chd = 0;
    ll l = 0 , r = 0;
    each(dst , g[cur]){
      if(dst == par) continue;
      rec(rec , dst , cur);
      l += L[dst];
      r += R[dst];
      chd++;
    }

    if(par == -1){
      int i = cur;
      trc(i , A[i] , l , r);
      if(A[i] % 2 != l % 2) die("NO");
      else if(l > A[i] || A[i] > r) die("NO");
      L[i] = R[i] = A[i];
    }

    if(chd == 0){
      L[cur] = R[cur] = A[cur];
      return;
    }

    // l 以上 r 以下だけ子からパスが来る
    // ceil(l , 2) <= A[i] <= r
    if(ceil(l , 2) > A[cur] || A[cur] > r) die("NO");

    // 子が1個 -> 調整できない
    if(chd == 1){
      // 2 * A[cur]本のパス
      R[cur] = 2 * A[cur] - l;
      L[cur] = max(R[cur] % 2 , 2 * A[cur] - r);
    }
    // 子が複数 -> 2本単位で調整可能
    else{
      R[cur] = 2 * A[cur] - l;
      L[cur] = R[cur] % 2;
    }
  };

  int start = 0;
  while(g[start].size() != 1) start++;
  dfs(dfs , start);
  trc(L);
  trc(R);

  out("YES");

}

