int n, u, v, root, visited[100001], a[100001];
vector <int> adj[100001];

bool dfs(int u) {
    visited[u] = 1;
    if(adj[u].size() == 1) return 1;
    int sum = 0, mx = -1;
    for(auto v : adj[u]) {
        if (!visited[v]) {
            if(!dfs(v)) return 0;
            sum += a[v];
            mx = max(mx, a[v]);
        }
    }
    if(mx <= a[u] && a[u] <= sum && sum <= a[u] << 1) {
        a[u] = (a[u] << 1) - sum;
        if (u == root) return !a[u];
        return 1;
    }
    return 0;
}
