    long long ans = (dfs(root) == 0);
    for(long long i = 1; i <= n; ++i) ans = (ans and (2*A[i] - X[i] >= 0) and (A[i] <= X[i]));
    return cout << (ans ? "YES" : "NO") << "\n", 0;
}
