				solve_ston[q] = 0;
			}
		}
		nya += solve_ston[i];
	}
	wa -= nya;
	wa *= 2;
	wa += nya;
	if (wa < stones[now]) can_do = false;
	if (nya > stones[back]) can_do = false;
	return stones[back];
