        else cout << "NO" << endl;
        return;
    }

    vector<i64> r(n);
    function<bool(int,int)> rec=[&](int u,int p){
        if(graph[u].size()==1) return true;
        r[u]=-a[u];
        priority_queue<int,vector<int>>  que;
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            r[u]+=a[v]-r[v];
            que.push(a[v]-r[v]);
        }
        int x=0;
        while(x<r[u] and que.size()>=2){
            auto f=que.top(),g=que.top();
            que.pop();
            que.pop();
            x+=g;
            if(f-g) que.push(f-g);
            if(x>r[u]) x=r[u];
        }
        if(p==-1) return r[u]==a[u] and x==r[u] and que.empty();
        return x==r[u];
    };

