int dfs(int p, int v) {
   if (G[v].size() == 1) return As[v];
   V<int> rec;
   for (int i = 0; i < G[v].size(); i++) {
      int u = G[v][i];
      if (u == p) continue;
      int res = dfs(v, u);
      if (res == INF) {
