void dfs(int u, int prev)
{
	if (prev != -1 && graph[u].size() == 1)
	{
		dp[u] = a[u];
		//cerr << '@' << u << ' ' << dp[u] << endl;
		return;
	}
	for (int i : graph[u])
		if (i != prev)
			dfs(i, u);

	deque<ll> dq;
	ll sum = 0;
	for (int i : graph[u])
		if (i != prev)
			dq.pb(dp[i]), sum += dp[i];
	sort(all(dq));
	for (int i = dq.size() - 1; i >= 1; i--)
		dq[i] -= dq[i - 1];
	ll count = sum - a[u], lim = 0, last = 0;
	for (int i : dq)
		last += i;
	while (dq.size() > 1)
	{
		ll now = last;
		last -= dq.back();
		dq.popb();
		while (!dq.empty() && (now > 0 && now / dq.size() >= dq.front()))
		{
			now -= dq.front() * dq.size();
			lim += dq.front() * dq.size();
			last -= dq.front();
			dq[0] = 0;
			if (dq.size() > 1)
				dq[1] += dq[0];
			dq.popf();
		}
		if (now && !dq.empty())
		{
			dq[0]--;
			last--;
			if (now < dq.size())
				dq[now]++, last++;
			lim += min(now, (ll)dq.size());
			now = 0;
		}
	}
	if (count > lim || count < 0)
	{
		cout << "NO" << endl;
		exit(0);
	}
	dp[u] = a[u] - count;
	//cerr << '@' << u << ' ' << dp[u] << endl;
}

