Node tree[MAX_N];

void set_rank_children(int i, int rank, int parent) {
    tree[i].rank = rank;
    for (int n : tree[i].neighbor) {
        if (n != parent) {
            set_rank_children(n, rank + 1, i);
            tree[i].children.push_back(n);
        }
    }
}

int main(int argc, char **argv) {
