int main()
{
    int N;
    scanf("%d\n", &N);
    vector<int> A(N);
    for (int i = 0; i < N; ++i){
        int Ai;
        scanf("%d", &Ai); getchar();
        A[i] = Ai;
    }
    vector<unordered_set<int>> edges(N);
    for (int i = 0; i < N - 1; ++i){
        int ai, bi;
        scanf("%d %d\n", &ai, &bi); --ai; --bi;
        edges[ai].emplace(bi);
        edges[bi].emplace(ai);
    }
    int root = 0;
    while (root < N && edges[root].size() == 1) ++root;
    if (root == N){
        if (N == 2){
            if (A[0] == A[1]){
                puts("YES");
            }else{
                puts("NO");
            }
        }
        return 0;
    }
    bool contradict_flag = false;
    function<ll(int, int)> check = [&](int node, int parent) -> ll {
        if (edges[node].size() == 1) return A[node];
        ll leaf_sum = 0;
        vector<ll> children;
        for (auto& edge : edges[node]){
            if (edge == parent) continue;
            children.emplace_back(check(edge, node));
            leaf_sum += children.back();
            if (contradict_flag) return 0;
        }
        if (!(A[node] <= leaf_sum && leaf_sum <= A[node] * 2)){
            contradict_flag = true;
            return 0;
        }
        ll inner_count = 0;
        for (auto& child : children){
            inner_count += min(child, leaf_sum - child);
        }
        if (inner_count < (leaf_sum - A[node]) * 2) contradict_flag = true;
        return A[node] * 2 - leaf_sum;
    };
    if (check(root, root) == 0 && !contradict_flag){
        puts("YES");
    }else{
        puts("NO");
    }
}

