const int N = 100000 + 10;
int a[N];

vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  lli mx = *max_element(b.begin(), b.end());
  lli paired = min<lli>(sum / 2, mx);
  lli x = a[curr] - paired;
  lli y = a[curr] * 2 - sum;
  if (sum < a[curr]) throw "";
  if (x < 0 || y < 0 || (curr == prev && y)) throw "";
  return y;
}

