void out(bool a)
{
	if (a) cout << "YES" << endl;
	else cout << "NO" << endl;
	exit(EXIT_SUCCESS);
}

ll solve(int v, const vi& a, const vector<vi>& tree)
{
	if (tree[v].size() == 0) return a[v];
	vi t;
	for (auto i : tree[v])
	{
		ll tmp = solve(i, a, tree);
		if (tmp == -1) return -1;
		t.push_back(tmp);
	}
	ll sum = 0;
	for (auto i : t)
	{
		sum += i;
		if (sum > a[v] * 2) return -1;
	}
	if (sum < a[v]) return -1;
	ll res = a[v] * 2 - sum;
	ll del = (sum - res) / 2;
	ll mi = sum - *max_element(ALL(t));
	if (mi < del) return -1;
	if (res < 0) res = -1;
	return res;
}

