		v.push_back(r);
		sm += r;
	}

	if (v.size() == 1) {
		if (sm != A[cur]) return -1;
		return A[cur];
	}

	if (sm < A[cur]) return -1;

	sort(v.begin(), v.end());
	int l = 0, r = v.size() - 1;
	ll d = sm - A[cur];
	while (0 < d) {
		ll t = min(v[l], v[r]);

