const ll MOD=1e9+7;

int N;
LL A[114514];
vector<int> es[114514];

pair<LL, LL> dfs(int v, int p) {
  int num_ch = 0;
  LL l = 0;
  LL r = 0;
  LL s = 0;
  LL ls = 0;
  LL maxa = -1;
  LL maxb = -1;
  for (int u : es[v]) {
    if (p == u) continue;
    LL x, y;
    tie(x, y) = dfs(u, v);
    s += y;
    ls += x;
    maxa = max(maxa, x);
    maxb = max(maxb, y);
    LL nr = y+r;
    LL nl = max(0LL, max(x, l) - min(y, r));
    l = nl;
    r = nr;
    num_ch++;
  }

  if (ls/2 + ls%2 > A[v]) {
    puts("NO");
    exit(0);
  }

  LL mp = 0;
  if (2*maxa > s) mp = s-maxa;

  LL mp2 = s/2;
  if (2*maxb > s) mp2 = s - maxb;
  mp2 = A[v] - mp2;

  if (num_ch == 0) return make_pair(A[v], A[v]);
  if (num_ch == 1) {
    if (l <= A[v] && A[v] <= r) return make_pair(A[v], A[v]);
    puts("NO");
    exit(0);
  }
  return make_pair(max(l, max(mp2, mp)), min(r, A[v]));
}

int main() {
