    if (es[v].size() > 1) {
      if (dfs(v, v).first == 0) puts("YES");
      else puts("NO");
      return 0;
    }
  }

  assert(N == 2);
  if (A[0] == A[1]) puts("YES");
  else puts("NO");
}

