using namespace std;

typedef long long ll;

typedef vector<vector<int>> Graph;
vector<ll> a(100000),c(100000,-1);
bool f=true;

ll dfs(const Graph& g, int node){
  int sz=g[node].size();
  if(sz==0){
    return c[node]=a[node];
  }
  ll sum=0;
  for(int i=0;i<sz;i++){
    int next=g[node][i];
    sum += dfs(g,next);
  }
  c[node]=2*a[node]-sum;
  if(c[node]<0) f=false;
  if((sum-c[node])%2) f=false;
  ll num=(sum-c[node])/2; // num 組作れるか
  ll tmp=sum/2;
  for(int i=0;i<sz;i++){
    int next=g[node][i];
    tmp = min(tmp,sum-c[next]);
  }
  if(tmp<num) f=false;
  return c[node];
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;cin>>n;
    Graph g(n);
    for(int i=0;i<n;i++) cin>>a[i];
    for(int i=0;i<n-1;i++){
      int st,gt;cin>>st>>gt;
      st--;gt--;
      g[st].push_back(gt);
      g[gt].push_back(st);
    }
    Graph tr(n);
    vector<int> used(n,0);
    queue<int> q;
    q.push(0);
    used[0]=1;
    while(!q.empty()){
      int v=q.front();q.pop();
      for(int i=0;i<(int)g[v].size();i++){
        int next=g[v][i];
        if(used[next]) continue;
        tr[v].push_back(next);
        q.push(next); used[next]=1;
      }
    }
    dfs(tr,0);
    if(f) cout<<"YES"<<endl;
    else cout<<"NO"<<endl;
}

