	multimap<int, int> dmp;
	for(int i=0; i<n; i++){
		dmp.insert(make_pair(-d[i], i));
	}
	long long int m[100000];
	for(auto itr=dmp.begin(); itr!=dmp.end(); itr++){
		int x=itr->second;
		if(x!=0){
		int vp=-1;
		long long int sum=0;
		if(v[x].size()==1){
			m[e[P(x, v[x][0])]]=A[x];
		}else{
		for(int i=0; i<v[x].size(); i++){
			if(d[v[x][i]]<d[x]){
				vp=v[x][i];
			}else{
				sum+=m[e[P(x, v[x][i])]];
			}
		}

		if(vp!=-1) m[e[P(x, vp)]]=2*A[x]-sum;
		}
		}else{
			if(v[0].size()==1){
				if(m[e[P(0, v[0][0])]]!=A[0]){
					printf("%s\n", "NO");
					return 0;
				}
			}else{
				long long int sum=0;
				for(int i=0; i<v[0].size(); i++){
					sum+=m[e[P(0, v[0][i])]];
				}
				if(2*A[0]!=sum){
					printf("%s\n", "NO");
					return 0;
				}
			}
		}
	}
	for(int x=0; x<n; x++){
		if(v[x].size()!=1){
			for(int i=0; i<v[x].size(); i++){
				if(m[e[P(v[x][i], x)]]>A[x] || m[e[P(v[x][i], x)]]<0){
					printf("%s\n", "NO");
					return 0;
				}
			}
		}
	}
	printf("%s\n", "YES");
	return 0;
}

