#define mod 1000000007

int n;
vector<vector<int> > graph(100001);
vector<bool> ischecked(100001, false);
vector<long long int> stonenum(100001);

int cansolve(int node)
{
	if(graph[node].size() == 1) return stonenum[node];
	ischecked[node] = true;
	int ans = 2 * stonenum[node];
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		int tmp = cansolve(child);
		ans -= tmp;
		if(tmp == -1 || tmp > stonenum[node] || ans < 0) return -1;
	}
	if(ans > stonenum[node]) return -1;
	return ans;
}

int main()
{
	cin >> n;
	for(int i = 0; i < n; i++){
		cin >> stonenum[i];
	}
	int a, b;
	for(int i = 0; i < n - 1; i++){
		cin >> a >> b;
		a--;
		b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	int root = 0;
	while(root < n && graph[root].size() == 1) root++;
	if(cansolve(root)) cout << "NO" << endl;
	else cout << "YES" << endl;
	// cout << stonenum[0] << endl;
	return 0;
}

