ll dfs(int i, int p) {
	if (sz(g[i]) == 1) return a[i];

	ll sum = 0;
	int count = 0;
	priority_queue<ll> pq;
	for (int j : g[i]) {
		if (j == p) continue;
		ll now = dfs(j, i);
		if (now == -1) NO();
		sum += now;
		++count;
		pq.push(now);
	}
	ll can = 0;
	while (sz(pq) > 1) {
		ll v1 = pq.top(); pq.pop();
		ll v2 = pq.top(); pq.pop();
		can += v2;
		if (v1 - v2)
			pq.push(v1 - v2);
	}
	if (a[i] >= sum - can and a[i] <= sum) return 2*a[i] - sum;
	NO();
	return -1;
}

