#include <bits/stdc++.h>
using namespace std;

vector<int> graph[100005];
int dat[100005];
long long up[100005];

void dfs(int t, int p)
{
	vector<long long> ups;

	for (int nxt : graph[t])
	{
		if (nxt == p) continue;
		dfs(nxt, t);
		ups.push_back(up[nxt]);
	}

	if (ups.empty())
	{
		up[t] = dat[t];
		return;
	}

	if (ups.size() == 1)
	{
		if (ups[0] != dat[t])
		{
			printf("NO\n");
			exit(0);
		}
		up[t] = dat[t];
		return;
	}

	sort(ups.begin(), ups.end());

	long long maxmatch = 0;
	long long sum = 0;
	for (int i = 0; i < ups.size() - 1; i++)
	{
		sum += ups[i];
	}

	if (sum <= ups.back()) maxmatch = sum;
	else maxmatch = (sum + ups.back()) / 2;
	sum += ups.back();

	if (dat[t] > sum)
	{
		printf("NO\n");
		exit(0);
	}

	long long diff = sum - dat[t];
	if (diff < maxmatch)
	{
		printf("NO\n");
		exit(0);
	}

	up[t] = dat[t] - diff;
}

int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		scanf("%d", &dat[i]);
	}

	for (int i = 1; i < n; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		a--; b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	if (n == 2)
	{
		if (dat[0] == dat[1]) printf("YES\n");
		else printf("NO\n");
		return 0;
	}

	for (int i = 0; i < n; i++)
	{
		if (graph[i].size() >= 2)
		{
			dfs(i, -1);

			if (up[i] == 0) printf("YES\n");
			else printf("NO\n");

			return 0;
		}
	}
}

