auto soln() {
    int n = scan<int>(), root;
    auto A = scan<int>(n, 1);
    vector<vector<int>> g(n + 1);
    vector<int> deg(n + 1, 0), vis(n + 1, false), X(n + 1, 0);
    for (int i = 0; i < n - 1; ++i) {
        auto [u, v] = scan<int, 2>();
        g[u].push_back(v), g[v].push_back(u);
        deg[u] += 1, deg[v] += 1;
    }
    if(n == 2) return cout << (A[1] == A[2] ? "YES" : "NO") << "\n", 0;
    function<int(int u)> dfs = [&](int u) -> int{
        vis[u] = true;
        if(deg[u] == 1) return A[u];
        for(auto v : g[u]) { if(!vis[v]) { X[u] += dfs(v); } }
        return 2*A[u] - X[u];
    };
    for(int i = 1; i <= n; ++i) if (deg[i] != 1) { root = i; break; }
    int ans = dfs(root) == 0;
    for(int i = 1; i <= n; ++i) ans = ans and A[i] >= 0;
    return cout << (ans ? "YES" : "NO") << "\n", 0;
}
signed main() {
    int t = 1;
    ios_base::sync_with_stdio(false), cin.tie(NULL), cout.tie(NULL);
    while (t--)
        soln();
    return 0;
}

