typedef long long li;

vector<li> a;
vector<vector<int>> e;

li dfs(int v, int p = -1)
{
    if (e[v].size() == 1)
        return a[v];

    li sum = 0, maxnum = 0;
    for (int u: e[v])
    {
        if (u == p) continue;

        li dChild = dfs(u, v);
        sum += dChild;
        maxnum = max(maxnum, dChild);
    }

    li paired = sum - a[v];
    //printf("at %d %lld paired, sum %lld maxnum %lld\n", v + 1, paired, sum, maxnum);
    if (paired < 0 || paired > min(sum / 2, sum - maxnum))
    {
        cout << "NO\n";
        exit(0);
    }

    return sum - paired * 2;
}

