inline void ins(int f,int t)
{
	e[++cnt]=(edge){t,head[f]};head[f]=cnt;++d[f];
	e[++cnt]=(edge){f,head[t]};head[t]=cnt;++d[t];
}
ll dfs(int x,int fa)
{
	if(d[x]==1) return a[x];
	ll tot=0,mx=0;
	for(int i=head[x];i;i=e[i].next)
