    for(int v : child[u]){
        s += A[v];
    }

    LL C1 = 0;
    for(int v : child[u]) {
        C1 += inner[v];
    }

    LL C23 = 0;
    for(int v : child[u]) {
        C23 += outer[v];
    }

    if(child[u].size() == 0) {
        inner[u] = 0;
        outer[u] = a;
        return true;
    }

    // C2 + C3 = a
    // 2 * C2 + C3 = (s-2*C1)
    // C2 = (s-2*C1) - a
    // C3 = a - C2
    //
    LL C2 = s-2*C1 - a;
