typedef long long ll;

const int MAXN = 100005;

struct Edge
{
	int to;
	int nxt;
}edge[MAXN << 1];

int n,id;
int a[MAXN];
int first[MAXN];
int deg[MAXN];

ll v1[MAXN];
ll v2[MAXN];

void addE(int u,int v)
{
	edge[++id] = (Edge){v,first[u]};
	first[u] = id;
	deg[v]++;
}

void dfs(int u,int fa)
{
	if (deg[u] == 1)
	{
		v1[u] = -a[u];
		v2[u] = a[u];
		return;
	}
	ll MAX = 0;
	for (int i = first[u];i;i = edge[i].nxt)
		if (edge[i].to != fa)
		{
			dfs(edge[i].to,u);
			v1[u] += v1[edge[i].to];
			v2[u] += v2[edge[i].to];
			MAX = max(MAX,v2[edge[i].to]);
		}
	ll tmp = v1[u];
	v1[u] = -v1[u] - a[u];
	if (v1[u] < 0)
	{
		puts("NO");
		exit(0);
	}
	if ((MAX << 1) > v2[u])
		MAX = v2[u] - MAX;
	else
		MAX = v2[u] >> 1;
	if (MAX < v1[u])
	{
		puts("NO");
		exit(0);
	}
	v2[u] -= v1[u] << 1;
	v1[fa] += v1[u];
	v1[u] += tmp;
}

int main()
{
	ios::sync_with_stdio(0);
	cin >> n;
	for (int i = 1;i <= n;i++)
		cin >> a[i];
	for (int u,v,i = 1;i < n;i++)
	{
		cin >> u >> v;
		addE(u,v);
		addE(v,u);
	}
	if (n == 2)
	{
		puts(a[1] == a[2] ? "YES" : "NO");
		return 0;
	}
	for (int i = 1;i <= n;i++)
		if (deg[i] > 1)
		{
			dfs(i,0);
			puts(v2[i] ? "NO" : "YES");
			return 0;
		}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
using ll = long long;

int imp = 0;
const int N = 1e5;
ll a[N];
vector<int> treeone[N];
using P = pair<ll, ll>;
P Z(-1, -1);

P calc(int i, ll s, ll mx) {
  ll r = s - a[i];

  if(r < 0) {
    return Z;
  }

  r = r / 2;

  ll c = min(s / 2, s - mx);
  c = min(c, a[i]);

  if(c < r) {
    return Z;
  }
  return P(a[i] - c, a[i] - r);
}

P dfs(int i, int p = -1) {
  if(imp) return Z;
  if(p != -1 && (int) treeone[i].size() == 1) return P(a[i], a[i]);
  ll Ms = 0, ms = 0;
  ll Mmx = 0, mmx = 0;

  for(int j : treeone[i]) if(p != j) {
    P t = dfs(j, i);
    ll mt = get<0>(t), Mt = get<1>(t);
    if(imp) return Z;
    ms += mt;
    Ms += Mt;
    mmx = max(mmx, mt);
    Mmx = max(Mmx, Mt);
  }

  P m = calc(i, ms, mmx), M = calc(i, Ms, Mmx);
  if(m == Z && M == Z) {
    imp = 1; return Z;
  } else if(m == Z) return M;
  else if(M == Z) return m;
  else return P(min(get<0>(m), get<0>(M)), max(get<1>(m), get<1>(M)));
}

int solve() {
  ios::sync_with_stdio(false), cin.tie(0);
  int n; cin >> n;
  for(int i = 0; i < n; i++) cin >> a[i];
  for(int i = 0; i < n - 1; i++) {
    int x, y; cin >> x >> y; x--; y--;
    treeone[x].emplace_back(y);
    treeone[y].emplace_back(x);
  }
  if(n == 2) return a[0] == a[1];
  int x;
  for(int i = 0; i < n; i++) if((int) treeone[i].size() != 1) x = i;
  if(dfs(x) > P(0, 1e8)) return 0;
  return !imp;
}

int main() {
  cout << (solve() ? "YES" : "NO") << endl;
}

