	string solve(){
		vb used(V,0);
		queue<int> q;
		for(int i=0;i<V;i++) if(List[i].size()==1){
			q.push(i);
			used[i]=1;
		}
		while(!q.empty()){
			int v=q.front();
			q.pop();
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(!used[u]){
