					ll num;
					if(M>sum-M) num=sum-M;
					else num=sum/2;
					ll x=sum-a[u];
					if(0>x||x>num) return "NO";
					a[u]-=x;
					q.push(u);
				}
			}
		}
		for(int i=0;i<V;i++) if(a[i]) return "NO";
		return "YES";
	}
};

