bool ok = true;

ll f(int u, int p, vector<vector<int> >& G, vector<int>& a) {
	vector<int> vs;
	for (int v: G[u]) if (v != p) vs.pb(v);
	if (vs.empty()) return a[u];
	ll sum = 0, ma = 0;
	for (int v: vs) {
		ll x = f(v, u, G, a);
		sum += x;
		ma = max(ma, x);
	}
	ll ub = min(sum / 2, sum - ma);
	if (sum < a[u]) {
		ok = false;
		return 0;
	}
	ll unko = sum - a[u];
	if (unko > ub) {
		ok = false;
		return 0;
	}
	return sum - unko * 2;
}

