void solve (ll cur, ll prv) {
	if(adj[cur].size() == 1) {
		up[cur] = a[cur];
		return;
	}
	ll sum = 0, mx = 0;
	for(auto &nxt : adj[cur]) {
		if(nxt == prv) continue;
		solve(nxt, cur);
		sum += up[nxt];
		mx = max(up[nxt], mx);
