bool dfs(int v, int par){
    int sum = 0;
    for(int u : edge[v]){
        if(u == par){
            continue;
        }
        if(not dfs(u, v)){
            return false;
        }
        sum += a[u];
    }

    if(sum == 0){
        return true;
    }

    int child = sum - a[v];
    if(child < 0 || a[v] - child < 0 || child > sum / 2){
        return false;
    }

    a[v] -= child;
    return true;
}

