		--u; --v;
		adjlist[u].push_back(v);
		adjlist[v].push_back(u);
	}

	try {
		int root = 0;
		while (adjlist[root].size() == 1) ++root; // ensure that root is not a leaf
		if (dfs(root, -1) != 0) throw 0;
		std::cout << "YES\n";
	} catch (int) {
		std::cout << "NO\n";
	}
}

