using namespace std;
int a[N],b[N],n,x,y,fst[N],nxt[N],to[N],l,dig[N];
void link(int x,int y)
{
	dig[x]++;dig[y]++;
	to[++l]=y;nxt[l]=fst[x];fst[x]=l;
	to[++l]=x;nxt[l]=fst[y];fst[y]=l;
}
void biu()
{
	puts("NO");
	exit(0);
}
void dfs(int x)
{
	dig[x]=-1;
	int flag=0;
	for (int i=fst[x];i;i=nxt[i])
		if (dig[to[i]]!=-1)
		{
			flag=1;
			dig[to[i]]--;b[to[i]]-=b[x];
			//v[to[i]].push_back((T){a[x],b[x]});
			if (dig[to[i]]==1) dfs(to[i]);
		}
	if (flag==0&&b[x])biu();
}
int main()
{
	scanf("%d",&n);
	for (int i=1;i<=n;i++)
		scanf("%d",&a[i]);
	for (int i=1;i<n;i++)
	{
		scanf("%d%d",&x,&y);
		link(x,y);
	}
	for (int i=1;i<=n;i++)
		if (dig[i]==1) b[i]=a[i];
		else b[i]=a[i]*2;
	for (int i=1;i<=n;i++)
	{
		if (dig[i]==1) dfs(i);
		if (b[i]<0) biu();
	}
	puts("YES");
}

