ll dfs(int u, int p) {
    bool leaf = true;
    ll sum = 0, mx = 0;
    for (int v : adj[u]) if (v != p) {
        ll dv = dfs(v,u);
        sum += dv;
        mx = max(mx, dv);
        leaf = false;
    }
    if (leaf) return a[u];


    auto rest = sum - a[u];
