    int N;
    cin >> N;
    vector<int> A(N);
    cin >> A;
    vector<vector<int>> g(N);
    REP(i, N - 1) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    int root = 0;
    auto dfs = [&](auto f, int v, int p) -> int {
        if (SZ(g[v]) == 1 && v != root) { return A[v]; }

        int sc = 0;
        int mxc = 0;
        FORE(w, g[v]) {
            if (w == p) continue;
            int c = f(f, w, v);
            sc += c;
            chmax(mxc, c);
        }
        int T = 2 * A[v] - sc;
        if (T < 0) {
            cout << "NO" << endl;
            exit(0);
        }
        chmax(mxc, T);
        if (mxc > (sc + T) / 2) {
            cout << "NO" << endl;
            exit(0);
        }
        return T;
    };
    while (SZ(g[root]) > 1) root++;
    dfs(dfs, root, -1);
    cout << "YES" << endl;
    return (0^_^0);
}

