vector<vector<int>> g;
int a[100100];
bool ok;
LL dfs(int v, int par) {
	LL sum = 0;
	LL max1 = 0;
	bool wasChild = false;
	FOR(i,0,g[v].size()) {
		if (!ok) {
			return 0;
		}
		int to = g[v][i];
		if (to == par) {
			continue;
		}
		LL val = dfs(to, v);
		sum += val;
		max1 = max(max1, val);
		wasChild = true;
	}
	if (!ok) {
		return 0;
	}
	if (!wasChild) {
		return a[v];
	}
	LL maxC = 0;
	if (max1 + max1 <= sum) {
		maxC = sum / 2;
	} else {
		maxC = sum - max1;
	}
	LL c = sum - a[v];
	if ((c < 0) || (c > maxC)) {
		ok = false;
		return 0;
	}
	return sum - c - c;
}

