bool used[100001];

ll dfs(int v){
	used[v]=true;
	ll pass=0;
	int fl=0;
	ll maxi=0;
	for(int i=0;i<G[v].size();i++){
		if(!used[G[v][i]]){
			fl++;
			ll get=dfs(G[v][i]);
			pass+=get;
			maxi=max(get,maxi);
		}
	}
	if(fl==0)return a[v];
	ll val=pass;
	if(val<a[v] || val>a[v]*2LL)flag=false;
	ll T=a[v]*2LL-pass;
	if((pass-T)%2LL==1)flag=false;
	if((pass-T)/2LL>min(a[v],pass/2LL))flag=false;
	if(G[v].size()==1){
		if(a[v]==val)return 0;
		return -1;
	}
	return T;
}

