int main() {
	#ifdef INPUT_FROM_FILE
	ifstream cin("sample.in");
	ofstream cout("sample.out");
	#endif
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(50);
	ll n; cin >> n;
	vl A(n); REP(i, n) cin >> A[i];
	vvl path(n);
	REP(i, n - 1) {
		ll a, b; cin >> a >> b;
		a--, b--;
		path[a].push_back(b);
		path[b].push_back(a);
	}
	ll yes = true;
	function<ll(ll, ll)> dfs = [&](ll cur, ll par) {
		if (path[cur].size() == 1) return A[cur];
		ll ma = 0, sum = 0;
		for (auto e : path[cur]) if (e != par) {
			ll x = dfs(e, cur);
			ma = max(x, ma);
			sum += x;
		}
		if (A[cur] > sum || A[cur] < max(ma, sum / 2)) {
			yes = false;
			return 0ll;
		}
		return sum - (sum - A[cur]) * 2;
	};

	ll root = 0;
	REP(i, n) if (path[i].size() != 1) root = i;

	if (dfs(root, -1) != 0) {
		yes = false;
	}
	cout << (yes ? "YES" : "NO") << endl;
}

