const int maxn = 100000 + 10;
typedef long long int lli;

struct Node {
    int to;
    int next;
} edge[maxn];

int head[maxn];
int tot = 0;
lli a[maxn];
int du[maxn];

void addedge(int u, int v) {
    edge[tot].to = v;
    edge[tot].next = head[u];
    head[u] = tot++;
}

bool flag = true;

void dfs(int x, int last) {
    if (!flag) return;
    if (du[x] == 1) return;
    lli sum = 0, mx = 0;
    for (int i = head[x]; i != -1; i = edge[i].next) {
        int v = edge[i].to;
        if (v == last) continue;
        dfs(v, x);
        if (!flag) return;
        sum += a[v];
        mx = max(a[v], mx);
    }
    if (sum < a[x] || sum > a[x] * 2) {
        flag = false;
        return;
    }
    if (a[x] < mx) {
        flag = false;
        return;
    }
    a[x] = a[x] * 2 - sum;
}

int main() {
//    freopen("in", "r", stdin);
    memset(head, -1, sizeof(head));
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (int i = 1; i <= n - 1; i++) {
        int x, y;
        scanf("%d%d", &x, &y);
        addedge(x, y);
        addedge(y, x);
        du[x]++;
        du[y]++;
    }
    if (n == 2) printf("%s\n", a[1] == a[2] ? "YES" : "NO");
    else {
        int p = 1;
        while (du[p] == 1) p++;
        dfs(p, -1);
        if (a[p] != 0) flag = false;
        printf("%s\n", flag ? "YES" : "NO");
    }
    return 0;
}

