bool dfs(int v)
{
	visited[v] = true;
	if (g[v].size() == 1)
	{
		f[v] = a[v];
		return true;
	}

	ll cnt = 0;
	ll mx = 0;
	for (int i = 0; i < g[v].size(); i++)
	{
		if (!visited[g[v][i]])
		{
			if (!dfs(g[v][i]))
			{
				return false;
