struct Edge{
	int to,nxt;
}e[N*2];

void addedge(int x,int y){
	e[++tot].to=y;e[tot].nxt=fst[x];fst[x]=tot;deg[y]++;
}

bool dfs(int x,int father){
	if (deg[x]==1){

		return 1;
	}
	int sum=0,mx=0;
	for (int i=fst[x];i;i=e[i].nxt){
		int y=e[i].to;
		if (y!=father){
			if (!dfs(y,x)) return 0;
			sum+=a[y];
			mx=std::max(mx,a[y]);
		}
	}
	a[x]=a[x]*2-sum;
	return (a[x]>=0 && mx*2-sum<=a[x]);
}

