int dfs(int v) {
    used[v] = true;
    if (G[v].size() == 1) {
        ch[v] = A[v];
    }
    int max_ch = 0;
    for (int i = 0; i < G[v].size(); i++) {
        if (!used[G[v][i]]) {
            int cur_ch = dfs(G[v][i]);
            ch[v] += cur_ch;
            max_ch = max(max_ch, cur_ch);
        }
