bool dfs(int v, int par) {
	bool leaf = 1;
	ll sum = 0;
	ll m = 0;
	for (int to : G[v]) {
		if (to == par) continue;
		if (!dfs(to, v)) return 0;
		sum += c[to];
		m = max(m, c[to]);
		leaf = 0;
	}
	if (leaf) {
		c[v] = A[v];
		return 1;
	}
	if (2 * A[v] < sum || sum < A[v]) return 0;
	ll T = 2 * A[v] - sum;
	if (min(sum - m, sum / 2) >= (sum - T) / 2) {
		c[v] = T;
		return 1;
	}
	return 0;
}
