void addedge(int u, int v) {
  e[++cnt] = (Edge){head[u], v}, head[u] = cnt;
  e[++cnt] = (Edge){head[v], u}, head[v] = cnt;
}

i64 f[MAX_N], mx[MAX_N];

void dfs(int u, int v) {
  if (deg[u] == 1) {
    f[v] += A[u], mx[v] = max(mx[v], (i64)A[u]);
  } else {
    for (int i = head[u]; i; i = e[i].nxt)
      if (e[i].to != v) {
	dfs(e[i].to, u);
      }
    if (f[u] > A[u] * 2 || f[u] < A[u] || mx[u] > A[u]) flag = 0;
    f[v] += A[u] * 2 - f[u], mx[v] = max(mx[v], A[u] * 2 - f[u]);
  }
}

