ll evaluation(int u) {
  if (leaves.find(u) != end(leaves)) {
    return a[u];
  }
  ll sum_childs = 0;
  vll childs;
  for (int v : g[u]) {
    if (v == par[u]) {
      continue;
    }
    ll tmp = evaluation(v);
    childs.push_back(tmp);
    sum_childs += tmp;
  }
  sort(all(childs));
  ll min_a, max_a;
  max_a = sum_childs;
  min_a = (sum_childs&1);
  if (childs.back() * 2 > sum_childs) {
    min_a = max(min_a, childs.back());
  } else {
    min_a = max(min_a, (ll)0);
  }

  if (a[u] < min_a || max_a < a[u]) {
    printf("NO\n");
    exit(0);
  }
  return sum_childs - (sum_childs - a[u]) * 2;
}

void search_main(int root) {
  ll sum_child = 0;
  vll childs;
  for (int u : g[root]) {
    ll tmp = evaluation(u);
    childs.push_back(tmp);
    sum_child += tmp;
  }
  if (a[root] * 2 != sum_child) {
    printf("NO\n");
    exit(0);
  }
  sort(all(childs));
  if (childs.back() * 2 > sum_child) {
    printf("NO\n");
    exit(0);
  }
}

