    if (a[0] == a[1]) {
      printf("YES\n");
    } else {
      printf("NO\n");
    }
    return 0;
  }
  ll sum_leaves = 0;
  int root = 0;
  rep (i, n) {
    if (g[root].size() < g[i].size()) {
      root = i;
    }
    if ((int)g[i].size() == 1) {
      leaves.insert(i);
      sum_leaves += a[i];
    }
  }
  if ((sum_leaves&1) == 1) {
    printf("NO\n");
    return 0;
  }
  ll times = sum_leaves / 2;
  par.resize(n);
