        if(graph[u].size()<=2 and p!=-1) return true;
        r[u]=-a[u];
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            r[u]+=a[v]-r[v];
        }
        if(p==-1) return r[u]==a[u];
        return (0<=r[u] and r[u]<=a[u]);
    };

    rep(i,0,n){
        if(graph[i].size()<2) continue;
        if(rec(i,-1)) cout << "YES" << endl;
        else cout << "NO" << endl;
        return;
    }
}

