struct tree {
	int hd[100005], vr[200005], nt[200005], tt;
	void push(int x, int y) {
		vr[++tt] = y; nt[tt] = hd[x]; hd[x] = tt;
	}
	void dfs(int nw, int en) {
		int sm, S = 0, T = 0, mx = 0, k = 0, MX = 0, SM = 0, db = 0, GD = 0, hc = 0, ZD = 0;
		for(int i = hd[nw]; i; i = nt[i]) {
			if(vr[i] == en) continue;
			dfs(vr[i], nw);
			if(mx < mn[vr[i]]) S += mx, mx = mn[vr[i]], k = vr[i];
			else S += mn[vr[i]];
		}
		if(mx > S) {
			T = mx - S;
			sm = mx;
			db = S;
		} else {
			T = (S + mx) & 1;
			sm = (S + mx) / 2 + T;
			db = (S + mx) / 2;
			k = 0;
		}
		if(sm > a[nw]) {puts("NO"); exit(0);}
		hc = a[nw] - sm;

		for(int i = hd[nw]; i; i = nt[i]) {
			if(vr[i] == en || vr[i] == k) continue;
			if(T > (a[vr[i]] - mn[vr[i]]) * 2) T -= (a[vr[i]] - mn[vr[i]]) * 2;
			else {
				int X = (a[vr[i]] - mn[vr[i]]) * 2 - ((T >> 1) << 1);
				if(MX < X) SM += MX, MX = X;
				T = T & 1;
			}
		}

		if(MX > SM) {
			ZD = SM;
			GD = MX - SM;
		} else {
			ZD = (SM + MX) / 2;
			GD = (SM + MX) & 1;
		}
		if(nt[hd[nw]] == 0) {mn[nw] = a[nw]; return;}
		mn[nw] = T;
		if(ZD > hc) mn[nw] += 0;
		else {
			hc -= ZD;
			if(GD + db >= hc) mn[nw] += hc;
			else {puts("NO"); exit(0);}
		}
		return;
	}
}T;
