	long long cur = 0ll;

	for (int i = 0; i + 1 < (int)vec.size(); i++) {
		cur += vec[i];
	}	

	long long carry = 0;

	if (vec.back() > cur) {
		carry += vec.back() - cur;
		sum -= carry;
	} else {
		if (sum & 1) {
			carry++;
			sum--;
		}
	}

