ll deru(int now) {
  if (!ok) return 0;
  if ((int)children[now].size() == 0) return A[now];
  ll sum = 0;
  ll maxi = 0;
  for (auto x : children[now]) {
    ll temp = deru(x);
    sum += temp;
    maxi = max(maxi, temp);
  }
  if ((int)children[now].size() == 1) {
    if (A[now] == sum) return A[now];
