  ll x = A[now] - y;
#if DEBUG == 1
    cerr << "now = " << now << ", x = " << x << ", y = " << y << endl; 
#endif
  if (y >= 0 && x >= 0 && y <= sum - maxi) {
    return x;
  } else {
    ok = false;
    return 0;
  }
}

