			sum+=dp[G[v][i]];
			ma=max(ma,dp[G[v][i]]);
		}
	}
	ll x,y;
	x=sum-A[v];
	y=A[v]-x;
	if (A[v]<(sum+1)/2 || sum<A[v]) ok=false;
