void dfs1(long long v, long long p) {
    d[v] += a[v];
    long long f = 0;
    for (long long i = 0; i < g[v].size(); ++i) {
        if (g[v][i] != p) {
            d[g[v][i]] -= a[v];
            dfs1(g[v][i], v);
            ++f;
        }
    }
    if (f == 0) {
        //cout << "#" << v << " " << d[v] << endl;
        return;
    }
    if (f <= 2) {
        for (long long i = 0; i < g[v].size(); ++i) {
            if (g[v][i] != p) {
                if (d[g[v][i]] != 0) {
                    //cout << "#" << v << " " << g[v][i] << "    " << d[g[v][i]] << endl;
                    wa();
                }
            }
        }
        return;
    }
    long long sum = 0;
    for (long long i = 0; i < g[v].size(); ++i) {
        if (g[v][i] != p) {
            if (d[g[v][i]] > 0) {
                wa();
            }
            sum -= d[g[v][i]];
        }
    }
    if (sum % (f - 2)) {
        wa();
    }
    sum /= (f - 2);
    //cout << "#" << sum << endl;
    long long all = 0, mx = 0;
    for (long long i = 0; i < g[v].size(); ++i) {
        if (g[v][i] != p) {
            if (sum + d[g[v][i]] < 0) {
                wa();
            }
            all += sum + d[g[v][i]];
            mx = max(mx, sum + d[g[v][i]]);
        }
    }
    //cout << all << " " << mx << endl;
    if (all - mx < mx) {
        wa();
    }
    d[v] -= sum;
}

