int assign(int v, int p) {

  long long res = 2 * arr[v];
  if (adj[v].size() == 1) res = arr[v];
  for (int i = 0; i < adj[v].size(); ++i) {
    int u = adj[v][i];
    if (u == p) continue;
    int p_id = assign(u, v);
    res -= edges[u][p_id];
    edges[v][i] = edges[u][p_id];
  }
  int ret = 0;
  for (int i = 0; i < adj[v].size(); ++i) {
    int u = adj[v][i];
    if (u != p) continue;
    ret = i;
    edges[v][i] = res;
    //cout << v << " " << edges[v][i] << endl;
  }
  return ret;
}
