        if (it == dad) continue;
        leaf = 0; dfs(it, node);
        cnt[node] += cnt[it];
    }

    if (leaf == 1) cnt[node] = a[node];
    else cnt[node] = a[node] * 2 - cnt[node];
}

bool dfs2(int node, int dad) {
    int sum = 0; bool leaf = 1;
    for (auto &it : g[node])
        if (it == dad) sum += cnt[node];
        else leaf = 0, sum += cnt[it];

    if (!leaf)
        for (auto &it : g[node])
            if (it == dad && cnt[node] * 2 > sum) return 0;
            else if (it != dad && cnt[it] * 2 > sum) return 0;

    for (auto &it : g[node]) {
        if (it == dad) continue;
        if (dfs2(it, node) == 0) return 0;
    }

    return 1;
}

