void solve(){
  ini(N);
  vl A(N); in(A);
  auto g = graph(N);


  vl L(N);

  auto dfs = [&](auto rec,int cur,int par = -1) -> void{
    // 根からのアレを集計する    
    int chd = 0;
    ll l = 0 ;
    each(dst , g[cur]){
      if(dst == par) continue;
      rec(rec , dst , cur);
      l += L[dst];
      chd++;
    }

    if(par == -1){
      int i = cur;
      trc(i , A[i] , l);
      if(l != A[i]) die("NO");
      L[i] = A[i];
      return;
    }

    if(chd == 0){
      L[cur] = A[cur];
      return;
    }

    // l 以上 r 以下だけ子からパスが来る
    // ceil(l , 2) <= A[i] <= r
    if(l > 2 * A[cur] || l < A[cur]) die("NO");
    L[cur] = 2 * A[cur] - l;
  };

  int start = 0;
  while(g[start].size() != 1) start++;
  dfs(dfs , start);
  trc(L);

  out("YES");

}

