long long dfs(int v, int p = -1) 
{
    if (a[v].size() == 1) 
    {
        return cnt[v];
    }
    long long mx = 0;
    long long sum = 0;
    for (int i=0;i<a[v].size();i++) 
    { 
        int x = a[v][i];
        if (x == p) continue; 
        long long mn = dfs(x, v); 
        mx = max(mx, mn); sum += mn; 
    }
    int num_sm = (sum - max(sum % 2, 2 * mx - sum)) / 2;
    if (sum - num_sm <= cnt[v] && sum >= cnt[v]) 
        return sum - 2 * (sum - cnt[v]); 
    else {
        puts("NO");
        exit(0);
    }
}

