ll dfs(ll p){
    if(used[p]) return 0;
    used[p] = true;
    if(g[p].size() == 1) return a[p];

    ll sum = 0, mx = -1;
    for(auto &x : g[p]){
        ll tmp = dfs(x);
        sum += tmp;
        mx = max(mx, tmp);
    }

    ll l = max(mx, sum / 2);
    if(l > a[p] || sum < a[p]){
        cout << "NO" << endl;
        exit(0);
    }

    ll t = 2 * a[p] - sum;
    if(t < 0){
        cout << "NO" << endl;
        exit(0);
    }

    return t;
}

