#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100005;
int A[MAXN];
long long int minval[MAXN], maxval[MAXN];
vector <int> G[MAXN];
bool dfs(int pos, int prev)
{
	bool is_leaf = true;
	long long int t1 = 0, t2 = 0, t3 = 0;
	for (int i = 0; i < G[pos].size(); ++i)
	{
		if(G[pos][i] != prev)
		{
			bool temp = dfs(G[pos][i],pos);
			if(!temp)
				return false;
			t1+=minval[G[pos][i]];
			t2+=maxval[G[pos][i]];
			t3 = max(t3, minval[G[pos][i]]);
			is_leaf = false;
		}
	}
	long long int temp = t1;
	if(is_leaf)
	{
		minval[pos] = maxval[pos] = A[pos];
		return true;
	}
	else
	{
		if(t1%2)
		{
			t1--;
			t3--;
			minval[pos]++;
		}
		minval[pos]+=max(2*t3 - t1,0ll);
		maxval[pos] = A[pos];
		if((temp - minval[pos])/2 + minval[pos] > A[pos])
			return false;
		if(t2 < A[pos])
			return false;
		return true;
	}
}
