bool ok=true;

void dfs(int v,int p){
    priority_queue<int> pq;
    for (auto nv:G[v]){
        if (nv==p) continue;
        dfs(nv,v);
        propagate[v]+=A[nv];
        pq.push(A[nv]);
    }
    ll s=pq.size(),sum=0;
    rep(i,s){
        int p=pq.top();
        pq.pop();
        if (i%2==1) sum+=p;
    }
    if (p!=-1){
        if (G[v].size()==2&&A[v]!=propagate[v]) ok=false;
        if (G[v].size()>2&&(propagate[v]<A[v]||sum<propagate[v]-A[v])) ok=false;
        if (G[v].size()>1) A[v]=2*A[v]-propagate[v];
