using namespace std;

vector<int> g[100010];
vector<long long> A;

bool res = true;

void fail() {
    cout << "NO" << endl;
    exit(0);
}

long long dfs(int root, int prev) {
    vector<long long> ws;
    for (auto e : g[root]) {
        if (e == prev) continue;
        ws.push_back(dfs(e, root));
    }

    if (ws.size() == 0) {
        return A[root];
    }


    long long max_consume = accumulate(ws.begin(), ws.end(), 0ll);
    long long min_consume = 0;

    sort(ws.begin(), ws.end());


    for(int i = 0 ; i+1 < ws.size() ; i++){
        min_consume += ws[i];
        ws[i+1] -= ws[i];

        if( i + 2 == ws.size() && ws[i+1] > 0) {
            long long decop = (min_consume - ws[i]);
            long long u = min(decop * 2, ws[i + 1]) / 2 * 2;
            min_consume += u / 2;
            ws[i + 1] -= u;
        }
    }
    long long remain = ws.back();




    //cout << prev << " -> " << root + 1 << ": " << min_consume << " " << max_consume << "|" << ws.size() << endl;
    if (A[root] > max_consume) fail();
    if (A[root] < remain + min_consume) fail();

    if( prev == -1) {
        if( min_consume != A[root] ) fail();
        if( remain != 0 ) fail();
    }

    //  cout << root + 1 << ": " << A[root] - min_consume << endl;
    return A[root] - min_consume;
}

void solve(long long N, vector<long long> A_, vector<long long> a, vector<long long> b) {
    A = A_;
    for (int i = 0; i < N - 1; i++) {
        g[a[i] - 1].push_back(b[i] - 1);
        g[b[i] - 1].push_back(a[i] - 1);
    }
    if (N == 2) {
        cout << (A[0] == A[1] ? "YES" : "NO") << endl;
        return;
    }
    for (int i = 0; i < N; i++) {
        if (g[i].size() >= 2) {
            dfs(i, -1);
            cout << "YES" << endl;
            return;
        }
    }
    assert(0);
}

