int main()
{
    RD(N);
    RDV(A + 1, A + N + 1);
    for(int i: RG(N - 1))
    {
        int u, v;
        RD(u, v);
        adj[u].push_back(v);
        adj[v].push_back(u);
        deg[u]++;
        deg[v]++;
    }

    if(N == 2)
    {
        WTL(A[1] == A[2]? "YES": "NO");
        return 0;
    }

    ll leaf = 0, inter = 0;
