        if(deg[i] == 1)
            leaf += A[i];
        else
            inter += A[i];

    if((leaf & 1) || inter * 2 != leaf)
        return WTL("NO"), 0;


    queue<int> que;
    for(int i: RG(1, N + 1))
        if(deg[i] == 1)
            que.push(i);

    for(int z = que.size(); z > 0; z--)
    {
        int i = que.front();
        que.pop();
        for(int to: adj[i])
        {
            B[to] += A[i];
            if(--deg[to] == 1)
                que.push(to);
        }
    }

    bool ans = true;

    while(que.size() > 1)
    {
        int u = que.front();
        que.pop();

        if(A[u] * 2 < B[u] || A[u] > B[u])
        {
            ans = false;
            break;
        }
        for(int to: adj[u])
        {
            B[to] += A[u] * 2 - B[u];
