  if (c[v].empty()){
    return;
  }
  long long sum = 0;
  vector<long long> a; 
  for (int w : c[v]){
    dfs(A, c, w, ok);
    sum += A[w];
    a.push_back(A[w]);
  }
  sort(a.begin(), a.end());
  long long tmp = A[v] * 2 - sum;
  long long pair_cnt = sum - A[v];
  if (sum - a.back() < pair_cnt){
    ok = false;
  }
  A[v] = tmp;
}
