long long solve(long long p) {
	if (OK == false)return 1LL << 62;
	long long y = 0; vector<long long>z; used[p] = true;
	for (long long i = 0; i < x[p].size(); i++) {
		if (used[x[p][i]] == false) {
			long long w = solve(x[p][i]); y += w; z.push_back(w);
		}
	}
	if (x[p].size() == 1)return c[p]; sort(z.begin(), z.end());
	long long L1 = 0, L2 = 0, L = 0;
	L1 = z[z.size() - 1];
	for (int i = 0; i < z.size() - 1; i++)L2 += z[i];
	L = min(y, L2 * 2); L /= 2;

	long long LB = y - L;
	long long RB = y;
	if (!(LB <= c[p] && c[p] <= RB)) { OK = false; return 1LL << 62; }
	long long H = y - (y - c[p]) * 2;
	return H;
