struct Edge {
	ll to, cap, rev;
	Edge(ll _to, ll _cap, ll _rev) {
	to = _to; cap = _cap; rev = _rev;
	}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve(){
	ll n;
	cin>>n;
	Array a(n);
	REP(i,n) cin>>a[i];

	Graph g(n);
	REP(i,n-1){
		ll a,b;
		cin>>a>>b;
		a--;b--;
		add_edge(g,a,b,1,true,1);
	}

	auto dfs=[&](auto &&self,int v, int p)->P{
		//cout<<v<<en;
		ll sum=0;
		if(p!=-1 && g[v].size()==1) return {true,a[v]};
		ll con=0;
		for(auto e:g[v]){
			if(e.to==p) continue;
			P ret = self(self, e.to, v);
			if(ret.first==false || ret.second>a[v]) return {false,0};
			sum += ret.second;
			con++;
		}
		ll z=a[v];
		ll x = sum-z;
		ll y = z-x;
		//cout<<v<<" "<<x<<" "<<y<<en;
		if(x<0 || y<0) return {false,0};
		if(con==1 && x>0) return {false,0};
		return {true, y};
	};
	P ans = dfs(dfs,0,-1);
	cout<<(ans.first?"YES":"NO")<<en;
}

