struct Node{
    vector<Node*> dests;
    ll a;
    void add(Node* n){
        dests.push_back(n);
    }
    void add2(Node* n){
        add(n);
        n->add(this);
    }
    pair<ll, ll> dfs(Node* from = nullptr){
        vector<pair<ll, ll>> vp;
        int cnt = 0;
        for(Node* d : dests){
            if(d == from){ continue; }
            cnt++;
            vp.push_back(d -> dfs(this));
        }
        if(!cnt){ return {a, a}; }
        ll mini = 0, maxi = 0, mami = 0;
        for(auto p : vp){
            mini += p.first;
            maxi += p.second;
            mami = max(mami, p.first);
        }
        if(a < mami){
            cout << "NO" << '\n';
            exit(0);
        }
        mini = (mini + 1) / 2;
        // maxi /= 2;
        // prints(a - maxi, a - mini);
        return {a - maxi / 2, min(maxi, a)};
    }
};

