const int N = 123456;

int n, root, degree[N];
long long s[N];
vector<int> adj[N];

int dfs(int x, int f) {
  bool go = false;
  vector<long long> values;
  for (auto y : adj[x]) {
    if (y != f) {
      go = true;
      values.push_back(dfs(y, x));
    }
  }
  if (!go) {
    return s[x];
  }
  long long sum = 0;
  for (auto v : values) {
    sum += v;
  }
  int i = 0, j = values.size() - 1;
  while (s[x] && sum > s[x]) {
    if (!values[i]) {
      ++i;
    }
    if (!values[j]) {
      --j;
    }
    if (i >= j) {
      cout << "NO" << '\n';
      exit(0);
    }
    long long diff = min(min(sum - s[x], s[x]), min(values[i], values[j]));
    values[i] -= diff;
    values[j] -= diff;
    sum -= diff << 1;
    s[x] -= diff;
  }
  if (x != root && sum != s[x]) {
    cout << "NO" << '\n';
    exit(0);
  } else if (x == root && (s[x] > 0 || sum > 0)) {
    cout << "NO" << '\n';
    exit(0);
  }
  return sum;
}

