    ++degree[x];
    ++degree[y];
  }
  for (int i = 1; i <= n; ++i) {
    if (degree[i] > 1) {
      root = i;
    }
  }
  dfs(root, 0);
  cout << "YES" << '\n';
  return 0;
}

