ll dfs(UnWeightedGraph& g, int v, int p = -1){
    if(p != -1 and g[v].size() == 1){
        return A[v];
    }
    ll sum = 0, M = 0;
    for(auto nv: g[v]){
        if(nv == p) continue;
        ll k = dfs(g, nv, v);
        if(k == -1) return -1;
        chmax(M, k);
        sum += k;
    }
    // cerr << v << " " << sum << endl;
    if(sum < A[v] or A[v] * 2LL < sum) return -1;
    ll cp = sum - A[v];
    if(p == -1){
        if(sum == A[v]) return 0;
        return -1;
    }
    if(cp < M - (A[v] * 2LL - sum)) return -1;
    return A[v] * 2LL - sum;
}

