long long violate(int id, int par){
    if(deg[id] == 1) return v[id];
    long long s = 0, l = 0;
    for(auto i : adj[id]){
        if(i == par) continue;
        t[i] = violate(i, id);
        if(t[i] == -1) return -1;
        s += t[i];
        l = max(l, t[i]);
    }
    long long meen;
    if(s < l*2) meen = l;
    else meen = s/2 + s%2;
    if(v[id] < meen || v[id] > s) return -1;
    return s - 2ll * (s - v[id]);
}

