            } else {
                if (g != 0) r = false;
                if (0 < m - (s - m)) r = false;
            }
            return 0;
        }
        if (g < 0 || g < m - (s - m)) r = false;
        return (int)g;
    };
    f(0, -1);
    return r;
}

