    if(n == 2 and A[0] != A[1]) {
        cout<<"NO";return 0;
    }

    int start = -1;
    rep(i, n) if(g[i].size() > 1) start = i;
    //debug(start);

    if(dfs(start, -1) != 0) possible = false;

    if(possible) cout<<"YES";
    else cout<<"NO";

    return 0;
}

