using namespace std;

typedef long long i64;

const int NMAX = 100005;

vector<int> G[NMAX];
int values[NMAX];
int64_t dpOut[NMAX];

void dfs(int node, int prev) {
    if (SZ(G[node]) == 1) {
        dpOut[node] = values[node];
    } else {
        int64_t sum = 0;
        int64_t vmax = 0;
        for (int to: G[node]) {
            if (to != prev) {
                dfs(to, node);
                sum += dpOut[to];
                vmax = max(vmax, dpOut[to]);
            }
        }
        if (sum < values[node]) {
            cout << "NO\n";
            exit(0);
        }
        int pr = 2 * (sum - values[node]);
        dpOut[node] = sum - pr;
        if (2 * (vmax - dpOut[node]) > pr) {
            cout << "NO\n";
            exit(0);
        }
    }
}

