constexpr int maxn = 1e5 + 100;

vector<int> vec[maxn] = {};
int n;   
ll stones[maxn] = {}, dyn[maxn] = {};
bool bad = false;

void dfs(const int cur){
    if(vec[cur].empty()){
        dyn[cur] = stones[cur];
        return; }
    for(const auto next : vec[cur]){
        vec[next].erase(find(begin(vec[next]), end(vec[next]), cur));
        dfs(next); }
    vector<ll> v(vec[cur].size());
    transform(begin(vec[cur]), end(vec[cur]),
        begin(v), [](const int x){ return dyn[x]; });

    nth_element(begin(v), end(v)-1, end(v));
    const ll all_except_big = accumulate(begin(v), end(v)-1, 0ll),
        full_sum = all_except_big + v.back();
    const ll linked = full_sum - stones[cur];
    if(linked < 0) bad = true;
    else if(full_sum - 2*linked < 0) bad = true;
    else if(all_except_big >= v.back() && linked > full_sum) bad = true;
    else if(all_except_big  < v.back() && linked > all_except_big) bad = true;
    else dyn[cur] = full_sum-2*linked; }

