    cin >> n;
    copy_n(istream_iterator<ll>(cin), n, stones);
    for(int i = 0, x, y; i < n-1; ++i){
        cin >> x >> y;
        --x, --y;
        vec[x].push_back(y);
        vec[y].push_back(x); }
    if(n == 2){
        cout << (stones[0] == stones[2] ? "YES" : "NO") << endl;
        return 0; }
    int rad = 0;
    while(vec[rad].size() == 1) ++rad;
    dfs(rad);
    cout << (!bad && dyn[rad] == 0 ? "YES" : "NO") << endl;
