struct Edge {
  int to,last;
  Edge () {}
  Edge (int a,int b) :to(a),last(b) {}
}edge[N<<1];
void ADD(int a,int b) {
  edge[++p]=Edge(b,head[a]); head[a]=p;
  edge[++p]=Edge(a,head[b]); head[b]=p;
}
void DFS(int u,int f) {
  if(In[u]==1) {
    F[u]=A[u];
    return;
  }
  int cnt=0,g=0;
  for(int i=head[u];i;i=edge[i].last) {
    int v=edge[i].to;
    if(v!=f) {
      ++g;
      DFS(v,u);
      sum[u]+=F[v];
      if(F[v]==-1) ++cnt;
    }
  }
  if(cnt==2) puts("NO"),exit(0);
  if(cnt==1||sum[u]<A[u]) F[u]=-1;
  else {
    if(g==1) {
      YES[u]=true;
      if(sum[u]!=A[u]) F[u]=-1;
      else F[u]=A[u];
    }
    else F[u]=A[u]-(sum[u]-A[u]);
  }
}
void SFD(int u,int f) {
  if(In[u]==1) return;
  if(F[u]==-1) {
    for(int i=head[u];i;i=edge[i].last) {
      int v=edge[i].to;
      if(v!=f&&F[v]==-1) {
        if(YES[u]) {
          if(G[f]==A[u]) G[u]=A[u],SFD(v,u);
        }
        else if(G[f]+sum[u]-F[v]>A[u]) G[u]=A[u]-(G[f]+sum[u]-F[v]-A[u]),SFD(v,u);
      }
    }
  }
  else {
    if((sum[u]+G[f])==A[u]*2ll) puts("YES"),exit(0);
    for(int i=head[u];i;i=edge[i].last) {
      int v=edge[i].to;
      if(v!=f) {
        if(YES[u]) {
          if(G[f]==A[u]) G[u]=A[u],SFD(v,u);
        }
        else if(G[f]+sum[u]-F[v]>A[u]) G[u]=A[u]-(G[f]+sum[u]-F[v]-A[u]),SFD(v,u);
      }
    }
  }
}
