    if (v!=0 && adj[v].size()==1){
        dp[v] = A[v];
        return;
    }
    ll sum=0,cnt=0;
    for(auto u:adj[v]){
        if (u==p) continue;
        dfs(u,v);
        sum+=dp[u];
        if (dp[u]>0) cnt++;
    }
