bool dfs(int u, int p) {
	if (g[u].size() == 1) {
		if (a[u] > 0) b[p].push_back(a[u]);
		return true;
	}
	for (int v : g[u]) if (v != p) {
		if (!dfs(v, u)) return false;
	}
	long long sum = accumulate(b[u].begin(), b[u].end(), 0LL);
	long long x = 2 * a[u] - sum;
	if (x < 0) return false;
	sum += x;
	if (x > 0) {
		if (p == -1) return false;
		b[u].push_back(x);
		b[p].push_back(x);
	}
	long long mx = *max_element(b[u].begin(), b[u].end());
	return 2 * mx <= sum;
}

