ll dfs(const vector<vecint>& g, vecint& a, int i, int p=-1) {
  int ch = 0;
  ll csum = 0;
  for(auto&& to:g[i]) {
    if (to == p) continue;
    ++ch;
    ll child = dfs(g, a, to, i);
    if (child < 0) return -1;
    csum += child;
  }
  if (g[i].size() == 1) return max(-1l, a[i] - csum);
  return max(-1l, 2*a[i] - csum);
}

