int n,a[N],u[N];
vector<int> adj[N];
int dfs(int p = 1,int fa = 0)
{
    int tot = 0;
    for (int i = 0;i < adj[p].size();i++)
    {
        int x = adj[p][i];
        if (x == fa) continue;
        if (!dfs(x,p)) return 0;
        tot += u[x];
    }
    if (p != 1)
    {
        if (adj[p].size() == 1)
        {
            u[p] = a[p];
            return 1;
        } else {
            u[p] = 2*a[p]-tot;
            if (u[p] < 0) return 0;
            else return 1;
        }
    } else {
        if (adj[p].size() == 1)
        {
            if (tot != a[p]) return 0;
            return 1;
        } else {
            if (tot != a[p]*2) return 0;
            return 1;
        }
    }
}
