int N;
int a[112345];
vector<int> g[112345];
vector<pll> buf[112345];

int main() {
	cin >> N;
	REP(i, N) scanf("%d", a + i);
	REP(i, N - 1) {
		int a, b;
		scanf("%d %d", &a, &b);
		a--; b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}


	queue<pii> que; // 現在の頂点, どの頂点からきたか
	REP(i, N) if (g[i].size() == 1) {
		que.push(pii(i, -1));
		buf[i].push_back(pll(a[i], -1));
	}

	bool ans = true;

	while (!que.empty()) {
		pii now = que.front(); que.pop();

		int u = now.fi, bef = now.se;
		ll sum = 0, cnt = 0;
		REP(i, buf[u].size()) {
			sum += buf[u][i].fi;
			if (buf[u][i].se != -1) cnt++;
		}

		if (cnt + 1 == g[u].size()) {
			ll to = 2 * a[u] - sum;
			if (to < 0) ans = false;

			set<int> ss;
			REP(i, buf[u].size()) ss.insert(buf[u][i].se);
			REP(i, g[u].size()) {
				int v = g[u][i];
				if (v == bef || ss.find(v) != ss.end()) continue;

				que.push(pii(v, u));
				buf[v].push_back(pll(to, u));
			}
		}
		else if (cnt == g[u].size()) {
			if (sum != 2 * a[u]) ans = false;
		}
	}

	puts(ans ? "YES" : "NO");

	return 0;
}

