bool visited[100010] = {};

vector<int> graph[100010];

long long dfs(int idx){
    visited[idx] = true;

    priority_queue<long long> que;

    long long line = 0;
    for(int i = 0;i < graph[idx].size();i++){
        if(!visited[graph[idx][i]]){
            long long tmp = dfs(graph[idx][i]);
            que.push(tmp);
            line += tmp;
        }
    }

    if(que.empty()){
        return a[idx];
    }

    long long ok = line - a[idx];

    if(ok < 0){
        cout << "NO" << endl;
        exit(0);
    }

    long long cnt = 0;
    while(que.size() > 1){
        long long tmp = que.top();
        que.pop();
        long long tmp2 = que.top();
        cnt += que.top();
        que.pop();
        if(tmp-tmp2 > 0){
            que.push(tmp-tmp2);
        }
    }

    if(ok <= cnt){
        if(a[idx] -ok >= 0){
            return a[idx]-ok;
        }else{
            cout << "NO" << endl;
            exit(0);
        }
    }else{
        cout << "NO" << endl;
        exit(0);
    }
}

