bool dfs(const auto &graph,int v,int p){
	bool leaf=true;
	bool ret=true;

	childsum[v]=0LL;

	for(auto &e:graph[v]){
		if(e.to==p) continue;
 		ret&=dfs(graph,e.to,v);
		childsum[v]+=childup[e.to];
		leaf=false;
	}

	if(leaf){
		childup[v]=num[v];
		return true;
	} 


	childin[v]=childsum[v]-num[v];
	childup[v]=num[v]-childin[v];
	if(childin[v]<0 or childup[v] <0) ret&=false;
	//error(v,num[v],childsum[v],childin[v],childup[v]);
	return ret;
}


