#define pb push_back
int N;
VV g(112345),tree(112345),cost(112345);
LL A[112345];
bool res=true;
int make_tree(int v,int p){
    LL rest=A[v];
    if(g[v].size()!=1)rest+=A[v];
    for(auto &u:g[v])
        if(u!=p){
            tree[v].pb(u);
            LL k=make_tree(u,v);
            cost[v].pb(k);
            rest-=k;
            if(A[v]<k)res=false;
        }
    if(rest<0||rest>A[v])res=false;//cout<<v<<" "<<rest<<endl;
    return rest;
}

