long long d[MAXN],rd[MAXN];
vector<int>w[MAXN];
long long key=0;
void dfs(long long u,long long f)
{
	long long cnt=0,MX=0,e=0;
	for(long long i=0;i<int(w[u].size());i++)
	{
		long long v=w[u][i];
		if(v!=f)
		{
			e=1;
			dfs(v,u);
			cnt+=d[v];
			MX=max(MX,d[v]);
		}
	}
	if(!e)
		return ;
	if(key)
		return ;
	if(d[u]>cnt)
	{
		key=1;
		return ;
	}
	long long o=cnt-d[u];
	long long yb=min(cnt/2,cnt-MX);
	if(yb<o)
	{
		key=1;
		return ;
	}
	d[u]=cnt-2*o;
	if(d[u]<0)
	{
		key=1;
		return ;
	}
}
