void build(int v, int p=-1) {
    for(int u : next[v]) {
        if(u == p) continue;
        parent[u] = v;
        child[v].push_back(u);
        build(u, v);
    }
}

LL inner[MAX_N];
LL last_C3;
bool dfs(int u) {
    for(int v : child[u]) {
        bool b = dfs(v);
        if(!b) {
            return false;
        }
    }


    const LL a = A[u];

    LL s = 0;
    for(int v : child[u]){
        s += A[v];
    }

    LL C1 = 0;
    for(int v : child[u]) {
        C1 += inner[v];
    }

    if(child[u].size() == 0) {
        inner[u] = 0;
        return true;
    }

    // C2 + C3 = a
    // 2 * C2 + C3 = (s-2*C1)
    // C2 = (s-2*C1) - a
