const int N = 100000 + 10;
int a[N];

vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

map<lli, lli> memo;
lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];
  if (memo.count(curr)) return memo[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (curr == prev) { // root
    if (sum % 2) throw "";
    if (a[curr] - sum / 2) throw "";
    return 0;
  }

  lli mx = *max_element(b.begin(), b.end());
  lli mn = min(sum / 2, mx);
  lli x = a[curr] - mn;
  if (x < 0 || sum - mn * 2 == x) throw "";
  return memo[curr] = x;
}

