LL solve(int pos, int pre = -1)
{
  vector<LL> list;
  LL Sum = 0;
  bool update_flag = false;
  for (int i = 0; i < Edge[pos].size(); i++) {
    if(Edge[pos][i] == pre){
      continue;
    }
    update_flag = true;
    LL tmp = solve(Edge[pos][i], pos);
    if(tmp == -1){
      return -1;
    }
    list.push_back(tmp);
    Sum += tmp;
  }

  if(!update_flag){
    return A[pos];
  }

  if(Sum < A[pos]){
    return -1;
  }

  sort(list.begin(), list.end());

  LL pair_cnt = 0;
  LL geta = 0;
  LL amari = 0;
  for (int i = 0; i < list.size()-1; i++) {
    LL tmp = list[i] - geta;
    amari += tmp%2;
    pair_cnt += tmp/2 * (list.size() - i);
    geta += (tmp/2)*2;
  }

  LL tmp = list[list.size()-1] - geta;
  if(tmp >= amari){
    pair_cnt += amari;
  }
  else{
    pair_cnt += tmp;
    amari -= tmp;
    pair_cnt += amari/2;
  }

  if(Sum - pair_cnt > A[pos]){
    return -1;
  }

  pair_cnt = Sum - A[pos];

  //cerr << pos << " " << Sum - 2*pair_cnt << endl;
  return Sum - 2*pair_cnt;
}

