bool cansolve(int node)
{
	if(graph[node].size() == 1) return true;
	ischecked[node] = true;
	long long int sum = 0;
	vector<int> v;
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		if(cansolve(child)) {
			sum += stonenum[child];
			v.push_back(stonenum[child]);
		} else {
			return false;
		}
	}
	int pairnum = 0;
	while(v.size() > 1){
		sort(v.begin(), v.end());
		int s = v.size();
		if(v[0] == v[s - 1]){
			pairnum += s / 2;
			break;
		}
		pairnum += v[s - 2];
		v[s - 1] -= v[s - 2];
		v.erase(v.begin() + s - 2);
	}
	if(stonenum[node] > sum) {
		return false;
	} else if(stonenum[node] == sum) {
		return true;
	} else if(sum - stonenum[node] <= pairnum){
		stonenum[node] -= sum - stonenum[node];
		return true;
	}
	return false;
}

