int dfs(int v)
{
	mark[v] = true;

	if( a[v].size() == 1 && mark[a[v][0]] ) return s[v];

	if( a[v].size() == 1 )
	{
		int ans = s[v] - dfs( a[v][0] );
		if ( ans < 0 ) 
			return -1;
		else
			return ans; 
	}

	int sum = 0;
	for(int i=0; i < a[v].size() ; i++)
		if( !mark[a[v][i]] )
		{
			int tmp = dfs(a[v][i]);

			s[a[v][i]] = tmp;

			if ( tmp != -1)
