int64 dfs(int32 v, int32 p){
	if(~dp[v]) return dp[v];
	if(G[v].size() == (p != -1)) return dp[v] = A[v];
	dp[v] = 0;
	int64 rest= A[v];
	vector<int64> c;
	int64 sum = 0;
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		c.push_back(dfs(G[v][i], v));
		sum += c[c.size()-1];
