bool dfs(const vvi& g,const vl& a,int p,int u,vl& xs)
{
	int m=0;
	for(int v:g[u]) if(v!=p) m++;
	if(m==0){
		xs[u]=a[u];
		return true;
	}
	ll sum=0,mx=0;
	for(int v:g[u]) if(v!=p){
		if(!dfs(g,a,u,v,xs))
			return false;
		sum+=xs[v];
		mx=max(mx,xs[v]);
	}
	xs[u]=2*a[u]-sum;
	if(xs[u]<0||sum-xs[u]<0||(sum-xs[u])/2>sum-mx)
		return false;
	if(u==0){	// root
		if(m==1&&xs[u]!=sum)
			return false;
		if(m>1&&xs[u]>0)
			return false;
	}
	return true;
}

