using namespace std;

ll a[100000];
vector<int> g[100000];

ll dfs(int pos, int prev = -1){
  if(g[pos].size() == 1){
    return a[pos];
  }else{
    vector<ll> v;

    REP(i,g[pos].size()){
      if(g[pos][i] == prev) continue;
      const ll t = dfs(g[pos][i], pos);
      if(t == -1) return -1;
      v.push_back(t);
    }

    const ll tot = accumulate(v.begin(), v.end(), 0ll);

    if(v.size() == 1) {
      if(v[0] != a[pos]) return -1;
      return a[pos];
    } else {
      // q = match; p = pass through
      // p + q = a
      // p + 2 * q = tot
      // -q = a - tot
      // q = tot - a
      // p = 2 * a - tot

      const ll p = 2 * a[pos] - tot;
      const ll q = tot - a[pos];

      if(p < 0 || q < 0) return -1;

      const ll mx = *max_element(v.begin(), v.end());
      // if((tot - p) / 2 < mx) return -1;
      if((tot - mx) < q) return -1;

      return p;
    }
  }
}

