  for(int i=0;i<N;i++){
    cin>>a[i];
  }
  for(int i=0;i<N-1;i++){
    int from,to;
    cin>>from>>to;
    from--,to--;
    g[from].push_back(to);
    g[to].push_back(from);
  }
  cout<< (solve()?"YES":"NO") <<endl;
  return 0;
}

