		cin>>u>>v;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	root=1;
	for(int i=1;i<=n;i++){
		if(adj[i].size() > adj[root].size()){
			root=i;
		}
	}
	if(adj[root].size()==1){
		if(a[1]==a[2]){
			cout<<"YES";
		}else{
			cout<<"NO";
		}
	}else{
		if(dfs(root)==1){
			cout<<"YES";
		}else{
			cout<<"NO";
		}
	}
}

