const int NICO = 1000000 + 10;
typedef long long LL;
int a[NICO], b[NICO], deg[NICO], root;
int n, vis[NICO], ok = 1;
LL val[NICO];
vector<int> vec[NICO];
void dfs(int x)
{
    vis[x] = 1; LL sum = 0;
    if(deg[x] == 1) return;
    for(int i=0;i<vec[x].size();i++)
    {
        int cur = vec[x][i];
        if(vis[cur]) continue;
        dfs(cur);
        sum += val[cur];
    }
    LL tmp = 2 * val[x] - sum;
    if(x == root)
    {
        if(tmp != 0) ok = 0;
    } else
    if(vec[x].size() == 2)
    {
        if(sum != val[x]) ok = 0;
    } else
    if(tmp > val[x] || tmp < 0)
    {
        ok = 0;
    }
    val[x] = tmp;
    return;
}
