bool flag = true;

void dfs(int v, int p)
{
	ll sum = 0;
	bool find = false;
	for (auto u : adj[v])
	{
		if (u == p)
			continue;
		dfs(u, v);
		find = true;
		sum += a[u];
	}
	if (find)
	{
		if (sum < a[v])
			flag = false;
		a[v] = 2 * a[v] - sum;
	}
	//cout << v << " ~ " <<  a[v] << "\n";
}

