class Graph{
	private:
	int V;
	vvi List;
	public:
	Graph(int v){
		V=v;
		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
	string solve(){
		vb used(V,0);
		queue<int> q;
		for(int i=0;i<V;i++) if(List[i].size()==1){
			q.push(i);
			used[i]=1;
		}
		while(!q.empty()){
			int v=q.front();
			q.pop();
			for(int i=0;i<List[v].size();i++){
				int u=List[v][i];
				if(!used[u]){
					used[u]=1;
					ll sum=0,M=0;
					for(int j=0;j<List[u].size();j++){
						int w=List[u][j];
						if(used[w]){
							sum+=a[w];
							M=max(M,(ll)a[w]);
							a[w]=0;
						}
					}
					ll num=2*M>sum?sum-M:sum/2,x=sum-a[u];
					if(0>x||x>num||x>a[u]) return "NO";
					a[u]-=x;
					q.push(u);
				}
			}
		}
		vi b;
		for(int i=0;i<V;i++) if(a[i]) b.push_back(a[i]);
		if((b.size()==2&&b[0]==b[1])||b.empty()) return "YES";
		return "NO";
	}
};

