int dfs(int node)
{
    used[node] = 1;
    if(v[node].size()==1) return A[node];

    int edge = A[node] << 1, nr;

    for(auto it : v[node])
        if(!used[it])
        {
            nr = dfs(it);
            edge -= nr;
            if(nr>A[node] || nr==-1) return -1;
        }

    if(edge < -1) edge = -1;
    return edge;
}

