void addArc(Graph &g, int s, int d, Weight w = 1) {
    g[s].emplace_back(s, d, w);
}
void addEdge(Graph &g, int a, int b, Weight w = 1) {
    addArc(g, a, b, w);
    addArc(g, b, a, w);
}

int getMin(vi &data)
{
    if (data.size() == 0) return 0;
    if (data.size() == 1) return data.back();
    int yui = 0;
    rep(i, data.size()) yui += data[i];
    return max(data.back() + data.back() - yui, 0LL);
}

int dfs(Graph &g, vi &data, int pos, int bef)
{
    if (g[pos].size() == 1) {
        return data[pos];
    }
    int yui = 0;
    vi cnt;
    for (auto i : g[pos]) {
        if (i.d != bef) {
            cnt.pb(dfs(g, data, i.d, pos));
            yui += cnt.back();
        }
    }
    sort(all(cnt));
    /*
    cout << pos << " : ";
    rep(i, cnt.size()) cout << cnt[i] << " "; cout << endl;
    */
    int kyoko = getMin(cnt);
    if (kyoko <= data[pos] && data[pos] <= yui) {
        return data[pos] - (yui - data[pos]);
    } else {
        return INF;
    }
}

bool solve(Graph &g, vi &data, int pos)
{
    vi cnt;
    for (auto i : g[pos]) {
        cnt.pb(dfs(g, data, i.d, pos));
    }
    int yui = 0;
    rep(i, cnt.size()) yui += cnt[i];
    sort(all(cnt));
    //rep(i, cnt.size()) cout << cnt[i] << " "; cout << endl;
    return (data[pos] + data[pos] == yui && yui % 2 == 0);
}

