ll f(ll x, ll p) {
	ll ans;
	if (g[x].size()==1) ans=a[x];
	else {
		ll sum=0,hi=0;
		for (auto &y:g[x]) {
			if (y==p) continue;
			ll got=f(y,x);
			sum+=got;
			chkmax(hi,got);
