void E_add(int x,int y) {
	d[x]++;d[y]++;
	E[++En].s=y;E[En].n=h[x];h[x]=En;
	E[++En].s=x;E[En].n=h[y];h[y]=En;
}
void dfs(int x,int F) {
	ll sum=0,ma=0;
	int fg=0;
	for (int k=h[x];k;k=E[k].n) if (E[k].s!=F) {
		fg=1;
		dfs(E[k].s,x);
		if (Fg) return;
		sum+=f[E[k].s];
		ma=max(ma,f[E[k].s]);
	}
	if (!fg) f[x]=A[x];
	else {
		f[x]=2*A[x]-sum;
		if (f[x]<0) { Fg=1;return;}
		if (ma*2-sum>f[x] || f[x]>sum) { Fg=1;return;}
	}
}
