vector<ll> A; 
ll dfs(UnWeightedGraph& g, int v, int p = -1){
    if(p != -1 and g[v].size() == 1){
        return A[v];
    }
    ll sum = 0;
    for(auto nv: g[v]){
        if(nv == p) continue;
        ll k = dfs(g, nv, v);
        if(k == -1) return -1;
        sum += k;
    }
    // cerr << v << " " << sum << endl;
    if(sum < A[v] or A[v] * 2LL < sum) return -1;
    if(p == -1){
        if(sum == A[v]) return 0;
        return -1;
    }
    return A[v] * 2LL - sum;
}

