ll dfs(int v, const vector<vi> &tree, const vi& a)
{
	if (tree[v].size() == 0) return a[v];
	ll cnt = 0;
	ll mx = 0;
	for (auto u : tree[v])
	{
		ll tmp = dfs(u, tree, a);
		if (tmp == -1) return -1;
		cnt += tmp;
		chmax(mx, tmp);
	}
	if (a[v] > cnt || a[v] * 2 < cnt || mx > a[v]) return -1;
	int res = a[v] - (cnt - a[v]);
	return res;
}

int get_size(int v, const vector<vi>& tree, vi& size)
{
	int cnt = 1;
	for (auto u : tree[v])
	{
		cnt += get_size(u, tree, size);
	}
	return size[v] = cnt;
}

