bool is_leaf(int n)
{
  return g[n].size() == 1;
}

lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  lli mx = *max_element(b.begin(), b.end());
  lli n = sum - a[curr];
  if (n > sum - mx) throw "";
  if (sum < a[curr]) throw "";

  lli passed = a[curr] * 2 - sum;
  if (passed < 0 || (curr == prev && passed)) throw "";
  return passed;
}

