}
bool dp(int u,int fa) {
	bool res=true;
	if (deg[u]<=1) {f[u]=a[u];return 1;}
	LL sum=0,mx=0;
	for (int v,j=ehead[u];j;j=edg[j].next)
	if ((v=edg[j].v)!=fa) {
		res&=dp(v,u);sum+=f[v];mx=max(mx,f[v]);
	}
	LL t=sum-a[u];f[u]=sum-2*t;
	res&=(f[u]>=0&&t>=0&&sum-mx>=t);
	return res;
}
