vector<ll> C[100005];
ll A[100005];
ll root;
void dfs(ll id, ll pr){
  for( ll to : G[id] ){
    if( to == pr ) continue;
    C[id].push_back( to );
    dfs( to, id );
  }
}

bool valid(){
  queue<ll> q;
  vector<ll> r;
  q.push( root );
  while( !q.empty() ){
    ll p = q.front(); q.pop();
    r.push_back( p );
    for(ll to : C[p] ) 
      q.push( to );
  }

  reverse( r.begin(), r.end() );

  for( ll id : r ){
    if( C[id].empty() ) continue;
    ll sum = 0;
    ll maxi = 0;
    for(ll to : C[id] ){
      sum += A[to];
      maxi = max( maxi, A[to] );
    }
    ll k = sum - A[id];
    if( k < 0 ) return false;
    if( sum-maxi < k ) return false;
    A[id] = sum - 2LL * k;
    if( A[id] < 0 ) return false;
  }
  return A[root] == 0LL;
}

