    G[b].push_back( a );
  }
  for(ll i=0;i<N;i++)
    if( G[i].size() > 1 ){
      dfs( root = i, i ); break;
    }



  if( valid() ) cout << "YES" << endl;
  else cout << "NO" << endl;
}

