bool pairnum(vector<int>V, int N) {
	sort(V.begin(), V.end());
	int s = 0;
	rep(i, V.size() - 1) {
		s += V[i];
	}
	int r = V[V.size() - 1];
	if (r > s)r = s;
	return (r + s) / 2 >= N;
}

int dfs(int now, int par) {//下から何本のパスを上に引き上げられるか
	if (dp[now] != -inf)return dp[now];
	vector<int>V; int S = 0;
	for (int e : G[now]) {
		if (e==par)continue;
		V.push_back(dfs(e, now));
		S += dp[e];
	}
	if (V.empty()) {
		return dp[now] = a[now];
	}

	int P = S - a[now], Q = a[now] - P;
	if (P < 0 || Q < 0)ng++;
	if (!pairnum(V,P))ng++;
	return dp[now] = Q;
}
