LL dfs(int v, int p) {
  int num_ch = 0;
  LL s = 0;
  LL maxa = 0;
  for (int u : es[v]) {
    if (p == u) continue;
    LL a = dfs(u, v);
    s += a;
    maxa = max(maxa, a);
    num_ch++;
  }

  if (num_ch == 0) return A[v];
  LL ret = A[v]*2 - s;
  if (0 <= (s-ret)/2 && (s-ret)/2 <= min(s-maxa, s/2)) return ret;
  puts("NO");
  exit(0);
}

