		V[T].push_back(S);
	}
	for (int i = 0; i < N; i++) {
		if (V[i].size() == 1) {
			cout << (DFS(V[i][0], i) == A[i] && A[i] <= A[V[i][0]] ? "YES" : "NO") << endl;
