bool solve() {
  int n = read<int>();
  vector<int> A(n);
  rep(i, n) A[i] = read<int>();
  vvi E(n);
  rep(i, n-1) {
    int u = read<int>() - 1;
    int v = read<int>() - 1;
    E[u].push_back(v);
    E[v].push_back(u);
  }

  bool ans = true;
  vi C(n);
  {
    function<void(int, int)> dfs = [&](int cur, int pre) {
      int sum_c = 0;
      int c_max = 0;

      forr(nex, E[cur]) {
        if (nex != pre) {
          dfs(nex, cur);
          sum_c += C[nex];
          c_max = max(c_max, C[nex]);
        }
      }

      if (sz(E[cur]) == 1) {
        C[cur] = A[cur];
      }
      else {
        C[cur] = 2 * A[cur] - sum_c;
        if ((sum_c - C[cur]) % 2) ans = false;
        ll l = (sum_c - C[cur]) / 2;
        if (l < 0) ans = false;
        //out(c_max, sum_c, c_max-C[cur]>sum_c/2);
        if (c_max-C[cur] > sum_c / 2) ans = false;
      }
    };
    dfs(0, -1);
  }

  return ans;
}

void Main() {
  cout << (solve() ? "YES" : "NO") << endl;
}
