typedef long long ll;

const int N_MAX = 100002;

int n;

ll a[N_MAX];

vector <int> edges[N_MAX];

int root;

bool ok = true;

ll dfs (int u, int parent = -1)
{
    if(edges[u].size() == 1)
        return a[u];
    ll sum = 0;
    ll unpaired = 0;
    for(int v : edges[u])
        if(v != parent)
        {
            ll up = dfs(v, u);
            sum += up;
            unpaired = abs(unpaired - up);
        }
    ll maxPairs = (sum - unpaired) / 2;
    if(sum - a[u] < 0)
        ok = false;
    if(sum - a[u] > maxPairs)
        ok = false;
    return a[u] * 2 - sum;
}

