void dfs(int p,int fa){
	long long Maxn=0,Sum=0;
	for(int ne=head[p];ne;ne=e[ne].Next){
		if(e[ne].v==fa) continue;
		dfs(e[ne].v,p);
		Sum+=a[e[ne].v];
		Maxn=max(Maxn,a[e[ne].v]);
	}
