long long requirePairNumber(vector<long long> v){
	sort(all(v), greater<long long>());

	long long sum = 0;
	sum += v[1];
	v[0] -= v[1];

	long long remainder = 0;
	range(i,2,v.size()){
		sum += v[i] / 2;
		if(v[i] % 2){
			if(v[0] > 0){
				v[0]--;
				sum++;
			}else{
				remainder++;
			}
		}
	}

	sum += remainder / 2;
	return sum;
}

long long dfs(int cur){
	used[cur] = true;

	vector<long long> v;
	for(auto to : g[cur]){
		if(used[to]) continue;
		v.emplace_back(dfs(to));
