		long long childSum = accumulate(all(v), 0);
		if(childSum < a[cur]){ //どのようにしても石が取りきれない
			ans = false;
			return 0;
		}

		long long maximumPair = 0;
		sort(all(v), greater<long long>());
		maximumPair = min(v[0], childSum / 2);
