		show(maximumPair)
		if(loot == cur and maximumPair != a[cur]){
			ans = false;
			return 0;
		}

		long long needPair = childSum - a[cur];
		if(maximumPair >= needPair){
			return a[cur] - needPair;
		}else{
			ans = false;
		}

		return 0;
	}
}

