const int MAXN = 100100;
vi adj[MAXN];
ll arr[MAXN];
int n;

ll dp(int u, int p){
    if ((int)adj[u].size() == 1){
        return arr[u];
    }
    ll pos = 0, mpos = 0;
    for (int v : adj[u]){
        if (v == p) continue;
        ll c = dp(v, u);
        if (c == LLONG_MIN) return LLONG_MIN;
        if (c) {
            pos += c;
            mpos = max(mpos, c);
        }
    }
    // cerr << u << ' ' << pos << ' ' << mpos << endl;
    if (arr[u] > pos || arr[u] * 2LL < pos) {
        // cerr << "FAILED1: " << u << endl;
        // cerr << arr[u] << ' ' << pos << endl;
        return LLONG_MIN;
    }
    ll j = pos - arr[u];
    // check if can join
    if (pos - mpos < j) {
        // cerr << "FAILED2: " << u << endl;
        // cerr << pos << ' ' << mpos << ' ' << j << endl;
        return LLONG_MIN;
    }

    return arr[u] - j;
}

