const int maxn=100010;
typedef long long LL;
int n;
LL x[maxn];
int in[maxn],fir[maxn],nxt[maxn<<1],v[maxn<<1],cnt;
inline void addedge(int a,int b) {
	nxt[++cnt]=fir[a],v[cnt]=b,fir[a]=cnt;
}
int dfs(int rt,int f) {
	LL sum=0,rem=0,mx=0;
	int sons=0;
	for(int u=fir[rt];u;u=nxt[u]) {
		if(v[u]==f) continue;
		++sons;
		LL tmp=dfs(v[u],rt);
		mx+=min(rem+mx,tmp);
		rem=max(rem+mx,tmp)-min(rem+mx,tmp);
		sum+=tmp;
	}
	if(sons==0) return x[rt];
	if(sum<x[rt]||mx<sum-x[rt]) {
		puts("NO");
		exit(0);
	}
	return x[rt]-(sum-x[rt]);
}
