#include<bits/stdc++.h>
using namespace std;
#define int long long

void Make(int cur, vector<vector<int> > &adj, vector<vector<int> > &G, vector<bool> &used){

    used[cur] = true;
    for(auto nxt : adj[cur]){
        if(used[nxt]) continue;
        G[cur].push_back(nxt);
        Make(nxt, adj, G, used);
    }
}

int dfs(int cur, vector<vector<int> > &G, vector<int> &A){

    if(G[cur].size() == 0){
        cerr << cur << " " << A[cur] << endl;
        return A[cur];
    }

    int sum = 0;

    vector<int> vec;    
    for(auto nxt : G[cur]){
        int val = dfs(nxt, G, A);
        if(val < 0){
            cerr << cur << " " << -1 << endl;
            return -1;
        }
        vec.push_back(val);
        sum += val;
    }

    int ret = 2 * A[cur] - sum;
    //cout << cur << " " << sum << " " << A[cur] << " " << ret << endl;
    if(ret < 0){
        cerr << cur << " " << -1 << endl;
        return -1;
    }

    vec.push_back(ret);

    int n = (int)vec.size();
    sum += ret;
    assert(sum % 2 == 0);

    bool ok = true;
    for(int i = 0; i < n; i++){
        if(vec[i] > sum / 2){
            cerr << cur << " " << -1 << endl;            
            return -1;
        }
    }

    cerr << cur << " " << ret << endl;
    return ret;
}

