	{
		cin >> a[i];
	}

	for(int i = 0;i < n - 1;i++)
	{
		int s,t;

		cin >> s >> t;

		edges[s].push_back(t);
		edges[t].push_back(s);
	}
}

vector<int> leave;

void get_leave()
{
	for(int i = 1;i <= n;i++)
	{
		if(edges[i].size() == 1)
		{
			leave.push_back(i);
		}
	}
}

vector<int> topolo[100010];

vector<int> deeper;

void get_topolo()
{
	vector<bool> vec(n + 1,false);
	queue<int> que;

	for(int l : leave)
	{
		que.push(l);
	}

	while(!que.empty())
	{
		int v = que.front();
		que.pop();

		if(vec[v]) continue;
		vec[v] = true;
		deeper.push_back(v);

		for(int to : edges[v])
		{
			if(vec[to] == false)
			{
				topolo[to].push_back(v);
				que.push(to);
			}
		}
	}
}

bool solve()
{
	for(int v : deeper)
	{
		//////cout << v << ":";
		//leaf
		if(topolo[v].size() == 0)
		{
		}
		else if(topolo[v].size() == 1)
		{
			int chi = topolo[v][0];
			if(a[chi] != a[v])
			{
				//cout << a[v] << "=" << a[chi] << endl;
				return false;
			}
		}
		else
		{
			//can solve self
			i64 sum = 0;

			for(int chi : topolo[v])
			{
				sum += a[chi];
			}

			//cout << endl << "sum" << sum << endl;

			i64 x = 2 * a[v] - sum;

			if(x < 0 || a[v] < x) return false;

			a[v] = x;

			if(deeper[deeper.size() - 1] == v)
			{
				if(x != 0)
				{
					return false;
				}
			}
		}
		//cout << a[v] << endl;
	}
	return true;
}

int main()
{
	input();

	get_leave();

	get_topolo();

	if(solve())
	{
		cout << "YES" << endl;
	}
	else
	{
		cout << "NO" << endl;
	}
	return 0;
}

