signed main() {
	INIT;
	VAR(int, n);
	VEC(int, A, n);
	VEC_ROW(int, n - 1, a, b);
	std::vector<std::set<int>> g(n);
	REP(i, n-1) {
		--a[i]; --b[i];
		g[a[i]].insert(b[i]);
		g[b[i]].insert(a[i]);
	}
	std::function<int(int, int)> dfs = [&](int d, int v) {
		int res = A[v] * 2;
		bool flag = false;
		for (const auto & x : g[v]) {
			if (x == d) continue;
			flag = true;
			int t;
			if (g[x].size() == 1) {
				t = A[x];
			}
			else {
				t = dfs(v, x);
			}
			res -= t;
		}
		if (res < 0) {
			assert(false);
			OUT("NO")BR;
			exit(0);
		}
		if (!flag) res /= 2;
		return res;
	};
	int leaf = 0;
	REP(i, n) {
		if (g[i].size() == 1) {
			leaf = i;
			break;
		}
	}
	if (A[leaf] == dfs(leaf, *g[leaf].begin())) {
		OUT("YES")BR;
	}
	else {
		OUT("NO")BR;
	}
	return 0;
}

