int f(int x, int p) {
  if (L[x]) return A[x];
  if (p >= 0 && G[x].size() == 2) {
    int k = 0;
    if (G[x][k] == p) k++;
    int e = f(G[x][k], x);
    if (A[x] != e) return -1;
    return e;
  }

  long long sum = 0;
  vector<int> s;
  for (int t : G[x]) {
    if (t == p) continue;
    int e = f(t, x);
    if (e == -1) return -1;
    s.push_back(e);
    sum += e;
  }
  if (sum != A[x]*2) return -1;
  int m = 0;
  for (auto x : s) m = max(m, x);
  if (m > sum - m) return -1;
  return A[x];
}

