bool noSolution = false;

inline void addEdge(int u, int v, int i)
{
	Adj[u].push_back(make_pair(v, i));
	Adj[v].push_back(make_pair(u, i));
}

void DFS(int cur, int pre)
{
	if (noSolution)
		return;

	if (Adj[cur].size() == 1)		// Leaf node
	{
		if (edgeLabel[Adj[cur].front().second] != 0
				&& edgeLabel[Adj[cur].front().second] != A[cur])
			noSolution = true;
		else
			edgeLabel[Adj[cur].front().second] = A[cur];

		return;
	}

	int sum = 0, faEdge = 0;
	for(vector<pair<int, int> >::iterator itr = Adj[cur].begin(); itr != Adj[cur].end(); ++itr)
	{
		const int & to = itr->first;
		if(to == pre)
		{
			faEdge = itr->second;
			continue;
		}
		DFS(to, cur);
		sum += edgeLabel[itr->second];
	}

	if(sum > 2 * A[cur])
	{
		noSolution = true;
		return;
	}

	edgeLabel[faEdge] = 2 * A[cur] - sum;
}

