bool res;

pair<int, int> calc(int now, int prv, const vector<int>& num, const vector<vector<int> >& G) {
  vector<pair<int, int> > S;
  for (int nxt : G[now]) {
    if (nxt == prv) continue;
    S.push_back(calc(nxt, now, num, G));
  }
  if (!S.size()) return pair<int, int>(num[now], num[now]);
  int min_sum = 0, max_sum = 0;
  for (auto pr : S) {
//    printf("%d : %d %d\n", now, pr.first, pr.second);
    min_sum += pr.first;
    max_sum += pr.second;
  }
  if (max_sum < num[now] || min_sum > num[now] * 2) {
    res = false;
    return pair<int, int>(0, 0);
  }
//  printf("!\n");

  pair<int, int> ret;
  int use = max_sum - num[now];
//  printf("use = %d\n", use);
  ret.first = ret.second = max_sum - use * 2;
  for (auto pr : S) {
    if ((max_sum - pr.second) < use) {
      res = false;
      return pair<int, int>(0, 0);
    }
  }
//  printf("now : %d %d, res = %d\n", ret.first, ret.second, res);
  return ret;
}

