void out(bool a)
{
	if (a) cout << "YES" << endl;
	else cout << "NO" << endl;
	exit(EXIT_SUCCESS);
}

ll solve(int v, const vi& a, const vector<vi>& tree)
{
	if (tree[v].size() == 0) return a[v];
	vi t;
	for (auto i : tree[v])
	{
		ll tmp = solve(i, a, tree);
		if (tmp == -1) return -1;
		t.push_back(tmp);
	}
	ll sum = 0;
	for (auto i : t) sum += i;
	if (sum < a[v] || sum > a[v] * 2) return -1;
	ll res = a[v] * 2 - sum;
	if (res < 0) res = -1;
	return res;
}

int main()
{
	cin.sync_with_stdio(false); cout << fixed << setprecision(10);
	int n;
	cin >> n;
	vi a(n);
	for (auto &i : a) cin >> i;
	vector<vi> v(n);
	REP(i, n - 1)
	{
		int a, b; cin >> a >> b;
		a--; b--;
		v[a].push_back(b);
		v[b].push_back(a);
	}
	if (n == 2) out(a[0] == a[1]);
	int root;
	REP(i, n)
	{
		if (v[i].size() > 1) root = i;
	}
	vector<vi> tree(n);
	vector<bool> vis(n);
	vis[root] = true;
	queue<int> que;
	que.push(root);
	while (!que.empty())
	{
		int t = que.front();
		que.pop();
		for (auto u : v[t])
		{
			if (vis[u]) continue;
			vis[u] = true;
			que.push(u);
			tree[t].push_back(u);
		}
	}
	out(solve(root, a, tree) == 0);
	return 0;
}

