bool flag=true;
long long dfs(int x,int y=0)
{
    if(!flag)return -1;
    if(e[x].size()==1)return a[x];
    long long sum=0;
    vector<long long>tmp;
    for(int i=0;i<e[x].size();i++)
    {
        int z=e[x][i];
        if(z==y)continue;
        long long j=dfs(z,x);

        if(j==-1)return -1;
        tmp.push_back(j);
        sum+=j;
    }
    long long delta=(sum-a[x]),ans=sum-2*delta;
    if( ans <0 || delta <0)
    {
        flag=false;
        return -1;
    }
    sort(tmp.begin(),tmp.end());
    int pos=tmp.size()-1;
    for(int i=0;i<pos;)
    {
        if(!delta)break;
        long long p=min(min(delta,tmp[i]),tmp[pos]);
        tmp[i]-=p;
        tmp[pos]-=p;
        delta-=p;
        if(!delta)break;
        if(tmp[pos]==0)pos--;
        else i++;
    }
    if(delta)
    {
        flag=false;
    }
    if(x==rt&&ans>0)
    {
        flag=false;
    }
    return ans;
}
