bool dfs(int x, int fa) {
	bool lf = 1;
	for (int now = head[x]; now; now = e[now].next) {
		if (e[now].to != fa) {
			lf = 0;
			if (dfs(e[now].to, x)) return 1;
			tot[x] += a[e[now].to];
		}
	}
	if (!lf) {
		if (tot[x] < a[x]) return 1;
		if (tot[x] > 2 * a[x]) return 1;
		LL ta = 2 * a[x] - tot[x], su = 0;
		for (int now = head[x]; now; now = e[now].next) {
			if (e[now].to != fa) {
