  if (c[v].empty()){
    return;
  }
  long long sum = 0;
  long long M = 0;
  for (int w : c[v]){
    dfs(A, c, w, ok);
    sum += A[w];
    M = max(M, A[w]);
  }
  long long tmp = A[v] * 2 - sum;
  long long pair_cnt = max(sum - A[v], (long long) 0);
  /*
