bool mark[maxn];

bool check(long long v, long long k)
{
	long long mx = k;
	long long sum = k;
	if( k < 0 ) 
		return false;
	for(int i=0 ; i < a[v].size() ; i++)
	{
		sum += s[a[v][i]];
		mx = max(mx, s[a[v][i]]);
	}

//	cout << v << ": " << mx << " - " << sum - mx << " -- " << k<< endl;
	if (mx > sum - mx)
		return false;
	else 
		return true;	
}

long long dfs(long long v)
{
	mark[v] = true;

	if( a[v].size() == 1 && mark[a[v][0]] ) return s[v];

	if( a[v].size() == 1 )
	{
		long long ans = s[v] - dfs( a[v][0] );
		if ( ans < 0 ) 
			return -1;
		else
			return ans; 
	}

	long long sum = 0;
	for(int i=0; i < a[v].size() ; i++)
		if( !mark[a[v][i]] )
		{
			long long tmp = dfs(a[v][i]);

			s[a[v][i]] = tmp;

			if ( tmp != -1)
				sum += tmp; 
			else 
				return -1;
		}

	long long k =  2*s[v] - sum;

	if ( !check(v, k) ) 
		return -1;
	else 
		return k;	
}

