V<ll> A;
VV<ll> edges;

ll dfs(ll now, ll pre) {
    ll ret = 0;
    V<ll> recs;
    ll sum = 0;
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        ll tmp = dfs(nxt, now);
        if(tmp == -1) return -1;
        recs.push_back(tmp);
        sum += tmp;
    }
    if(recs.empty()) return A[now];
    if(A[now] > sum) return -1;
    ll to_del = sum - A[now];
    DEBUG(now, A[now], sum, to_del);
    if(to_del > A[now]) return -1;
    if(sum - *max_element(ALL(recs)) < to_del) return -1;
    return A[now] - to_del;
}

bool solve() {
    ll N;
    cin >> N;
    A.resize(N);
    edges.resize(N);
    for(ll &e : A) cin >> e;
    for(ll i = 1; i < N; i++) {
        ll a, b;
