        a--;
        b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    if(N == 2) return A[0] == A[1];

    for(ll i = 0; i < N; i++) {
        if(edges[i].size() == 1) continue;
        return dfs(i, -1) == 0;
    }
    assert(false);
}

