const int N=100000+19;

struct Edge{
	int y,nxt;
} E[N*2];
ll F[N];
int las[N],A[N],d[N];
int n,cnt,rt;

void Link(int x,int y){
	E[cnt]=(Edge){y,las[x]};las[x]=cnt++;
	E[cnt]=(Edge){x,las[y]};las[y]=cnt++;
	d[x]++,d[y]++;
}
bool dfs(int x,int fa){
	if (d[x]==1){
		F[x]=A[x];
		return 1;
	}
	ll sum=0,mx=0;
	for (int i=las[x],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=fa){
			if (!dfs(y,x)) return 0;
			sum+=F[y];
			mx=max(mx,F[y]);
		}
	if (A[x]<sum-min(sum/2,sum-mx)||A[x]>sum) return 0;
	F[x]=2*A[x]-sum;
	assert(F[x]>=0);
	return 1;
}

