int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    vector<int64> vec;

    int64 sum = 0;

    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
        if (child < 0) return -1;
        vec.push_back(child);
        sum += child;
    }
    if (sum < A[v]) return -1;

    int64 T = sum - A[v];

    if (T > min(vec.back(), sum / 2)) return -1;
    return sum - 2 * T;
