int dfs(int now, int pre)
{
  int ret = 0, many = 0;
  VI und;
  deque<int> dq;

  if(node[now].size() == 1)
    return isi[now];
  for(auto pt:node[now]){
    if(pt != pre){
      int ret = dfs(pt, now);
      if(ret == -1)
	return -1;
      und.PB(ret);
      many += ret;
    }
  }

  sort(und.begin(), und.end());
  for(auto pt:und)
    dq.push_back(pt);

  while(dq.size() > 1){
    if(dq.front() > dq.back()){
      dq.front() -= dq.back();
      dq.pop_back();
    }
    else{
      dq.back() -= dq.front();
      dq.pop_front();
    }
  }

  ret += dq.front();
  many -= dq.front();
  isi[now] -= dq.front();

  if(many / 2 <= isi[now] && isi[now] <= many){
    return ret + (isi[now] - many / 2) * 2;
  }
  else{
    return -1;
  }
}

