int dfs(int v, int prev) {
        int sum = 0;
        int ma = -1;
        for (auto u : g[v]) {
                if (u == prev) continue;
                int get = dfs(u, v);
                ma = max(ma, get);
                sum += get;
        }
        if (ma == -1) return a[v];
        if (sum > 2 * a[v]) throw -1;
