long long dfs(const vector<vector<int>> &G, const vector<long long> &A, int v, int prev){
  //cerr << v << endl;
  if(G[v].size() == 1 and G[v][0] == prev) return A[v];
  vector<long long> B;
  long long s = 0;
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    long long t = dfs(G,A,v_,v);
    if(t < 0) return -1;
    B.push_back(t);
    s += t;
  }
  sort(B.rbegin(), B.rend());
  long long d = s - A[v];
  // fprintf(stderr,"v = %d, d = %lld, s = %lld\n",v,d,s);
  // cerr << "B : ";
  // for(auto b : B) cerr << b << " " ;
  // cerr << endl;
  while(d > 0 and B.size() >= 2){
    long long d_ = min(B.back(),d);
    d -= d_;
    s -= 2*d_;
    size_t b = B.size();
    B[b-1] -= d_;
    B[b-2] -= d_;
    if(not d) break;
    if(not B.back()) B.pop_back();
  }
  // fprintf(stderr,"v = %d, d = %lld, s = %lld\n",v,d,s);
  if(d) return -1;
  return s;
}

