int64 dfs(int32 v, int32 p){
	if(~dp[v]) return dp[v];
	if(G[v].size() == (p != -1)) return dp[v] = A[v];
	dp[v] = 0;
	int64 rest= A[v];
	vector<int64> c;
	int64 sum = 0;
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		c.push_back(dfs(G[v][i], v));
		sum += c[c.size()-1];
		if(c[c.size()-1] == -1) return dp[v] = -1;
	}
	sort(all(c));
	dp[v] += max((int64)0, 2*c[c.size()-1]-sum);
	sum -= dp[v];
	dp[v] += sum%2; sum -= sum%2;
	rest -= dp[v];
	if(dp[v]+sum/2 > A[v] || A[v] > dp[v]+sum) return -1;
	dp[v] += 2*rest-sum;
	return dp[v];
}

