void solve() {
	cerr << "solve" << endl;

	Vec< Vec< int > > leaf(N, Vec< int >());
	Vec< int > sum(N, 0);
	set< int > target;

	for_(v,0,N) {
		if (tree[v].size() == 1) {
			for (int u : tree[v]) {
				leaf[u].push_back(v);
				sum[u] += A[v];
			}
		} else {
			target.insert(v);
		}
	}

	while (target.size() > 0) {
		//cerr << "-----" << endl;
		Vec< int > unlock;
		for (int v : target) {
			//cerr << v << " " << sum[v] << " " << A[v] << endl;
			if (tree[v].size() - leaf[v].size() > 1) continue;
			if (sum[v] == A[v]) {
				if (tree[v].size() == leaf[v].size()) isno();

				for (int u : tree[v]) {
					leaf[u].push_back(v);
					sum[u] += A[v];
				}
			} else if (sum[v] * 2 == A[v]) {
