using namespace std;

bool solve(const vector<vector<int>>& g, const vector<int>& A){
	const int N = g.size();
	vector<int> deg(N);
	vector<long long> rest(N);
	queue<int> qu;
	for(int i=0;i<N;i++){
		deg[i] = g[i].size();
		rest[i] = A[i];
		if(g[i].size() == 1){
			qu.push(i);
		} else {
			rest[i] *= 2;
		}
	}
	vector<int> visit(N, 0);
	while(!qu.empty()){
		int p = qu.front(); qu.pop();
		visit[p] = 1;
		for(auto& t : g[p]){
			if(visit[t]) continue;
			if(deg[t] == 1) return rest[t] == rest[p];
			if(A[t] < rest[p]) return false;
			rest[t] -= rest[p];
			if(rest[t] < 0) return false;
			--deg[t];
			if(deg[t] == 1) qu.push(t);
		}
	}
	return true;
}

