vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

map<lli, lli> memo;
lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];
  if (memo.count(curr)) return memo[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  lli mx = *max_element(b.begin(), b.end());
  lli paired = min<lli>(sum / 2, mx);
  lli x = a[curr] - paired; // pass to parent
  lli y = a[curr] * 2 - sum;
  if (x < 0 || y < 0 || paired < x || (curr == prev && y)) throw "";
  return memo[curr] = y;
}

