int dfs(int idx,int par,Graph &g,vector<ll> &A){
    //cout<<idx<<" "<<success<<endl;
    vector<ll> v;
    for(int to:g[idx]){
        if(to==par) continue;
        v.push_back(dfs(to,idx,g,A));
    }
    if(v.size()==0){
        return A[idx];
    }
    if(v.size()==1){
        if(v[0]==A[idx]) return v[0];
        success=false;
        return v[0];
    }
    ll sum=0,num=0;
    for(ll x:v){
        sum+=x;
