void dfs(int k,int pre){
	int j,u,cnt=0,mx,sum;
	if (!tag) return;
	if (d[k]==1) return;
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		dfs(u,k);
	}
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (u==pre) continue;
		b[++cnt]=dp[u];
	}
	if (!tag) return;
	sort(b+1,b+1+cnt);
	mx=0; sum=0;
	for (j=1;j<=cnt;j++) sum+=b[j];
	if (a[k]>sum||(a[k]>all-sum&&all-sum>0)){
		printf("NO\n");
		tag=0;
		return;
	}
	if (b[cnt]>sum/2) mx=sum-b[cnt];
	else mx=sum/2;
	if (a[k]<sum-mx){
		printf("NO\n");
		tag=0;
		return;
	}
	dp[k]=2ll*a[k]-sum;
}

