const int maxn = 1e5+5;

int n,a[maxn],deg[maxn];
vector<int> g[maxn];
int ok;

void dfs(int u,int fa){
	if(deg[u] == 1) return;
	LL sum = 0LL;
	LL mx = 0LL;
	for(int i = 0;i < g[u].size();i++){
		int v = g[u][i];
		if(v == fa) continue;
		dfs(v,u);
		sum += a[v];
		mx = max(mx,1LL*a[v]);
	}
	if(sum < a[u] || sum > 2*a[u] || mx > a[u]) ok = 0;
	if(ok == 0) return;
	a[u] = 2*a[u] - sum;
}

void solve(){
	int root;
	if(n == 2){
		if(a[1] == a[2]) puts("YES");
		else puts("NO");
	}
	for(int i = 1;i <= n;i++){
		if(deg[i] != 1){
			root = i;
			break;
		}
	}
	ok = 1;
	dfs(root,-1);
	LL ans = a[root];
	//printf("ans = %I64d ok = %d\n",ans,ok);
	if(ok == 1 && ans == 0) puts("YES");
	else puts("NO");
}

