	while(scanf("%d",&n) != EOF){
		for(int i = 1;i <= n;i++) g[i].clear();
		for(int i = 1;i <= n;i++) scanf("%d",&a[i]);
		int u,v;
		memset(deg,0,sizeof(deg));
		for(int i = 1;i < n;i++){
			scanf("%d %d",&u,&v);
			g[u].push_back(v);
			g[v].push_back(u);
			deg[u]++;
			deg[v]++;
		}
		solve();
	}
	return 0;
}

