bool rec(int i,int p=-1){
    if(e[i].size()==1){
        dp[i]=a[i];
        return true;
    }
    ll s{},S{},x{};
    for(auto&j:e[i]){
        if(j==p) continue;
        if(!rec(j,i)) return false;
        s+=dp[j];
        x=max(x,dp[j]);
    }
    if(2*x>s){
        if(a[i]<x||s<a[i]) return false;
    }
    else if(a[i]<s/2+s%2||s<a[i]) return false;
    dp[i]=2*a[i]-s;
    return p!=-1||dp[i]==0;
}

