typedef long long ll;

const int N = 500505;
const int mod = 1e9 + 7;

int n, a[N], u, v;
vector<int> g[N];
inline void no() {
    cout << "NO";
    exit(0);
}

inline ll dfs(int v, int p = 0) {
    multiset<ll> h;
    for(int to : g[v]) {
        if(to == p) continue;
        h.insert(dfs(to, v));
    }
    if(!h.size()) return a[v];
    ll sum = 0;
    for(ll w : h) sum += w;
    ll min_moves = sum / 2;
    ll max_moves = sum;
    if(a[v] < min_moves || a[v] > max_moves)
        no();
    ll moves_by_two = max_moves - a[v];
    while(moves_by_two && h.size() > 1) {
        ll h1 = *(--h.end());
        h.erase(--h.end());
        ll h2 = *(--h.end());
        h.erase(--h.end());
        h1--;
        h2--;
        if(h1 < 0 || h2 < 0) no();
        if(h1 > 0) h.insert(h1);
        if(h2 > 0) h.insert(h2);
        moves_by_two--;
    }
    if(moves_by_two > 0) no();
    sum = 0;
    for(ll w : h) sum += w;
    return sum;
}

