bool foo() {
    int64_t n;
    cin >> n;
    vector<int64_t> A(n), a(n), b(n);
    for (int64_t i = 0; i < n; i++) {
        cin >> A[i];
    }
    for (int64_t i = 0; i < n - 1; i++) {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
    }

    vector<pair<int64_t, int64_t>> e((n - 1) * 2);
    for (int64_t i = 0; i < n - 1; i++) {
        e[i * 2 + 0] = { a[i], b[i] };
        e[i * 2 + 1] = { b[i], a[i] };
    }
    sort(e.begin(), e.end());

    bool r = true;

    std::function<int64_t(int64_t, int64_t)> f = [&](int64_t i, int64_t parent) -> int64_t {
        auto p0 = lower_bound(e.begin(), e.end(), pair<int64_t, int64_t>{ i, 0 });
        auto p1 = lower_bound(e.begin(), e.end(), pair<int64_t, int64_t>{ i + 1, 0 });
        if (parent >= 0 && p1 - p0 == 1) {
            return A[i];
        }
        int64_t s = 0;
        int64_t m = 0;
        for (auto it = p0; it != p1; it++) {
            int64_t j = it->second;
            if (j == parent) continue;
            int64_t t = f(j, i);
            s += t;
            m = max(m, t);
        }
        int64_t g = A[i] * 2 - s;
        if (parent < 0) {
            if (p1 - p0 == 1) {
                if (s != A[i]) r = false;
            } else {
                if (g != 0) r = false;
                if (0 < m - (s - m)) r = false;
            }
            return 0;
        }
        if (g < 0 || g < m - (s - m)) r = false;
        return (int64_t)g;
    };
    f(0, -1);
    return r;
}

int main() {
    cout << (foo() ? "YES" : "NO") << endl;
    return 0;
}

