bool ans;

ll f(int v, int p) {
  if (!ans) return 0;
  ll T = 0;
  if (g[v].size() == 1 && p == -1) {
    ll ci = f(g[v][0], v);
    if (A[v] != ci) { ans = false; }
    return 0;
  } else if (g[v].size() == 1 && p != -1) {
    T = A[v];
  } else {
    ll L = 0;
    vector<ll> c;
    for (int u : g[v]) if (u != p) {
      ll ci = f(u, v);
      L += ci;
      c.push_back(ci);
    }
    T = 2 * A[v] - L;
    if (T < 0 || T > A[v]) { ans = false; }
    if ((L - T) % 2 != 0) { ans = false; }
    if ((L - T) < 0) { ans = false; }
    ll P = (L - T) / 2;
    ll Q = L/2;
    REP(i, c.size()) {
      Q = min(Q, L-c[i]);
    }
    // if (ans) {
      // cout << "v=" << v << ", Q=" << Q << ", p=" << P << endl;
    // }
    if (Q < P) { ans = false; }
  }
  return T;
}

