vector<ll> A;
vector<vector<int>> G;

ll dfs(int v, int p) {
  ll a = A[v];
  vector<ll> children;
  for (int u : G[v]) {
    if (u != p) {
      children.push_back(dfs(u, v));
    }
  }
  if (children.empty()) {
    return a;
  }
  ll sum = accumulate(children.begin(), children.end(), 0ll);
  ll y = sum - a;
  ll x = a - y;
  if (x < 0 || y < 0) {
    cout << "NO" << endl;
    exit(0);
  }
  sort(children.rbegin(), children.rend());
  ll rem = 0, tot = 0;
  for (ll c : children) {
    ll t = min(rem, c);
    tot += t;
    rem = rem + c - 2 * t;
  }
  if (tot < y) {
    cout << "NO" << endl;
    exit(0);
  }
  return a - y;
}

