int N;

vector<int>node[100010];//2次元配列
long long int nost[100010];//上方向にまわる石の数
long long int stone[100010];//元の石の数
int solve(int ter,int parent) {
	int i,tchild;
	long long int max = 0, sum = 0;
	//maxは子ノードのnostの最大値
	if (node[ter].size() == 1) { nost[ter] = stone[ter]; return 0; }
	for (i = 0; i < node[ter].size(); i++) {
		tchild = node[ter][i];
		if (tchild == parent) { continue; }//親ノードは無視する
		solve(tchild, ter);
		if (nost[tchild] == -1) {nost[ter] = -1;return 0;}
		sum += nost[tchild];
		if (max < nost[tchild]) { max = nost[tchild]; }
	}
	if (sum < stone[ter]) { nost[ter] = -1; }//合計より自分の石が多いとか無理
	if (sum > stone[ter] * 2) { nost[ter] = -1; }//合計が多すぎて石のペアが作れない。むりぽ.
	if (max > stone[ter]) {nost[ter] = -1;}//最大がでかすぎてペアがそんなに作れなくてむry(
	nost[ter] = stone[ter] * 2 - sum;
	return 0;
}
int main(void) {
	int root = 0,a,b,i,j,ans;
	scanf("%d", &N);
	if (N == 2) {
		scanf("%d %d", &a, &b);
		if (a == b) { printf("YES"); }
		else { printf("NO"); }
		return 0;
	}//N==2ならば全てが葉ノードなので別処理
	for (i = 1; i <= N; i++) {
		scanf("%d", &a);
		stone[i] = a;
		nost[i] = a;
	}
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &a, &b);
		node[a].push_back(b);
		node[b].push_back(a);
	}
	if (node[N/2].size() > 1) { root = N/2; }
	else { root = node[N/2][0]; }//N/2でなくてもよいが1だと狙い打ち入力でTREそう
	solve(root,0);
	ans = nost[root];
	if (ans == 0) { printf("YES\n"); }
	else { printf("NO\n"); }
	return 0;
}

