vector<int> g[100010];
bool used[100010];
ll path[100010];

bool dfs(int now){
    used[now]=true;
    ll sum=0;
    bool leaf=true;
    vector<int> next;
    for(int i=0;i<g[now].size();i++){
        int u=g[now][i];
        if(used[u]) continue;
        if(!dfs(u)) return false;
        sum+=path[u];
        leaf=false;
        next.push_back(u);
    }
    if(leaf){
        path[now]=A[now];
        return true;
    }

    ll res=2*A[now]-sum;
    path[now]=res;
    if(res<0) return false;

    ll tmp=res+sum;
    if(tmp%2||res*2>tmp) return false;
    for(int i=0;i<next.size();i++){
        if(path[next[i]]*2>tmp) return false;
    }
    return true;
}

