void dfs(int u, int p){
	if(sz(e[u]) == 1){
		dp[u] = a[u];
		return;
	}

	ll S = 0;
	fi(0, sz(e[u])){
		int to = e[u][i];
		if(to == p){
			continue;
		}
		dfs(to, u);
		S += dp[to];
		cur[u].pb(dp[to]);
	}
	ll k = a[u] * 2 - S;
	if(k < 0){
		bad();
	}
	if(S % 2 != k % 2){
		bad();
	}
	if(!can(u, (S - k) / 2)){
		bad();
	}
	if(u == root){
		if(k != 0){
			bad();
		}
	}

	dp[u] = k;
}

