int w[101000], n, D[101000];
vector<int>E[101000];
void DFS(int a, int pp){
    int i, x, ck = 0, Mx = 0;
    long long s = 0;
    for(i=0;i<E[a].size();i++){
        x = E[a][i];
        if(x==pp)continue;
        DFS(x, a);
        ck = 1;
        if(D[x]==-1){
            D[a]=-1;
            return;
        }
        Mx = max(Mx, D[x]);
        s += D[x];
    }
    if(!ck){
        D[a]=w[a];
        return;
    }
    if(s > w[a]*2 || s < w[a] || Mx > w[a]){
        D[a]=-1;
        return;
    }
    D[a] = w[a]*2-s;
}
