    int mx = 0;
    int childs = 0;
    for(int child: adj[cur]){
        if(child == P)continue;
        int pass = check(child, cur);
        sum += pass;
        mx = max(mx, pass);
        childs++;
        if(fail)return 0;
    }
    // sum - inner == vals[cur]
    if(childs == 0)return vals[cur];

    int mxPaths = vals[cur];
