ll go(int u, int p) {
    ll sum = 0;
    bool leaf = true;
    vector<ll> d(g[u].size());
    for(int i = 0; i < g[u].size(); i++) {
        int v = g[u][i];
        if(v != p) {
            leaf = false;
            d[i] = go(v, u);
            sum += d[i];
        }
    }
//    cout << u << " - " << sum << endl;
    if(leaf || (p == -1 && g[u].size() == 1)) {
        if(p == -1) ok &= sum == a[u];
        return a[u];
    }
    ll r = 2*a[u] - sum;
//    cout << u << " " << r << " " << sum << endl;
    if(p != -1) ok &= r >= 0;
    if(p != -1) sum += r;
    ok &= sum == 2*a[u];
    ok &= sum % 2 == 0;
    for(int i = 0; i < g[u].size(); i++) {
        ok &= d[i] <= sum/2;
    }
    ok &= r <= sum/2;
    return r;
}

