int dfs(VVI& G, int u, int p){
  if(SZ(G[u]) == 1){
	return xs[u];
  }

  int as = 0;
  for(int to: G[u]){
	if(to == p) continue;
	int tmp = dfs(G, to, u);
	if(tmp < 0) return -1;
	as += tmp;
  }

  int res = 2*xs[u] - as;
  if(!(0 <= res && res <= xs[u])) return -1;
  return res;
}

