	REP(i, graph[v].size()) {
		if (used[graph[v][i].to] == 0) {
			child.push_back(dfs(graph, graph[v][i].to));
			if (child[child.size() - 1] == -1)return -1;
			total += child[child.size() - 1];
		}
	}
	if (child.size() == 0)return a[v];
	sort(all(child),greater<ll>());
	ll ma = min(total / 2, total - child[0]);
	if (total < a[v]||total-a[v]>ma)return -1;
	return total - (total - a[v]) * 2;
}



