  }
  if (number_of_child == 0) {
    return A[v];
  } else if (number_of_child == 1) {
    if (c_sum == A[v]) return c_sum;
    else return -1;
  } else {
    int c = 2 * A[v] - c_sum;
    int both = c_sum - A[v];
    if (c < 0 || both < 0 || min(c_sum - c_max, (c_sum - c) / 2) < both) return -1;
    return c;
  }
}

