bool ok = true;

ll deru(int now) {
  if (!ok) return 0;
  if ((int)children[now].size() == 0) return A[now];
  ll sum = 0;
  ll maxi = 0;
  for (auto x : children[now]) {
    ll temp = deru(x);
    sum += temp;
    maxi = max(maxi, temp);
  }
  if ((int)children[now].size() == 1) {
    if (A[now] == sum) return A[now];
    ok = false;
    return 0;
  }
  ll y = sum - A[now];
  ll x = 2 * A[now] - sum;
#if DEBUG == 1
    cerr << "now = " << now << ", x = " << x << ", y = " << y << endl; 
#endif
  if (y >= 0 && x >= 0 && y <= sum - maxi && y <= sum/2) {
    return x;
  } else {
    ok = false;
    return 0;
  }
}

