const ll maxn=1e5+5;
ll n,tot,flag,rt;
ll d[maxn],a[maxn],head[maxn],des[maxn<<1],nxt[maxn<<1];
void adde(ll x,ll y){
	des[++tot]=y;nxt[tot]=head[x];head[x]=tot;
