ll dfs(ll x,ll fa){
	ll can=0,rest=0,tot=0,cnt=0;
	vector<ll>q;
	Rep(p,x)if(des[p]!=fa)q.pb(dfs(des[p],x));
	sort(All(q));reverse(All(q));
