#include <bits/stdc++.h>
using namespace std;
vector<int> parent(vector<vector<int>> &E, int r){
	int N = E.size();
	vector<int> p(N, -1);
	queue<int> Q;
	Q.push(r);
	while (!Q.empty()){
		int v = Q.front();
		Q.pop();
		for (int w : E[v]){
			if (p[w] == -1){
				p[w] = v;
				Q.push(w);
			}
		}
	}
	return p;
}
vector<vector<int>> child_2(vector<int> &p, int r){
	int N = p.size();
	vector<vector<int>> c(N);
	for (int i = 0; i < N; i++){
		if (i != r){
			c[p[i]].push_back(i);
		}
	}
	return c;
}
void dfs(vector<long long> &A, vector<long long> &B, vector<vector<int>> &c, int v){
  if (c[v].empty()){
    return;
  }
  long long tmp = A[v] * 2;
  for (int w : c[v]){
    dfs(A, B, c, w);
    tmp -= A[w];
  }
  B[v] = tmp;
}
int main(){
  int N;
  cin >> N;
  vector<long long> A(N + 1, 0);
  for (int i = 1; i <= N; i++){
    cin >> A[i];
  }
  if (N == 2){
    if (A[1] == A[2]){
      cout << "YES" << endl;
    } else {
      cout << "NO" << endl;
    }
    return 0;
  }
  vector<vector<int>> E(N + 1);
  for (int i = 0; i < N - 1; i++){
    int a, b;
    cin >> a >> b;
    E[a].push_back(b);
    E[b].push_back(a);
  }
  //find non-leaf
  int r = 0;
  for (int i = 1; i <= N; i++){
    if (E[i].size() != 1){
      E[0].push_back(i);
      E[i].push_back(0);
      r = i;
      break;
    }
  }
  N++;
  vector<int> p = parent(E, 0);
  vector<vector<int>> c = child_2(p, 0);
  vector<long long> B = A;
  dfs(A, B, c, 0);
  if (B[r] != 0){
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
  }
}

#include "bits/stdc++.h"
using namespace std;

#define repl(i,a,b) for(int i=(int)(a);i<(int)(b);i++)
#define rep(i,n) repl(i,0,n)
#define replrev(i,a,b) for(int i=(int)(b)-1;i>=(int)(a);i--)
#define reprev(i,n) replrev(i,0,n)
#define repi(itr,ds) for(auto itr = ds.begin(); itr != ds.end(); ++itr)
#define mp make_pair
#define INF 2000000000
#define MOD 1000000007
#define PI 3.1415926536
typedef long long ll;
typedef pair<int, int> P;

vector<int> A, par;
vector<ll> num;
vector<vector<int>> T;
int root;
int N;

ll dfs() {
	vector<int> ord(N);

	stack<int> s;
	s.push(root);
	par[root] = -1;
	int cnt = 0;

	while (!s.empty()) {
		int pos = s.top();
		s.pop();
		ord[cnt] = pos;
		cnt++;
		rep(i, T[pos].size()) {
			if (T[pos][i] == par[pos])continue;
			par[T[pos][i]] = pos;
			s.push(T[pos][i]);
		}
	}

	reprev(i, N) {
		int p = ord[i];
		if (T[p].size() == 1) {
			num[p] = A[p];
		}
		else {
			ll sum = 0;

			if (T[p].size() == 1) {
				num[p] = A[p];
				continue;
			}
			// 子同士のペアがi個
			// s-2i=A-i, i=s-A, A-i=2A-s
			int zero = 0;
			ll m = 0;
			rep(i, T[p].size()) {
				if (T[p][i] == par[p])continue;
				sum += num[T[p][i]];
				m = max((ll)m, num[T[p][i]]);
				if (num[T[p][i]] == 0)zero++;
			}

			if (2 * A[p] - sum < 0 || sum < A[p] || A[p] < m)return -1;

			if (p != root && T[p].size() - zero == 2) {
				if (A[p] == sum) {
					num[p] = A[p];
				}
				else {
					return -1;
				}
			}
			else {
				num[p] = 2 * A[p] - sum;
			}
		}
	}
	return num[root];
}

int main() {
	cin >> N;
	A = vector<int>(N);
	par = vector<int>(N);
	num = vector<ll>(N);
	T = vector<vector<int>>(N);
	rep(i, N) {
		cin >> A[i];
	}
	rep(i, N - 1) {
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		T[a].push_back(b);
		T[b].push_back(a);
	}
	if (N == 2) {
		if (A[0] == A[1]) {
			cout << "YES" << endl;
		}
		else {
			cout << "NO" << endl;
		}
		return 0;
	}
	rep(i, N) {
		if (T[i].size() > 1) {
			root = i;
			break;
		}
	}

	if (dfs() == 0) {
		cout << "YES" << endl;
	}
	else {
		cout << "NO" << endl;
	}

	return 0;
}

#include <bits/stdc++.h>
#define pb push_back
using namespace std;
typedef long long ll;
typedef vector<int> vi;
#define TAM 100100

ll A[TAM];
vi G[TAM];

bool ok ( int i, int pi = -1 ) {
  if ( G[i].size() == 1 )
    return true;

  ll sum = 0, maxAj = 0;
  for ( int j : G[i] )
    if ( j != pi ) {
      if ( !ok(j, i) )
        return false;
      sum += A[j];
      maxAj = max ( maxAj, A[j] );
    }

  // x + A[i] = sum
  ll x = sum - A[i];

  if ( x < 0 || maxAj > A[i] )
    return false;

  A[i] -= x;
  return true;
}

int main() {
  int n;
  scanf ( "%d", &n );
  for ( int i = 1, tmp; i <= n; ++i ) {
    scanf ( "%d", &tmp );
    A[i] = tmp;
  }
  for ( int edges = n-1, a, b; edges--; ) {
    scanf ( "%d%d", &a, &b );
    G[a].pb ( b );
    G[b].pb ( a );
  }

  if ( n == 2 ) {
    puts ( A[1] == A[2] ? "YES" : "NO" );
    return 0;
  }

  int root = 1;
  while ( G[root].size() == 1 ) root++;

  if ( ok(root) && A[root] == 0 ) puts ("YES");
  else puts("NO");
  return 0;
}

