	{
		scanf("%d%d",&u,&v);
		du[u]++,du[v]++;
		AddEdge(u,v);
		AddEdge(v,u);
	}
	if(n==2)
	{
		if(a[1]==a[2])
			printf("YES\n");
		else printf("NO\n");
		return 0;
	}
	int rt=1;
