LL dp(int x,int p){
	multiset<LL> s;
	LL sum=0;
	for(int i:adj[x]){
		if(i==p)continue;
		LL nv=dp(i,x);sum+=nv;
		s.insert(nv);
	}
	if(SZ(s)==0){
		return v[x];
	}
	LL maxp=0;
	while(SZ(s)>1){
		int f=*s.begin();
		maxp+=f;
		int l=*s.rbegin();
		s.erase(s.begin());
		s.erase(--s.end());
		if(l-f)s.insert(l-f);
	}
	LL pn=sum-v[x];
	if(maxp<pn){
		printf("NO");exit(0);
	}
	return sum-pn*2;
}

