int n;
ll a[100100];
vector<int> G[100100];

ll calc(int v, int p) {
    vector<ll> vec;
    for (int i = 0; i < G[v].size(); i++) {
        if (G[v][i] != p) {
            vec.push_back(calc(G[v][i], v));
        }
    }
    int l = vec.size();
    /*
    cerr << v << ": ";
    for (int i = 0; i < l; i++)
        cerr << vec[i] << " ";
    cerr << endl;
    */
    if (l == 0) return a[v];

    sort(ALL(vec));
    if (vec[0] < 0) return -1;
    ll s = 0;
    for (int i = 0; i < l; i++) s += vec[i];
    ll d = s - a[v];
    if (d < 0 || a[v] - d < 0) return -1;
    ll t;
    if (vec[l-1] > s - vec[l-1]) t = s - vec[l-1];
    else t = s - (s%2);

    if (t < d) return -1;
    return a[v] - d;
}

bool solve() {
    if (G[0].size() > 1) return calc(0, -1) == 0;
    return calc(0, -1) >= 0;
}

