#include <bits/stdc++.h>
using namespace std;
#define REP(i,a,n) for(int i=(a); i<(int)(n); i++)
#define rep(i,n) REP(i,0,n)
#define FOR(it,c) for(__typeof((c).begin()) it=(c).begin(); it!=(c).end(); ++it)
#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
typedef unsigned long long ull;

#define INF 10000000000000LL

int N;
vector<ll> A;
vector<int> G[100005];

ll dfs(int v, int p){
  if(p!=-1 && G[v].size() == 1) return A[v];

  ll sum = 0;
  vector<ll> c;
  rep(i,G[v].size()){
    if(G[v][i] == p) continue;
    ll res = dfs(G[v][i], v);
    if(res < 0) return -INF;
    sum += res;
    c.push_back(res);
  }
  if(c.size() == 1){
    if(A[v] == c[0]) return c[0];
    else return -INF;
  }

  ll T = 2LL*A[v] - sum;
  if(T<0 || T>A[v]) return -INF;
  ll L = A[v] - T;

  int n = 0;
  int m = c.size()-1;
  ll PR = 0;
  sort(ALLOF(c));
  while(n < m){
    ll mn = min(c[n],c[m]);
    PR += mn;
    c[n] -= mn;
    c[m] -= mn;
    if(c[n]==0) n++;
    if(c[m]==0) m--;
  }
  if(L <= PR) return T;
  return -INF;
}


bool solve(){
  ll leaf1 = -1;
  ll sum = 0;
  rep(i,N){
    if(G[i].size() == 1){
      leaf1 = i;
      sum += A[i];
    }
  }
  if(sum%2!=0) return false;
  rep(i,N){
    if(A[i] > sum/2) return false;
  }

  ll res = dfs(leaf1,-1);
  if(res == A[leaf1]) return true;
  return false;
}

int main(){
  cin >> N;
  rep(i,N){
    ll a;
    cin >> a;
    A.push_back(a);
  }
  rep(i,N-1){
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  if(solve()) cout << "YES" << endl;
  else cout << "NO" << endl;

  return 0;
}

