typedef ll Weight;
struct Edge {
  int src, dst;
  Weight weight;
  Edge(int src, int dst, Weight weight) :
    src(src), dst(dst), weight(weight) { }
};
bool operator < (const Edge &e, const Edge &f) {
  return e.weight != f.weight ? e.weight > f.weight : // !!INVERSE!!
    e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef vector<Weight> Array;
typedef vector<Array> Matrix;

Graph g;
vector<ll> power;
ll N;
bool dame;
ll solve(ll now, ll to){
	vector<ll> flow;
	ll sum=0;
	for(int i=0;i<g[now].size();i++){
		if(g[now][i].dst==to)
			continue;
		flow.push_back(solve(g[now][i].dst, now));
		sum+=flow[flow.size()-1];
	}
	if(flow.empty())
		return power[now];
	ll naibu=sum-power[now];
	if(naibu<0)
		return dame=true;
	ll l=0;
	ll r=flow.size()-1;
	sort(flow.begin(),flow.end());
	while(l<r && naibu>0){
		ll syori=min(flow[l], min(flow[r], naibu));
		flow[l]-=syori;
		flow[r]-=syori;
		if(flow[l]==0)
			l++;
		if(flow[r]==0)
			r--;
		naibu-=syori;
		if(naibu==0)
			break;
	}
	if(naibu>0 && l==r){
		ll syori=min(naibu, flow[l]/2);
		naibu-=syori;
	}
	if(naibu>0)
		dame=true;
	if(sum==power[now] && now == to)
		return 0;
	return power[now]-(sum-power[now]);
}

int main(){
	cin >> N;
	power =vector<ll>(N);
	for(int i=0;i<N;i++)
		cin >> power[i];
	g = Graph(N);
	dame=false;
	for(int i=0;i<N-1;i++){
		ll a,b;
		cin >> a >> b;
		a--; b--;
		g[a].push_back(Edge(a,b,0));
		g[b].push_back(Edge(b,a,0));
	}
	ll ans=solve(0,0);
	if(ans==0 && !dame)
		cout << "YES" << endl;
	else
		cout << "NO" << endl;
	return 0;
}

