using namespace std;

vector<int> g[100010];
vector<long long> A;

bool res = true;

void fail() {
    cout << "NO" << endl;
    exit(0);
}

long long smart_greedy(vector<long long> ws){
    long long min_consume = 0;
    sort(ws.begin(), ws.end());
    for(int i = 0 ; i+1 < ws.size() ; i++){
        min_consume += ws[i];
        ws[i+1] -= ws[i];

        if( i + 2 == ws.size() && ws[i+1] > 0) {
            long long decop = (min_consume - ws[i]);
            long long u = min(decop * 2, ws[i + 1]) / 2 * 2;
            min_consume += u / 2;
            ws[i + 1] -= u;

        }
    }
    return min_consume;
}

long long dfs(int root, int prev) {
    vector<long long> ws;
    for (auto e : g[root]) {
        if (e == prev) continue;
        ws.push_back(dfs(e, root));
    }

    if (ws.size() == 0) {
        return A[root];
    }


    long long max_consume = accumulate(ws.begin(), ws.end(), 0ll);
    long long max_pair_consume = smart_greedy(ws);
    long long min_remain = max_consume - 2 * max_pair_consume;



    //cout << prev << " -> " << root + 1 << ": " << min_consume << " " << max_consume << "|" << ws.size() << endl;
    if (A[root] > max_consume) fail();
    if (A[root] < min_remain) fail();

    long long t = 2 * A[root] - max_consume;

    if( prev == -1) {
        if( t != 0 ) fail();
    }

    return t;
}

void solve(long long N, vector<long long> A_, vector<long long> a, vector<long long> b) {
    A = A_;
    for (int i = 0; i < N - 1; i++) {
        g[a[i] - 1].push_back(b[i] - 1);
        g[b[i] - 1].push_back(a[i] - 1);
    }
    if (N == 2) {
        cout << (A[0] == A[1] ? "YES" : "NO") << endl;
        return;
    }
    for (int i = 0; i < N; i++) {
        if (g[i].size() >= 2) {
            dfs(i, -1);
            cout << "YES" << endl;
            return;
        }
    }
    assert(0);
}

int main() {
    long long N;
    scanf("%lld", &N);
    vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        scanf("%lld", &A[i]);
    }
    vector<long long> a(N - 1);
    vector<long long> b(N - 1);
    for (int i = 0; i < N - 1; i++) {
        scanf("%lld", &a[i]);
        scanf("%lld", &b[i]);
    }
    solve(N, A, a, b);
    return 0;
}

