    rep(i,e[v].size()){
        if(saw[e[v][i]]) continue;
        P rec = dfs(e[v][i]);
        //cout << v << " " << rec.fi << " " << rec.sc << endl;
        if(rec.fi == -1) return P(-1,-1);
        tmp1.push_back(rec.fi);
