    }
    ll sum1 = 0, sum2 = 0;;
    sort(tmp1.begin(),tmp1.end(),greater<ll>());
    sort(tmp2.begin(),tmp2.end(),greater<ll>());
    if(tmp1.size() == 0) return P(a[v],a[v]);
