    }
    for(int i = 1; i < tmp1.size(); i++){
        sum1 += tmp1[i];
        sum2 += tmp2[i];
    }
    P ret;
    if(tmp2[0]+sum2 < a[v]) return P(-1,-1);
    ret.sc = a[v];
    if(tmp1[0] > sum1){
        if(a[v]-tmp1[0] < 0) return P(-1,-1);
