long long int Search(int num) {
	if (up[num] != -1) {
		return up[num];
	}
	if (edge[num].size() == 1) {
		up[num] = box[num];
		return up[num];
	}
	flag[num] = false;
	long long int sum = 0;
	long long int ma = 0;
	for (auto i : edge[num]) {
