int getMin(vi &data)
{
    if (data.size() == 0) return 0;
    vi s(data.size(), 0);
    s[0] = data[0];
    Rep(i, data.size()) {
        s[i] = s[i-1] + data[i];
    }
    int ret = INF;
    rep(i, s.size()) {
        ret = min(ret, abs(s.back() - s[i] * 2));
    }
    return ret;
}

