#define INF 10000000000000LL

int N;
vector<ll> A;
vector<int> G[100005];

ll dfs(int v, int p){
  if(p!=-1 && G[v].size() == 1) return A[v];

  ll sum = 0;
  vector<ll> c;
  rep(i,G[v].size()){
    if(G[v][i] == p) continue;
    ll res = dfs(G[v][i], v);
    sum += res;
    c.push_back(res);
  }
  if(c.size() == 1) return c[0];

  ll T = 2LL*A[v] - sum;
  if(T<0 || T>A[v]) return -INF;
  ll L = A[v] - T;
  int n = 0;
  int m = c.size()-1;
  ll PR = 0;
  while(n < m){
    ll mn = min(c[n],c[m]);
    PR += mn;
    c[n] -= mn;
    c[m] -= mn;
    if(c[n]==0) n++;
    if(c[m]==0) m--;
  }
  if(L <= PR) return T;
  return -INF;
}


bool solve(){
  ll sum = 0;
  ll leaf1 = -1;
  rep(i,N){
    if(G[i].size() == 1){
      sum += A[i];
      leaf1 = i;
    }
  }
  if(sum%2!=0) return false;
  ll n = sum/2;
  rep(i,N){
    if(A[i] > n) return false;
  }
  ll res = dfs(leaf1,-1);
  if(res == A[leaf1]) return true;
  return false;
}

