ll dfs(ll now, ll from){
  vector<ll> xs;
  ll M = 0;
  for(ll to : E[now]){
    if(to == from) continue;
    xs.pb(dfs(to, now));
    M += xs.back();
    if(xs.back() == -1) return -1;
  }
  if(xs.size() == 0) return A[now];
  ll M_loop = 0;
  sort(xs.begin(), xs.end());
  ll t = xs.size();
  for(ll i = 1; i < t; i++){
    if(xs[i-1] < xs[i]) swap(xs[i-1], xs[i]);
    M_loop += xs[i];
    xs[i-1] -= xs[i];
    xs[i] = 0;
  }
  ll m = 0;
  rep(i, t){
    m += xs[i];
  }
  if(A[now] < m + M_loop || A[now] > M) return -1;
  return 2 * A[now] - M;
}

