ll dfs(ll num, ll par) {
  ll sum = 0;
  for (ll i : e[num]) if (i != par) {
    ll temp = dfs(i, num);
    if (temp == -1) return -1;
    if (a[num] < temp) return -1;
    sum += temp;
  }
  if (sum == 0) return a[num];
  if (2 * a[num] - sum < 0) return -1;
  return 2 * a[num] - sum;
}

