const int N = 1234567;

vector <int> g[N];
int a[N];
bool err;

int dfs(int v, int pr) {
  int sz = g[v].size();
  int sum = 0;
  int cnt = 0;
  int mx = 0;
  for (int j = 0; j < sz; j++) {
    int u = g[v][j];
    if (u == pr) {
      continue;
    }
    cnt++;
    int cur = dfs(u, v);
    sum += cur;
    mx = max(mx, cur);
  }
  if (cnt == 0) {
    return a[v];
  }
  if (a[v] > sum || a[v] < mx || 2 * a[v] < sum) {
    err = true;
    return 0;
  }
  return 2 * a[v] - sum;
}

int main() {
