using namespace std;

vector<int> t[100009];
int n;
long long arr[100009];

long long solve(int cur, int p = -1) {
	long long sum = 0;
	if (t[cur].size() == 1)
		return arr[cur];
	for (int i = 0; i < t[cur].size(); i++) {
		if (t[cur][i] == p)
			continue;
		long long tmp = solve(t[cur][i], cur);
		if (tmp == -1)
			return -1;
		sum += tmp;
	}
	if (t[cur].size() == 2) {
		if (sum != arr[cur])
			return -1;
		else
			return sum;
	}
	if (arr[cur] > sum) {
		return -1;
	}
	if (arr[cur] * 2 < sum) {
		return -1;
	}
	return 2 * arr[cur] - sum;
}

