            tr(it, graph[v]) {
                if (*it != par) {
                    child_cnt += dp[*it];
                    chmax(child_max, dp[*it]);
                }
            }

            ll internal = child_cnt - A[v];
            ll external = A[v] - internal;

            if(internal < 0 || external < 0)
                ok = false;
            if(child_max * 2 > child_cnt) {
                if(internal > (child_cnt - child_max))
                    ok = false;
            }
            else if(internal * 2 > child_cnt)
                ok = false;

            dp[v] = external;
        }
    };

    dfs(0, -1);

//    cerr << dp << endl;

    cout << (ok ? "YES" : "NO") << endl;

    return 0;
}

