    }
    ll cur = dfs(to, v);
    up += cur;
    mx = max(mx, cur);
  }
  if (up < a[v]) {
    ok = false;
  }
  ll inside = up - a[v];
  if (inside > up - mx) {
    ok = false;
  }
  if (inside * 2 > up) {
    ok = false;
  }
  return up - inside * 2;
}

