    a--;b--;
    vec[a].pb(b);
    vec[b].pb(a);
  }
  if(n==2) return num[0]==num[1];

  // n>=3
  // だめじゃん
  function<long(int,int)> dfs = [&](int from, int d){
    if(vec[d].size()==1) return (long)num[d];
    long c=0;
    long mx=0;
    for(auto to : vec[d]) if(to!=from){
      long tmp = dfs(d, to);
      if(tmp==-1) return -1LL;
      c += tmp;
      mx = max(tmp, mx);
    }
    if(c >= num[d]){
      // c-num[d]を中で
      if(c-num[d]>min(c/2,c-mx)) return -1LL;
      else return c-2*(c-num[d]);
    }
    return -1LL;
  };

  int s=0;
  while(vec[s].size()==1) s++;

  return dfs(-1, s)==0;
}

