    srep (v, 1, n+1) ccnt[v] = children[v].size();

    S queue<ll> q;
    srep (v, 2, n+1) if (ccnt[v] == 0) q.push(v);

    S V<ll> stonecnts[100005];

    while (q.size()) {
        ll v = q.front(); q.pop();
        ll pv = parents[v];

        if (stonecnts[v].empty()) {
            stonecnts[pv].pb(alist[v]);
            ccnt[pv]--; if (!ccnt[pv] && v != 1) q.push(pv);
            continue;
        }

        ll maxcnt = 0;
        for (auto scnt : stonecnts[v]) maxcnt = max(maxcnt, scnt);
        ll totalcnt = 0;
        for (auto scnt : stonecnts[v]) totalcnt += scnt;

        ll upcnt = max(0LL, maxcnt - (totalcnt - maxcnt));
        ll anycnt = totalcnt - upcnt;
        ll maxa = totalcnt;
        ll mina = upcnt + anycnt / 2LL + (anycnt & 1LL);
