        if (v == 1) {
            bool ng = false;
            if (children[v].size() == 1) ng = (realupcnt != a);
            else ng = !!(realupcnt);

            if (ng) {
                debug_printf("---- no 2\n");
                cout << "NO" << endl;
                return;
            }

            continue;
        }

        stonecnts[pv].pb(realupcnt);
        ccnt[pv]--; if (!ccnt[pv] && v != 1) q.push(pv);
    }

    cout << "YES" << endl;
