#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;

struct node {
	int to, next;
} edge[MAXN*2];
int head[MAXN], top = 0;
inline void push(int i, int j)
{ edge[++top] = (node) {j, head[i]}, head[i] = top; }

int n, a[MAXN], u, v, d[MAXN];

int flag = 1;

long long dfs(int nd, int f)
{
	if (d[nd] == 1) return a[nd];
	long long pre = 0, tot = 0, sub = 0, maxp = 0;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == f) continue;
		long long tar = dfs(to, nd);
		maxp = max(maxp, tar);
		tot += tar;
	}
	if (maxp*2 > tot) sub = tot-maxp;
	else sub = tot/2;
	if (tot < a[nd] || tot-sub > a[nd]) 
		flag = 0;
	// cerr << flag << " " << nd << " " << tot << " " << sub << " " << a[nd] << " " << tot-2*(tot-a[nd]) << endl;
	return tot-2*(tot-a[nd]);
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &u, &v);
		push(u, v), push(v, u), d[u]++, d[v]++;
	}
	int rt = 0;
	for (int i = 1; i <= n; i++)
		if (d[i] > 1) {
			rt = i;
			break;
		}
	long long t = dfs(rt, 0);
	if (t == 0 && flag) puts("YES");
	else puts("NO");
	return 0;
}

