using namespace std;
int n, a, b; long long x[100009], dp[100009]; vector<int> G[100009];
bool solve(int pos, int pre) {
	if (G[pos].size() == 1) {
		dp[pos] = x[pos];
		return true;
	}
	long long sum = 0, m = 0, cnt = 0;
	for (int i : G[pos]) {
		if (i == pre) continue;
		if (!solve(i, pos)) return false;
		sum += dp[i];
		m = max(m, dp[i]);
		cnt++;
	}
	if (cnt == 1) {
		for (int i : G[pos]) {
			if (i != pre) {
				if (dp[i] != x[pos]) return false;
				dp[pos] = dp[i];
				return true;
			}
		}
	}
	long long R = min(sum / 2, sum - m);
	if (0 <= sum - x[pos] && sum - x[pos] <= R) {
		dp[pos] = 2 * x[pos] - sum;
		if (dp[pos] < 0) return false;
		return true;
	}
	return true;
}
int main() {
	cin >> n;
	for (int i = 0; i < n; i++) cin >> x[i];
	if (n == 2) {
		cout << (x[0] == x[1] ? "YES" : "NO") << endl;
		return 0;
	}
	for (int i = 0; i < n - 1; i++) {
		cin >> a >> b; a--, b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	int root = -1;
	for (int i = 0; i < n; i++) {
		if (G[i].size() >= 2) {
			root = i;
			break;
		}
	}
	bool ret = solve(root, -1);
	if (dp[root] != 0) ret = false;
	cout << (ret ? "YES" : "NO") << endl;
	return 0;
}

