const int SIZE=5+3*1e5;
const int INF=10+1e9;
const LL p =7+1e9;
LL A[SIZE];
VI edges[SIZE];
LL reached[SIZE];
bool isUsed[SIZE];
LL maxim[SIZE];
LL sum[SIZE];
VI results;
bool solve(){
	int N,a,b;
	cin.tie(0);
	cin >> N;
	FOR(i,1,N+1) cin >> A[i];
	REP(i,N-1){
		cin >> a >> b;
		edges[a].PB(b);
		edges[b].PB(a);
	}
	queue<int> qu;
	FOR(i,1,N+1){
		if(edges[i].size()==1) {
			isUsed[i]=true;
			qu.push(i);
		}
	}
	while(!qu.empty()){
		int now=qu.front();
		qu.pop();
		if(A[now]>sum[now] && edges[now].size()!=1) return false;
		if(A[now]*2<sum[now]) return false;
		if(A[now]<maxim[now]) return false;
		if(edges[now].size()!=1) A[now]-=sum[now]-A[now];
		results.PB(A[now]);
		REP(i,edges[now].size()){
			int next=edges[now][i];
			if(isUsed[next]) continue;
			reached[next]++;
			sum[next]+=A[now];
			maxim[next]=max(maxim[next],A[now]);
			if(reached[next]==edges[next].size()-1){
				isUsed[next]=true;
				qu.push(next);
			}
		}
	}
	return results[N-1]==results[N-2];
}
