long long dfs2(int v){
  if(GG[v].size()==0){
    b[v]=a[v];
    return b[v];
  }
  vector<long long> kk;
  for(int u:GG[v]){
    kk.push_back(dfs2(u));
  }
  long long tmp=0;
  for(long long t:kk)tmp+=t;
  // if(tmp<a[v])res=false;
  long long pr=tmp-a[v];
  int si=kk.size();
  if(si>1){
    sort(kk.begin(),kk.end());
    while(pr>0&&kk[si-2]>0){
      long long di = min(kk[si-2],pr);
      di=max(1ll,di/2);
      kk[si-2]-=di;
      kk[si-1]-=di;
      pr-=di;
      sort(kk.begin(),kk.end());
    }
  }
  if(pr>0)res=false;
  b[v]=2*a[v]-tmp;
  if(b[v]<0)res=false;
  return b[v];
}

