      if(V[i] > V[i+1]) swap(V[i], V[i+1]);
      cnt += V[i];
      V[i+1] -= V[i];
    }
    int t = a[u] * 2 - sum;
    if(cnt < (sum - t) / 2) fail();
    return t;
  };
