int64_t dfs(int cur, int root)
{
	int64_t out = paths[cur];

	if (adj[cur].size() > 1)
	{
		out += paths[cur];
	}

	for (int next : adj[cur])
	{
		if (next == root) continue;

		int64_t in = dfs(next, cur);
		if (in > paths[cur]) ok = false;

		out -= in;
	}

	if (out < 0) ok = false;
	if (out > paths[cur]) ok = false;

	return out;
}

