bool dfs(int v, int pv, int r) {
  int sum = 0;
  int mx = 0;
  for (int to : g[v]) {
    if (to == pv) {
      continue;
    }
    if (!dfs(to, v, r)) {
      return false;
    }
    mx = max(mx, f[to]);
    sum += f[to];
  }
  if ((int) g[v].size() == 1) {
    f[v] = a[v] - sum;
  } else {
    f[v] = 2 * a[v] - sum;
  }
  if (f[v] < 0 || sum < a[v] || mx > a[v]) {
    return false;
  }
  return true;
}

bool ok() {
  int sum_a = 0;
  vector<int> all;
  for (int i = 0; i < n; i++) {
