void get_topolo()
{
	vector<bool> vec(n + 1,false);
	queue<int> que;

	for(int l : leave)
	{
		que.push(l);
	}

	while(!que.empty())
	{
		int v = que.front();
		que.pop();

		if(vec[v]) continue;
		vec[v] = true;
		deeper.push_back(v);

		for(int to : edges[v])
		{
			if(vec[to] == false)
			{
				topolo[to].push_back(v);
				que.push(to);
			}
		}
	}
}

