vector<vector<int>> T;
int root;
int N;

ll dfs() {
	int pos = root;
	vector<int> ord(N);

	stack<int> s;
	s.push(pos);
	par[root] = -1;
	int cnt = 0;

	while (!s.empty()) {
		pos = s.top();
		s.pop();
		ord[cnt] = pos;
		cnt++;
		rep(i, T[pos].size()) {
			if (T[pos][i] == par[pos])continue;
			par[T[pos][i]] = pos;
			s.push(T[pos][i]);
		}
	}

	reprev(i, N) {
		int p = ord[i];
		if (T[p].size() == 1) {
			num[p] = A[p];
		}
		else {
			ll sum = 0;
			rep(i, T[p].size()) {
				sum += num[T[p][i]];
			}
			if (2 * A[p] - sum < 0 || (p != root && 2 * A[p] - sum == 0))return -1;
			num[p] = 2 * A[p] - sum;
		}
	}
	return num[root];
}

