int dfs(int cv, int pv, vector<vector<int>> &G, vector<ll> &a){

    ll sum = 0;
    int children_cnt = 0;
    for(auto nv : G[cv]){
        if(nv == pv) continue;
        children_cnt++;
        sum += dfs(nv, cv, G, a);
    }

    if(cv == 0){
        if(children_cnt == 1){
            if(a[0] != sum) valid = false;
        }
        else{
            if(a[0] * 2 != sum) valid = false;
        }
    }

    if(children_cnt == 0){
        return a[cv];
    }
    else{
        if(a[cv] * 2 - sum < 0) valid = false;
        return a[cv] * 2 - sum;
    }
}

