LL dfs(int i, int p) {
	vector<LL> v;
	LL sum = 0;
	for(auto && e: g[i]) {
		if(e == p) { continue; }
		LL r = dfs(e, i);
		// cout << e + 1 << ": " << r << endl;
		if(r == -1) { return -1; }
		v.PB(r);
		sum += r;
	}
	sort(RALL(v));

	if(v.empty()) { return a[i]; }

	LL ma = sum;
	LL mi = max(v[0], ce(sum, 2));

	return (inII(a[i], mi, ma) ? ma - 2 * (ma - a[i]) : -1);
}

