			for ( int i = 0; i < val.size()-1; i++ ){
				LL v = val[i];
				if ( fsum <= target && fsum + v >= target ){
					LL l = 0, r = v;
					while ( l < r){
						LL m = ( l + r ) / 2;
						if ( fsum + m >= target ) r = m;
						else l = m + 1;
					}
					fsum += l;
					sum -= l;
					if ( fsum >= target && sum >= target ){
						yes();
					} else {
						no();
					}
				}

				fsum += v;
				sum -= v;
				if ( fsum >= target ){
					if ( sum >= target ){
						yes();
					}
					no();
				}
				if ( sum < target ){
					no();
				}
			}	
		}	
	}

	no();
	return 0;
}

