typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

const int N = 1e5 + 5;

int n;
int root;
int a[N];
bool isLeaf[N];
bool can = true;
vi g[N];

void dfs(int u, int par) {
  ll childrenTotal = 0;
  if (isLeaf[u]) {
    return;
  }
  vi children;
  for (int v : g[u]) {
    if (v == par) {
      continue;
    }
    dfs(v, u);
    children.push_back(v);
    childrenTotal += a[v];
  }
  if (childrenTotal < a[u] || childrenTotal > 2 * a[u]) {
    can = false;
  } else {
    ll cur = childrenTotal - a[u];
    a[u] = 2 * a[u] - childrenTotal;
    sort(ALL(children), [&] (int x, int y) { return a[x] < a[y]; });
    ll largest = 0;
    ll limit = cur;
    cur *= 2;
    for (int c : children) {
      if (cur == 0) break;
      ll take = min(cur, (ll)a[c]);
      largest = max(largest, take);
      cur -= take;
    }
    if (largest > limit || cur > 0) {
      can = false;
    }
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
