    u--; v--;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  REP(i, n) isLeaf[i] = SZ(g[i]) == 1;
  REP(i, n) {
    if (!isLeaf[i]) {
      root = i;
      dfs(i, -1);
      break;
    }
  }
  if (can && a[root] == 0) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

