using namespace std;

#define MAX_N 100005
int N;
LL A[MAX_N];
vector<int> Edge[MAX_N];
int EdgeCnt[MAX_N];

void input()
{
  cin >> N;
  for (int i = 0; i < N; i++) {
    cin >> A[i];
  }
  for (int i = 0; i < N-1; i++) {
    int a, b;
    cin >> a >> b; a--; b--;
    Edge[a].push_back(b);
    Edge[b].push_back(a);
    EdgeCnt[a]++;
    EdgeCnt[b]++;

  }
}

LL solve(int pos, int pre = -1)
{
  vector<LL> list;
  LL Sum = 0;
  bool update_flag = false;
  for (int i = 0; i < Edge[pos].size(); i++) {
    if(Edge[pos][i] == pre){
      continue;
    }
    update_flag = true;
    LL tmp = solve(Edge[pos][i], pos);
    if(tmp == -1){
      return -1;
    }
    list.push_back(tmp);
    Sum += tmp;
  }

  if(!update_flag){
    return A[pos];
  }

  if(Sum < A[pos]){
    return -1;
  }

  sort(list.begin(), list.end());

  LL pair_cnt = 0;
  LL geta = 0;
  LL amari = 0;
  for (int i = 0; i < list.size(); i++) {
    LL tmp = list[i] - geta;
    amari += tmp%2;
    pair_cnt += tmp/2 * (list.size() - i);
    geta += (tmp/2)*2;
  }

  pair_cnt += amari/2;

  if(Sum - pair_cnt > A[pos]){
    return -1;
  }

  pair_cnt = Sum - A[pos];

  //cerr << pos << " " << Sum - 2*pair_cnt << endl;
  return Sum - 2*pair_cnt;
}

int main()
{
  input();

  if(N == 2){
    if(A[0] == A[1] && A[0] == 1){
      cout << "YES" << endl;
    }
    else{
      cout << "NO" << endl;
    }
  }

  for (int i = 0; i < N; i++) {
    //cerr << i << " " << EdgeCnt[i] << endl;
    if(EdgeCnt[i] != 1){
      if(solve(i) == 0){
        cout << "YES" << endl;
      }
      else{
        cout << "NO" << endl;
      }
      break;
    }
  }

  return 0;
}

