#define MAX 100001
int A[MAX];
vector<int> v[MAX];

void dfs(int root, int parent) {
    if(v[root].size() == 1) return;

    ll mx = -1, sum = -A[root];
    for(int vv : v[root]) {
        if(vv != parent) {
            dfs(vv, root);
            sum += A[vv];
            if(mx < A[vv]) mx = A[vv];
        }
    }
    if(sum < 0 || A[root] < mx || (A[root]-=sum) < 0) puts("NO"), exit(0);
}

int main(void) {
    int i, n, a, b, root;
    scanf("%d", &n);
