    for(i=0; i<n-1; i++) {
        scanf("%d%d", &a, &b);
        v[a-1].emplace_back(b-1);
        v[b-1].emplace_back(a-1);
    }
    for(root=0; root<n; root++) {
        if(v[root].size() > 1) {dfs(root, -1); break;}
    }
    puts(A[root] ? "NO" : "YES");
    return 0;

}

