ll U[100010];

void dfs(int x, int fa){
	ll sum = 0, mx = 0;
	for(int e : E[x])if(e != fa){
		dfs(e, x);
		sum += U[e];
		mx = max(mx, U[e]);
	}
	if(sz(E[x]) == 1){
		U[x] = A[x];
	}
	else{
		if(A[x] > sum){
			puts("NO");
			exit(0);
		}
		ll temp = 2LL * A[x] - sum;
		if(temp < 0){
			puts("NO");
			exit(0);
		}
		ll match = sum - A[x];
		if(match > sum - mx){
			puts("NO");
			exit(0);
		}
		U[x] = temp;
	}
}

