void dfs(int v, int f = -1) {
    int ct = 0;
    for (int u : g[v]) {
        if (u == f)
            continue;
        ct++;
        dfs(u, v);
    }

    if (ct == 0) {
        val[v] = a[v];
        return;
    }

    vector<ll> w;
    for (int u : g[v]) {
        if (u == f)
            continue;
        w.push_back(val[u]);
    }
    sort(w.begin(), w.end());
    ll sum = 0, sum1 = 0;
    for (int i = 0; i < w.size(); ++i) {
        sum += w[i];
        if (i == w.size()-1) {
            sum1 = sum;
            sum1 -= w[i];
        }
    }

    ll m = sum - a[v];
    if (m > sum1) {
        cout << "NO\n";
        exit(0);
    } if (a[v] - m < 0) {
        cout << "NO\n";
        exit(0);
    }

    val[v] = a[v] - m;
}

