// edge
int cnt, h[maxn];
struct edge
{
    int to, pre;
} e[maxn<<1];
void add(int from, int to)
{
    cnt++;
    e[cnt].pre = h[from];
    e[cnt].to = to;
    h[from] = cnt;
}

int deg[maxn], ok;
LL dfs(int x, int f)
{
    if(deg[x] == 1) return v[x];
    LL ret = v[x] + v[x];
    for(int i = h[x]; i; i = e[i].pre)
    {
        int to = e[i].to;
        if(to == f) continue;
        LL tmp = dfs(to, x);
        if(tmp > v[x]) ok = 0;
        ret -= tmp;
    }
    if(ret > v[x]) ok = 0;
    return ret;
}

int main(void)
{
    int N;
