constexpr static int MAXN = 1e6;

int n;
int64_t A[MAXN];
vector <int> adj[MAXN];

int p[MAXN];
int64_t cnt[MAXN];

void dfs(int u, int prv) {
    p[u] = prv;
    for (int v : adj[u])
        if (v != prv)
            dfs(v, u);
}

bool calc(int u) {
    if (p[u] != -1 && adj[u].size() == 1) {
        cnt[u] = A[u];
        return true;
    }

    vector <int64_t> vals;
    for (int v : adj[u])
        if (p[v] == u) {
            if (!calc(v))
                return false;
            vals.push_back(cnt[v]);
        }

    int64_t total = 0;
    int64_t maxval = 0;
    for (int64_t val : vals) {
        total += val;
        maxval = max(maxval, val);
    }
    int64_t maxpairs = total / 2;
    if (total - maxval < maxval)
        maxpairs = total - maxval;
    if (vals.size() == 1)
        maxpairs = 0;

    // x + y == A[u]
    // 2*x + y == total
    // x = total - A[u]
    int64_t npairs = total - A[u];
    if (npairs < 0 || npairs > maxpairs)
        return false;
    int64_t nextra = A[u] - npairs;
    if (nextra < 0)
        return false;
    cnt[u] = nextra;
    //cout << "u: " << cnt[u] << endl;
    return true;
}

