ll dfs(int v, int p) {
  vector<ll> edges;
  for (int u : G[v]) {
    if (u != p) {
      ll e = dfs(u, v);
      if (e < 0) {
        return -1;
      }
      edges.push_back(e);
    }
  }
  if (edges.empty()) {
    return A[v];
  }
  ll sum = accumulate(edges.begin(), edges.end(), 0ll);
  ll mx = *max_element(edges.begin(), edges.end());
  ll x = 2 * A[v] - sum;
  sum += x;
  mx = max(mx, x);
  if (x < 0 || mx > A[v]) {
    return -1;
  }
  return x;
}

