	long long ret = dat[nod] * 2;
	int ccnt = 0;
	for (auto next : graph[nod]) {
		if (next == par) continue;
		ccnt++;
		long long sub = rec(next, nod);
		if (sub < 0) return -1;
		ret -= sub;
	}
	if (par == -1) {
		if (ccnt == 1) {
			ret -= dat[nod]*2;
			return (-ret == dat[nod]);
		} else {
			return ret == 0;
		}
	}
	if (ccnt == 0)
		return dat[nod];
	return ret;
}

