Graph g;

// 親への辺は何回通るか
int dfs(int v) {
    if (g[v].size() == 0) {
        return a[v];
    } else if (g[v].size() == 1) {
        int c = g[v][0].dst;
        return dfs(c) == a[v] ? a[v] : -1;
    } else {
        vector<int> dfsc;
        int sum = 0;
        for (auto &e : g[v]) {
            int x = dfs(e.dst);
            dfsc.push_back(x);
            sum += x;
        }
        bool ok = true;
        for (auto &x : dfsc) {
            if (x < 0 || a[v] * 2 < x) {
                ok = false;
                break;
            }
        }
        int res = 2 * a[v] - sum;
        if (res < 0 || a[v] * 2 < res) {
            ok = false;
        }
        return ok ? res : -1;
    }
}

bool solve() {
    int r = -1;
    for (int i = 0; i < n; i++) {
        if (g[i].size() != 1) {
            r = i;
            break;
        }
    }
    g = to_rooted_tree(g, r);
    int x = dfs(r);
    return x == 0;
}

