void dfs(int v, int par = -1) {
    int S = 0;
    vector<int> sons;
    for (int to : g[v]) {
        if (to == par) continue;
        sons.push_back(to);
        dfs(to, v);
        S += up[to];
    }
    if (sons.empty()) {
        up[v] = a[v];
        return;
    }
    sort(sons.begin(), sons.end(), [&] (int i, int j) {
        return up[i] < up[j];
    });
    if ((int)sons.size() == 1) {
        if (up[sons[0]] != a[v]) {
            // ya che-to seychas voobshe ne ponyal
            cout << "NO\n";
            exit(0);
        }
        up[v] = up[sons[0]];
    } else {
        if (a[v] > S || 2 * a[v] - S < 0) {
            cout << "NO\n";
            exit(0);
        }
        up[v] = 2 * a[v] - S;
        int new_S = S - up[v];
        int all = 0;
        for (int son : sons) {
            all += max(0LL, up[son] - new_S / 2);
        }
        if (all > up[v]) {
            cout << "NO\n";
            exit(0);
        }
    }
}

