ll dfs(int v, int par, VL &a, VVI &g, bool &good) {
    if (SIZE(g[v]) == 1) {
        return a[v];
    }

    ll lb = 0, ub = 0;
    for (int u : g[v]) if (u != par) {
        ll fromSon = dfs(u, v, a, g, good);

        lb = abs(lb - fromSon);
        ub += fromSon;
    }

    ll res = 2 * a[v] - ub;
    good = good && (res >= 0);

    return res;
}

