	for ( int i = 1; i <= n; i++ ){
		if ( D[i] == 1 ){
			continue;
		}
		vector < LL > val;
		for ( int v : E[i] ){
			val.push_back(a[v]);
		}
		sort(val.begin(),val.end());

		LL sum = 0;
		for ( LL v : val ) sum += v;
		LL fsum = 0;
