					LL m = ( l + r ) / 2;
					if ( fsum + m >= target ) r = m;
					else l = m + 1;
				}

				if ( fsum + l >= target && sum - l >= target ){
					fsum += l;
					sum -= l;
					break;
				}
				ans = 0;
