			// cout << v << " " << fsum << " " << sum << endl;
			if ( fsum >= target && sum >= target ){
				break;
			} 
		}
		if ( fsum < target || sum < target ) ans = 0;
		if ( !ans ) break;
	}


	if ( ans ) yes();
	else no();
	return 0;
}

