const int N = 100000 + 10;
int a[N];

vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

map<pair<lli, lli>, lli> memo;
lli rec(int curr, int prev)
{
  pair<lli, lli> key = make_pair(curr, prev);
  if (memo.count(key)) return memo[key];
  if (is_leaf(curr)) return memo[key] = a[curr];

  vector<lli> v;
  each (next, g[curr]) {
    if (next == prev) continue;
    v.push_back(rec(next, curr));
  }
  sort(v.begin(), v.end());

  lli x = a[curr];
  lli y = accumulate(v.begin(), v.end(), 0LL);
  unless (x <= y) throw "";
  lli z = (y - x);
  unless (x - z == y - 2 * z) throw "";
  return memo[key] = x - z;
}

