bool solve() {
  int n = read<int>();
  vector<int> A(n);
  rep(i, n) A[i] = read<int>();
  vvi E(n);
  rep(i, n-1) {
    int u = read<int>() - 1;
    int v = read<int>() - 1;
    E[u].push_back(v);
    E[v].push_back(u);
  }

  if (n == 2) {
    return A[0] == A[1];
  }

  bool ans = true;
  vl C(n);

  function<void(int, int)> dfs = [&](int cur, int pre) {
    ll sum_c = 0;
    ll c_max = 0;

    forr(nex, E[cur]) {
      if (nex != pre) {
        dfs(nex, cur);
        sum_c += C[nex];
        c_max = max(c_max, C[nex]);
      }
    }

    if (sz(E[cur]) == 1) {
      // 葉の親向き辺を通る数は A[cur] と等しい
      C[cur] = A[cur];
    }
    else {
      // C[cur] は、cur から根方向への辺を通る回数
      C[cur] = 2 * A[cur] - sum_c;
      // 負だとダメ
      if (C[cur] < 0) ans = false;

      // r は、cur の子の間を行き来する回数
      ll r = (sum_c - C[cur]);
      // 奇数ならダメ
      if (r % 2) ans = false;
      // 負はダメ
      if (r < 0) ans = false;

      // 出ている辺を通る数の合計の半分より大きい辺があるとダメ
      if (c_max > (sum_c + C[cur]) / 2) ans = false;
      if (C[cur] > (sum_c + C[cur]) / 2) ans = false;
    }
  };

  rep(i, n) {
    if (sz(E[i]) != 1) {
      // 葉じゃない頂点からdfsする
      dfs(i, -1);
      if (C[i]) return false;
      return ans;
    }
  }
  return false;
}

