#define mod 1000000007

int n;
vector<vector<int> > graph(100001);
vector<bool> ischecked(100001, false);
vector<int> stonenum(100001);

bool cansolve(int node)
{
	if(graph[node].size() == 1) return true;
	ischecked[node] = true;
	int childstonesum = 0;
	int nummax = 0, secondnummax = 0;
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		if(cansolve(child)) {
			childstonesum += stonenum[child];
			if(nummax < stonenum[child]){
				secondnummax = nummax;
				nummax = stonenum[child];
			}
			secondnummax = max(secondnummax, stonenum[child]);
		} else {
			return false;
		}
	}
	if(stonenum[node] > childstonesum) {
		return false;
	} else if(stonenum[node] == childstonesum) {
		return true;
	} else if(stonenum[node] - secondnummax >= childstonesum - 2 * secondnummax){
		stonenum[node] -= childstonesum - stonenum[node];
		return true;
	}
	return false;
}

int main()
{
	cin >> n;
	for(int i = 0; i < n; i++){
		cin >> stonenum[i];
	}
	int a, b;
	for(int i = 0; i < n - 1; i++){
		cin >> a >> b;
		a--;
		b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	int root = 0;
	while(root < n && graph[root].size() == 1) root++;
	ischecked[root] = true;
	int childstonesum = 0;
	for(int i = 0; i < graph[root].size(); i++){
		if(!cansolve(graph[root][i])){
			cout << "NO" << endl;
			return 0;
		} else {
			childstonesum += stonenum[graph[root][i]];
		}
	}
	if(2 * stonenum[root] == childstonesum) cout << "YES" << endl;
	else cout << "NO" << endl;
	// cout << stonenum[0] << endl;
	return 0;
}

