const int N = 100000 + 10;
int a[N];

vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

map<lli, lli> memo;
lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];
  if (memo.count(curr)) return memo[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }
  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return a[curr];
  }
  if (curr == prev) {
    if (sum % 2) throw "";
    each (i, b) {
      if (i > sum / 2) throw "";
    }
    if (a[curr] - sum / 2) throw "";
    return 0;
  }
  lli mx = *max_element(b.begin(), b.end());
  lli mn = min(sum / 2, mx);
  lli x = a[curr] - mn;
  if (x < 0) throw "";
  // each (i, b) cout << i << ' ' ; cout << endl;
  return memo[curr] = x;
}

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    memo.clear();
    fill(g, g + N, vector<int>());
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n - 1; ++i) {
      int a, b;
