void addArc(Graph &g, int s, int d, Weight w = 1) {
    g[s].emplace_back(s, d, w);
}
void addEdge(Graph &g, int a, int b, Weight w = 1) {
    addArc(g, a, b, w);
    addArc(g, b, a, w);
}

int dfs(Graph &g, vi &data, int pos, int bef)
{
    if (g[pos].size() == 1) {
        return data[pos];
    }
    int yui = 0;
    vi cnt;
    for (auto i : g[pos]) {
        if (i.d != bef) {
            cnt.pb(dfs(g, data, i.d, pos));
            yui += cnt.back();
        }
    }
    sort(all(cnt));
    if (cnt[0] < 0) return -1;
    int kyoko = data[pos] * 2 - yui;
    if (min(yui-cnt.back(), yui/2) >= data[pos]) {
        return -kyoko;
    } else {
        return -1;
    }
}

