void solve(){
    i64 n;
    cin >> n;
    vector<i64> a(n);
    rep(i,0,n) cin >> a[i];
    vector<vector<int>> graph(n);
    rep(i,0,n-1){
        i64 a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

