        if(graph[u].size()==1) return true;
        i64 s=0,m=0;
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            s+=a[v]-r[v];
            m=max(m,a[v]-r[v]);
        }
        r[u]=s-a[u];
        if(m>s/2) return 0<=r[u] and r[u]<=s-m;
        else return 0<=r[u] and r[u]<=s/2;
    };

