ll dfs(int cur, int par) {
	if (E[cur].size() == 1) return A[cur];

	ll sm = 0;
	ll ma = 0;
	for (int i : E[cur]) if (i != par) {
		ll r = dfs(i, cur);
		if (r < 0) return -1;
		sm += r;
		ma = max(ma, r);
	}

	ll nxt = 2LL * A[cur] - sm;

	if (sm < A[cur]) return -1;
	if (nxt < 0) return -1;
	if (ma > A[cur] && ma * 2 > sm) return -1;

	return nxt;
}
