    u--; v--;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  if(n == 2){
    println(a[0] == a[1] ? "YES" : "NO");
    return 0;
  }

  int root = -1;
  for(int i=0; i<n; i++){
    if(G[i].size() >= 2){
      root = i;
      break;
    }
  }

  auto res = dfs(G, a, root, -1);

  if(res == 0){
    println("YES");
  }else{
    println("NO");
  }
  return 0;
}

