using namespace std;

llint N;
vector<llint> G[100005];
llint A[100005];

llint dfs(llint v, llint prev)
{
	if(G[v].size() == 1 && G[v][0] == prev) return A[v];

	vector<llint> vec;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		vec.push_back(dfs(G[v][i], v));
		if(vec.back() < 0) return -1;
	}
	sort(vec.begin(), vec.end());

	llint sum = 0, sum2 = 0, pcnt;
	for(int i = 0; i < vec.size(); i++) sum += vec[i];
	sum2 = sum - vec.back();
	sum2 += min(vec.back(), sum2);
	pcnt = sum2/2;
	if(sum - 2*pcnt == A[v] - pcnt) return A[v] - pcnt;
	return -1;
}

