    while(ch-'0'>=0&&ch-'0'<=9){x=x*10+ch-'0';ch=getchar();}
    return x*f;
}
int n;
int a[maxn];
int head[maxn],nxt[maxn*2],to[maxn*2],tot;
void add(int u,int v)
{
    tot++;
    nxt[tot]=head[u];
    head[u]=tot;
    to[tot]=v;
}
int deg[maxn],rt;
ll solve(int x,int las)
{
    if(deg[x]==1)  return a[x];
    int rem=2*a[x];
    for(int i=head[x];i;i=nxt[i])
    {
        if(to[i]==las)  continue;
        ll tmp=solve(to[i],x);
        if(tmp>a[x])
        {
            puts("NO");
            exit(0);
        }
        rem-=tmp;
    }
    if(rem<0||rem>a[x])
    {
        puts("NO");
        exit(0);
    }
    return rem;
}
