      mx = max(temp, mx);
    }
  if (mx > a[x])
    ans = 0;
  if (fa == 0) {
    if (sum != val)
      ans = 0;
    return 0;
  }
  else {
    if (sum > val)
      ans = 0;
    return val - sum;
  }
}

