const int N = 1e5 + 5;
int n;
int arr[N];
long long dif[N];
int a , b;
vector < int > v[N];
long long dfs(int node , int parent){
    dif[node] = arr[node];
    vector < long long > s;
    s.clear();
    long long sum = 0;
    for(int next : v[node]){
        if(next != parent){
            s.push_back(dfs(next , node));
            sum += s.back();
            dif[node] -= arr[next];
        }
    }
    if(v[node].size() == 1){
        return dif[node];
    }
    if(dif[node] > 0){
        printf("NO\n");
        exit(0);
    }
    long long val = -dif[node];
    long long mx = 0;
    long long get;
    for(auto it : s){
        mx = max(mx , it);
    }
    if(mx <= sum - mx){
        get = sum >> 1;
    }
    else{
        get = sum - mx;
    }
    if(val > get){
        printf("NO\n");
        exit(0);
    }
    dif[parent] += val;
    return sum - val * 2;
}
