int main() {
    int N;
    cin >> N;
    vector<i64> A(N);
    for(i64 &x : A) cin >> x;
    vector2d<int> edge(N);
    for(int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        edge[a].push_back(b);
        edge[b].push_back(a);
    }
    int r = -1; // root
    for(r = 0; r < N; r++) {
        if(edge[r].size() == 1) {
            break;
        }
