        else n = 2 * A[i];
        for(int j : edge[i]) {
            if(j == prev) continue;
            i64 x = f(f, i, j);
            if(x > A[i]) ans = false;
            n -= x;
        }
        if(n > A[i]) ans = false;
        return n;
    })(r, r) == 0;
