const int maxn = 100005;
int head[maxn], nxt[maxn << 1], to[maxn << 1], hp = 1;
ll a[maxn];

inline void add(int u, int v) {
	nxt[++ hp] = head[u];
	head[u] = hp;
	to[hp] = v;
}

inline __attribute__((noreturn)) void shit() { puts("NO"); exit(0); }

ll dfs(int u, int fa) {
	if(!nxt[head[u]]) return a[u];

	ll tot = 0, max = 0;

	for(int i = head[u]; i; i = nxt[i])
		if(to[i] != fa) {
			ll x = dfs(to[i], u);
			tot += x;
			max = std::max(max, x);
		}

	ll k = tot - a[u];
	ll K = max >= tot - max ? tot - max : tot >> 1 << 1;
	/* debug("%d : %d %d\n", u, tot, k); */
	if(k < 0 or k > K) shit();

	return tot - (k << 1);
}

int main() {
	int n = read;

	for(int i = 1; i <= n; i ++)
		read(a[i]);

	if(n == 1) return puts(a[1] ? "NO" : "YES"), 0;

	for(int i = 1; i < n; i ++) {
		int u = read, v = read;
		add(u, v);
		add(v, u);
	}

	int root = 1;
	while(!nxt[head[root]])
		++ root;

	if(!dfs(root, 0)) puts("YES");
	else puts("NO");
}

