void make_family(int p, int now) {
  parent[now] = p;
  for (int i = 0; i < G[now].size(); i++) {
    if (G[now][i] == p) {
      continue;
    }
    int ch = G[now][i];
    child[now].push_back(ch);
    make_family(now, ch);
  }
  return;
