bool dfs(int p, int now) {
  if (child[now].size() == 0) {
    pathnum[now] = a[now];
    childpathnum[p] += pathnum[now];
    childpathnummax[p] = max(childpathnummax[p], pathnum[now]);
    return true;
  }
  for (int  i = 0; i < child[now].size(); i++) {
    if (!dfs(now, child[now][i])) {
      return false;
    }
  }
  pathnum[now] = 2 * a[now] - childpathnum[now];
  childpathnum[p] += pathnum[now];
  childpathnummax[p] = max(childpathnummax[p], pathnum[now]);

  if (pathnum[now] < 0) {
