const int maxn = 1e5 + 10;

struct Edge
{
	Edge *next;
	int to;
} pool[maxn * 2], *p = pool, *head[maxn];

void AddEdge(int fr, int to)
{
	p->to = to;
	p->next = head[fr];
	head[fr] = p ++;
}

LL a[maxn], d[maxn], f[maxn];

bool Dfs(int u, int fa)
{
	if (d[u] == 1)
	{
		f[u] = a[u];
		return true;
	}
	LL s = 0;
	int cnt = 0;
	for (Edge *t = head[u]; t; t = t->next)
	{
		int v = t->to;
		if (v == fa) continue;
		if (!Dfs(v, u)) return false;
		s += f[v];
		cnt += f[v] != 0;
	}
	if (cnt == 1)
	{
		if (a[u] != s) return false;
		f[u] = a[u];
	}
	else
	{
		f[u] = a[u] * 2 - s;
		if (f[u] < 0 || f[u] > a[u]) return false;
	}
	return true;
}

