bool dfs(int u, int p)
{
  // 葉は必ず貫いて通過する
  if(G[u].size() == 1) {
    dp[u] = A[u];
    return true;
  }

  for(int& v : G[u]) {
    if(v == p) continue;
    if(!dfs(v, u)) return false;
  }

  int sum = 0;
  for(int& v : G[u]) {
    if(v != p) sum += dp[v];
  }

  // uを貫いて通過するか折り返すかの2通り

  if(sum < A[u] || sum > 2*A[u]) return false;

  dp[u] = 2*A[u] - sum;

  int mx = 0;
  for(int& v : G[u]) {
    if(v != p) mx = max(mx, dp[v]);
  }

  if(A[u] < mx) return false;
  return true;
}

