ll dfs(int idx, int p) {
	if (g[idx].size() == 1) return a[idx];

	ll sum = 0;
	ll c_max = 0;
	for (int nex : g[idx]) {
		if (nex == p) continue;
		ll tmp = dfs(nex, idx);
		if (tmp == -1) return -1;
		sum += tmp;
		c_max = max(c_max, tmp);
	}

