	for(int i = 1;i <= n;i++)
	{
		if(edges[i].size() == 1)
		{
			leave.push_back(i);
		}
	}
}

vector<int> topolo[100010];

vector<int> deeper;

void get_topolo()
{
	vector<bool> vec(n + 1,false);
	queue<int> que;

	for(int l : leave)
	{
		que.push(l);
	}

	while(!que.empty())
	{
		int v = que.front();
		que.pop();

		if(vec[v]) continue;
		vec[v] = true;
		deeper.push_back(v);

		for(int to : edges[v])
		{
			if(vec[to] == false)
			{
				topolo[to].push_back(v);
				que.push(to);
			}
		}
	}
}

bool solve()
{
	for(int v : deeper)
	{
		//cout << v << ":";
		//leaf
		if(topolo[v].size() == 0)
		{
		}
		else if(topolo[v].size() == 1)
		{
			int chi = topolo[v][0];
			if(a[chi] != a[v])
			{
				////cout << a[v] << "=" << a[chi] << endl;
				return false;
			}
		}
		else
		{
			//can solve self
			i64 sum = 0;

			i64 path;
			i64 MAX = 0;


			for(int chi : topolo[v])
			{
				sum += a[chi];
				MAX = max(MAX , a[chi]);
			}

			path = min(MAX , sum / 2);





			//cout << endl << "sum" << sum << endl;

			i64 x = 2 * a[v] - sum;

			i64 y = a[v] - x;

			//cout << "x=" << x << endl;
			//cout << "y=" << y << endl;

			if(x < 0 || y < 0) return false;

			if(path < y) return false;



			a[v] = x;

			if(deeper[deeper.size() - 1] == v)
			{
				if(x != 0)
				{
					return false;
				}
			}
		}
		////cout << a[v] << endl;
	}
	return true;
}

