int n,now,a[N],v[M],b[N],nex[M],head[N];
void addedges(int x,int y){
	nex[++now]=head[x];
	head[x]=now,v[now]=y;
}
long long dfs(int x,int fa){
	long long res=0,mx=0;
	if(b[x]==1)	return a[x];
	for(int i=head[x];i;i=nex[i])
		if(v[i]!=fa){
			long long k=dfs(v[i],x);
			res+=k,mx=max(mx,k);
		}
	int up=(a[x]*2-res);
	if(up<0||up>a[x]||a[x]<mx){
		puts("NO");
		exit(0);
	}
	return up;
}
