using namespace::std;

vector< vector<int> > Gra;
map<pair<int,int>,LL> Edge;//辺の値
vector<LL> A;
vector<bool> use;

bool dfs(int v){
	use[v] = true;
	int size = Gra[v].size();
	if( size == 1 ){
		pair<int,int> temp;
		int to = Gra[v][0];
		temp.first = v;
		temp.second = to;
		if( temp.first > temp.second ){
			swap(temp.first, temp.second);
		}

		if( Edge.find(temp) != Edge.end() ){//値が設定済み
			LL res = Edge[temp];
			if( A[v] != res ){
				return false;
			}
		}else{
			Edge[temp] = A[v];
		}
		if( use[to] ){
			return true;//
		}else{
			return dfs( to );
		}
	}
	//子が複数
	LL EdgeSum = 0;//辺の値の総和
	pair<int,int> temp;
	int Root = -1;
	LL E_max = 0;//辺の値の最大値。
	for(int i=0;i<size;++i){
		int to = Gra[v][i];
		if( use[to] ){
			Root = to;//
			continue;//巡回済み
		}
		bool Bres = dfs( to );
		if( Bres == false ) return false;
		temp.first = v;
		temp.second = to;
		if( v > to ){
			swap(temp.first,temp.second);
		}
		LL Eval = Edge[temp];//行って帰ってくるので、値がある
		E_max = max(E_max, Eval);
		EdgeSum += Eval;
	}
	if( Root != -1 ){//子に巡回済みが1点あった。それは親
		//親とvとの辺の値を決定する。
		temp.first = v;
		temp.second = Root;
		if( v > Root ){
			swap(temp.first, temp.second);
		}
		//子が複数あるので、A[v]*2 = Σ子との辺 :=2回(入って出る)
		LL res = 2*A[v] - EdgeSum;//EdgeSumは他の辺の値の総和
		if( res < 0 ) return false;
		E_max = max(E_max,res);
		//
		if( Edge.find(temp) != Edge.end() ){//値が設定済み
			if( res != Edge[temp]){
				return false;
			}
		}else{
			Edge[temp] = res;//
		}
	}else{//子に巡回済みの頂点がなかった
		LL res = EdgeSum - 2*A[v];
		if( res != 0 ){
			return false;
		}
	}
	//頂点vへ接続する辺を通る回数が全て分かった。
	//別方向へのペアを作るために、
	//各辺の値は、最大値2*A[v]の半分以下になる必要がある。
	if( E_max > A[v] ){
		return false;
	}
	return true;
}
void solve(){
	int N;
	cin >> N;
	Gra = vector< vector<int> >(N);
	A = vector<LL>(N);
	use = vector<bool>(N,false);//dfsで使用
	for(int i=0;i<N;++i){
		cin >> A[i];
	}
	for(int i=0;i<(N-1);++i){//グラフは木
		int v,u;
		cin >> v >> u;
		--v;--u;
		Gra[v].push_back(u);
		Gra[u].push_back(v);
	}

	if( dfs(0) ){
		cout << "YES" << endl;
	}else{
		cout << "NO" << endl;
	}
}
