typedef long long ll;

int N;
list<int> edges [100001];

ll dfs(int curr,int prev,bool& ans,vector<ll>& A)
{
	ll res = 0;
	int children = 0;
	for(const auto& it : edges [curr]) if(it != prev){
		res += dfs(it,curr,ans,A);
		children++;
	}
	if(children == 0){
		return A [curr];
	}
	if(children == 1){
		ans &= res == A [curr];
		return res;
	}
	if(res < A [curr] || A [curr] * 2 - res < 0){
		ans = false;
		return 0;
	}
	return A [curr] * 2 - res;
}

