int a[100010], dp[100010], ans, root;

int dfs(int v, int p) {
  if(g[v].size() == 1) {
    dp[v] = a[v];
    return a[v];
  }
  int res = 0, ma = 0;
  for(int i: g[v]) {
    if(i == p) continue;
    int tmp = dfs(i, v);
    res += tmp;
    chmax(ma, tmp);
  }
  if(ma*2 > res) {
    int lim = res-ma;
    // cout << "lim:" << lim << " " << res-a[v] << endl;
    if(res-a[v] > lim) ans = -1;
    return 0;
  }
  if(v == root) {
    if(res%2 || res/2!=a[v]) ans = -1;
    return 0;
  }
  if(res < a[v] || 2*a[v] < res) {
    ans = -1;
    return 0;
  }
  return dp[v] = 2*a[v] - res;
}

