ll dfs() {
	vector<int> ord(N);

	stack<int> s;
	s.push(root);
	par[root] = -1;
	int cnt = 0;

	while (!s.empty()) {
		int pos = s.top();
		s.pop();
		ord[cnt] = pos;
		cnt++;
		rep(i, T[pos].size()) {
			if (T[pos][i] == par[pos])continue;
			par[T[pos][i]] = pos;
			s.push(T[pos][i]);
		}
	}

	reprev(i, N) {
		int p = ord[i];
		if (T[p].size() == 1) {
			num[p] = A[p];
		}
		else {
			ll sum = 0;
			rep(i, T[p].size()) {
				if (T[p][i] == par[p])continue;
				sum += num[T[p][i]];
			}
			if (2 * A[p] - sum < 0 || (p != root && 2 * A[p] - sum == 0))return -1;
			if (p != root && T[p].size() == 2) {
				int child = (T[p][0] == par[p] ? T[p][1] : T[p][0]);
				if (A[p] == A[child]) {
					num[p] = A[p];
				}
				else {
					return -1;
				}
			}
			else {
				num[p] = 2 * A[p] - sum;
			}
		}
	}
	return num[root];
}

