#include <bits/stdc++.h>

using namespace std;
typedef long long int lli;

const int MAXN = 100010;

int n;

int v[MAXN];

lli dp[MAXN];

bool hasAnswer = true;

vector< int > adj[MAXN];

void DFS(int cur, int p)
{
	if( adj[cur].size() == 1 )
	{
		dp[cur] = v[cur];
		return;
	}

	lli mx = -1;
	lli sum = 0;

	for(int i = 0 ; i < adj[cur].size() ; i++)
	{
		int viz = adj[cur][i];

		if( viz == p ) continue;

		DFS( viz , cur );

		sum += dp[viz];
		mx = max( mx , dp[viz] );
	}

	lli remain;
	lli qtdPairs;

	if( sum >= 2*mx )
	{
		remain = sum%2;
		qtdPairs = sum/2;
	}
	else
	{
		remain = 2*mx - sum;
		qtdPairs = sum - mx;
	}

	lli diff = v[cur] - (qtdPairs + remain);

	if( diff < 0 ) hasAnswer = false;

	qtdPairs -= diff;
	remain += 2*diff;

	dp[cur] = remain;
}

int main()
{
	scanf("%d",&n);

	for(int i = 1 ; i <= n ; i++)
		scanf("%d",&v[i]);

	for(int i = 1 ; i < n ; i++)
	{
		int U, V;
		scanf("%d %d",&U,&V);

		adj[ U ].push_back( V );
		adj[ V ].push_back( U );
	}

	if( n == 2 )
	{
		if( v[1] == v[2] ) printf("YES\n");
		else printf("NO\n");

		return 0;
	}

	int root;

	for(int i = 1 ; i <= n ; i++)
		if( adj[i].size() > 1 ) root = i;

	DFS( root , root );

	if( dp[root] != 0 ) hasAnswer = false;

	if( !hasAnswer ) printf("NO\n");
	else printf("YES\n");
}

