vector<int> G[100010];
typedef pair<ll, ll> P;
ll A[100010];
bool ok[100010];

P f(int v, int p) {
	if(G[v].size() == 1) {
		ok[v] = 1;
		return{ A[v], A[v] };
	}

	vector<P> r;
	for(auto c : G[v]) {
		if(c == p) continue;
		P res = f(c, v);
		if(res.first == -1) return{ -1, -1 };
		r.push_back(res);
	}
	sort(r.begin(), r.end());

	P ret(-1, A[v]);
	ll min_sum = 0, max_sum = 0;
	for(int i = 0; i < r.size(); i++) {
		min_sum += r[i].first;
		max_sum += r[i].second;
	}
	if(p == -1) {
		if(r.back().first > max_sum - r.back().second) {
			return{ -1, -1 };
		}
		A[v] *= 2;
	}
	if(A[v] < min_sum || max_sum < A[v]) {
		return{ -1, -1 };
	}

	ret.first = A[v] % 2;
	if(r.back().first > max_sum - r.back().second) {
		ret.first = r.back().first -( max_sum - r.back().second);
	}
	ok[v] = 1;
	return ret;
}

