void add(int x , int y) {
  ne[++ cnt] = fir[x];
  fir[x] = cnt;
  to[cnt] = y;
  ++ du[x];
}

void link(int x , int y) {
  add(x , y);
  add(y , x);
}

#define Foreachson(i , x) for(int i = fir[x];i;i = ne[i])

int st[N][22] , dep[N];

int LCA(int x , int y) {
  if(x == y) return x;
  if(dep[x] > dep[y]) swap(x , y);
  for(int i = 20;i >= 0;-- i) if(dep[st[y][i]] >= dep[x]) y = st[y][i];
  if(x == y) return x;
  for(int i = 20;i >= 0;-- i) if(st[x][i] != st[y][i]) x = st[x][i] , y = st[y][i];
  return st[x][0];
}

void dfs(int x , int f) {
  dep[x] = dep[f] + 1;
  st[x][0] = f;
  for(int i = 1;i <= 20;++ i)
    st[x][i] = st[st[x][i - 1]][i - 1];
  Foreachson(i , x) {
    int V = to[i];
    if(V == f)
      continue;
    A[x] -= A[V];
    dfs(V , x);
  }
}

#define Cannot exit(puts("NO") * 0)

void calc(int x , int f) {
  if(du[x] == 1) {
    dp[x] = A[x];
    return;
  }

  if(A[x] > 0) {
    Cannot;
  }

  vector <int> cxt;
  cxt.clear();

  Foreachson(i , x) {
    int V = to[i];
    if(V == f)
      continue;
    calc(V , x);
    cxt.push_back(dp[V]);
  }
  sort(cxt.begin() , cxt.end());
  int now = 0;
  for(int i = 0;i < (int) cxt.size() - 1;++ i) {
    now = now + cxt[i];
  }
  if(now + cxt.back() >= (-A[x]) * 2 && now >= (-A[x])) {
    dp[x] = now + cxt.back() + A[x] * 2;
  }
  else Cannot;
}

