bool dfs(int x,int p)
{
	if(ve[x].size()==1)return 1;
	ll sum=0;
	int mx=0;
	for(int i=0;i<ve[x].size();i++)
	{
		int &y=ve[x][i];
		if(y==p)continue;
		if(!dfs(y,x))
