			return 0;
		}
		sum+=ar[y];
		mx=max(mx,ar[y]);
	}

	if(sum<ar[x])return 0;

	int t=sum-ar[x];
	ar[x]-=t;
	if(ar[x]<0)return 0;

	if(t && mx>t)return 0;

	if(p==0)return ar[x]==0;
	return 1;
}

