vector<vi> tree;
vi a;

ll bfs(int v)
{
	if (tree[v].size() == 0) return a[v];
	ll cnt = 0;
	ll mx = 0;
	for (auto u : tree[v])
	{
		ll tmp = bfs(u);
		if (tmp == -1) return -1;
		cnt += tmp;
		chmax(mx, tmp);
	}
	if (a[v] > cnt || a[v] * 2 < cnt || mx > a[v]) return -1;
	int res = a[v] - (cnt - a[v]);
	return res;
}

