int n, a[N];
vector < int > g[N];

ll dfs(int v, int p = -1) {
  vector < ll > now;
  ll x = a[v];
  ll y = 0;
  for (auto to : g[v]) {
    if (to != p) {
      ll tmp = dfs(to, v);
      y += tmp;
      now.pb(y);
    }
  }
  if (now.size() == 0) return x;
  ll z = y - x;
  sort(now.begin(), now.end());
  for (int i = 0;i + 1 < now.size();i++) {
    if (z == 0) break;
    ll cur = min(now[i], z);
    x -= cur;
    y -= cur;
    z -= cur;
    now[i] -= cur;
    now[i + 1] -= cur;
  }
  if (z > 0) {
    cout << "NO\n";
    exit(0);
  }
  return x;
}
