//似乎有点毒瘤的样子。。

struct Edge {
    int v, nxt;
} E[MX * 2];
int Head[MX], erear;
void edge_add(int u, int v) {
    E[erear].v = v;
    E[erear].nxt = Head[u];
    Head[u] = erear++;
}
void edge_init() {
    erear = 0;
    memset(Head, -1, sizeof(Head));
}

int n, IN[MX];
int A[MX], ok = 1;

void DFS(int u, int f) {
    LL sum = 0;
    int Max = 0, child = 0;
    for(int i = Head[u]; ~i; i = E[i].nxt) {
        int v = E[i].v;
        if(v == f) continue;
        DFS(v, u);
        sum += A[v];
        Max = max(Max, A[v]);
        child++;
    }
    if(!child) return;

    LL x = sum - A[u], y = 2LL * A[u] - sum;
    LL opt = min(sum - Max, sum / 2);

    if(x < 0 || y < 0 || x > opt) {
        ok = 0; return;
    }
    A[u] = y;
}

