            s += vl;
            cnt++;
        }
    }

    sort(vals.rbegin(), vals.rend());
    if (s < vec[v]) {
        ret[v] = INF;
        return INF;
    }
    ll mn = 0;
    if (vals[0] <= (s - vals[0])) {
        mn = s / 2 + (s % 2);
    }
    else {
        ll lft = vals[0] - (s - vals[0]);
        mn = (s - vals[0]) + lft;
    }


    if (mn > vec[v]) {
        ret[v] = INF;
        return INF;
    }

    ll dif = s - vec[v];
    ll needed = s - dif * 2;

    ret[v] = needed;
    return needed;
}
