const int MAX_N = 100000;

int N;
vector<int> G[MAX_N];
ll a[MAX_N];

ll dfs(int v, int par = -1) {
    ll down, down_max, down_sum;

    if (G[v].size() == 1) {
        if (par == -1) {
            return (dfs(G[v][0], v) == a[v] ? 0 : -1);
        } else {
            return a[v];
        }
    }

    down_max = 0;
    down_sum = 0;
    for (int to : G[v]) {
        if (to == par) {
            continue;
        }
        down = dfs(to, v);
        if (down == -1) {
            return -1;
        }
        down_max = max(down_max, down);
        down_sum += down;
    }
    if (a[v] < max(down_max, down_sum / 2)) {
        return -1;
    }
    return 2 * a[v] - down_sum;
}

