		else printf("NO\n");

		return 0;
	}

	int root;

	for(int i = 1 ; i <= n ; i++)
		if( adj[i].size() > 1 ) root = i;

	DFS( root , root );

	if( dp[root] != 0 ) hasAnswer = false;

	if( !hasAnswer ) printf("NO\n");
	else printf("YES\n");
}

