vector<int> g[N];

int dfs(int cur, int p) {
	int sm = 0;
	vector<int> sn;
	for (auto t : g[cur]) {
		if (t != p) {
			int v = dfs(t, cur);
			sm += v;
			sn.push_back(v);
		}
	}
	if (sn.empty()) {
		return a[cur];
	}
	int tot = 0;
	for (auto t : sn) {
