ll const MAX = 200005;
ll a[MAX];
vll G[MAX];
ll parent[MAX]={};
ll ord[MAX];

void bfs(ll n) {
	queue<ll> qu;
	qu.push(1);
	parent[1] = 1;
	ll cnt = 1;
	while (!qu.empty()) {
		ll cur = qu.front();
		qu.pop();
		ord[cnt] = cur;
		cnt++;
		REP(i, 0, SIZE(G[cur]) - 1) {
			ll next = G[cur][i];
			if (parent[next] != 0)continue;
			parent[next] = cur;
			qu.push(next);
		}
	}
}

bool judge(ll i, ll n) {
	if (i != 1 && SIZE(G[i]) == 1) {
		return true;
	}
	ll c = 0;
	ll max_c = 0;
	REP(j, 0, SIZE(G[i]) - 1) {
		ll chi = G[i][j];
		if (chi != parent[i]) {
			c += a[chi];
			max_c = max(max_c, a[chi]);
		}
	}
	ll s, t;
	s = c - a[i];
	t = a[i] - s;
	if (s < 0 || t < 0) return false;
	if (s > min(c - max_c, c / 2)) return false;
	a[i] = t;
	return true;
}

