bool dfs(int now, int pre) {
    bool res = true;
    int cstone = 0;
    int child = 0;
    int mx = 0;
    for (int nxt : edge[now]) {
        if (nxt == pre) continue;
        res &= dfs(nxt, now);
        child++;
        cstone += A[nxt];
        mx = max(A[nxt], mx);
    }
    if (child == 0) return true;
    if (child == 1) return (A[now] == cstone);
    if (child >= 2) {
        if (cstone > A[now]*2) res = false;
        if (cstone < A[now]) res = false;
        if (cstone - A[now] > cstone-mx) res = false;
        A[now] -= (cstone - A[now]);
        return res;
    }
    return res;
}

