using namespace std;

int N;
VI A;
vector<VI> G;
vector<bool> searched;

int get_path_num(int v) {
  searched[v] = true;
  int c_sum = 0;
  int c_max = 0;
  int number_of_child = 0;
  REP(i, G[v].size()) {
    int child = G[v][i];
    if (!searched[child]) {
      number_of_child++;
      int tmp = get_path_num(child);
      if (tmp == -1) return -1;
      if (tmp > c_max) c_max = tmp;
      c_sum += tmp;
    }
  }
  if (number_of_child == 0) {
    return A[v];
  } else if (number_of_child == 1) {
    if (c_sum == A[v]) return c_sum;
    else return -1;
  } else {
    int c = 2 * A[v] - c_sum;
    int both = c_sum - A[v];
    int max_both;
    if (c_max > c_sum / 2) {
      max_both = c_sum - c_max;
    } else {
      max_both = c_sum / 2;
    }
    if (c < 0 || both < 0 || max_both < both) return -1;
    return c;
  }
}

void solve() {
  if (get_path_num(0) >= 0) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
}

