long long dfs(long long u, long long p){
	if(adj[u].size() == 1) return arr[u];
	long long rope = 0;
	for(long long v : adj[u]){
		if(v == p) continue;
		rope += dfs(v, u);
	}
	if(rope < arr[u]){
