bool cansolve(int node)
{
	if(graph[node].size() == 1) return true;
	ischecked[node] = true;
	long long int sum = 0;
	long long int pairnum = 0, rest = 0;
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		if(cansolve(child)) {
			sum += stonenum[child];
			if(rest > 0) {
				pairnum += max(rest, stonenum[child]);
				rest = abs(rest - stonenum[child]);
			} else {
				rest = stonenum[child];
			}
		} else {
			return false;
		}
	}
	if(stonenum[node] > sum) {
		return false;
	} else if(stonenum[node] == sum) {
		return true;
	} else if(sum - stonenum[node] <= pairnum){
		stonenum[node] -= sum - stonenum[node];
		return true;
	}
	return false;
}

