i64 dfs(int v,int f){
  i64 MAX = -1;
  i64 SUM = 0;
  for(int to : edges[v]){
    if(f != to){
      i64 dp = dfs(to,v);

      if(dp == -1) return -1;
      MAX = max(MAX,dp);
      SUM += dp;
    }
  }

  if(MAX == -1){
    return A[v];
  }

  cout << space(v) << space(SUM) << space(A[v]) << endl;

  if(f == -1){
    return SUM / 2 == A[v];
  }
  i64 Y = SUM - A[v];
  i64 X = A[v] - Y;

  i64 able = SUM / 2;
  if(MAX > able){
    able = SUM - MAX;
  }

  if(!(X >= 0 && Y >= 0 && able >= Y)){
    return -1;
  }

  return X;
}

