		g[a].push_back(Edge(a,b,0));
		g[b].push_back(Edge(b,a,0));
	}
	ll ans=solve(0,0);
	if(ans==0 && !dame)
		cout << "YES" << endl;
	else
		cout << "NO" << endl;
	return 0;
}

