ll a[100001];
VI e[100001];
bool f = true;

ll dfs(int now, int past){
    ll sum = 0;
    if (e[now].size() == 1) return a[now];
    ll ma = 0;
    REP(i,e[now].size()){
        int next = e[now][i];
        if (next == past) continue;
        ll x = dfs(next, now);
        sum += x;
        ma = max(ma, x);
    }
    ll ret = 2*a[now] - sum;
    if (a[now] < ma) f = false;
    if (ret < 0 || ret > sum) f = false;
    // printf("now %d a %d sum %lld\n", now, a[now], sum);
    return ret;
}

