int N;
vector<ll> A;
vector<int> G[100005];

ll dfs(int v, int p){
  if(p!=-1 && G[v].size() == 1) return A[v];

  ll sum = 0;
  vector<ll> c;
  rep(i,G[v].size()){
    if(G[v][i] == p) continue;
    ll res = dfs(G[v][i], v);
    if(res<0 || res > A[G[v][i]]) return -INF;
    sum += res;
    c.push_back(res);
  }
  if(c.size() == 1) return c[0];

  ll T = 2LL*A[v] - sum;
  if(T<0 || T>A[v]) return -INF;

  sum += T;
  rep(i,c.size()){
    if(c[i] > sum/2) return -INF;
  }
  return T;
}


