vector<bool> isVisited;

int maxpair(vector<int> &v){
    if(v.size() <= 2) return 0;

    sort(v.begin(), v.end());

    int sm = 0;
    for(int i=0; i<v.size()-1; i++) sm+=v[i];
    int mx = v.back();
    if(sm >= mx) return (sm+mx)/2;
    else return sm;
}

int dfs(int s){
    isVisited[s] = true;

    int cnt = 0;
    int num = 0;
    vector<int> v;
    for(int t : G[s]){
        if(isVisited[t]) continue;
        num++;
        B[t] = dfs(t);
        cnt += B[t];
        v.push_back(B[t]);
    }
    if(num==0) return A[s];
    int a=2*A[s]-cnt, b=cnt-A[s];
    int maxb = maxpair(v);
    if(a < 0 || b < 0 || b > maxb) return -1;
    return a;
    /*
    a: child -> parent
    b: child -> child
    cnt: from children
    a+2*b=cnt
    A=a+b
    ->a+2*(A-a)=cnt
    ->-a+2A=cnt
    ->a=2A-cnt
    ->b=A-a=cnt-A
     */
}

