vector<int> adjlist[100005];

long long dfs(int x, int p) {
	long long sum = 0;
	for (int i = 0; i < adjlist[x].size(); i++) {
		if (adjlist[x][i] == p) continue;
		sum += dfs(adjlist[x][i], x);
	}
	node_val[x] = A[x] - sum;
	return A[x];
}

long long dfs2(int x, int p) {
	if (adjlist[x].size() == 1) return node_val[x];
	else {
		if (node_val[x] > 0) {
			printf("NO\n");
			exit(0);
		}
	}
	long long cap = -node_val[x];
	long long act_cap = cap;
	if (p != -1) act_cap = min(act_cap, -node_val[p]);
	long long sum = 0;
	for (int i = 0; i < adjlist[x].size(); i++) {
		if (adjlist[x][i] == p) continue;
		sum += dfs2(adjlist[x][i], x);
	}
	long long use = min(sum / 2, act_cap);
	node_val[x] += use;
	if (p != -1) node_val[p] += use;
	else target += use;
	return sum - use * 2;
}

