using namespace std;
bool dfs(auto& G, auto& A, auto& C, auto cur, auto pre) {
  auto sum = 0;
  auto child = 0;
  for(auto e: G[cur]) if(!C.count(e.to)) if(e.to != pre) {
    ++child;
    sum += A[e.to];
    if(!dfs(G, A, C, e.to, cur)) return false;
  }
  if(child == 0) return true;
  if(C.count(cur)) return true;
  return child==1 ? A[cur]==sum : A[cur]==2*sum;
}
bool ok(auto& G, auto& A) {
  set<Vertex> C;
  for(auto v: centroid(G)) C.emplace(v);
  for(auto v: C) if(!dfs(G, A, C, v, -1)) return false;
  if(C.size() == 1) {
    auto v = *begin(C);
    auto sum = 0;
    for(auto e: G[v]) sum += A[e.to];
    return 2*A[v] <= sum;
  }
  auto u = *begin(C), v = *rbegin(C);
  auto su = 0, sv = 0;
  for(auto e: G[u]) if(e.to != v) su += A[e.to];
  for(auto e: G[v]) if(e.to != u) sv += A[e.to];
  auto s = min(su, sv);
  auto a = max(A[u], A[v]);
  return 2*a <= s;
}
