using namespace std;
using namespace boost;

int64_t dfs(const vector<vector<int64_t>>& links, const vector<int64_t>& a, int64_t current, int64_t parent) {
  if (links[current].size() == 1 && parent >= 0) {
    return a[current];
  }

  vector<int64_t> tmp;
  int64_t s = 0;
  for (auto v : links[current]) {
    if (v == parent) {
      continue;
    }
    tmp.push_back(dfs(links, a, v, current));
    if (tmp.back() < 0) {
      return -1;
    }
    s += tmp.back();
  }

  int64_t m = a[current];
  int64_t k = s - m;
  if (k < 0 || k > m || 2 * k > s) {
    return -1;
  }

  auto ret = m - k; // = 2 * m - s
  sort(tmp.begin(), tmp.end());
  while (!tmp.empty()) {
    auto x = tmp.back();
    s -= x;
    tmp.pop_back();
    if (x >= s) {
      if (s >= k) {
        return ret;
      } else {
        return -1;
      }
    }
    if (k < x) {
      return ret;
    }
    k -= x;
  }

  assert(false);
  return -1;
}

