		if(!comp(u, cur)) return false;
	}
	if(g[cur].size() == 1) return true;

	//non-leaf node
	int sum = 0, high = INT_MIN;
	for(int u: g[cur]){
		if(u == par) continue;
		sum += a[u];
		//cout<<"SUM "<<sum<<" "<<u<<endl;
		high = max(high, a[u]);
	}
	//cout<<"CUR "<<cur<<" "<<a[cur]<<" "<<sum<<" "<<a[g[cur][0]]<<" "<<a[g[cur][1]]<<endl;
	if(a[cur] > sum){
		pos = false; return false;
	}
	int internal = sum - a[cur];
	int out = a[cur] - internal;
	if(internal > sum - high){
		pos = false; return false;
	}
	a[cur] = out;
	for(int u: g[cur]){
		if(u == par) continue;
		a[u] = 0;
	}
	return true;
}

