LL F(int at, int par) {
	if (V[at].size() == 1) {
		// leaf
		return A[at];
	}

	LL sum = 0;
	LL mx = 0;
	for (int u : V[at]) {
		if (par != u) {
			LL z = F(u, at);
			sum += z;
			mx = MAX(mx, z);
		}
	}

	LL P = mx;
	LL Q = sum - mx;
	LL ret = 0;
	if (P > Q) {
		ret += P - Q;
		A[at] -= P - Q;
		P = Q;
		mx = P;
		sum = 2 * Q;
	}

	if (sum % 2) {
		ret++;
		A[at]--;
		sum--;
	}

	if (A[at] < 0) {
		flag = 0; return 0;
	}
	LL ex = 2 * A[at] - sum;
	if (ex < 0 || A[at] > sum) {
		flag = 0;
		return 0;
	}

	ret += ex;
	if (par == -1) {
		if (ret) flag = 0;
		return 0;
	}

	return ret;
}

int solve(int nl) {
	int f = F(nl, -1);
	return flag;
}

