void tdfs(int v){
	ll sum = 0LL;
	if(T[v].c.empty()){
		T[v].w = A[v];
		return;
	}
	for(int c : T[v].c) if(T[c].w == -1){
		tdfs(c);
		sum += T[c].w;
	}
	T[v].w = 2LL*A[v] - sum;
}

