void cdfs(int v){
	if(T[v].c.empty())return;
	ll sum = 0LL;
	ll maxc = 0LL;
	for(int c : T[v].c){
		cdfs(c);
		sum += T[c].w;
		maxc = max(maxc,T[c].w);
	}
	ll L = (sum-T[v].w)/2LL;
	ll ps = min(sum/2LL,sum-maxc);
	if(ps < L)C = false;
}

