    {
        if(A[1] == A[2])printf("YES\n");
        else printf("NO\n");
        return 0;
    }
    for(int i = 1; i <= N; i++)
    {
        if(G[i].size() > 1)
        {
            root = i;
            DFS(i,-1,0);
            break;
        }
