	if(sum % 2){
		vec.back()--;
		mx = max(vec.back(), vec[vec.size()-2]);
	}
	if(vec.size() == 2) kmax = min(vec[0], vec[1]);
	else{
		if(mx >= sum/2){
			kmax = sum - mx;
			if(sum % 2) kmax--;
		}
		else kmax = sum/2;
	}

	int k = sum - a[v];
	if(k <= kmax) return sum - 2*k;
	else return -1;
