using int64 = long long;

const int MAXN = 200000;

static int64 A[MAXN];
static vector<int> tree[MAXN];

int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    int64 sum = 0,
          max_c = 0;

    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
        if (child < 0) return -1;
        sum += child;
        max_c = max(max_c, child);
    }
    if (sum < A[v]) return -1;
    int64 T = 2 * A[v] - sum;
    // (sum - T) / 2回
    if ((sum - T) / 2 > min(max_c, sum / 2)) {
        return -1;
    }

    return T;
}

