using namespace std;

typedef pair<int,int>P;

const int MAX_N = 100000;

int a[MAX_N];
vector<int> G[MAX_N];
bool flag = false;
int n;

ll dfs(int p,int r)	//p:現在いる頂点,r:親の頂点
{
	if(G[p].size() == 1){	//葉なら
		return a[p];
	}
	ll sum = 0;
	ll maxa = -1;
	rep(d,G[p].size()){
		if(G[p][d] == r){
			continue;
		}
		ll u = dfs(G[p][d],p);
		if(flag == true){
			return 0;
		}
		sum += u;
		maxa = max(maxa,u);
	}
	ll rem = a[p]*2-sum;
	ll L = (sum - rem)/2;
	if(L > min(maxa,sum/2) || L < 0){
		flag = true;
		return 0;
	}
	return rem;
}

bool solve()
{
	if(n==2){
		return a[0] != a[1];
	}
	int r = -1;
	rep(i,n){
		if(G[i].size() >= 2){
			r = i;
			break;
		}
	}
	if(dfs(r,-1)){
		flag = true;
	}
	return flag;
}

int main()
{
	cin >> n;
	rep(i,n){
		scanf("%d",&a[i]);
	}
	rep(i,n-1){
		int p,q;
		scanf("%d%d",&p,&q);
		p--;	q--;
		G[p].push_back(q);
		G[q].push_back(p);
	}
	if(!solve()){
		cout << "YES" << "\n";
	}else{
		cout << "NO" << "\n";
	}
}

