vector<int> edge[100005];
ll A[100005];

ll dfs(int n, int b){
	if( edge[n].size() == 1 ){
		return A[n];
	}
	ll mx = 0, sum = 0;
	for(auto t: edge[n]) if( t != b ){
		auto r = dfs(t, n);
		if( r < 0 ) return -1;
		chmax(mx, r);
		sum += r;
	}
	if( A[n] < mx ) return -1;
	if( A[n]*2 < sum ) return -1;
	ll ret = A[n]*2 - sum;
	//cout << "dfs: " << n << " "  << ret << endl;
	return ret;
}

