bool success=true;

int dfs(int idx,int par,Graph &g,vector<ll> &A){
    //cout<<idx<<" "<<success<<endl;
    vector<int> v;
    for(int to:g[idx]){
        if(to==par) continue;
        v.push_back(dfs(to,idx,g,A));
    }
    if(v.size()==0){
        return A[idx];
    }
    if(v.size()==1){
        if(v[0]==A[idx]) return v[0];
        success=false;
        return v[0];
    }
    int sum=0,num=0;
    for(int x:v){
        sum+=x;
        chmax(num,x);
    }
    int use=sum-A[idx];
    if(use>=0 and ((sum-num>=num) or sum-num>=use)) return sum-use*2;
    success=false;
    return 1;
}

