bool flag;
bool used[100001];

ll dfs(int v){
	used[v]=true;
	if(G[v].size()==1)return a[v];
	ll pass=0;
	ll maxi=0;
	for(int i=0;i<G[v].size();i++){
		if(!used[G[v][i]]){
			ll get=dfs(G[v][i]);
			pass+=get;
			maxi=max(get,maxi);
		}
	}
	ll va=pass-maxi;
	va=min(va,pass/2LL);
	ll vb=pass-a[v];
	if(pass<a[v])flag=false;
	if(vb>va)flag=false;
	pass-=2LL*vb;
	return pass;
}

