inline void dfs(int x,int fa) { 
	if( deg[x] == 1 ) { f[x] = a[x]; return; }
	ll sum = 0, t, y; int maxl = 0;
	ez(i,x) if( to != fa ) { 
		dfs(to,x);
		sum += f[to];
		maxl = max(maxl,f[to]);
	}
	if( sum < a[x] ) out(); 
	if( sum > a[x] ) { 
		t = sum - a[x];
		if( maxl > sum / 2 ) y = sum - maxl;
		else y = sum / 2;

		if( t > y ) out();
		f[x] = sum - t * 2;
	} else f[x] = sum;
}

