using namespace std;

using int64 = long long;

const int MAXN = 200000;

static int64 A[MAXN];
static vector<int> tree[MAXN];

int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    vector<int64> vec;

    int64 sum = 0;

    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
        if (child < 0) return -1;
        vec.push_back(child);
        sum += child;
    }
    if (sum < A[v]) return -1;

    A[v] -= sum;
    sort(vec.begin(), vec.end(), greater<int64>());

    int64 can = vec[0];
    for (int i = 1; i < vec.size(); i++) {
        int64 x = max(0LL, min({can, vec[i], -A[v]}));

        A[v] += x;
        sum -= 2 * x;
        vec[i] -= x;
        can -= x;

        can += vec[i];
    }

    if (A[v] != 0) return -1;

    return sum;
}

int main() {
    int N;
    cin >> N;

    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        tree[a].push_back(b);
        tree[b].push_back(a);
    }

    if (N == 2) {
        cout << (A[0] == A[1] ? "YES" : "NO") << endl;
        return 0;
    }

    int r = -1;
    for (int i = 0; i < N; i++) if (tree[i].size() > 1) r = i;

    if (dfs(r, -1) == 0) cout << "YES" << endl;
    else cout << "NO" << endl;

    return 0;
}

