using namespace std;
template<class T> T gi() {
	T x = 0; bool f = 0; char c = getchar();
	while (c != '-' && (c < '0' || c > '9')) c = getchar();
	if (c == '-') f = 1, c = getchar();
	while (c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return f ? -x : x;
}
const int N = 1e5 + 10;
int a[N], n;
struct node {
	int to, nxt;
} g[N << 1];
int lst[N], gl, d[N];
void add(int x, int y) {
	g[++gl] = (node) {y, lst[x]}; lst[x] = gl;
	g[++gl] = (node) {x, lst[y]}; lst[y] = gl;
	d[x]++; d[y]++;
}
LL dfs(int u, int ff) {
	LL sum = 0; vector<LL> A;
	for (int i = lst[u]; i; i = g[i].nxt) {
		int v = g[i].to; if (v == ff) continue;
		LL k = dfs(v, u);
		sum += k; A.push_back(k);
	}
	if (A.size()) {
		sort(A.begin(), A.end());
		int p = 0; LL tmp = 0;
		while (tmp + A[p] <= sum / 2) p++;
		if (sum - tmp > A[p]) {
			puts("NO");
			exit(0);
		}
		return sum - (sum - a[u]) * 2;
	}
	return a[u];
}
