bool ok = true;
ll go(int v, int p)
{
	if (used[v]) re dp[v];
	used[v] = true;
	ll sum = 0;
	for (int i = 0; i < (int)g[v].size(); i++)
	{
		int to = g[v][i];
		if (to != p)
		{
			sum += go(to, v);
		}
	}
	if ((int)g[v].size() == 1)
	{
		dp[v] = a[v];
		re dp[v];
	}
	if (sum - a[v] < 0 || 2 * a[v] - sum < 0)
	{
		ok = false;
	}
	dp[v] = 2 * a[v] - sum;
	re dp[v];
}
