void dfs(LL v, LL p){

	if(deg[v] != 1) num[v] *= 2;
	vector<LL> r;
	for (LL x : edges[v]) {
		if (x != p){
			dfs(x, v);
			num[v] -= num[x];
			r.push_back(num[x]);
		}
	}
	if(num[v] < 0) ok = 0;
	if(v > 0) r.push_back(num[v]);
	sort(r.begin(), r.end());
	reverse(r.begin(), r.end());
	LL sum = 0;
	for(LL x : r){
		sum += x;
	}
	if(deg[v] > 1 && (sum % 2) != 0) ok = 0;
	if(deg[v] > 1 && r[0] * 2 > sum) ok = 0;
}
