using namespace std;

typedef long long LL;
const int N = 100000 + 5;

int n;
int a[N];
vector<int> adj[N];

LL dfs(int u, int f)
{
    if (adj[u].size() == 1) {
        return a[u];
    }
    LL sum = 0;
    LL mx = 0;
    for(auto v: adj[u]) {
        if (v == f) continue;
        LL tmp = dfs(v, u);
        if (tmp < 0) return -1;
        mx = max(mx, tmp);
        sum += tmp;
    }
    LL x = sum - a[u];
    LL can = min(sum / 2, sum - mx);
    if (x < 0 || can < x) {
        return -1;
    }
    //cout << u << ' ' << a[u] - x << endl;
    return a[u] - x;
}

void solve()
{
    cin >> n;
    for(int i = 0; i < n; ++ i) {
        scanf("%d", a + i);
    }
    for(int i = 1; i < n; ++ i) {
        int u, v;
        scanf("%d%d", &u, &v);
        --u, --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    if (n == 2) {
        if (a[0] == a[1]) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return;
    }
    for(int i = 0; i < n; ++ i) {
        if (adj[i].size() > 1) {
            LL tmp = dfs(i, -1);
            if (tmp) {
                cout << "NO" << endl;
            } else {
                cout << "YES" << endl;
            }
            return;
        }
    }
}

int main()
{
    solve();
    return 0;
}

