int n;
vector<int> e[111111];
long long int A[111111];
bool dfs(int x,int fat){
	if(e[x].size() == 1){
		return true;
	}
	long long int sum = 0, mx = 0;
	for(vector<int>::iterator it = e[x].begin(); it!=e[x].end(); it++){
		int y = *it;
		if(y == fat)continue;
		if(!dfs(y, x))
			return false;
		sum += A[y];
		mx = max(mx, A[y]);
	}
	mx = min(sum - mx, sum/2);

	long long int dec = sum - A[x];
	if(dec < 0 || dec > mx)
		return false;
	A[x] -= dec;
	if(x == fat)return A[x] == 0;
	A[fat] -= dec;
	return true;
}
