ll dfs(int v, int par, VL &a, VVI &g, bool &good) {
    if (SIZE(g[v]) == 1) {
        return a[v];
    }

    ll pairs = 0, sum = 0;
    for (int u : g[v]) if (u != par) {
        ll fromSon = dfs(u, v, a, g, good);

        ll b = (sum - fromSon) / 2;
        b = max(b, 0LL);
        b = min(b, pairs);

        pairs = min(fromSon + b, sum - b);
        sum += fromSon;
    }

    ll x = 2 * a[v] - sum;
    ll y = a[v] - x;

    good = good && (x >= 0) && (y >= 0) && (y <= pairs);

    return x;
}

bool solve(int n, VL &a, VVI &g) {
    if (n == 2) {
        return a[0] == a[1];
    }

    int root = 0;
    while (g[root].size() == 1) root++;

    bool good = true;
    if (dfs(root, -1, a, g, good) > 0) {
        good = false;
    }

    return good;
}

