#define N (100000+5)

int rt, dig[N];
LL f[N], a[N];
vector<int> G[N];

#define v G[now][i]

bool Dfs(int now, int F){
	if(G[now].size() == 1){
		f[now] = a[now]; return true;
	}

	priority_queue<LL> q;
	LL t, tot1 = 0, tot2 = 0, ntot1, ntot2, sum;
	int sz = 0;

	For(i, 0, G[now].size() - 1) if(v != F){
		if(!Dfs(v, now)) return false;
		if(f[v]){
			q.push(f[v]); ++sz; tot2 += f[v];
		}
	}

	sum = tot2;
	if(now == rt){
		if((sum & 1) || (sum >> 1) != a[now]) return false;
		LL o1, o2;

		while(!q.empty()){
			o1 = q.top(); q.pop();
			if(q.empty()) return false;
			o2 = q.top(); q.pop();

			LL tmp = min(o1, o2);
			o1 -= tmp; o2 -= tmp;

			if(o1) q.push(o1); if(o2) q.push(o2);
		}

		return true;
	}

	if(sz == 1){
		if(a[now] != q.top()) return false;
		f[now] = a[now]; return true;
	}

	LL o1, o2;

	while(!q.empty()){
		o1 = q.top(); q.pop();
		if(q.empty()) return false;
		o2 = q.top(); q.pop();

		t = min(o1, o2);
		ntot1 = tot1 + t, ntot2 = tot2 - 2 * t;

		if(a[now] <= (tot1+tot2) && a[now] >= (ntot1+ntot2)){
			LL tmp = tot1 + tot2 - a[now];
			f[now] = tot2 - (tmp << 1);

			return true;
		}

		tot1 = ntot1; tot2 = ntot2;
		o1 -= t; o2 -= t;
		if(o1) q.push(o1); if(o2) q.push(o2);
	}

	return false;
}

