void dfs(const vvi& g,const vl& a,int p,int u,vl& xs)
{
	int m=0;
	for(int v:g[u]) if(v!=p) m++;
	if(m==0){
		xs[u]=a[u];
		return;
	}
	ll sum=0,mx=0;
	for(int v:g[u]) if(v!=p){
		dfs(g,a,u,v,xs);
		sum+=xs[v];
		mx=max(mx,xs[v]);
	}
	xs[u]=2*a[u]-sum;
	if(xs[u]<0||sum-xs[u]<0||(sum-xs[u])/2>sum-mx)
		throw "invalid";
	if(u==0){
		if(m==1&&xs[u]!=sum)
			throw "invalid(root)";
		if(m>1&&xs[u]>0)
			throw "invalid(root)";
	}
}

