class Graph{
	private:
	int V,r;
	vvi List;
	vb used;
	bool dfs(int v){
		used[v]=1;
		ll sum=0,M=0;
		for(int i=0;i<List[v].size();i++){
			int u=List[v][i];
			if(!used[u]){
				if(!dfs(u)) return 0;
				sum+=a[u];
				M=max(M,a[u]);
			}
		}
		if(v==r||List[v].size()==1) return 1;
		ll x=2*a[v]-sum;
		if(x<0||x>a[v]||a[v]-x>(M>sum/2?sum-M:sum/2)) return 0;
		a[v]=x;
		return 1;
	}
	public:
	Graph(int v){
		V=v;
		List=vvi(v);
	}
	void add_edge(int s,int t){
		List[s].push_back(t);
		List[t].push_back(s);
	}
	void solve(){
		for(int i=0;i<V;i++) if(List[i].size()==1) r=i;
		used=vb(V);
		bool flag=dfs(r);
		if(a[r]!=a[List[r][0]]) flag=0;
		if(flag) cout<<"YES"<<endl;
		else cout<<"NO"<<endl;
	}
};

