lint rec(int v, int p) {
	if (adj[v].size() == 1 && p != -1) {
		//cerr << v+1 << " " << A[v] << endl;
		return A[v];
	}

	vector< lint > deg;
	lint sum = 0;
	for (int u : adj[v]) {
		if (u != p) {
			deg.push_back(rec(u, v));
			sum += deg.back();
