int n, a, b, x[100009], dp[100009]; vector<int> G[100009];
bool solve(int pos, int pre) {
	if (G[pos].size() == 1) {
		dp[pos] = x[pos];
		return true;
	}
	bool ok = true;
	int sum = 0, r = 0;
	for (int i : G[pos]) {
		if (i == pre) continue;
		if (!solve(i, pos)) ok = false;
		sum += dp[i];
		r = max(r, dp[i]);
	}
	int z = min(sum / 2, sum - r);
	if (x[pos] < sum - z && sum < x[pos]) return false;
	dp[pos] = sum - 2 * (sum - x[pos]);
	return true;
}
int main() {
	cin >> n;
	for (int i = 0; i < n; i++) cin >> x[i];
	for (int i = 0; i < n - 1; i++) {
		cin >> a >> b; a--, b--;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	int root = -1;
	for (int i = 0; i < n; i++) {
		if (G[i].size() >= 2) {
			root = i;
			break;
		}
	}
	bool ret = solve(root, -1);
	if (dp[root] != 0) ret = false;
	cout << (ret ? "YES" : "NO") << endl;
	return 0;
}

