bool ok = true;

ll dfs(int v, int par) {
	if (sz(e[v]) == 1) {
		return a[v];
	}

	ll mx = 0;
	ll child_sum = 0;
	for (auto to : e[v]) {
		if (to == par) continue;
	    ll tmp =dfs(to, v);
		child_sum += tmp;
		mx = max(mx, tmp);
	}
	ll ccc = child_sum - mx;
	ll x = child_sum - a[v];
	ll ret = child_sum - 2 * x;
	if (x < 0 || ret < 0) {
		ok = false;
	}
	if (x > ccc) {
		ok = false;
	}

	return ret;
}

