ll dfs(ll now, ll par, Graph &G, vector<ll> &A){

  if((int)G[now].size()==1 and par != -1){
    return A[now];
  }

  vector<ll> C;
  ll P = 0;
  for(auto next: G[now]){
    if(next == par) continue;
    ll val = dfs(next, now, G, A);
    C.push_back(val);
    P += val;
  }

  // dump(now)

  ll t = P - A[now];
  ll s = 2*A[now] - P;

  // dump(P)
  // dump(t)
  // dump(s)

  if(t<0 or s<0){
    cout << "NO" << endl;
    exit(0);
  }

  for(auto c: C){
    if(c>t){
      cout << "NO" << endl;
      exit(0);
    }
  }

  return s;
}

