pair<int, int> go(vvi& adj, vi& stones, int loc, int par) {
    bool leaf = true;
    int min_tot = 0, max_tot = 0, min_large = 0;

    for (int nbr : adj[loc]) if (nbr != par) {
        leaf = false;
        auto p = go(adj, stones, nbr, loc);

        min_tot += p.first;
        max_tot += p.second;
        min_large = max(min_large, p.first);
    }

    if (leaf) return { stones[loc], stones[loc] };

    int max_pair = min(min_tot - min_large, min_tot / 2);

    if (stones[loc] < min_tot - max_pair) fail();
    if (stones[loc] > max_tot) fail();

    return { max(0, min_tot - 2 * max_pair), min(stones[loc], max_tot) };
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N;
    cin >> N;

    vi stones(N);
    for (int i = 0; i < N; i++) {
        cin >> stones[i];
    }

    vvi adj(N);
    for (int i = 0, u, v; i < N - 1; i++) {
        cin >> u >> v;
        adj[u - 1].push_back(v - 1);
        adj[v - 1].push_back(u - 1);
    }

    int leaf = 0;
    while (adj[leaf].size() != 1)
        leaf++;

    go(adj, stones, leaf, leaf);

    cout << "YES\n";

    return 0;
}

