template< typename T >
struct edge {
  int src, to;
  T cost;

  edge(int to, T cost) : src(-1), to(to), cost(cost) {}
  edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}

  edge &operator=(const int &x) {
    to = x;
    return *this;
  }

  operator int() const { return to; }
};
template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnweightedGraph = vector< vector <int> >;

// グラフの入力
UnweightedGraph graph(
  int N , int M = -1 , bool is_directed = false, bool is_1origin = true){
  UnweightedGraph g(N);
  if(M == -1) M = N - 1;
  for(int _ = 0 ; _ < M ; _++){
    int x , y; cin >> x >> y;
    if(is_1origin) x-- , y--;
    g[x].pb(y);
    if(!is_directed) g[y].pb(x);
  }
  return g;
}

// 重み付きグラフの入力
template<typename T>
WeightedGraph<T> wgraph(
  int N , int M = -1 , bool is_directed = false , bool is_1origin = true){
  WeightedGraph<T> g(N);
  if(M == -1) M = N - 1;
  for(int _ = 0 ; _ < M ; _++){
    int x , y; cin >> x >> y;
    T c; cin >> c;
    if(is_1origin) x-- , y--;
    g[x].eb(y , c);
    if(!is_directed) g[y].eb(x , c);
  }
  return g;
}

void solve(){
  ini(N);
  vl A(N); in(A);
  auto g = graph(N);


  vl L(N);

  auto dfs = [&](auto rec,int cur,int par = -1) -> void{
    // 根からのアレを集計する    
    int chd = 0;
    ll l = 0 ;
    each(dst , g[cur]){
      if(dst == par) continue;
      rec(rec , dst , cur);
      l += L[dst];
      chd++;
    }

    if(par == -1){
      int i = cur;
      trc(i , A[i] , l);
      if(l != A[i]) die("NO");
      L[i] = A[i];
      return;
    }

    if(chd == 0){
      L[cur] = A[cur];
      return;
    }
    if(chd == 1){
      if(l != A[cur]) die("NO");
      L[cur] = A[cur];
      return;
    }
    if(l > 2 * A[cur] || l < A[cur]) die("NO");
    L[cur] = 2 * A[cur] - l;
  };

  int start = 0;
  while(g[start].size() != 1) start++;
  dfs(dfs , start);
  trc(L);

  out("YES");

}

