using namespace std;
template<class T> T gi() {
	T x = 0; bool f = 0; char c = getchar();
	while (c != '-' && (c < '0' || c > '9')) c = getchar();
	if (c == '-') f = 1, c = getchar();
	while (c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return f ? -x : x;
}
const int N = 1e5 + 10;
int a[N], n;
struct node {
	int to, nxt;
} g[N << 1];
int lst[N], gl, d[N];
void add(int x, int y) {
	g[++gl] = (node) {y, lst[x]}; lst[x] = gl;
	g[++gl] = (node) {x, lst[y]}; lst[y] = gl;
	d[x]++; d[y]++;
}
int dfs(int u, int ff) {
	int sum = 0; vector<int> A;
	for (int i = lst[u]; i; i = g[i].nxt) {
		int v = g[i].to; if (v == ff) continue;
		int k = dfs(v, u);
		sum += k; A.push_back(k);
	}
	if (A.size()) {
		sort(A.begin(), A.end());
		int p = 0; LL tmp = 0;
		while (tmp + A[p] <= sum / 2) p++;
		if (sum - tmp > A[p]) {
			puts("NO");
			exit(0);
		}
		return sum - (sum - a[u]) * 2;
	}
	return a[u];
}
int main() {
	//freopen(".in", "r", stdin);
	//freopen(".out", "w", stdout);
	n = gi<int>();
	for (int i = 1; i <= n; i++) a[i] = gi<int>();
	if (n == 2) {
		puts(a[1] == a[2] ? "YES" : "NO");
		return 0;
	}
	for (int i = 1; i < n; i++)
		add(gi<int>(), gi<int>());
	for (int i = 1; i <= n; i++)
		if (d[i] > 1) {
			puts(dfs(i, 0) ? "NO" : "YES");
			return 0;
		}
	return 0;
}

