void dfs(int v, int pr = -1) {
	d[v] = a[v];
	ll t = 0;
	int tt = 0;
	for (const int& v2 : g[v]) {
		if (v2 == pr) continue;
		dfs(v2, v);
		tt = max(tt, d[v2]);
		t += d[v2];
	}
	if (sz(g[v]) == 1) return;
	ll x = (t - tt);
	ll y = tt - x * 2;
	if (d[v] > t || y > d[v]) {
		puts("NO");
		exit(0);
	}
}

