long long dfs(int v,int p=-1)
{
	if (g[v].size()==1) return a[v];
	long long x=0,y=0,mx=0;
	for (auto u:g[v])
		if (u!=p)
		{
			x++;
			ll k=dfs(u,v);
			mx=max(mx,k);
			y+=k;
		}
	if (x==1 && a[v]!=y) cout<<"NO",exit(0);
	if (2*a[v]-y<0 || y-a[v]<0 || a[v]<mx) cout<<"NO",exit(0);
	return 2*a[v]-y;
}
