int n, a[100055], x, y, ans, deg[100055];
bool vis[100055];
vector<int> e[100055], w;

void GG() {
	printf("NO\n");
	exit(0);
}

int dfs(int x) {
//	printf(">> dfs %d\n", x);

	vis[x] = 1;

	w.clear();
	LL sum = 0;

	FOR(i, 0, e[x].size()) {
		int to = e[x][i];
		if (vis[to]) continue;
		int res = dfs(to);
		sum += res;
		w.pb(res);
	}

	if (sum > a[x] * 2) GG();

	LL left = sum - a[x];
	if (left < 0) GG();

	if (a[x] < left) GG();

	if (w.size() == 1 && left != 0) GG();

	LL extra = 0;

	FOR(i, 0, w.size()) {
		if (w[i] > left) extra += w[i] - left;
	}

	if (extra > a[x] - left) GG();

//	printf(">> dfs %d returns %d - %lld = %lld\n", x, a[x], left, a[x] - left);

	return a[x] - left;

}

