void findPar(int cur, int par){
    p[cur] = par;
    for(auto x : adj[cur]){
        if(x == par) continue;
        findPar(x, cur);
    }
}

bool solve(){

    vi leafchild(n,0);
    queue <int> q;
    vi c(n,0);
    rep(i,n){
        if(adj[i].size() == 1) {
            leafchild[p[i]]++;
            c[i] = a[i];
        }
    }
    rep(i,n){
        if((i!=root && leafchild[i] == adj[i].size()-1) || (i==root && leafchild[i] == adj[i].size())){
            if(adj[i].size()>1)
                q.push(i);
        }
    }

    while(!q.empty()){
        ll cur = q.front();
        //dbg(cur);
        q.pop();
        ll csum = 0;
        for(auto x : adj[cur]){
            if(x != p[cur]){
                csum+=c[x];
            }
        }
        c[cur] = 2*a[cur] - csum;
        if(c[cur] < 0){
            return false;
        }
        if(cur == root && c[cur] != 0){
            return false;
        }


        //now put parent;
        if(cur != root){
            leafchild[p[cur]]++;
            if((p[cur]!=root && leafchild[p[cur]] == adj[p[cur]].size()-1) || (p[cur]==root && leafchild[p[cur]] == adj[p[cur]].size())){
                q.push(p[cur]);
            }
        }
    }
    return true;
}

