const int N = 100010;

struct edge{
	int next, to;
};

edge e[N << 1];
int n, deg[N], first[N], e_cnt = 0;
ll a[N];

void addedge(int u, int v){
	e[++ e_cnt] = {first[u], v};
	first[u] = e_cnt;
	e[++ e_cnt] = {first[v], u};
	first[v] = e_cnt;
}

void dfs(int i, int fa){
	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		++ deg[i];
		if (x != fa){
			dfs(x, i);
		}
	}
}

void solve(int i, int fa){
	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		if (x == fa){
			continue;
		}
		a[i] -= a[x];
		solve(x, i);
	}
}

int main(){
