		scanf("%d%d", &u, &v);
		addedge(u, v);
	}
	if (n == 2){
		return printf(a[1] == a[2] ? "YES\n" : "NO\n"), 0;
	}
	dfs(1, 0);
	for (int i = 1; i <= n; ++ i){
		if (deg[i] > 1){
			solve(i, 0);
			break;
		}
	}
	ll sum1 = 0, sum2 = 0;
	for (int i = 1; i <= n; ++ i){
		if (deg[i] == 1){
			sum1 += a[i];
		}
	}
	for (int i = 1; i <= n; ++ i){
		if (deg[i] == 1){
			continue;
		}
		if (a[i] > 0 || sum2 < -sum1){
			return printf("NO\n"), 0;
		}
		sum2 += a[i];
	}
	return printf(sum2 * -2 == sum1 ? "YES\n" : "NO\n"), 0;
}

