int n, p;
int par[100010];
int dp[100010];
vector<int> G[100010];
vector<int> A;

void rec(int s) {
  for (int i = 0; i < G[s].size(); i++) {
    int v = G[s][i];
    if (par[v] >= 0) continue;
    par[v] = s;
    rec(v);
  }
}

int solve(int s) {
  if (G[s].size() == 1) return A[s];
  int sum = 0;
  for (int i = 0; i < G[s].size(); i++) {
    int v = G[s][i];
    if (v == par[s]) continue;
    int t = solve(v);
    if (t == -1) return -1;
    sum += t;
  }
  if (2 * A[s] < sum || sum < A[s]) return -1;
  if (s == p && sum != 2 * A[s]) return -1;
  return A[s] - 2 * (sum - A[s]);
}

