  for (int i = 0; i < n - 1; i++) {
    cin >> a[i] >> b[i];
    a[i]--, b[i]--;
    G[a[i]].push_back(b[i]);
    G[b[i]].push_back(a[i]);
  }

  fill(par, par + n, -1);
  for (int i = 0; i < n; i++) {
    if (G[i].size() == 1) continue;
    p = i;
    par[p] = p;
    rec(p);
    break;
  }

  cout << (solve(p) == -1 ? "NO" : "YES") << endl;

  return 0;
}

