    vector<i64> r(n);
    function<bool(int,int)> rec=[&](int u,int p){
        if(graph[u].size()==1) return true;
        r[u]=-a[u];
        priority_queue<i64,vector<i64>>  que;
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            r[u]+=a[v]-r[v];
            que.push(a[v]-r[v]);
        }
        i64 x=0;
        while(x<r[u] and que.size()>=2){
            i64 f=que.top();
            que.pop();
            i64 g=que.top();
            que.pop();
            x+=g;
            if(f-g) que.push(f-g);
            if(x>r[u]) x=r[u];
        }
        if(p==-1) return r[u]==a[u] and x==r[u] and que.empty();
        return x==r[u];
    };

