		}
		vector < LL > val;
		for ( int v : E[i] ){
			val.push_back(a[v]);
		}
		sort(val.begin(),val.end());

		LL sum = 0;
		for ( LL v : val ) sum += v;
		LL fsum = 0;
		LL target = a[i];
		for ( int j = 0; j < val.size()-1; j++ ){
			if ( fsum >= target && sum >= target ){
				break;
			}
			LL v = val[j];
			// cout << v << " " << i << endl;
			if ( fsum < target && fsum + v >= target ){
				LL l = 0, r = v;
				while ( l < r ){
					LL m = ( l + r ) / 2;
					if ( fsum + m >= target ) r = m;
					else l = m + 1;
				}

				if ( fsum + l >= target && sum - l >= target ){
					break;
				}
				ans = 0;
				break;
			}
			fsum += v;
			sum -= v;
			// cout << v << " " << fsum << " " << sum << endl;
			if ( fsum >= target && sum >= target ){
				break;
			} 
		}
