using namespace std;
const int N=1e6+5;
typedef long long ll;
struct node{
    int u,v,nxt;
}edge[N*2];
int head[N],mcnt;
int du[N];
int a[N];
int r[N];
int mx[N];
int n;
bool vis[N];
int deep[N];
void add_edge(int u,int v){
    mcnt++;
    du[u]++;
    edge[mcnt].u=u;
    edge[mcnt].v=v;
    edge[mcnt].nxt=head[u];
    head[u]=mcnt;
}
queue<int>q;
int main()
{
    //freopen("tree.in","r",stdin);
    //freopen("tree.out","w",stdout);
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
        scanf("%d",&a[i]);
    if(n==2){
        if(a[1]==a[2])
            puts("YES");
        else
            puts("NO");
        return 0;
    }
    for(int i=1;i<n;i++){
        int u,v;
        scanf("%d%d",&u,&v);
        add_edge(u,v);
        add_edge(v,u);
    }
    for(int i=1;i<=n;i++){
        if(du[i]==1){
            q.push(i);
            vis[i]=1;
            r[i]=a[i];
        }
    }
    while(!q.empty()){
        int u=q.front();
        q.pop();
        int z=2*a[u]-r[u];
        if(z>a[u]||mx[u]>a[u]){
            puts("NO");
            return 0;
        }
        int sz=0;
        for(int i=head[u];i;i=edge[i].nxt){
            int v=edge[i].v;
            sz++;
            if(!vis[v]){
                du[v]--;
                if(du[v]==1){
                    deep[v]=deep[u]+1;
                    q.push(v);
                    vis[v]=1;
                }
                mx[v]=max(mx[v],z);
                r[u]+=z;
                r[v]+=z;
            }
            else if(deep[u]<=deep[v]){
                mx[v]=max(mx[v],z);
                if(mx[v]>a[v]){
                    puts("NO");
                    return 0;
                }
                r[u]+=z;
                r[v]+=z;
            }
        }
    }
    for(int i=1;i<=n;i++)
        if(!vis[i]||r[i]!=2*a[i]){
            puts("NO");
            return 0;
        }
    puts("YES");
}

