#define int long long
#define MAXN 200000

int a[MAXN];
int n;
std::vector<int> Adj[MAXN];

int dfs(int u, int p = -1) {
  int ret = a[u];

  if(Adj[u].size() == 1 && p != -1)
    return ret;

  int sum = 0;
  int max = 0;
  for(int j : Adj[u]) {
    if(j == p)
      continue;

    int next = dfs(j, u);

    if(next == -1)
      return -1;

    sum += next;
    max = std::max(max, next);
  }

  ret = 2*a[u] - sum;

  if(ret < 2*max - sum)
    return -1;

  return ret;
}

