  if (is_leaf(curr)) return a[curr];
  if (memo.count(curr)) return memo[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  if (curr == prev) { // root
    if (sum % 2 || a[curr] * 2 - sum) throw "";
    return 0;
  }

  lli mx = *max_element(b.begin(), b.end());
  lli paired = min<lli>(sum / 2, mx);
  lli x = a[curr] - paired; // pass to parent
  lli y = a[curr] * 2 - sum;
  if (x < 0 || y < 0 || paired < x) throw "";
  return memo[curr] = y;
}

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    memo.clear();
    fill(g, g + N, vector<int>());
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n - 1; ++i) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      g[a].push_back(b);
      g[b].push_back(a);
    }
    int r = 0;
    for (int i = 0; i < n; ++i) {
      if (!is_leaf(i)) { r = i; break; }
    }
    if (n == 1) {
      puts(a[0] ? "NO" : "YES");
    } else if (n == 2) {
      puts(a[0] == a[1] ? "YES" : "NO");
    } else try {
      f(r, r);
      cout << "YES" << endl;
    } catch (const char* e) {
      cout << "NO" << endl;
    }
  }

  return 0;
}

