void add(int u,int v)
{
	edge[++num_edge].to=v;
	edge[num_edge].next=head[u];
	head[u]=num_edge;
}

void Dfs(int x,int fa)
{
	if (!flag) return;
	int maxn=0;
	long long sum=0;
	for (int i=head[x]; i; i=edge[i].next)
		if (edge[i].to!=fa)
		{
			Dfs(edge[i].to,x);
			sum+=a[edge[i].to];
			maxn=max(maxn,a[edge[i].to]);
		}
	if (!maxn) return;
	if (sum<a[x] || sum>2*a[x] || maxn>a[x]) flag=false;
	a[x]=a[x]*2-sum;
}

