typedef long long LL;
struct node
{
	int to;
	node *nxt;
}edges[MAXN*2+5];
node *ncnt=&edges[0],*Adj[MAXN+5];
int d[MAXN+5],rt,n,fa[MAXN+5];
LL a[MAXN+5];
LL sum[MAXN+5],tot1,tot2;
void AddEdge(int u,int v)
{
	node *p=++ncnt;
	p->to=v;
	p->nxt=Adj[u];
	Adj[u]=p;

	node *q=++ncnt;
	q->to=u;
	q->nxt=Adj[v];
	Adj[v]=q;
}
bool DFS(int u,int f)
{
	bool Find=false;
	LL sumn=0;
	for(node *p=Adj[u];p!=NULL;p=p->nxt)
	{
		int v=p->to;
		if(v==f)
			continue;
		Find=true;
		fa[v]=u;
		if(DFS(v,u)==false)
			return false;
		sumn+=sum[v];
	}
	sumn+=sum[u];
	if(Find==false)
	{
		sum[u]=-a[u];
		tot1+=a[u];
		return true;
	}
	LL add=-a[u]-sumn;
	tot2+=add*2LL;
	if(add<0)
		return false;
	sum[u]=add+sumn;
	if(u!=0)
		sum[fa[u]]+=add;
	return true;
}
