ll dfs(int now, int par) {
  if (G[now].size() == 1) return a[now];
  vl b;
  ll sum = 0;
  rep (i, G[now].size()) {
    if (G[now][i] == par) continue;
    b.push_back(dfs(G[now][i], now));
    sum += b.back();
  }

  if (sum < a[now]) NO();
  sort(all(b));
  int s1 = sum - b.back(), s2 = b.back();
  int mi;

  if (s1 <= s2) {
    mi = s2;
  }
  else {
    if (sum % 2 == 0) mi = sum / 2;
    else mi = sum / 2 + 1;
  }
  if (mi > a[now]) NO();
  return 2*a[now] - sum;
}

