                    cout << "NO" << endl;
                    return 0;
                }
                if (ra / 2 != A[t]) {
                    cout << "NO" << endl;
                    return 0;
                }
                REP(i, edge[t].size()) {
                    st.push(edge[t][i]);
                }
                break;
        }
    }

    REP(i,n){
        if(!ans[i]){
            cout << "NO" << endl;
            return 0;
        }
    }
    cout << "YES" << endl;
    return 0;
}

