bool flag = 0;

ll saiki(int x,vector<ll> &a,vector<set<int> > &st){
    if(flag)return -1;    
    if(st[x].size()==0){
        return a[x];
    }
    ll tmp = 0;
    ll mx = 0;
    for(auto k:st[x]){
        st[k].erase(x);
        ll z = saiki(k,a,st);
        mx = max(mx,z);
        tmp += z;
    }
    ll ans = 2*a[x]-tmp;
    ll k = a[x]-ans;
    if(k>tmp-mx||k>tmp/2){
        flag = 1;
        return -1;
    }
    if(ans<0){
        flag = 1;
        return -1;
    }else{
        return ans;
    }
}



