int du[maxn];
int n,m;

void mt(int now,int fa)
{
    for(unsigned int t=0;t<g[now].size();t++)
    {
        int v=g[now][t];
        if(v==fa)continue;
        son[now].push_back(v);
        mt(v,now);
    }
}

void solve(int now)
{
    if(son[now].size()==0)
    {
        x[now]=o[now]=0;
        y[now]=z[now]=a[now];
        return;
    }
    LL ss=0,tot=0;
    for(unsigned int t=0;t<son[now].size();t++)
    {
        solve(son[now][t]);
        ss+=x[son[now][t]];
        tot+=y[son[now][t]];
        z[now]+=z[son[now][t]];
    }
    LL temp=z[now]-2*ss;
    o[now]=x[now]=temp-a[now];
    y[now]=a[now]-x[now];
    ch[now]=a[now]+x[now]-tot;
    x[now]+=ss;
}

