bool visited[100005];

int dfs(int x) {
    visited[x] = true;
    if (G[x].size() == 1) return A[x];

    int cost=0, mx=0;
    for (int i = 0; i < G[x].size(); i++) {
        if (visited[G[x][i]]) continue;
        int d = dfs(G[x][i]);
        if (d == -1) return -1;
        cost += d;
        mx = max(d, mx);
    }

    if (A[x] > cost) return -1;
    if (2 * mx < cost && A[x] < cost - (cost/2)) return -1;
    if (2 * mx >= cost && A[x] < mx) return -1;
    return 2 * A[x] - cost;
}

