	}
	for(int i=1; i<n; ++i){
		const int a=nxi(),b=nxi();
		G::add(a,b);
	}
	G::get_rt();
	if(!G::dfs(G::rt,0)) puts("NO");
	else puts(G::req[G::rt]?"NO":"YES");
	return 0;
}

