int n, A[MAXN], c[MAXN], root, sum;
vector<pair<int, int>> g[MAXN];

void dfs(int v, int pr){
	c[v] = A[v] * ((g[v].size() != 1) + 1);

	int *b_edge;

	for(auto &&[to, cost] : g[v]){
		if(to != pr){
			dfs(to, v);
			c[v] -= c[to];
			cost = c[to];
		}
		else{
			b_edge = &cost;
		}
	}

	*b_edge = c[v];

	if(c[v] < 0){
		cout << "NO\n";
		exit(0);
	}
}

void check(int v){
	int sum = 0, mx = 0;

	for(auto &&[to, cost] : g[v]){
		sum += cost;
		mx = max(cost, mx);
	}

	if(sum & 1 || mx > sum / 2){
		cout << "NO\n";
		exit(0);
	}
}

