	cin >> n;

	for(int i = 1; i <= n; ++i){
		cin >> A[i];
	}

	for(int i = 2, u, v; i <= n; ++i){
		cin >> u >> v;
		g[u].pb({v, 0});
		g[v].pb({u, 0});
	}

