const int N = 100001;

int n;
vector <int> a, v[N];

ll dfs(int node, int pnode){
    ll s = 0;
    for(auto &i : v[node]){
        if(i == pnode) continue;
        s += dfs(i, node);
    }
    if(v[node].size() == 1) return a[node];
    ll x = 2 * a[node] - s;
    ll y = s - a[node];
    if(x < 0 || y < 0) finish("NO");
    if(pnode == -1 && x) finish("NO");
    return x;
}
