    int i,j;
    scanf("%d",&n);
    for(i=1;i<=n;i++)scanf("%d",&a[i]);
    for(i=1;i<n;i++)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        e[x].push_back(y);
        e[y].push_back(x);
    }
    if(n==2)
    {
        if(a[1]==a[2])puts("YES");
        else puts("NO");
        return 0;
    }
    for(i=1;i<=n;i++)if(e[i].size()>1)
    {
        rt=i;
        dfs(rt);
        break;
    }
    puts(flag?"YES":"NO");
    return 0;
}

