ll dfs(UnWeightedGraph& g, int v, int p = -1){
    if(g[v].size() == 1){
        return A[v];
    }
    ll sum = 0;
    for(auto nv: g[v]){
        if(nv == p) continue;
        ll k = dfs(g, nv, v);
        if(k == -1) return -1;
        sum += k;
    }
    if(sum < A[v] or A[v] * 2 < sum) return -1;
    if(p == -1){
        if(sum == A[v] * 2) return 0;
        else return -1;
    }
    return A[v] * 2 - sum;
}

