int64_t dfs(const vector<vector<int64_t>>& links, const vector<int64_t>& a, int64_t current, int64_t parent) {
  if (links[current].size() == 1 && parent >= 0) {
    return a[current];
  }

  int64_t s = 0;
  int64_t m = 0;
  for (auto v : links[current]) {
    if (v == parent) {
      continue;
    }
    auto tmp = dfs(links, a, v, current);
    if (tmp < 0) {
      return -1;
    }

    m = max(m, tmp);
    s += tmp;
  }



  int64_t l = a[current];
  int64_t k = s - l;
  if (k < 0 || k > l || 2 * k > s) {
    return -1;
  }

  if (m >= s - m) {
    if (k <= s - m) {
      return l - k;
    } else {
      return -1;
    }
  } else {
    if (k <= s / 2) {
      return l - k;
    } else {
      return -1;
    }
  }
}

