Graph g;
ll a[100010];

ll dfs(int idx, int p) {
	if (p != -1 && g[idx].size() == 1) return a[idx];

	ll sum = 0;
	ll c_max = 0;
	for (int nex : g[idx]) {
		if (nex == p) continue;
		ll tmp = dfs(nex, idx);
		if (tmp == -1) return -1;
		sum += tmp;
		c_max = max(c_max, tmp);
	}

	if (p == -1) {
		if (g[idx].size() == 1) {
			if (a[idx] == sum) return 0;
			else return -1;			
		} else {
			if (a[idx] == sum / 2) return 0;
			else return -1;
		}
	}

	ll res = 2 * a[idx] - sum;
	if (res < 0 || res > a[idx] || sum < res) return -1;

	if ((sum - res) / 2 > min(c_max, sum / 2)) return -1;
	else return res;
}

