bool Go(int a) {
  done[a] = true;
  vi incoming;
  for (int i = 0; i < G[a].size(); ++i) {
    int other = G[a][i];
    if (done[other]) {
      continue;
    }
    if (!Go(other)) {
      return false;
    }
    incoming.push_back(d[other]);
  }
  ll sum = 0;
  ll mx = 0;
  for (int i = 0; i < incoming.size(); ++i) {
    sum += incoming[i];
    if (incoming[i] > mx) {
      mx = incoming[i];
    }
  }
  if (!incoming.empty() && sum < A[a]) {
    return false;
  }
  int inters = min(sum - mx, sum / 2);
  sum -= 2 * inters;
  A[a] -= inters;
  if (!incoming.empty() && sum != A[a]) {
    return false;
  }
  if (a == 0 && incoming.size() > 1 && A[a] != 0) {
    return false;
  }
  d[a] = A[a];
  return true;
}

