bool sol(int x)
{
	int s = (dis[x] == 1? hav[x]: 0), t = 0;
	for(int y = son[x]; y; y = bro[y])
	{
		if(not sol(y)) return false;
		s += rez[y], t = max(rez[y], t);
	}
	if(t < s) rez[x] = (t > s - t? s - (t << 1): 0);
	else rez[x] = s;
	if(s < hav[x]) return false;
	if((hav[x] << 1) - s < 0) return false;
	rez[x] = (hav[x] << 1) - s;
	return true;
