int dfs(int x, int p) {
	int sum = 0;
	for (int i = 0; i < adjlist[x].size(); i++) {
		if (adjlist[x][i] == p) continue;
		sum += dfs(adjlist[x][i], x);
	}
	node_val[x] = A[x] - sum;
	return A[x];
}

int dfs2(int x, int p) {
	if (adjlist[x].size() == 1) return node_val[x];
	else {
		if (node_val[x] > 0) {
			printf("NO\n");
			exit(0);
		}
	}
	int cap = -node_val[x];
	int act_cap = cap;
	if (p != -1) act_cap = min(act_cap, -node_val[p]);
	vector<int> v;
	int sum = 0;
	for (int i = 0; i < adjlist[x].size(); i++) {
		if (adjlist[x][i] == p) continue;
		sum += dfs2(adjlist[x][i], x);
	}
	int use = min(sum, act_cap);
	node_val[x] += use;
	if (p != -1) node_val[p] += use;
	return sum - use;
}

