        if(p > l) {
            ll tmp = p - l;
            tmp = min(tmp, t - sub);
            q.push(tmp);
            sub += tmp;
        }
        else break;
    }
    ll ss = 0LL;
    while(!q.empty()) {
        ll p = q.top();
        q.pop();
