/* ------------- Functions -------------- */

ll dfs(ll v) {
    visited[v] = true;
    ll sum = 0, maxs = 0;
    for (ll sv : path[v]) {
        if (!visited[sv]) {
            ll s = dfs(sv);
            if (s < 0) {
                return -1;
            } else {
                sum += s;
                maxs = max(maxs, s);
            }
        }
    }

    if (sum == 0) {
        if (SIZE(path[v]) == 1) {
            return A[v];
        } else {
            return -1;
        }
    } else {
        ll mi = max(sum / 2 + sum % 2, maxs);
        if (A[v] < mi || A[v] > sum) {
            return -1;
        } else {
            return A[v] * 2 - sum;
        }
    }
}

