using namespace std;

using ll = long long;

ll dfs(int v, vector<vector<int>>& g, vector<ll> const& A, int prev) {
    vector<ll> child(g[v].size());
    if(prev != -1 && g[v].size() == 1) {
        return A[v];
    }
    ll sum = 0, ma = -1;
    for(int i=0; i<g[v].size(); ++i) {
        if(g[v][i] == prev) {
            continue;
        }
        child[i] = dfs(g[v][i], g, A, v);
        if(child[i] == -1) {
            return -1;
        }
        sum += child[i];
        ma = max(ma, child[i]);
    }
    ll up = 2*A[v] - sum;
    ll p_cnt = (sum - up) / 2;
    //cout << "v: " << v << " up: " << up << " p_cnt: " << p_cnt << endl;
    if(p_cnt * 2 != sum - up || p_cnt > sum - ma) {
        return -1;
    }
    return up;
}

int main() {
    int N;
    cin >> N;
    vector<ll> A(N);
    for(int i=0; i<N; ++i) {
        cin >> A[i];
    }
    vector<vector<int>> g(N);
    for(int i=0; i<N-1; ++i) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    if(N == 2) {
        if(A[0] == A[1]) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
        return 0;
    }
    for(int i=0; i<N; ++i) {
        if(g[i].size() != 1) {
            if(dfs(i, g, A, -1) != 0) {
                cout << "NO" << endl;
            } else {
                cout << "YES" << endl;
            }
            return 0;
        }
    }
}

