int dfs(int v, int p = -1) {
if (a[v].size() == 1) {
return cnt[v];
}
long long mx = 0;
long long sum = 0;
for (int x : a[v]) { if (x == p) continue; int mn = dfs(x, v); mx = max(mx, mn); sum += mn; }
int num_sm = (sum - max(sum % 2, 2 * mx - sum)) / 2;
if (sum - num_sm <= cnt[v] && sum >= cnt[v]) return sum - 2 * (sum - cnt[v]); else {
puts("NO");
exit(0);
}
}

