ll dfs(int v) {
    use[v] = 1;
    vector<ll> ch;
    for (auto u: e[v]) {
        if (!use[u]) {
            ll tmp = dfs(u);
            ch.pb(tmp);
        }
    }
    if (ch.empty()) 
        return w[v];
    //db2(v, w[v]);
    //cerr << "ch: ";
    //for (auto x: ch)
        //cerr << x << " ";
    //cerr << endl;
    sort(all(ch));
    ll sum = 0;
    for (auto x: ch)
        sum += x;

    ll mn;
    ll mxPair;
    if (ch.back() * 2 > sum) {
        mxPair = sum - ch.back();
    }
    else 
        mxPair = sum / 2;
    mn = sum - mxPair;
    if (!(mn <= w[v] && w[v] <= sum)) {
        ret(0);
    }
    ll needPair = sum - w[v];
    return sum - needPair * 2;
}

