vector<int32> G[112345];
int32 N;
vector<int64> A;

int64 dfs(int32 v, int32 p){
	if(G[v].size() == (p != -1)) return A[v];
	int64 rest= A[v];
	vector<int64> c;
	int64 sum = 0;
	int32 cnt = 0;
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		c.push_back(dfs(G[v][i], v));
		sum += c[c.size()-1];
		if(c[c.size()-1] == -1) return -1;
	}
	sort(all(c), greater<int64>());
	cnt += max((int64)0, 2*c[0]-sum);
	rest -= cnt; sum -= cnt;
	cnt += sum%2; rest -= sum%2; sum -= sum%2;
	cnt += 2*rest-sum;
	return cnt;
}

