const int MAXN = (int)1e5 + 7;
vector<int> G[MAXN];
int n, root;
int deg[MAXN];
ll A[MAXN], must[MAXN];
int good = 1;
void dfs(int v, int pa) {
	vector<ll> piles;
	if(pa != NIL) piles.push_back(A[pa]);
	for(auto& u: G[v]) if(u != pa) {
		dfs(u, v);
		piles.push_back(A[u]);
	}
	DBG(v + 1);
	DBG(A[v]);
	if(len(piles) == 1) {
		good &= (piles.front() >= A[v]);
		DBG(piles.front());
		must[v] = A[v];
	} else {
		ll sum = 0;
		for(auto& el: piles) sum += el;
		ll cntPairs = 0;
		for(auto& el: piles) cntPairs += min(el, sum - el);
		cntPairs /= 2LL;
		DBG(cntPairs);
		good &= cntPairs >= A[v];

		sum = 0;
		for(auto& u: G[v]) if(u != pa) {
			sum += must[u];
		}
		cntPairs = 0;
		for(auto& u: G[v]) if(u != pa) {
			cntPairs += min(must[u], sum - must[u]);
		}
		cntPairs /= 2LL;
		must[v] = sum - min(2 * cntPairs, A[v]);
		if(must[v] < 0) must[v] = 0;
		DBG(must[v]);
		good &= must[v] == A[v];
	}
}
void solve() {
	cin >> n; for(int i = 0; i < n; ++i) cin >> A[i];
	for(int i = 0; i < n - 1; ++i) {
		int v = fetch<int>() - 1;
		int u = fetch<int>() - 1;
		G[v].push_back(u);
		G[u].push_back(v);
		++deg[v];
		++deg[u];
	}
	if(n == 2) {
		cout << (A[0] == A[1] ? "YES\n" : "NO\n");
		return;
	}
	root = 0;
	while(root < n && deg[root] <= 1) ++root;
	assert(root < n);
	dfs(root, NIL);
	cout << (good ? "YES\n" : "NO\n");
}

int main() {
	fast_io();
	solve();

	return 0;
}

