  }
  ll sum_leaves = 0;
  int root = 0;
  rep (i, n) {
    if (g[root].size() < g[i].size()) {
      root = i;
    }
    if ((int)g[i].size() == 1) {
      leaves.insert(i);
      sum_leaves += a[i];
    }
  }
  if ((sum_leaves&1) == 1) {
