typedef long long ll;
typedef vector< vector<int> > Graph;

Graph g;
ll a[100010];
int root = 0;
bool used[100010];

ll dfs(int idx, int p) {
	used[idx] = true;
	if (idx != root && g[idx].size() == 1) return a[idx];

	priority_queue<ll> pq;
	for (int nex : g[idx]) {
		if (nex == p) continue;
		ll tmp = dfs(nex, idx);
		if (tmp == -1) return -1;
		if (tmp == 0) continue;
		pq.push(tmp);
	}

	ll res = a[idx];
	while (pq.size() > 1) {
		ll x = pq.top();
		pq.pop();
		ll y = pq.top();
		pq.pop();
		if (x > y) {
			pq.push(x - y);
			res -= y;
		} else if (x < y) {
			pq.push(y - x);
			res -= x;
		} else {
			res -= x;
		}
		if (res < 0) return -1;
	}	
	if (pq.empty()) {
		if (idx != root) return res;
		else if (res != 0) return -1;
		else return 0;
	}
	if (res < pq.top()) return -1;
	if (idx != root) return res;
	else return 0;
}

