ll dfs(int a, int par) {
	if((int) w[a].size() == 1)
		return val[a];
	vector<ll> children;
	for(int b : w[a]) if(b != par)
		children.push_back(dfs(b, a));
	ll s = 0;
	ll big = 0;
	for(ll x : children) {
		s += x;
		big = max(big, x);
	}
	// sum + ? = 2 * val
