        if (g[v][i] != p) {
            d[g[v][i]] -= a[v];
            dfs1(g[v][i], v);
            ++f;
        }
    }
    if (f == 0) {
        //cout << "#" << v << " " << d[v] << endl;
        return;
    }
    if (f <= 2) {
        for (long long i = 0; i < g[v].size(); ++i) {
