    for (long long i = 0; i < g[v].size(); ++i) {
        if (g[v][i] != p) {
            if (d[g[v][i]] > 0) {
                wa();
            }
            sum -= d[g[v][i]];
        }
    }
    if (sum % (f - 2)) {
        wa();
    }
    sum /= (f - 2);
    //cout << "#" << sum << endl;
    long long all = 0, mx = 0;
    for (long long i = 0; i < g[v].size(); ++i) {
        if (g[v][i] != p) {
