int dfs(int x){
	if(ed[x].size() == 1u) return stone[x];
	multiset<int> ss;
	ll paths=0;
	for(int y:ed[x]) if(par[x]!=y){
		par[y]=x;
		ll tmp=dfs(y);
		ss.insert(tmp);
		paths += tmp;
	}
	ll pairs = paths-stone[x];
	if(pairs < 0) NO();
	if(paths - 2*pairs < 0) NO();
	ll mm=0;
	while(ss.size() >= 2u){
		ll a=*--ss.end();
		ll b=*--(--ss.end());
		if(b == 0) break;
		if(b > 5){
			ll tmp=b-5;
			a-=tmp; b-=tmp; mm+=tmp;
			ss.erase(--ss.end());
			ss.erase(--ss.end());
			ss.insert(a);
			ss.insert(b);
			continue;
