	}
	int new1(int p,int from)
	{
		if(degree[p]==1)return time[from]=A[p];
		int sum=0;
		for(int i=last[p];i;i=next[i])
		if((i>>1)!=from)sum+=new1(son[i],i>>1);
		if(sum>A[p]<<1)printf("NO"),exit(0);
		if(!from)
		{
			if(sum==A[p]<<1)printf("YES");
			else printf("NO");
			exit(0);
		}
		return time[from]=(A[p]<<1)-sum;
	}
};
