  }

  if (N == 2) {
    if (A[1] == A[2]) puts("YES");
    else puts("NO");
    return 0;
  }

  flag = 1;
  for (int i = 1; i <= N; ++i)
    if (deg[i] > 1) {
      dfs(i, 0);
      if (f[i] != A[i] * 2) flag = 0;
      break;
    }

  if (flag) puts("YES");
  else puts("NO");

  return 0;
}

