long long calc(int pos, int pre) {
	if (g[pos].size() == 1) return a[pos];
	int mx = 0; long long sum = 0;
	for (int i : g[pos]) {
		if (i == pre) continue;
		int res = calc(i, pos);
		if (res == -1) return -1;
		sum += res;
		mx = max(mx, res);
	}
	long long ops = sum - a[pos];
	long long lim = min(sum - mx, sum / 2);
	if (ops > lim) return -1;
	return sum - ops * 2;
}
