bool foo() {
    int64_t n;
    cin >> n;
    vector<int> A(n), a(n), b(n);
    for (int i = 0; i < n; i++) {
        cin >> A[i];
    }
    for (int i = 0; i < n - 1; i++) {
        cin >> a[i] >> b[i];
        a[i]--;
        b[i]--;
    }

    vector<pair<int, int>> e((n - 1) * 2);
    for (int i = 0; i < n - 1; i++) {
        e[i * 2 + 0] = { a[i], b[i] };
        e[i * 2 + 1] = { b[i], a[i] };
    }
    sort(e.begin(), e.end());

    bool r = true;

    std::function<int(int, int)> f = [&](int i, int parent) {
        auto p0 = lower_bound(e.begin(), e.end(), pair<int, int>{ i, 0 });
        auto p1 = lower_bound(e.begin(), e.end(), pair<int, int>{ i + 1, 0 });
        if (parent >= 0 && p1 - p0 == 1) {
            return A[i];
        }
        int64_t s = 0;
        int m = 0;
        for (auto it = p0; it != p1; it++) {
            int j = it->second;
            if (j == parent) continue;
            int t = f(j, i);
            s += t;
            m = max(m, t);
        }
        int g = A[i] * 2 - s;
        if (parent < 0) {
            if (p1 - p0 == 1) {
                if (s != A[i]) r = false;
            } else {
                if (g != 0) r = false;
                if (0 < m - (s - m)) r = false;
            }
            return 0;
        }
        if (g < 0 || g < m - (s - m)) r = false;
        return (int)g;
    };
    f(0, -1);
    return r;
}

int main() {
    cout << (foo() ? "YES" : "NO") << endl;
    return 0;
}

