inline void addedge(int u, int v)
{
	edge[++tot] = Edge{ v, start[u] };
	start[u] = tot;
	edge[++tot] = Edge{ u, start[v] };
	start[v] = tot;
	d[u]++;
	d[v]++;
	return;
}
inline bool dfs(int u, int fa)
{
	if (d[u] == 1) {
		up[u] = val[u];
		return false;
	}
	int sum = 0, maxx = 0;
	for (int i = start[u]; i; i = edge[i].next) {
		int v = edge[i].to;
		if (v != fa) {
			if (dfs(v, u))
				return true;
			sum += up[v];
			maxx = max(maxx, up[v]);
		}
	}
	up[u] = (val[u] << 1) - sum;
	if (up[u] < 0 || up[u] > val[u] || val[u] < maxx) {
		printf("NO\n");
		return true;
	}
	return false;
}
