        } else {
          cout << "NO\n";
        }
        return;
      }
    }
    if (n == 2 && a[0] == a[1]) {
      cout << "YES\n";
    } else {
      cout << "NO\n";
    }
  }

  ll dfs(int v) {
    used[v] = true;

    vector<ll> vv;
    ll total = 0;
    int child_count = 0;
    for (auto u : g[v]) {
      if (used[u]) {
        continue;
      }

      ++child_count;
      auto value = dfs(u);
      vv.push_back(value);
      total += value;
    }

    if (!child_count) {
      return a[v];
    }

    sort(vv.begin(), vv.end());

    auto calc_value = [](const auto& values) {
      ll res = 0;
      ll sum = 0;
      for (auto value : values) {
        sum += value;
      }
      if (sum - values.back() < values.back()) {
        return sum - values.back();
      }
      return sum / 2;
    };

    auto matches = calc_value(vv);

    if (a[v] > total || a[v] < total - matches) {
      DEBUG("v: " << v << " a[v]: " << a[v] << " total: " << total << " matches: " << matches);
      cout << "NO\n";
      exit(0);
    }

    DEBUG("v: " << v << " res: " << total - 2ll * a[v]);
    return 2 * a[v] - total;
  }

  int n;
  vector<int> a;
  vector<vector<int>> g;
  vector<bool> used;
};

