    vector<Node*> dests;
    ll a;
    void add(Node* n){
        dests.push_back(n);
    }
    void add2(Node* n){
        add(n);
        n->add(this);
    }
    pair<ll, ll> dfs(Node* from = nullptr){
        vector<pair<ll, ll>> vp;
        int cnt = 0;
        bool even = true;
        for(Node* d : dests){
            if(d == from){ continue; }
            cnt++;
            vp.push_back(d -> dfs(this));
        }
        if(!cnt){ return {a, a}; }
        ll mini = 0, maxi = 0, mami = 0, mama = 0;
        for(auto p : vp){
            even ^= p.first % 2;
            mini += p.first;
            maxi += p.second;
            mami = max(mami, p.first);
            mama = max(mama, p.second);
        }
        if(a < mami || a < (mini + 1) / 2){
            cout << "NO" << '\n';
            exit(0);
        }
        ll rmi = a, rma = a;
        rmi = maxi - mama + 2 <= mama ? a - (maxi - mama) : a - maxi / 2;
        if(rmi < 0){
            rmi = 0;
        }
        // rma = mini <= a ? a : a - (mini + 1) / 2;
        rma = mini <= a ? a : a - (mini - a);
        prints(a, rmi, rma);
        return {rmi, max(rmi, rma)};
    }
};

