ll dfs(int v, int p) {
	if  (sz(g[v]) == 1) {
		return a[v];
	}

	// printf("in v=%d\n", v + 1);

	multiset<ll> S;

	ll sum = 0;
	for (int to : g[v]) {
		if (to == p) {
			continue;
		}

		ll x = dfs(to, v);
		// printf("to=%d, x=%lld\n", to + 1, x);
		if  (x == -1) {
			return -1;
		}
		sum += x;
		S.insert(x);
	}

	ll up = 2 * a[v] - sum;
	if  (up < 0) {
		return -1;
	}

	// printf("v=%d, up=%lld\n", v + 1, up);
	// for (auto x : S) {
	// 	printf("%lld ", x);
	// }
	// puts("");

	while (sum > up) {
		if  (sz(S) <= 1) {
			return -1;
		}

		ll mx1 = *S.rbegin();
		S.erase(S.find(mx1));

		ll mx2 = *S.rbegin();
		S.erase(S.find(mx2));

		ll mx3 = 0;
		if  (!S.empty()) {
			mx3 = *S.rbegin();
		}

		ll max_neg = mx2 - mx3 + 1;

		assert(max_neg > 0);

		// sum - neg * 2 >= up
		// sum - up >= neg * 2
		// (sum - up) / 2 >= neg
		max_neg = min(max_neg, (sum - up) / 2);

		if  (!max_neg) {
			return 0;
		}

		sum -= max_neg * 2;
		mx2 -= max_neg;
		mx1 -= max_neg;
		if  (mx1) {
			S.insert(mx1);
		}
		if  (mx2) {
			S.insert(mx2);
		}
	}

	return up;
}

