    if(G[v][i] == p) continue;
    ll res = dfs(G[v][i], v);
    if(res < 0) return -INF;
    sum += res;
    c.push_back(res);
  }
  if(c.size() == 1){
    if(A[v] == c[0]) return c[0];
    else return -INF;
  }

  ll T = 2LL*A[v] - sum;
  if(T<0 || T>A[v]) return -INF;
  ll L = A[v] - T;

  int n = 0;
  int m = c.size()-1;
  ll PR = 0;
  sort(ALLOF(c));
  while(n < m){
    ll mn = min(c[n],c[m]);
    PR += mn;
    c[n] -= mn;
    c[m] -= mn;
    if(c[n]==0) n++;
    if(c[m]==0) m--;
  }
  if(L <= PR) return T;
  return -INF;
}


bool solve(){
  if(N==2){
    return A[0] == A[1];
  }

  ll leaf1 = -1;
  ll sum = 0;
  rep(i,N){
    if(G[i].size() == 1){
      leaf1 = i;
      sum += A[i];
    }
  }
  if(sum%2!=0) return false;
  rep(i,N){
    if(A[i] > sum/2) return false;
  }

  ll res = dfs(leaf1,-1);
  if(res == A[leaf1]) return true;
  return false;
}

