void solve(){
    i64 n;
    cin >> n;
    vector<i64> a(n);
    rep(i,0,n) cin >> a[i];
    vector<vector<int>> graph(n);
    rep(i,0,n-1){
        i64 a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if(n==2){
        if(a[0]==a[1]) cout << "YES" << endl;
        else cout << "NO" << endl;
        return;
    }

    vector<i64> r(n);
    function<bool(int,int)> rec=[&](int u,int p){
        if(graph[u].size()==1) return true;
        r[u]=-a[u];
        priority_queue<int,vector<int>>  que;
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            r[u]+=a[v]-r[v];
            que.push(a[v]-r[v]);
        }
        int x=0;
        while(x<r[u] and que.size()>=2){
            auto f=que.top(),g=que.top();
            que.pop();
            que.pop();
            x+=g;
            if(f-g) que.push(f-g);
            if(x>r[u]) x=r[u];
        }
        if(p==-1) return r[u]==a[u] and x==r[u];
        return x==r[u];
    };

    rep(i,0,n){
        if(graph[i].size()<2) continue;
        if(rec(i,-1)) cout << "YES" << endl;
        else cout << "NO" << endl;
        return;
    }
}

