bool flag=true;

ll dfs(int idx,int par,vector<ll> &A,Graph &g){
	ll sum=0;
	ll num=0;
	int cnt=0;
	for(int next:g[idx]){
		if(par==next) continue;
		ll v=dfs(next,idx,A,g);
		chmax(num,v);
		sum+=v;
		cnt++;
	}
	//cout<<idx<<" "<<sum<<endl;
	//cout<<flag<<endl;
	if(par==-1){
		if(cnt==0){
			if(A[idx]!=sum) flag=false;
		}else{
			if(sum%2==1 || A[idx]!=sum/2) flag=false;
		}
		return 0;
	}
	if(cnt==0) return A[idx];
	ll x=sum-A[idx]; //完結
	ll k=0;
	if((sum-num)*2>=sum){
		k=sum/2;
	}else{
		k=(sum-num);
	}
	//cout<<endl<<x<<" "<<k<<endl;
	if( !(x>=0 && x<=k) ){
		flag=false;
	}
	return sum-x*2;
}

