bool f=true;

ll dfs(const Graph& g, int node){
  int sz=g[node].size();
  if(sz==0){
    return c[node]=a[node];
  }
  ll sum=0;
  for(int i=0;i<sz;i++){
    int next=g[node][i];
    sum += dfs(g,next);
  }
  c[node]=2*a[node]-sum;
  if(c[node]<0 || c[node]>a[node]) f=false;
  if((sum-c[node])%2) f=false;
  if(sz==1){
    if(c[node] != a[node] || a[node] != c[g[node][0]]) f=false;
  }
  ll num=(sum-c[node])/2; // num 組作れるか
  ll ma=0;
  if(num<0) f=false;
  ll tmp=sum/2;
  for(int i=0;i<sz;i++){
    int next=g[node][i];
    ma=max(ma,c[next]);
  }
  tmp = min(ma,tmp);
  if(tmp<num) f=false;
  return c[node];
}

