ll dfs(int v, int p) {
	if  (sz(g[v]) == 1) {
		return a[v];
	}

	// printf("in v=%d\n", v + 1);

	vll sons;
	ll sum = 0;
	for (int to : g[v]) {
		if (to == p) {
