	if  (up < 0) {
		return -1;
	}

	sort(all(sons));
	if  (sz(sons) == 1) {
		if  (sons[0] != up) {
			return -1;
		}
		return up;
	}

	ll Up = up;

	ll neg = min(Up, sons.back() - sons[sz(sons) - 2]);
	sons.back() -= neg;
	Up -= neg;

	if  (Up > 0) {
		forn(i, sz(sons)) {
			sons[i] += Up / sz(sons);
			if  (i < Up % sz(sons)) {
				++sons[i];
			}
		}
		Up = 0;
	}


	{
		ll s = accumulate(all(sons), 0ll);
		s -= sons.back();
		if  (s < sons.back()) {
			return -1;
		}
	}

	return up;
}

