void fail() {
    cout << "NO\n";
    exit(0);
}

pair<ll, ll> go(vvi& adj, vi& stones, int loc, int par) {
    bool leaf = true;
    ll min_tot = 0, max_tot = 0;

    vector<pair<int, int>> below;
    for (int nbr : adj[loc]) if (nbr != par) {
        leaf = false;

        auto p = go(adj, stones, nbr, loc);
        below.push_back(p);

        min_tot += p.first;
        max_tot += p.second;
    }

    if (loc == par) {
        if (stones[loc] < min_tot) fail();
        if (stones[loc] > max_tot) fail();
        if ((stones[loc] ^ min_tot)&1) fail();
        return { 0ll, 0ll };
    }
    if (leaf) return { stones[loc], stones[loc] };

    sort(all(below));
    auto big = below.back();

    if (max_tot < stones[loc]) fail();

    ll max_pairs = min(min_tot - big.first, min_tot / 2);
    if (stones[loc] < min_tot - max_pairs) fail();

    return { stones[loc] - max_pairs, stones[loc] };
}

