long long dfs(const vector<vector<int>> &G, const vector<long long> &A, int v, int prev){
  //cerr << v << endl;
  if(G[v].size() == 1 and G[v][0] == prev) return A[v];
  vector<long long> B;
  long long s = 0;
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    long long t = dfs(G,A,v_,v);
    if(t < 0) return -1;
    B.push_back(t);
    s += t;
  }
  sort(B.rbegin(), B.rend());
  long long d = s - A[v];
  // fprintf(stderr,"v = %d, d = %lld, s = %lld\n",v,d,s);
  // cerr << "B : ";
  // for(auto b : B) cerr << b << " " ;
  // cerr << endl;
  int l = 0, r = B.size()-1;
  while(d > 0 and r-l+1 >= 2){
    long long d_ = min({B[r],B[l],d});
    d -= d_;
    s -= 2*d_;
    B[r] -= d_;
    B[l] -= d_;
    if(not d) break;
    if(not B[r]) --r;
    if(not B[l]) ++l;
  }
  // fprintf(stderr,"v = %d, d = %lld, s = %lld\n",v,d,s);
  if(d) return -1;
  return s;
}

