void dfs(int x){
	bz[x]=1;
	if (d[x]==1){c[x]=a[x];return;}
	for(int p=h[x];p;p=e[p].nxt)
	if (!bz[e[p].x]){
		fa[e[p].x]=x;
		dfs(e[p].x);
