		mv=maxll(mv,c[e[p].x]);
	}
	LL k=s-a[x];
	if (k<0)ans=0;
	c[x]=s-k*2;
	if (c[x]<0)ans=0;
	if (mv>s/2&&s-mv<k)ans=0;
}

