ll countPairs(const vector<ll> &g) {
  if (g.size() < 2) {
    return 0;
  }
  ll sum = accumulate(g.begin(), g.end(), 0ll);
  ll res = 1ll << 60;
  for (ll x : g) {
    res = min(res, max(x, sum / 2));
  }
  return res;
}

ll dfs(int v, int p) {
  ll a = A[v];
  vector<ll> children;
  for (int u : G[v]) {
    if (u != p) {
      ll c = dfs(u, v);
      if (c < 0) {
        return -1;
      }
      children.push_back(c);
    }
  }
  if (children.empty()) {
    return a;
  }
  ll sum = accumulate(children.begin(), children.end(), 0ll);
  ll y = sum - a;
  ll x = a - y;
  if (x < 0 || y < 0 || countPairs(children) < y) {
    return -1;
  }
  return x;
}

