	if(v.empty()){
		//cout << "return " << a[cur] << endl;
		return a[cur];
	}else{
		if(childSum < a[cur]){ //どのようにしても石が取りきれない
			ans = false;
			return 0;
		}

		long long sum = requirePairNumber(v);
		if(loot == cur and sum != a[cur]){
			ans = false;
			return 0;
		}

		long long needPair = childSum - a[cur];
		if(sum >= needPair){
			return a[cur] - needPair;
		}else{
			ans = false;
		}

		return 0;
	}
}

