struct edd{
	int nxt,v;
}e[maxn*2];

inline void add(int a,int b){
	e[k].v=b; e[k].nxt=head[a]; head[a]=k++;
	e[k].v=a; e[k].nxt=head[b]; head[b]=k++;
}

inline int rd(){
	int ret=0,af=1; char gc=getchar();
	while(gc < '0' || gc > '9'){ if(gc=='-') af=-af; gc=getchar(); }
	while(gc >= '0' && gc <= '9') ret=ret*10+gc-'0',gc=getchar();
	return ret*af;
}

void dfs(int u,int fa){
	if(ans) return;
	ll f,sf=0,sum=0,d;
	tl=0;
	for(int i=head[u];i+1;i=e[i].nxt){
		int v=e[i].v;
		if(v==fa) continue;
		dfs(v,u);
		if(ans) return;
		q[++tl]=up[v],sum+=up[v];
	}
	if(!tl) up[u]=a[u];
	else{
		f=2*a[u]-sum;d=sum-f;
		if(f<0){ans=1;return;}
		for(int i=1;i<=tl;++i){
			sf+=q[i]>d/2?q[i]-d/2:0;
		}
		if(sf>f){ans=1;return;}
		//我们在“子节点自行解决的时候 ”，子节点总权值-2，父节点权值-1，已排除了一些情况 
		//然而子节点之间的差值过大的时候，同样是不可行的
		//对于一个较大的子节点，如果他的权值数大于“自行解决”的总次数，就必须通过父节点解决，将这些“必须通过父节点解决的权值”加起来与“应该通过父节点解决的权值”比较
		//若sf<f，说明权值比较均匀
		up[u]=f;
	}
}

