#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll upper_bound(const vector<int>& stones)
{
    if (stones.size() == 1) return 0;
    const auto max = *max_element(begin(stones), end(stones));
    const auto sum = accumulate(begin(stones), end(stones), 0LL);
    if (max >= sum-max) return sum-max;
    else return sum/2;
}

int main()
{
    int N; cin >> N;

    auto stones = vector<int>(N);
    for (auto& x : stones) cin >> x;

    if (N == 2)
    {
        cout << (stones[0] == stones[1] ? "YES" : "NO") << endl;
        return 0;
    }

    auto adjacency_list = vector<vector<int>>(N);
    for (auto i = 0; i < N-1; i++)
    {
        int a, b; cin >> a >> b;
        a--; b--;
        adjacency_list[a].push_back(b);
        adjacency_list[b].push_back(a);
    }

    const function<bool(int, int)> dfs = [&](const int v, const int parent)
    {
        if (adjacency_list[v].size() == 1) return true;

        auto counts = vector<int>();
        for (auto child : adjacency_list[v]) if (child != parent)
        {
            if (!dfs(child, v)) return false;
            else counts.push_back(stones[child]);
        }

        const auto sum = accumulate(begin(counts), end(counts), 0LL);
        const auto a = sum - stones[v], b = 2*stones[v] - sum;
        stones[v] = int(b);
        return 0 <= a && a <= upper_bound(counts) && 0 <= b;
    };

    auto root = 0;
    while (adjacency_list[root].size() == 1) root++;
    cout << (dfs(root, -1) && stones[root] == 0 ? "YES" : "NO") << endl;
}

