    vector<int> roots;
    REP(i, N) if(next[i].size() > 1){
        roots.push_back(i);
    }

    REP(j, min(5, (int)roots.size())) {
        REP(i, a::N) a::child[i].clear();
        REP(i, a::N) a::inner[i] = 0;
        build(roots[j]);
        bool answer = dfs(roots[j]);
        if(!answer) {
            return answer;
        }
    }

    return true;
}

}

