	if(g[v].size() == 1 and v != 0) return dp[v] = c[v];
	if(~dp[v]) return dp[v];

	std::vector<long> vec;
	for(auto e : g[v]) if(e != p) vec.push_back(dfs(e, v));
	sort(begin(vec), end(vec));

	long S = std::accumulate(begin(vec), end(vec), 0LL);
