int get_path_num(int v) {
  searched[v] = true;
  int c_sum = 0;
  int c_max = 0;
  bool is_leaf = true;
  REP(i, G[v].size()) {
    int child = G[v][i];
    if (!searched[child]) {
      is_leaf = false;
      int tmp = get_path_num(child);
      if (tmp == -1) return -1;
      if (tmp > c_max) c_max = tmp;
      c_sum += tmp;
    }
  }
  if (is_leaf) {
    return A[v];
  } else {
    int c = 2 * A[v] - c_sum;
    int both = c_sum - A[v];
    if (c < 0 || both < 0 || min(c_sum - c_max, c_sum / 2) < both) return -1;
    return c;
  }
}

