using namespace std;

Graph to_rooted_tree(const Graph &g, int root = 0) {
    int n = g.size();
    Graph res(n);
    constexpr Weight INF = std::numeric_limits<Weight>::max() / 2;
    std::vector<int> dist(n, INF);
    std::deque<std::pair<int, int>> to_visit; // fixme
    dist[root] = 0;
    to_visit.emplace_back(0, root);
    while (to_visit.size()) {
        Weight d; int v;
        std::tie(d, v) = to_visit.back(); // fixme
        to_visit.pop_back(); // fixme
        d = -d;
        for(auto &e : g[v]){
            if (dist[e.dst] > dist[v] + e.weight) {
                dist[e.dst] = dist[v] + e.weight;
                to_visit.emplace_back(dist[e.dst], e.dst); // fixme
                res[e.src].emplace_back(e);
            }
        }
    }
    return res;
}

int n;
int a[100010];
Graph g;

// 親への辺は何回通るか
int dfs(int v) {
    if (g[v].size() == 0) {
        return a[v];
    } else if (g[v].size() == 1) {
        int c = g[v][0].dst;
        return dfs(c) == a[v] ? a[v] : -1;
    } else {
        static vector<int> dfsc;
        dfsc.clear();
        int sum = 0;
        for (auto &e : g[v]) {
            int x = dfs(e.dst);
            dfsc.push_back(x);
            sum += x;
        }
        bool ok = true;
        for (auto &x : dfsc) {
            if (x < 0 || a[v] < x) {
                ok = false;
                break;
            }
        }
        int res = 2 * a[v] - sum;
        if (res < 0 || a[v] < res) {
            ok = false;
        }
        return ok ? res : -1;
    }
}

bool solve() {
    int r = -1;
    for (int i = 0; i < n; i++) {
        if (g[i].size() != 1) {
            r = i;
            break;
        }
    }
    if (n == 2) return a[0] == a[1];
    g = to_rooted_tree(g, r);
    return dfs(r) == 0;
}

