ll obtain(vector<ll>&chs) {

	if(!sz(chs)) return 0;

	ll mt=0,re=chs[0];

	for(int i=1;i<sz(chs);i++) {

		ll nm=min(chs[i],re);

		chs[i]-=nm;
		re-=nm;

		ll cm=min(chs[i]/2,mt);

		chs[i]-=cm*2;
		re+=chs[i];
		mt+=cm+nm;

	}

