int N;
int A[100005];
vector <int> G[100005];
bool visited[100005];

int dfs(int x) {
    visited[x] = true;
    if (G[x].size() == 1) {
        return A[x];
    } else {
        int cost = 0;
        int mx = 0;
        for (int i = 0; i < G[x].size(); i++) {
            if (visited[G[x][i]]) continue;

            int d = dfs(G[x][i]);
            if (d == -1) return -1;

            cost += d;
            mx = max(d, mx);
        }

        if (A[x] > cost || A[x] < mx) {
            return -1;
        } else {
            return 2 * A[x] - cost;
        }
    }
}

