LL dfs(int p , int q){
	if((int)V[q].size() == 1) return A[q];
	LL z = 0;
	repv(int,it,V[q]){
		if(*it == p) continue;
		LL w = dfs(q,*it);
		if(w > (LL)A[q]) b = 0;
		z += w;
