// EOT

const int MAXN = 1e5 + 5;

struct Edge {
    int v, next;
    Edge() { }
    Edge(int v_, int next_): v(v_), next(next_) { }
};

int N;
LL A[MAXN];
int tote, head[MAXN];
Edge edge[MAXN * 2 + 5];
int deg[MAXN];

inline void addEdge(int u, int v)
{
    edge[++tote] = Edge(v, head[u]);
    head[u] = tote;
}

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
    for (int i = 1; i < N; ++i) {
        int u, v;
        read(u); read(v);
        addEdge(u, v);
        addEdge(v, u);
        ++deg[u]; ++deg[v];
    }
}

LL dfs(int u, int f)
{
    if (deg[u] == 1)
        return A[u];
    LL sum = 0;
    LL max = 0;
    for (int i = head[u]; i; i = edge[i].next) {
        int v = edge[i].v;
        if (v == f) continue;
        LL cur = dfs(v, u);
        sum += cur;
        chkmax(max, cur);
    }
    LL fe = 2 * A[u] - sum;
    sum += fe;
    chkmax(max, fe);
    if (fe < 0 || sum % 2 != 0 || (max > sum / 2)) {
        puts("NO");
        exit(0);
    }
    return fe;
}

void solve()
{
    if (N == 2) {
        puts(A[1] == A[2] ? "YES" : "NO");
        return;
    }
    int rt = 0;
    for (int i = 1; i <= N; ++i) {
        if (deg[i] != 1) {
            rt = i;
            break;
        }
    }
    LL left = dfs(rt, 0);
    puts(left == 0 ? "YES" : "NO");
}

int main()
{
#ifdef __DEBUG
    freopen("C.in", "r", stdin);
    freopen("C.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

