int parent[100010];
vector<int>nodes[100010];

void maketree(int x){
    for(int y:nodes[x]){
        if(y==parent[x])continue;
        parent[y]=x;
        maketree(y);
    }
}

bool f(int x){
    if(nodes[x].size()==1)return true;
    ll sum=0;
    for(int y:nodes[x]){
        if(y==parent[x])continue;
        if(!f(y))return false;
        sum+=arr[y];
    }
    if(arr[x]>sum)return false;
    arr[x]-=sum-arr[x];
    if(arr[x]<0)return false;
    //printf("%d:%d\n",x,arr[x]);
    return true;
}

