#include <bits/stdc++.h>
using namespace std;
const int MAXN = 100005;
typedef long long ll;

vector <int> g[MAXN];
bool visited[MAXN];
ll f[MAXN];
ll a[MAXN];

bool dfs(int v)
{
	visited[v] = true;
	if (g[v].size() == 1)
	{
		f[v] = a[v];
		return true;
	}

	ll cnt = 0;
	ll mx = 0;
	for (int i = 0; i < g[v].size(); i++)
	{
		if (!visited[g[v][i]])
		{
			if (!dfs(g[v][i]))
			{
				return false;
			}
            cnt += f[g[v][i]];
            mx = max(f[g[v][i]], mx);
		}
	}

	if (a[v] > cnt) return false;

    ll mxop = min(cnt - mx, cnt/2);

	if (cnt - a[v] > mxop) return false;

	f[v] = a[v] - (cnt - a[v]);
	return true;
}

int main()
{
    int n;
	cin >> n;
	for (int i = 1; i <= n; i++)
		cin >> a[i];

