using namespace std;

static vector<int> adj[100005];
static int arr[100005];

int dfs(int u, int p){
	if(adj[u].size() == 1) return arr[u];
	int rope = 0;
	for(int v : adj[u]){
		if(v == p) continue;
		rope += dfs(v, u);
	}
	if(rope < arr[u]){
		cout << "NO";
		exit(0);
	}
	rope -= 2 * (rope - arr[u]);
	if(rope < 0){
		cout << "NO";
		exit(0);
	}
	return rope;
}

