int findx(int p[], vector<int> ko[], int oya, int co){
    if(ko[co].size()==1)return p[co];

    int sum=0,t,maxs=0;
    for(int i=0;i<ko[co].size();i++){
        if(ko[co][i]!=oya){
            t=findx(p,ko,co,ko[co][i]);
            if(t==-1)return -1;
            maxs=max(maxs,t);
            sum+=t;
        }
    }
    if(2*p[co]<sum)return -1;
    maxs=max(maxs,2*p[co]-sum);
    if(maxs>p[co])return -1;
    return 2*p[co]-sum;
}

