Int A[216000];
Int a, b, n;

int dfs(int x, int last = -1){
  if(deg[x] == 1)return A[x];
  Int mx = 0;
  Int sum = 0;
  for(auto to: edge[x]){
    if(to == last)continue;
    Int u = dfs(to, x);
    mx = max(mx, u);
    sum += u;
  }
  Int flip = sum - A[x];
  Int res = sum - 2 * flip;
  if(flip < 0)ng();
  if(flip > min(sum - mx, sum / 2))ng();
  if(res < 0)ng();
  return res;
}


