void yes(){
	cout << "YES" << endl;
	exit(0);
}

void no(){
	cout << "NO" << endl;
	exit(0);
}

int main(){

	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	cin >> n;
	for ( int i = 1; i <= n; i++ ) cin >> a[i];

	for ( int i = 0; i < n-1; i++ ){
		int u , v;
		cin >> u >> v;
		E[u].pb(v);
		E[v].pb(u);
		D[u]++;
		D[v]++;
	}

	if ( n == 2 ){
		yes();
	}

	bool ans = true;
	for ( int i = 1; i <= n; i++ ){
		if ( D[i] == 1 ){
			continue;
		}
		vector < LL > val;
		for ( int v : E[i] ){
			val.push_back(a[v]);
		}
		sort(val.begin(),val.end());

		LL sum = 0;
		for ( LL v : val ) sum += v;
		LL fsum = 0;
		LL target = a[i];
		while ( !val.empty() ){
			LL bck = val.back();
			val.pop_back();
			if ( fsum >= target && sum >= target ){
				break;
			}
			if ( fsum <= target && fsum + bck >= target ){
				LL diff = target - fsum;
				LL rdiff = bck - diff;
				if ( sum - diff >= target && fsum >= rdiff ){
					sum -= diff;
					fsum += diff;
					break;
				}
			}

			fsum += bck;
			sum -= bck;
			if ( fsum >= target && sum >= target ) break;
		}	
		if ( fsum < target || sum < target ) {
			// cout << i << " " << fsum << " " << sum << " " << target << endl;
			no();
		}
	}

	yes();
	return 0;
}

