bool dfs (int x, int p, const vvi &g, vi &a, vll &cnt)
{
    bool ans = true;
    int sons = 0;

    for (int dest : g[x])
    if (dest != p)
    {
        ans |= dfs(dest, x, g, a, cnt);
        cnt[x] += cnt[dest];
        sons++;
    }

    // cnt[x] - paths leave subtree
    if (sons == 0)
        cnt[x] = a[x];
    else
    {
        // they all contain a[x]
        // so either 2 for strictly in, or 1 for leaving
        // a[x] = in + (cnt[x] - 2 * in)
        // a[x] = cnt[x] - in
        ans &= (cnt[x] >= a[x]);
        ll in = cnt[x] - a[x];
        cnt[x] -= 2 * in;
        ans &= (cnt[x] >= 0);
    }

    return ans;
}

void solve (int n)
{
    vi a(n);
    forn (i, n) cin >> a[i];

    vvi g(n);
    forn (i, n - 1)
    {
        int u, v;
        cin >> u >> v;
        --u, --v;
        g[u].pb(v);
        g[v].pb(u);
    }

    int root = -1;
    forn (i, n) if (sz(g[i]) > 1) root = i;

    if (root == -1)
    {
        assert(n == 2);
        cout << (a[0] == a[1] ? "YES" : "NO") << endl;
        return;
    }

    vll cnt(n);
    bool ok = dfs(root, -1, g, a, cnt);
    ok &= (cnt[root] == 0);
    cout << (ok ? "YES" : "NO") << endl;
    //exit(0);
}

