vector <int> adjList[100005];
int s;

long long dfs(int u, int p) {
	priority_queue <long long> childw;
	long long maxval = 0;
	for (int v : adjList[u]) {
		if (v == p) continue;
		long long cur = dfs(v, u);
		maxval += cur;
		if (cur == -1) return -1;
		if (cur != 0) childw.push(cur);
	}
	if (childw.empty()) return a[u];
	long long maxinner = 0;
	while (childw.size() > 1) {
		long long minus = childw.top(); childw.pop();
		long long cur = childw.top(); childw.pop();
		maxinner += minus - cur;
		if (minus - cur != 0) childw.push(minus - cur);
	}
	long long minval = (childw.empty() ? 0 : childw.top()) + maxinner;
	if (!(a[u] >= minval && a[u] <= maxval)) return -1;
	long long inner = maxval - a[u];
	return maxval - (inner * 2);
}

