vector<long long int>box;
vector<vector<int>>edge;
vector<long long int>up;
vector<bool>flag;
bool can = true;

long long int Search(int num) {
	if (up[num] != -1) {
		return up[num];
	}
	if (edge[num].size() == 1) {
		up[num] = box[num];
		return up[num];
	}
	flag[num] = false;
	long long int bag = box[num] * 2;
	for (auto i : edge[num]) {
		if (flag[i]) {
			bag -= Search(i);
		}
	}
	if (bag < 0||bag>box[num]) {
		can = false;
	}
	up[num] = bag;
	return up[num];
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	box.resize(N + 1);
	edge.resize(N + 1);
	up.resize(N + 1,-1);
	flag.resize(N + 1, true);
	for (int i = 1; i <= N; i++) {
		cin >> box[i];
	}
	for (int i = 0; i < N - 1; i++) {
		cin >> L >> R;
		edge[L].push_back(R);
		edge[R].push_back(L);
	}
	for (int i = 1; i <= N; i++) {
		if (edge[i].size() != 1) {
			if (!Search(i)&&can) {
				cout << "YES\n";
				return 0;
			}
			cout << "NO\n";
			return 0;
		}
	}
	return 0;
}

