ll stone[100010];
bool ch[100010];

ll dfs(int key, vector<vector<int>> &g){
    ch[key]=1;
    ll sum=0, mx=0;
    int cnt=0;
    for(int i=0; i<g[key].size(); ++i){
        if(!ch[g[key][i]]){
            ++cnt;
            ll p=dfs(g[key][i], g);
            if(p<0) return -1;
            sum += p;
            mx=max(mx, p);
        }
    }
    if(cnt==0) return stone[key];
    if(cnt==1){
        if(sum==stone[key]) return stone[key];
        else return -1;
    }
    ll num_pair=sum-stone[key];
    if(num_pair<0 || min(sum/2, sum-mx)<num_pair) return -1;
    stone[key] -= num_pair;
    return stone[key];
}

