void solve(int v, int par)
{
    if ((int)g[v].size() == 1) return;
    ll sum = 0;
    int mx = 0;
    for (int u : g[v])
    {
        if (u == par) continue;
        solve(u, v);
        sum += a[u];
        mx = max(mx, a[u]);
    }
    if (a[v] > sum || sum > 2 * a[v])
    {
        printf("NO\n");
        exit(0);
    }
    int k = sum - a[v];
    if (k > sum - mx)
    {
        printf("NO\n");
        exit(0);
    }
    a[v] -= k;
    return;
}

