#define N 100010
vector<int> g[N];
ll v[N], dp[N], n;
bool used[N], ok = true;

void rec(int x){
	used[x] = true;
	vector<int> r;
	r.reserve(g[x].size());
	for(auto y: g[x]){
		if(used[y]) continue;
		rec(y);
		r.push_back(dp[y]);
	}
	if(r.empty()){
		dp[x] = v[x];
		return;
	}
	sort(all(r));
	ll s = 0;
	int m = r.size();
	rep(i, m) s += r[i];
	dp[x] = v[x] - (s-v[x]);
	ll t = (s-dp[x])/2;
	if(dp[x]<0||dp[x]>v[x]||t<min(s/2, s-r[m-1])||(s-dp[x])%2){
		ok = false;
	}
}

