using namespace std;

using int64 = long long;

const int MAXN = 200000;

static int64 A[MAXN];
static vector<int> tree[MAXN];

int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    vector<int64> vec;

    int64 sum = 0;

    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
        if (child < 0) return -1;
        vec.push_back(child);
        sum += child;
    }
    if (sum < A[v]) return -1;

    A[v] -= sum;
    sort(vec.begin(), vec.end());

    for (int i = 0; i + 1 < vec.size(); i++) {
        int64 x = max(0LL, min(vec[i], -A[v]));

        A[v] += x;
        sum -= 2 * x;
        vec[i] -= x;
        vec[i + 1] -= x;
    }

    if (A[v] != 0) return -1;

    return sum;
}

