const int maxn = 1e5 + 100;
const ll inf = 2e18, mod = 1e9 + 7;

int n;
ll a[maxn], dp[maxn];
vector<int> graph[maxn];

void dfs(int u, int prev)
{
	if (prev != -1 && graph[u].size() == 1)
	{
		dp[u] = a[u];
		//cerr << '@' << u << ' ' << dp[u] << endl;
		return;
	}
	for (int i : graph[u])
		if (i != prev)
			dfs(i, u);

	multiset<ll> st;
	ll sum = 0;
	for (int i : graph[u])
		if (i != prev)
			st.insert(dp[i]), sum += dp[i];
	ll count = sum - a[u], lim = 0;
	while (st.size() > 1)
	{
		auto it = st.end();
		--it;
		ll now = *it;
		while (now)
		{
			ll tmp = *st.begin();
			lim += min(tmp, now);
			st.erase(st.begin());
			if (tmp > now)
				tmp -= now, now = 0;
			else
				now -= tmp, tmp = 0;
			if (tmp)
				st.insert(tmp);
		}
	}
	if (count > lim)
	{
		cout << "NO" << endl;
		exit(0);
	}
	dp[u] = a[u] - count;
	//cerr << '@' << u << ' ' << dp[u] << endl;
}

