#include <bits/stdc++.h>

using namespace std;

vector<int> g[100010];
vector<long long> A;

bool res = true;

void fail() {
    cout << "NO" << endl;
    exit(0);
}

long long dfs(int root, int prev) {
    vector<int> ws;
    for (auto e : g[root]) {
        if (e == prev) continue;
        ws.push_back(dfs(e, root));
    }

    if (ws.size() == 0) {
        return A[root];
    }


    long long max_consume = accumulate(ws.begin(), ws.end(), 0ll);
    long long min_consume = max_consume;

    priority_queue<long long> Q(ws.begin(), ws.end());

    while (Q.size() >= 2) {
        long long a = Q.top();
        Q.pop();
        long long b = Q.top();
        Q.pop();
        if (b == 0) break;
        min_consume -= b * 2;
        Q.push(a - b);
    }

    if (A[root] > max_consume) fail();
    if (A[root] < min_consume) fail();
    if( prev == -1) {
        if( max_consume != 2 * A[root] ) fail();
    }
    return A[root];
}

void solve(long long N, vector<long long> A_, vector<long long> a, vector<long long> b) {
    A = A_;
    for (int i = 0; i < N - 1; i++) {
        g[a[i] - 1].push_back(b[i] - 1);
        g[b[i] - 1].push_back(a[i] - 1);
    }
    if (N == 2) {
        cout << (A[0] == A[1] ? "YES" : "NO") << endl;
        return;
    }
    for (int i = 0; i < N; i++) {
        if (g[i].size() >= 2) {
            dfs(i, -1);
            cout << "YES" << endl;
            return;
        }
    }
    assert(0);
}

