    scanf("%lld", &N);
    vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        scanf("%lld", &A[i]);
    }
    vector<long long> a(N - 1);
    vector<long long> b(N - 1);
    for (int i = 0; i < N - 1; i++) {
        scanf("%lld", &a[i]);
        scanf("%lld", &b[i]);
    }
    solve(N, A, a, b);
    return 0;
}

