		if (cn[0] == cn[1]) {
			cout << "YES" << endl;
		}
		else {
			cout << "NO" << endl;
		}
		return 0;
	}

	function<ll(int, int)> imo = [&](int c, int p) {
		ll sum = 0;
		if (g[c].size() == 1) {
			sum = num[c];
		}
		for (auto itr : g[c]) {
			if (itr.to == p) continue;
			sum += imo(itr.to, c);
		}
		cn[c] -= sum;
		return sum;
	};

	imo(root, -1);

	function<pll(int, int)> dfs = [&](int c, int p) {
		ll es = 0;

		if (g[c].size() == 1) {
			return make_pair( num[c], 0LL );
		}
		vector<ll> up;
		for (auto itr : g[c]) {
			if (itr.to == p) continue;
			pll cc;
			cc = dfs(itr.to, c);
			up.push_back(cc.first);
			es += cc.second;
			cn[c] += cc.second * 2;
		}
		ll be = -cn[c];
		ll en = -cn[c], mt = 0;
		if(be < 0) {
			cout << "NO" << endl;
			exit(0);
		}
		ll mx = 0, sm = 0;
		for (auto itr : up) {
			mx = max(mx, itr);
			sm += itr;
		}
		if (mx > sm / 2)
			mx = n - mx;
		else
			mx = sm/2;

		if (mx < be) {
			cout << "NO" << endl;
			exit(0);
		}

		mt = sm - be * 2;

		return MP(mt, es + be);
	};

	pll ret = dfs(root, -1);

	if (ret.first != 0) {
		cout << "NO" << endl;
	}
	else {
		cout << "YES" << endl;
	}


	return 0;
}

