bool dfs(int v, int par){
    int sum = 0;
    int maxi = 0;
    int child = 0;
    for(int u : edge[v]){
        if(u == par){
            continue;
        }
        if(not dfs(u, v)){
            return false;
        }
        sum += a[u];
        maxi = max(maxi, a[u]);
        child++;
    }

    if(child == 0 && sum == 0){
        return true;
    }
    if(child == 1){
        return sum == a[v];
    }

    int path = sum - a[v];
    a[v] -= path;
    if(path < 0 || a[v] < 0){
        return false;
    }
    if(maxi < sum / 2 && path > sum / 2){
        return false;
    }
    if(maxi >= sum / 2 && sum - maxi < path){
        return false;
    }

    return true;
}

