ll a[100001];
vector<int> g[100001];
ll dfs(int v,int p){
    ll sum=0,mx=0;
    rep(i,g[v].size()){
        if(g[v][i]==p) continue;
        if(g[g[v][i]].size()==1){
            sum+=a[g[v][i]];
            mx=max(a[g[v][i]],mx);
        }
        else{
            ll r=dfs(g[v][i],v);
            if(r==-1) return -1;
            else sum+=r;
            mx=max(mx,r);
        }
    }
    ll t=a[v]*2-sum;
    if(a[v]<mx||t<0||a[v]>sum) return -1;
    return t;
}
