priority_queue<ll> Q;
void dfs(int x,int fa){
	if(d[x]==1){
		g[x] = a[x];
		return ;
	}
	for(int i = 0;i<v[x].size();i++) if(v[x][i]!=fa){
		int t = v[x][i];
