	if(t1<0 || t2<0) pd = false;
	//Q.clear();
	for(int i =0;i<b[x].size();i++) if(b[x][i]) Q.push(b[x][i]);
	ll tmp =0,t3,t4;
	while(Q.size()>=2){
		t3 = Q.top();
		Q.pop();
		t4  = Q.top();
		Q.pop();
		tmp+=t4;
		if(t3-t4) Q.push(t3-t4);
