int N;
vector<int> A;
vector<vector<int> > E;

int solve(int n, int p, bool & flg) {
	if(E[n].size() == 1)
		return A[n];
	ll s = 0;
	rep(i,E[n].size()) {
		if(E[n][i] == p) continue;
		s += solve(E[n][i], n, flg);
	}
	int I, O;
	I = s - A[n];
	O = A[n] - I;
	if(I < 0 || O < 0) flg = false;
	return O;
}

int main() {
	int root;
	cin >> N;
	A.resize(N); E.resize(N);
	rep(i,N) cin >> A[i];
	rep(i,N-1) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		E[a].push_back(b);
		E[b].push_back(a);
	}
	for(; root < N; root++) {
		if(E[root].size() > 1)
			break;
	}
	bool flg = true;
	int res = solve(root,-1,flg);
	if(flg && !res)
		cout << "YES" << endl;
	else
		cout << "NO" << endl;
	return 0;
}

