using namespace std;

typedef struct {
  int a;
  vector<int> ns;
} node;

int n;
vector<node> nodes;

bool dfs(int cur, int parent)
{
  node n = nodes[cur];
  int sum = 0;
  rep(i, n.ns.size()) {
    int next = n.ns[i];
    if(next != parent) {
      if(dfs(next, cur))
	sum += nodes[next].a;
      else
	return false;
    }
  }
  if(parent == -1) {
    node t = nodes[n.ns[0]];
    if(n.ns.size() == 1) {
      return n.a == t.a;
    } else {
      return (2 * n.a - sum == 2 * t.a);
    }
  } else {
    if(sum == 0) return true;
    if(2 * n.a < sum || n.a > sum)
      return false;
    else {
      nodes[cur].a = 2 * n.a - sum;
      return true;
    }
  }
}

int main()
{
  cin >> n;

  nodes.resize(n);
  rep(i, n)
    cin >> nodes[i].a;

  rep(i, n - 1) {
    int s, t;
    cin >> s >> t;
    nodes[s-1].ns.push_back(t-1);
    nodes[t-1].ns.push_back(s-1);
  }

  if(dfs(0, -1))
    cout << "YES" << endl;
  else
    cout << "NO" << endl;

  return 0;
}

