vvll rin;
vll oto;
vll A;
ll can;

ll dfs(ll now) {

	oto[now] = 1;
	ll hi = 0;
	ll rtn;
	if (rin[now].sz >= 3) {
		ROR(rin[now], i) {
			if (!oto[i]) hi += dfs(i);
		}
		if (A[now] > hi) can = 0;
		rtn = A[now] * 2 - hi;
	}
	if (rin[now].sz == 2) {
		ROR(rin[now], i) {
			if (!oto[i]) hi += dfs(i);
		}
		if (A[now] != hi) can = 0;
		rtn = hi;
	}
	if (rin[now].sz == 1) {
		if (oto[rin[now][0]]) rtn = A[now];
		else {
			rtn = dfs(rin[now][0]);
			if (rtn != A[now]) can = 0;
		}
	}
	return rtn;

}

