ll solve(int v, const vi& a, const vector<vi>& tree)
{
	if (tree[v].size() == 0) return a[v];
	vi t;
	for (auto i : tree[v])
	{
		ll tmp = solve(i, a, tree);
		if (tmp == -1) return -1;
		t.push_back(tmp);
	}
	ll sum = 0;
	for (auto i : t)
	{
		sum += i;
		if (sum > a[v] * 2) return -1;
	}
	if (sum < a[v]) return -1;
	ll res = a[v] * 2 - sum;
	if (res < 0) res = -1;
	return res;
}

