bool dfs(int now, int pre) {
    bool res = true;
    ll cstone = 0;
    ll child = 0;
    ll mx = 0;
    for (int nxt : edge[now]) {
        if (nxt == pre) continue;
        res &= dfs(nxt, now);
        child++;
        cstone += A[nxt];
        mx = max(A[nxt], mx);
    }
    if (child == 0) return true;
    if (child == 1) return (A[now] == cstone);
