		int nc;
		if (c[i].size() == 1) {
			if (A[i] != c[i][0]) return false;
			nc = A[i];
		}
		else {
			int sm = 0;
			for (int cs : c[i]) sm += cs;
			if (sm < A[i]) return false;

			int d = sm - A[i];

			sort(c[i].begin(), c[i].end());

			int l = 0, r = c[i].size() - 1;
			while (0 < d) {
				int ma = max(c[i][l], c[i][r]);
				if (d < ma) break;

				c[i][l] -= ma;
				c[i][r] -= ma;
				d -= ma;

				if (c[i][l] == 0) l++;
				if (c[i][r] == 0) r++;
				if (!(l < r)) return false;
