bool cansolve(int node)
{
	if(graph[node].size() == 1) return true;
	ischecked[node] = true;
	int childstonesum = 0;
	int nummax = 0, secondnummax = 0;
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		if(cansolve(child)) {
			childstonesum += stonenum[child];
			if(nummax < stonenum[child]){
				secondnummax = nummax;
				nummax = stonenum[child];
			}
			secondnummax = max(secondnummax, stonenum[child]);
		} else {
			return false;
		}
	}
	if(stonenum[node] > childstonesum) {
		return false;
	} else if(stonenum[node] == childstonesum) {
		return true;
	} else if(stonenum[node] - secondnummax >= childstonesum - 2 * secondnummax){
		stonenum[node] -= childstonesum - stonenum[node];
		return true;
	}
	return false;
}

