void dfs(int u, int fu) {
    int sum = 0;
    int ln = -1;
    bool hasChild = 0;

    for(int v : ke[u]) {
        if (v == fu) continue;

        dfs(v, u);
        hasChild = 1;
        sum += f[v];
        ln = max(ln, f[v]);
    }

    if (!hasChild) {
        f[u] = a[u];
        return ;
    }

    int pair = sum - a[u];
    f[u] = a[u] - pair;

    if (pair < 0) throw 1;
    if (f[u] < 0) throw 1;

    if (pair > sum - ln) throw 1;

}

