vector<int> adj[MAXN];

int arr[MAXN];

int n;

bool check(ll sum, int mx, int st, int p) {
	ll t = 0;     

	if (mx < p) {
		return 0;
	}

    if (mx - sum > p) {
    	return 0;
    }

    t += (mx - p);
	sum -= (mx - p);

	if (sum & 1) {
		return 0;
	}

	t += (sum >> 1);
	return st - t == p;
}

bool dfs(int v, int pr) {
	if ((int)adj[v].size() - (pr != -1) == 0) {
		return 1;
	}

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}

		if (!dfs(to, v)) {
			return 0;
		}
	}

	int mx = 0;
	ll sum = 0;

	for (int to : adj[v]) {
		if (to == pr) {
			continue;
		}		

		sum += arr[to];
		mx = max(mx, arr[to]);
	}    

	sum -= mx;

	for (int x = max(0ll, mx - sum); x <= mx; ++x) {
		if (check(sum, mx, arr[v], x)) {
			arr[v] = x;
			return 1;
		}
	}

	return 0;
}

void solve() {                   
	scanf("%d", &n);

    for (int i = 1; i <= n; ++i) {
    	scanf("%d", &arr[i]);
    }    

    for (int i = 1, u, v; i < n; ++i) {
    	scanf("%d %d", &u, &v);
    	adj[u].pb(v);
    	adj[v].pb(u);
    }

    int root = -1;

    for (int i = 1; i <= n; ++i) {
    	if (adj[i].size() > 1) {
    		root = i;
    	}
    }

    if (root == -1) {
		printf(arr[1] == arr[2] ? "YES\n" : "NO\n");
		return;
    }

    printf(dfs(root, -1) ? "YES\n" : "NO\n");
}

int main() {    
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

