long long dfs(vector<vector<int>>& G, vector<long long>& a, int pos, int last){
  if(G[pos].size() == 1) return a[pos];

  long long mx  = 0;
  long long sum = 0;
  for(int nx : G[pos]){
    if(nx == last) continue;
    long long tmp = dfs(G, a, nx, pos);
    if(tmp == -1) return -1;
    mx = max(tmp, mx);
    sum += tmp;
  }

  long long p = sum - a[pos];
  long long max_p;
  if(sum/2 >= mx){
    max_p = sum/2;
  }else{
    max_p = sum - mx;
  }
  if(max_p < p){
    return -1;
  }
  long long d = sum - 2*p;
  if(d < 0){
    return -1;
  }
  if( d + p == a[pos] ){
    return d;
  }else{
    return -1;
  }

}

