    if(e != p){
      child[i].pb(e);
      dfs(e, i);
    }
  }
}

bool calc(int i){
  int bsum = 0;
  if(sz(child[i]) == 0)return true;
  bool ok = true;
  for(auto e: child[i]){
    bool cc = calc(e);
    ok &= cc;
  }
  for(auto e: child[i])bsum += a[e];
  ll k = bsum - a[i];
  if(k < 0 || a[i] < k || bsum < 2 * k)return false;
  for(auto e: child[i])if(bsum - a[e] < k)return false;
  a[i] = a[i] - k;
  return ok;
}

