typedef long long ll;
ll n, rt, a[100005], up[100005];

vector<ll> adj[100005];

void solve (ll cur, ll prv) {
	if(adj[cur].size() == 1) {
		up[cur] = a[cur];
		return;
	}
	ll sum = 0, mx = 0;
	for(auto &nxt : adj[cur]) {
		if(nxt == prv) continue;
		solve(nxt, cur);
		sum += up[nxt];
		mx = max(up[nxt], mx);
	}
	if(a[cur] > sum || sum - (mx * 2 > sum ? sum - mx : sum / 2) > a[cur]) {
		puts("NO"); exit(0);
	}
	up[cur] = sum - 2*(sum - a[cur]);
}

