void dfs(int u, int p) {
	int mx = 0;
	rem[u] = (G[u].size() == 1 ? a[u] : 0);
	for (int v : G[u]) if (v != p) {
		dfs(v, u);
		rem[u] += rem[v];
		mx = max(mx, rem[v]);
	}
	if (a[u] > rem[u]) { printf("NO\n"); exit(0); }
	int need = rem[u] - a[u]; // number of needed pairs

	mx = min(mx, rem[u] - mx);
	if (mx < need) { printf("NO\n"); exit(0); }

	rem[u] -= 2 * need;
	a[u] = 0;
	//cerr << u << ' ' << rem[u] << endl;
}

