void dfs(int t, int p)
{
	vector<long long> vt;

	for (int nxt : graph[t])
	{
		if (nxt == p) continue;
		dfs(nxt, t);
		vt.push_back(up[nxt]);
	}

	if (vt.empty())
	{
		up[t] = dat[t];
		return;
	}

	if (vt.size() == 1)
	{
		if (vt[0] != dat[t])
		{
			printf("NO\n");
			exit(0);
		}
		up[t] = dat[t];
		return;
	}

	sort(vt.begin(), vt.end());

	long long maxmatch = 0;
	long long sum = 0;
	for (int i = 0; i < vt.size() - 1; i++)
	{
		sum += vt[i];
	}

	if (sum <= vt.back()) maxmatch = sum;
	else maxmatch = (sum + vt.back()) / 2;
	sum += vt.back();

	if (dat[t] > sum)
	{
		printf("NO\n");
		exit(0);
	}

	long long diff = sum - dat[t];
	if (diff > maxmatch)
	{
		printf("NO\n");
		exit(0);
	}

	up[t] = dat[t] - diff;
}

