void getAns(int u, int fa)
{
	long long maxLine = 0;
	long long allLine = 0;
	for (int v : adj[u])
	{
		if (v == fa)
			continue;
		getAns(v, u);

		maxLine = max(maxLine, f[v]),
		allLine += f[v];
	}

	if (!allLine)
	{
