//上に流れる分
long long dfs(long long pa, long long cur){

	//leaf
	if(tree[cur].size() == 1 && tree[cur][0] == pa){
		return A[cur];
	}

	long long child = 0;
	long long mach = 0;
	for(long long i = 0; i < tree[cur].size(); i++){
		if(pa == tree[cur][i]){
			continue;
		}
		long long tmp = dfs(cur, tree[cur][i]);
		mach = max(mach, tmp);
		if(tmp < 0){
			return -1;
		}
		child += tmp;
	}

	long long up = (2 * A[cur] - child);
	long long down = (child - up)/2;
	if(child - up % 2 != 0 || down < 0){
		return -1;
	}

	if(down > min(mach, child/2)){
		return -1;
	}

	return up;
}

