const int maxn = 1e5 + 10;

struct Edge
{
	Edge *next;
	int to;
} pool[maxn * 2], *p = pool, *head[maxn];

void AddEdge(int fr, int to)
{
	p->to = to;
	p->next = head[fr];
	head[fr] = p ++;
}

int a[maxn], d[maxn], f[maxn];

bool Dfs(int u, int fa)
{
	if (d[u] == 1)
	{
		f[u] = a[u];
		return true;
	}
	int s = 0, cnt = 0, Mx = 0;
	for (Edge *t = head[u]; t; t = t->next)
	{
		int v = t->to;
		if (v == fa) continue;
		if (!Dfs(v, u)) return false;
		s += f[v];
		if (s > a[u] * 2) return false;
		Mx = max(Mx, f[v]);
	}
	int x = s - a[u];
	if (x < 0) return false;
	s = min(s - Mx, s / 2);
	if (x > s) return false;
	f[u] = a[u] - x;
	return true;
}

