bool ok = true;

ll dfs(ll v, ll prev) {
        if (G[v].size() == 1) return (A[v]);
        ll sum = 0ll;
        int cnt = 0;
        ll maxv = 0;
        for (auto &u : G[v]) {
                if (u != prev) {
                        ll val = dfs(u, v);
                        if (val > 0) {
                                cnt++;
                                sum += val;
                                maxv = max(maxv, val);
                        }
                }
        }

        if (cnt == 0) return (A[v]);
        if (cnt == 1) {
                if (sum != A[v]) ok = false;
                return (A[v]);
        }

        if (sum < A[v]) ok = false;
        if (sum > A[v] * 2 || maxv > A[v]) ok = false;
        return (A[v] * 2 - sum);
}

