bool ng=false;

void dfs(int v, int p){
    if (ng) return;
    if (v!=0 && adj[v].size()==1){
        dp[v] = A[v];
        return;
    }
    ll sum=0,cnt=0;
    for(auto u:adj[v]){
        if (u==p) continue;
        dfs(u,v);
        sum+=dp[u];
        if (dp[u]>0) cnt++;
    }
    if (cnt==1){
        if (sum!=A[v]){
            ng=true;
            return;
        }
    }
    ll x = sum-A[v];
    if (x<0){ng=true; return;}
    ll y = A[v]-x;
    if (y<0){ng=true; return;}
    dp[v] = y;
    if (v==0 && y>0 && adj[v].size()!=1) ng=true;
}

