const int MAX_N = 200010;
const int MAX_V = 100010;
const double eps = 1e-6;
const ll mod = 1000000007;
const int inf = 1 << 29;
const ll linf = 1LL << 60;
const double PI = 3.14159265358979323846;
///////////////////////////////////////////////////////////////////////////////////////////////////

int N;
int A[MAX_N];
vector<int> G[MAX_N];

int loop(int v, int p) {
	int cnt = 0, ccnt = 0;
	vector<int> pv;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		int tmp = loop(n, v);
		// debug(n, tmp);
		if(tmp == inf) return inf;
		cnt += tmp;
		pv.pb(cnt);
		ccnt++;
	}
	if(ccnt == 0) return A[v];
	else if(ccnt == 1) {
		if(A[v] != cnt) return inf;
		else {
			if(v == 0) return 0;
			else return cnt;
		}
	}
	else {
		sort(all(pv));
		if(cnt - A[v] < 0 || 2 * A[v] - cnt < 0) return inf;
		else {
			ll s = accumulate(pv.begin(), pv.end() - 1, 0LL);
			if(s < (*(--pv.end()))) {
				if(cnt - A[v] > s) return inf;
			}
			return 2 * A[v] - cnt;
		}
	}
}

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	rep(i, 0, N - 1) {
		int a, b; cin >> a >> b; a--; b--;
		G[a].pb(b);
		G[b].pb(a);
	}
	if(loop(0, -1) != 0) cout << "NO\n";
	else cout << "YES\n";
}

