	for(auto e : E[x])if(!vis[e]){
		ll t = dfs(e); 
		v.pb(t); sum += t;
	}
	v.pb(2*p[x]-sum);
	for(auto e : v){
		if( e > 2*p[x] ) ok = false;
	}
	if( x == root ){
		if( sum != 2*p[x] ) ok = false;
	}
	if( 2*p[x]-sum < 0 ) ok = false;
	return 2*p[x] - sum;
}

int main()
{
	geti(N);
	repp(i,N) scanf("%lld",&p[i]);
	rep(i,N-1){
		int a,b; geti(a,b);
		deg[a]++; deg[b]++;
		E[a].pb(b); E[b].pb(a);
	}

	if( N == 2 ){
		if( p[1] == p[2] ){
			cout <<"YES";
		}
		else{
			cout <<"NO";
		}
		return 0;
	}

	repp(i,N){
		if( deg[i] >= 2 ) root = i;
	}

	dfs(root);
	printf("%s",ok?"YES":"NO");
}

