map<lli, lli> memo;
lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];
  if (memo.count(curr)) return memo[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }
  if (b.size() == 1) return b[0];

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  // cout << curr+1 << ": "; each (i, b) cout << i << ' ' ; cout << endl;
  // each (i, b) {
  //   if (i * 2 > sum) throw "";
  // }
  if (curr == prev) { // root
    if (sum % 2) throw "";
    if (a[curr] - sum / 2) throw "";
    return 0;
  }
  lli mx = *max_element(b.begin(), b.end());
  lli mn = min(sum / 2, mx);
  lli x = a[curr] - mn;
  if (x < 0) throw "";
  return memo[curr] = x;
}

