        int64_t tmp = dfs(v, u);
        sum += tmp;
        chmax(max, tmp);
      }
    }
    int64_t pairs = sum - A[u];
    int64_t up = A[u] - pairs;
    if (pairs < 0 || std::min(sum / 2, sum - max) < pairs) {
      answer = false;
    }
    return up;
  })(root, -1) != 0) {
    answer = false;
  } 
  std::cout << (answer ? "YES" : "NO") << '\n';
  return 0;
}

