bool dfs(int now,int pre){
  if(siz(e[now])==1)return true;

  ll sum=0,nex,rem;
  V<ll> c(0);
  for(auto&& to:e[now]){
    if(to==pre)continue;
    if(!dfs(to,now))return false;

    c.pb(v[to]);
    sum+=v[to];
  }
  if(sum<v[now])return false;

  nex=2*v[now]-sum;
  if(pre==-1 && nex!=0)return false;  

  rem=(sum-nex);
  v[now]=nex;

  rep(i,0,siz(c)){
    if(c[i]>rem/2)nex-=c[i]-(rem/2);
  }

  if(nex<0)return false;
  else return true;
}

