const int MAXN = 100010;

int n;
vector<int> out[MAXN];
long long stones[MAXN];
bool vis[MAXN];
bool ok;

long long solve(int u, bool root = 0){
	//printf("solve %d\n", u);
	vis[u] = 1;
	long long sup = 0;
	long long mup = -1;
	for(int v : out[u]) if(!vis[v]){
		long long up = solve(v);
		//printf("%d from %d %lld\n", u, v, up);
		sup += up;
		mup = max(mup, up);
	}
	if(root){
		if(sup != stones[u]) ok = 0;
		return 0;
	}
	if(mup == -1) return stones[u];
	// 2x + y = sup
	// x + y = stones[u]
	long long x = sup - stones[u];
	long long y = stones[u] - x;
	//printf("%d %lld %lld\n", u, x, y);
	if(x < 0 || y < 0) ok = 0;
	if(y < mup - (sup - mup)) ok = 0;
	return y;
}

