	scanf("%d", &n);
	FWD(i,1,n+1) scanf("%lld", &stones[i]);
	FWD(i,1,n){
		int a, b;
		scanf("%d %d", &a, &b);
		out[a].push_back(b);
		out[b].push_back(a);
	}
	ok = 1;
	FWD(i,1,n+1) if(SIZE(out[i]) == 1){
		solve(i, 1);
		break;
	}
	printf(ok?"YES\n":"NO\n");
	return 0;
}

