    --b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  d.assign(n, 0);
  done.assign(n, false);
  if (Go(0)) {
    cout << "YES" << endl;
  } else {
    cout << "NO" << endl;
  }
  return 0;
}

