struct node{
    int u,v,nxt;
}edge[N*2];
int head[N],mcnt;
int du[N];
int a[N];
int n;
void add_edge(int u,int v){
    mcnt++;
    du[u]++;
    edge[mcnt].u=u;
    edge[mcnt].v=v;
    edge[mcnt].nxt=head[u];
    head[u]=mcnt;
}
void nosol(){
    puts("NO");
    exit(0);
}
void dfs(int u,int fa){
    if(du[u]==1)
        return ;
    int sum=0,mx=0;
    for(int i=head[u];i;i=edge[i].nxt){
        int v=edge[i].v;
        if(v==fa)
            continue;
        dfs(v,u);
        sum+=a[v];
        mx=max(mx,a[v]);
    }
    if(sum<a[u]||sum>2*a[u])
        nosol();
    if(mx>a[u])
        nosol();
    a[u]=2*a[u]-sum;
}
int main()
{
    //freopen("tree.in","r",stdin);
    //freopen("tree.out","w",stdout);
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
        scanf("%d",&a[i]);
