        if(a[1]==a[2])
            puts("YES");
        else
            puts("NO");
        return 0;
    }
    for(int i=1;i<n;i++){
        int u,v;
        scanf("%d%d",&u,&v);
        add_edge(u,v);
        add_edge(v,u);
    }
    int root=1;
    while(du[root]==1)
        root++;
    dfs(root,0);
    if(a[root])
        nosol();
    puts("YES");
}

