int dfs (int v, int pr) {
	int cost = a[v] + a[v];
	if (g[v].size () == 1) {
		return a[v];
	}
	int mx = 0;
	for (auto to : g[v]) {
		if (to == pr) continue;
		int len = dfs (to, v);
		cost -= len; 
		mx = max (mx, len);
	}        
	if (v == st && cost > 0) {
		cout << "NO";
		exit (0);
	}
	if (cost < 0) {
		cout << "NO";
		exit (0);
	}
	mx = max (mx, cost);
	if (mx > a[v]) {
		cout << "NO";
		exit (0);
	}
	return cost;
}

