ll dfs(int v, int par, VL &a, VVI &g, bool &good) {
    if (SIZE(g[v]) == 1) {
        return a[v];
    }

    ll ub = 0;
    for (int u : g[v]) if (u != par) {
        ll fromSon = dfs(u, v, a, g, good);
        ub += fromSon;
    }

    ll res = 2 * a[v] - ub;
    good = good && (res >= 0);
    good = good && (res <= a[v]);

    return res;
}

