ll A[100010];
vector<int> path[100010];
bool visited[100010];

ll dfs(int v) {
    visited[v] = true;

    vector<ll> chl;
    ll sum = 0;
    for (int sv : path[v]) {
        if (visited[sv]) continue;
        ll res = dfs(sv);

        if (res < 0) return -1;

        chl.push_back(res);
        sum += res;
    }

    if (chl.empty()) {
        return A[v];
    }

    if (sum < A[v] || A[v] * 2 < sum) {
        return -1;
    }

    sort(chl.begin(), chl.end());
    ll ma = chl.back();

    if (sum - ma < ma && ma > A[v]) {
        return -1;
    }

    return A[v] * 2 - sum;
}

