int N;

ll dfs() {
	vector<int> ord(N);

	stack<int> s;
	s.push(root);
	par[root] = -1;
	int cnt = 0;

	while (!s.empty()) {
		int pos = s.top();
		s.pop();
		ord[cnt] = pos;
		cnt++;
		rep(i, T[pos].size()) {
			if (T[pos][i] == par[pos])continue;
			par[T[pos][i]] = pos;
			s.push(T[pos][i]);
		}
	}

	reprev(i, N) {
		int p = ord[i];
		if (T[p].size() == 1) {
			num[p] = A[p];
		}
		else {
			ll sum = 0;

			if (T[p].size() == 1) {
				num[p] = A[p];
				continue;
			}
			// 子同士のペアがi個
			// s-2i=A-i, i=s-A, A-i=2A-s
			int zero = 0;
			rep(i, T[p].size()) {
				if (T[p][i] == par[p])continue;
				sum += num[T[p][i]];
				if (num[T[p][i]] == 0)zero++;
			}

			if (2 * A[p] - sum < 0 || sum < A[p])return -1;

			if (p != root && T[p].size() - zero == 2) {
				if (A[p] == sum) {
					num[p] = A[p];
				}
				else {
					return -1;
				}
			}
			else {
				num[p] = 2 * A[p] - sum;
			}
		}
	}
	return num[root];
}

