    E[x].push_back(y);
    E[y].push_back(x);

  }
}

void dfs(int x, int p, int d) {
  nodes[d].push_back(x);
  dad[x] = p;
  for (int i = 0; i < E[x].size(); i++)
    if (E[x][i] != p)
      dfs(E[x][i], x, d + 1);
}

bool work(int depth) {
  vector <int> curr = nodes[depth];
  while (!curr.empty()) {
    int node = curr.back();
    int parent = dad[node];
    vector <ll> tmp;
    for (; !curr.empty() && dad[curr.back()] == parent; curr.pop_back()) 
      tmp.push_back(a[curr.back()]);
    ll sum = 0;
    for (int i = 0; i < tmp.size(); i++)
      sum += tmp[i];
    if (tmp.size() > 1)  {
      if (sum < a[parent] || sum > 2 * a[parent])
        return false;
      ll val = sum - a[parent];
      ll mx = *max_element(tmp.begin(), tmp.end());
      if (val > min(sum / 2, sum - mx))
        return false;
      a[parent] *= 2;
      a[parent] -= sum;
    }
    else if (a[node] != a[parent])
      return false;
  }

  return true;
}

bool solve() {
  if (N == 2)
    return a[1] == a[2];

  int root = 0;
  for (int i = 1; i <= N; i++)
    if (E[i].size() > 1) {
      root = i;
      break;
    }

  dfs(root, 0, 0);

  for (int i = N - 1; i >= 0; i--)
    if (!work(i))
      return false;

  return true;
}

int main() {
  load();
  puts(solve() ? "YES" : "NO");
  return 0;
}

