  bool leaf = true;
  LL ret = 0 , mx = 0 , res = 0;
  for( int son : v[ now ] ){
    if( son == prt ) continue;
    leaf = false;
    LL tmp = go( son , now );
    if( tmp < 0 ){
      puts( "NO" );
      Bye;
    }
    LL mr = min( ret , tmp );
    mr = min( mr , ( res + tmp ) / 2 );
    ret += tmp;
    mx += mr;
    res = res + tmp - mr - mr;
  }
  if( leaf ) return a[ now ];
  if( ret < a[ now ] || ret - a[ now ] > mx ){
    puts( "NO" );
    Bye;
  }
  return ret - 2 * ( ret - a[ now ] );
}
void solve(){
  int rt = -1;
  for( int i = 1 ; i <= n ; i ++ )
    if( v[ i ].size() > 1u ){
      rt = i;
      break;
    }
  if( rt == -1 ){
    puts( a[ 1 ] == a[ 2 ] ? "YES" : "NO" );
    Bye;
  }
  if( go( rt , rt ) == 0 )
    puts( "YES" );
  else
    puts( "NO" );
}
int main(){
  build();
  //__ = getint();
  while( __ -- ){
    init();
    solve();
  }
}

