void dfs(int idx, int p, int d) {
    D[idx] = d;
    for(auto i : edges[idx]) {
        if(i == p) {
            continue;
        }
        children[idx].push_back(i);
        dfs(i, idx, d + 1);
    }
}

signed main() {
    std::cin >> n;

    for(int i = 0; i < n; ++i)
        std::cin >> C[i];

    if(n == 2) {
        if(C[0] == C[1]) {
            std::cout << "YES" << std::endl;
        }else {
            std::cout << "NO" << std::endl;
        }

        return 0;
    }

    edges.resize(n);
