        --a, --b;

        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    int b = 0;
    for(int i = 0; i < n; ++i) {
        if(edges[i].size() != 1) {
            b = i;
            break;
        }
    }
    dfs(b, -1, 0);

    std::priority_queue<P, std::vector<P>> que;

    for(int i = 0; i < n; ++i)
        que.push({D[i], i});

    int last = 0;
    while(!que.empty()) {
        auto p = que.top();que.pop();
        last = p.second;

        int sum = 0, max = 0;
        if(children[p.second].size() == 0) {
            continue;
        }
        for(auto i : children[p.second]) {
            int v = C[i];

            max = std::max(max, v);
            sum += v;
        }

        int s = 0;
        if(sum - max < max) {
            s = (sum - max);
        }else {
            s = sum / 2;
        }

        if(sum >= C[p.second] && sum - C[p.second] <= s) {
            C[p.second] -= sum - C[p.second];
        }else {
            std::cout << "NO" << std::endl;
            return 0;
        }
    }

    if(C[last] == 0) {
        std::cout << "YES" << std::endl;
    }else {
        std::cout << "NO" << std::endl;
    }
}

