vector<bool> ischecked(100001, false);
vector<long long int> stonenum(100001);

bool cansolve(int node)
{
	if(graph[node].size() == 1) return true;
	ischecked[node] = true;
	long long int childstonesum = 0;
	long long int nummax = 0;
	for(int i = 0; i < graph[node].size(); i++){
		int child = graph[node][i];
		if(ischecked[child]) continue;
		if(cansolve(child)) {
			childstonesum += stonenum[child];
			nummax = max(nummax, stonenum[child]);
		} else {
			return false;
		}
	}
	if(stonenum[node] > childstonesum) {
		return false;
	} else if(stonenum[node] == childstonesum) {
		return true;
	} else if(childstonesum - stonenum[node] <= min(nummax, childstonesum / 2) && graph[node].size() > 2){
		stonenum[node] -= childstonesum - stonenum[node];
		return true;
	}
	return false;
}

