int n;
vector<ll> a(100000), c(100000, -1);
bool f = true;

ll dfs(const Graph &g, int cur, int pre)
{
  int sz = g[cur].size();
  if (pre != -1 && sz == 1)
  {
    // leaf
    return c[cur] = a[cur];
  }
  ll sum = 0;
  vector<int> v;
  for (int i = 0; i < sz; i++)
  {
    int next = g[cur][i];
    if (next == pre)
      continue;
    sum += dfs(g, next, cur);
    v.push_back(next);
  }
  c[cur] = 2 * a[cur] - sum;
  if (c[cur] < 0 || c[cur] > a[cur])
  {
    f = false;
  }
  if ((sum - c[cur]) % 2 || sum - c[cur] < 0)
  {
    f = false;
  }
  ll num = (sum - c[cur]) / 2; // num 組作れるか
  ll cnt = 0;
  for (int i = 0; i < sz; i++)
  {
    int next = g[cur][i];
    if (next == pre)
      continue;
    if (c[next] > num)
    {
      cnt += c[next] - num;
    }
  }
  if (cnt > c[cur])
    f = false;
  return c[cur];
}

