void mt(int now,int fa)
{
    for(unsigned int t=0;t<g[now].size();t++)
    {
        int v=g[now][t];
        if(v==fa)continue;
        son[now].push_back(v);
        mt(v,now);
    }
}

bool cmp(LL p,LL q)
{
    return p>q;
}

void solve(int now)
{
    if(son[now].size()==0)
    {
        x[now]=o[now]=0;
        y[now]=a[now];
        z[now]=a[now];
        return;
    }
    LL ss=0,ma=0,tot=0;
    for(unsigned int t=0;t<son[now].size();t++)
    {
        solve(son[now][t]);
        ss+=x[son[now][t]];
        ma=max(ma,y[son[now][t]]);
        tot+=y[son[now][t]];
        z[now]+=z[son[now][t]];
    }
    LL temp=z[now]-2*ss;
    LL su=min(tot/2,tot-ma);
    x[now]=temp-a[now];
    o[now]=x[now];
    y[now]=a[now]-x[now];
    ch[now]=su-x[now];
    x[now]+=ss;
}

