using int64 = long long;

const int MAXN = 200000;

static int64 A[MAXN];
static vector<int> tree[MAXN];

int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    int64 sum = 0,
          maxc = 0;

    vector<int64> vec;
    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
        if (child < 0) return -1;
        sum += child;
        maxc = max(maxc, child);

        vec.push_back(sum);
    }
    // sum - A[v]個のペアを作りたい
    int64 L = sum - A[v];

    sort(vec.begin(), vec.end(), greater<int64>());
    int64 x = 0,
          cum = vec[0];
    for (int i = 1; i < vec.size(); i++) {
        x += min(vec[i], cum);
        vec[i] -= min(vec[i], cum);
        cum += vec[i];
    }

    if (L < 0 or x < L) return -1;
    // if (L < 0 or min(sum / 2, sum - maxc) < L) return -1;
    return sum - 2 * L;
}

