    for (int i = 1; i < n; i++) {
        p[i] = *g[i].begin();
        std::copy(std::next(g[i].begin()), g[i].end(), std::back_inserter(ch[i]));
    }

    std::deque<long long> q;
    std::vector<bool> done(n, false);
    std::vector<long long> c(n), t(n);
    q.push_back(0);
    while (!q.empty()) {
        auto curr = q.back();
        if (ch[curr].empty()) {
            t[curr] = a[curr];
