using namespace std;
typedef long long int lli;

const int MAXN = 100010;

int n;

int v[MAXN];

lli dp[MAXN];

bool hasAnswer = true;

vector< int > adj[MAXN];

void DFS(int cur, int p)
{
	if( adj[cur].size() == 1 )
	{
		dp[cur] = v[cur];
		return;
	}

	lli mx = -1;
	lli sum = 0;
	int qtdSon = 0;

	for(int i = 0 ; i < adj[cur].size() ; i++)
	{
		int viz = adj[cur][i];

		if( viz == p ) continue;

		qtdSon++;
		DFS( viz , cur );

		sum += dp[viz];
		mx = max( mx , dp[viz] );
	}

	if( qtdSon == 1 )
	{
		dp[cur] = sum;
		return;
	}

	lli remain;
	lli qtdPairs;

	if( sum >= 2*mx )
	{
		remain = sum%2;
		qtdPairs = sum/2;
	}
	else
	{
		remain = 2*mx - sum;
		qtdPairs = sum - mx;
	}

	lli diff = v[cur];
	diff -= qtdPairs + remain;

	diff = min( diff , qtdPairs );

	if( diff < 0 ) hasAnswer = false;

	dp[cur] = remain + 2*diff;
}

