void solve(int i, int fa){
	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		if (x == fa){
			continue;
		}
		a[i] -= a[x];
		solve(x, i);
		if (deg[x] > 1){
			a[i] -= a[x];
		}
		orz[i] += a[i];
	}
}

