	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		if (x == fa){
			continue;
		}
		dfs2(x, i);
		a[i] += a[x];
		e[j].w += a[x];
		e[j ^ 1].w += a[x];
	}
}

