struct Solver {
  void solve() {
    cin >> n;
    a.resize(n);
    for (int i = 0; i < n; i++) {
      cin >> a[i];
    }
    g.resize(n);
    for (int i = 0; i < n - 1; i++) {
      int x, y;
      cin >> x >> y;
      --x;
      --y;
      g[x].push_back(y);
      g[y].push_back(x);
    }
    used.resize(n, false);
    for (int i = 0; i < n; i++) {
      if (g[i].size() > 1) {
        auto value = dfs(i);
        if (value.first == 0) {
          cout << "YES\n";
        } else {
          cout << "NO\n";
        }
        return;
      }
    }
    if (n == 2 && a[0] == a[1]) {
      cout << "YES\n";
    } else {
      cout << "NO\n";
    }
  }

  pair<ll, ll> dfs(int v) {
    used[v] = true;

    vector<ll> mins, maxs;
    ll total_mins = 0;
    ll total_maxs = 0;
    int child_count = 0;
    for (auto u : g[v]) {
      if (used[u]) {
        continue;
      }

      ++child_count;
      auto value = dfs(u);

      if (value.first == -1) {
        DEBUG("v: " << v + 1 << " a[v]: " << a[v] << " min: " << -1 << " max: " << -1);
        return {-1, -1};
      }

      mins.push_back(value.first);
      maxs.push_back(value.second);

      total_mins += value.first;
      total_maxs += value.second;
    }

    if (!child_count) {
      DEBUG("v: " << v + 1 << " a[v]: " << a[v] << " min: " << a[v] << " max: " << a[v]);
      return {a[v], a[v]};
    }

    sort(mins.begin(), mins.end());
    sort(maxs.begin(), maxs.end());

    auto calc_value = [](const auto& values) {
      ll res = 0;
      ll sum = 0;
      for (auto value : values) {
        sum += value;
      }
      if (sum - values.back() < values.back()) {
        return sum - values.back();
      }
      return sum / 2;
    };

    auto min_all_matches = calc_value(mins);
    auto max_all_matches = calc_value(maxs);

    if (a[v] < min(total_mins - min_all_matches, total_maxs - max_all_matches) || a[v] > total_maxs) {
      DEBUG("v: " << v + 1 << " a[v]: " << a[v] << " min: " << -1 << " max: " << -1);
      DEBUG("total_mins: " << total_mins << " total_maxs: " << total_maxs << " min_all_matches: " << min_all_matches);
      return {-1, -1};
    }

    DEBUG("v: " << v + 1 << " a[v]: " << a[v] << " min: " << a[v] - min_all_matches << " max: " << a[v] << " min_all_matches: " << min_all_matches);

    return {max(0ll, a[v] - max(min_all_matches, max_all_matches)), a[v]};
  }

  int n;
  vector<int> a;
  vector<vector<int>> g;
  vector<bool> used;
};

