  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    long long t = dfs(G,A,v_,v);
    if(t < 0) return -1;
    B.push_back(t);
    s += t;
  }
  sort(B.rbegin(), B.rend());
  long long d = s - A[v];
  // fprintf(stderr,"v = %d, d = %lld, s = %lld\n",v,d,s);
  // cerr << "B : ";
  // for(auto b : B) cerr << b << " " ;
