bool dfs(int x, int fa) {
	bool lf = 1;
	for (int now = head[x]; now; now = e[now].next) {
		if (e[now].to != fa) {
			lf = 0;
			if (dfs(e[now].to, x)) return 1;
			tot[x] += a[e[now].to];
		}
	}
	if (!lf) {
		LL ta = 2 * a[x] - tot[x], su = 0;
		if (ta < 0) return 1;
		for (int now = head[x]; now; now = e[now].next) {
			if (e[now].to != fa) {
				su = min(2 * (a[x] - ta), su + min(a[x] - ta, a[e[now].to]));
			}
		}
		if (su < 2 * (a[x] - ta)) return 1; 
		a[x] = ta;
	}
	return 0;
}

