const int DIM = 1e5 + 5;

int rnk[DIM], val[DIM], cst[DIM];
vector<pair<int, int>> edg[DIM];

void dfs(int x, int f, bool &ok) {
    if (rnk[x] > 1)
        val[x] *= 2;

    for (pair<int, int> y : edg[x]) {
        if (y.first == f)
            continue;

        dfs(y.first, x, ok);
        cst[y.second] = val[y.first];
        val[x] -= val[y.first];
    }

    ok &= (val[x] >= 0);
    if (!f) ok &= !val[x];

    return;
}

int main(void) {
    int n;
