        ++rnk[x]; ++rnk[y];
        edg[x].push_back(make_pair(y, i));
        edg[y].push_back(make_pair(x, i));
    }

    bool ok = true;

    if (n == 2)
        ok = (val[1] == val[2]);
    else {
        int r = 1;
        for (int i = 2; i <= n; ++i)
            if (rnk[i] > 1) r = i;

