using namespace std;
using ll = long long;

ll solve(int u, int p, const vector<ll>& x, const vector<vector<int>>& conn){
	if(conn[u].size() == 1u){ return x[u]; }
	ll csum = 0, cmax = 0;
	for(const int v : conn[u]){
		if(v == p){ continue; }
		const ll t = solve(v, u, x, conn);
		if(t < 0){ return -1; }
		csum += t;
		cmax = max(cmax, t);
	}
	const ll y = max(0ll, cmax - (csum - cmax));
	const ll r = (csum - y) / 2;
	if(x[u] < csum - r || csum < x[u]){ return -1; }
	return csum - 2 * (csum - x[u]);
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
