	vector<vector<int>> conn(n);
	for(int i = 1; i < n; ++i){
		int a, b;
		cin >> a >> b;
		--a; --b;
		conn[a].push_back(b);
		conn[b].push_back(a);
	}
	if(n == 2){
		cout << (x[0] == x[1] ? "YES" : "NO") << endl;
		return 0;
	}
	int root = 0;
	for(; root < n; ++root){
		if(conn[root].size() >= 2u){ break; }
	}
	cout << (solve(root, -1, x, conn) == 0 ? "YES" : "NO") << endl;
	return 0;
}

