	vector<int> ord(N);

	stack<int> s;
	s.push(root);
	par[root] = -1;
	int cnt = 0;

	while (!s.empty()) {
		int pos = s.top();
		s.pop();
		ord[cnt] = pos;
		cnt++;
		rep(i, T[pos].size()) {
			if (T[pos][i] == par[pos])continue;
			par[T[pos][i]] = pos;
			s.push(T[pos][i]);
		}
