		int p = ord[i];
		if (T[p].size() == 1) {
			num[p] = A[p];
		}
		else {
			ll sum = 0;
			rep(i, T[p].size()) {
				if (T[p][i] == par[p])continue;
				sum += num[T[p][i]];
			}
			if (2 * A[p] - sum < 0 || (p != root && 2 * A[p] - sum == 0))return -1;
			if (T[p].size() == 2) {
