pair<ll, ll> go(vvi& adj, vi& stones, int loc, int par) {
    bool leaf = true;
    ll min_tot = 0, max_tot = 0, min_large = 0;

    for (int nbr : adj[loc]) if (nbr != par) {
        leaf = false;
        auto p = go(adj, stones, nbr, loc);

        min_tot += p.first;
        max_tot += p.second;
        min_large = max(min_large, p.first);
    }

    if (loc == par) {
        if (stones[loc] < min_tot) fail();
        if (stones[loc] > max_tot) fail();
        return { 0ll, 0ll };
    }

    if (leaf) return { stones[loc], stones[loc] };

    ll max_pair = min(min_tot - min_large, min_tot / 2);

    if (stones[loc] < min_tot - max_pair) fail();
    if (stones[loc] > max_tot) fail();

    return { max(0ll, min_tot - 2 * max_pair), min(ll(stones[loc]), max_tot) };
}

