int loop(int v, int p) {
	int cnt = 0, ccnt = 0;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		int tmp = loop(n, v);
		// debug(n, tmp);
		if(tmp == inf) return inf;
		cnt += tmp;
		ccnt++;
	}
	if(ccnt == 0) return A[v];
