namespace a{
int N;
const int MAX_N = 1e5 + 10;
LL A[MAX_N];
vector<int> next[MAX_N];

vector<int> child[MAX_N];
int parent[MAX_N];

void build(int v, int p=-1) {
    for(int u : next[v]) {
        if(u == p) continue;
        parent[u] = v;
        child[v].push_back(u);
        build(u, v);
    }
}

LL inner[MAX_N];
LL last_C3;
bool dfs(int u) {
    for(int v : child[u]) {
        bool b = dfs(v);
        if(!b) {
            return false;
        }
    }


    const LL a = A[u];

    LL s = 0;
    for(int v : child[u]){
        s += A[v];
    }

    LL C1 = 0;
    for(int v : child[u]) {
        C1 += inner[v];
    }

    if(child[u].size() == 0) {
        inner[u] = 0;
        return true;
    }

    // C2 + C3 = a
    // 2 * C2 + C3 = (s-2*C1)
    // C2 = (s-2*C1) - a
    // C3 = a - C2
    //
    LL C2 = s-2*C1 - a;
    LL C3 = a - C2;
    error(u, C1, C2, C3);
    last_C3 = C3;

    if(!(C2 >= 0 && C3 >= 0)) {
        return false;
    }

    inner[u] = C1 + C2;

    return true;
}

bool solve() {

    if(N == 2) {
        return A[0] == A[1];
    }
    if(N == 3) {
        return A[0] == A[1] && A[1] == A[2];
    }

    vector<int> roots;
    REP(i, N) if(next[i].size() > 1){
        roots.push_back(i);
    }

    int root = roots[rand() % roots.size()];
    REP(i, N) child[i].clear();
    build(root);
    bool res = dfs(root);
    if(last_C3 > 0) res = false;
    return res;
}

}

