typedef long long ll;
int N;
int A[101010];
vector<int> E[101010];
//-----------------------------------------------------------------
ll dfs(int cur, int par) {
	if (E[cur].size() == 1 && E[cur][0] == par) {
		// 葉
		return A[cur];
	}

	vector<ll> v;
	ll sm = 0;
	for (int i : E[cur]) if (i != par) {
		ll r = dfs(i, cur);
		if (r < 0) return -1;
		v.push_back(r);
		sm += r;
	}

	if (sm < A[cur]) return -1;

	sort(v.begin(), v.end());
	int l = 0, r = v.size() - 1;
	ll d = sm - A[cur];
	while (0 < d) {
		ll t = min(v[l], v[r]);

		t = min(d, t);

		A[cur] -= t;
		d -= t;
		v[l] -= t;
		v[r] -= t;

		if (v[l] == 0) l++;
		if (v[r] == 0) r--;

		if (!(l < r)) break;
	}
	if (0 < d) return -1;

	return A[cur];
}
