struct Node {
    std::vector<int> neighbor;
    std::vector<int> children;
    int rank;
    long long stone;
};

const int MAX_N = 100050;

int N, a[MAX_N], b[MAX_N];
long long A[MAX_N];

Node tree[MAX_N];

void set_rank_children(int i, int rank, int parent) {
    tree[i].rank = rank;
    for (int n : tree[i].neighbor) {
        if (n != parent) {
            set_rank_children(n, rank + 1, i);
            tree[i].children.push_back(n);
        }
    }
}

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> A[i];
    }

    for (int i = 1; i < N; i++) {
        std::cin >> a[i] >> b[i];
    }

    for (int i = 1; i <= N; i++) {
        tree[i].stone = A[i];
    }

    for (int i = 1; i < N; i++) {
        tree[a[i]].neighbor.push_back(b[i]);
        tree[b[i]].neighbor.push_back(a[i]);
    }

    set_rank_children(1, 0, 0);

    std::vector<std::pair<int, int>> node_rank;
    for (int i = 1; i < N; i++) {
        node_rank.push_back(std::pair<int, int>({i, tree[i].rank}));
    }
    std::sort(node_rank.begin(), node_rank.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) { return a.second > b.second; }
    );

    for (auto p : node_rank) {
        int n = p.first;
        long long child_sum = 0;
        long long max_num = 0;
        for (int c : tree[n].children) {
            child_sum += tree[c].stone;
            max_num = std::max(max_num, tree[c].stone);
        }

        if (tree[n].children.size() == 0) {
            continue;
        } else if (tree[n].children.size() == 1) {
            if (child_sum != tree[n].stone) {
                std::cout << "NO" << std::endl;
                return 0;
            }
            if (n == 1) {
                std::cout << "YES" << std::endl;
                return 0;
            }
        } else {
            long long proc_num = child_sum - tree[n].stone;
            tree[n].stone -= proc_num;
            if (proc_num < 0 || tree[n].stone < 0 || proc_num + tree[n].stone < max_num) {
                std::cout << "NO" << std::endl;
                return 0;
            }
            if (n == 1) {
                if (tree[n].stone == 0) {
                    std::cout << "YES" << std::endl;
                    return 0;
                } else {
                    std::cout << "NO" << std::endl;
                    return 0;
                }
            }
        }
    }

    assert(false);
    return 0;
}

