bool can = true;

long long int Search(int num) {
	if (up[num] != -1) {
		return up[num];
	}
	if (edge[num].size() == 1) {
		up[num] = box[num];
		return up[num];
	}
	flag[num] = false;
	long long int bag = box[num] * 2;
	for (auto i : edge[num]) {
		if (flag[i]) {
			bag -= Search(i);
		}
	}
	if (bag < 0) {
		can = false;
	}
	up[num] = bag;
	return up[num];
}

