void bfs() {
    fill(d, d + V, -1);
    queue<int> que;
    que.push(0);
    d[0] = 0;
    rk[0].push_back(0);
    while (!que.empty()) {
        int p = que.front();
        que.pop();
        for (int i = 0; i < (int)G[p].size(); i++) {
            edge e = G[p][i];
            if (d[e.to] == -1) {
                d[e.to] = d[p] + 1;
                rk[d[p] + 1].push_back(e.to);
                que.push(e.to);
            }
        }
    }
}

