    bool ok = true;
    for (int i = maxrk; i > 0; i--) {
        for (int j = 0; j < (int)rk[i].size(); j++) {
            int p = rk[i][j];
            //cout << p << endl;
            if (G[p].size() == 1) {
                cnt[p] = a[p];
                continue;
            }
            ll sum = 0;
            ll cntmax = 0;
            for (int k = 0; k < (int)G[p].size(); k++) {
                edge e = G[p][k];
                if (d[e.to] >= d[p]) {
                    sum += cnt[e.to];
                    cntmax = max(cntmax, cnt[e.to]);
                }
            }
            cnt[p] = 2 * a[p] - sum;
            ll tmp = (sum - cnt[p]) / 2;
            if (tmp < min(sum - cntmax, sum / 2)) {
                ok = false;
                break;
            }
        }
        if (!ok) {
            break;
        }
    }
