ll a[lmt];
map<pair<int, int>, ll> M;
vector<int> adj[lmt];
bool ans = true;

void dfs(int u, int p) {
    if((adj[u].size() == 1) && (p != 0)) {
        M[mp(max(u, p), min(u, p))] = a[u];
        return ;
    }
    ll sum = 0;
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(v != p)
            dfs(v, u);
        if(v != p) {
            ll tmp = M[mp(max(u, v), min(u, v))];
            if(tmp > a[u])
                ans = false;
            if(tmp < 0)
                ans = false;
            sum += tmp;
        }
    }
    ll val = 2LL*a[u] - sum;
    if(p == 0) {
        if((adj[u].size() > 1) && (val != 0))
            ans = false;
        else if((adj[u].size() == 1) && (sum != a[u]))
            ans = false;
    }
    M[mp(max(u, p), min(u, p))] = val;
    if(val <= 0)
        ans = false;
}

