typedef long long i64;

struct Edge
{
    int nxt, to;
} e[200010];
int head[100010], cnt;
int val[100010];
bool ok = 1;

void add_edge(int a, int b)
{
    e[++cnt] = { head[a], b };
    head[a] = cnt;
}

int dfs(int nod, int tata)
{
    int sum(0);
    int vmax(0);
    for (int i(head[nod]); i; i = e[i].nxt) {
        if (e[i].to == tata)
            continue;
        int x = dfs(e[i].to, nod);
        sum += x;
        vmax = max(vmax, x);
    }
    if (e[head[nod]].nxt == 0)
        return val[nod];

    if (sum < 0 || sum > 2 * val[nod])
        ok = 0;

    vmax = max(1ll * vmax, 2ll * val[nod] - sum);
    if (vmax > val[nod])
        ok = 0;
    return 2 * val[nod] - sum;
}

int main()
{
    int n, a, b;
    cin >> n;

    for (int i(1); i <= n; i++)
        cin >> val[i];

    for (int i(1); i < n; i++) {
        cin >> a >> b;
        add_edge(a, b);
        add_edge(b, a);
    }

    if (n == 2) {
        if (val[1] == val[2])
            cout << "YES\n";
        else
            cout << "NO\n";
        return 0;
    }

    int root = 0;
    for (int i(n); i >= 1; i--)
        if (e[head[i]].nxt)
            root = i;

    int x = dfs(root, 0);

    if (x || !ok)
        cout << "NO\n";
    else
        cout << "YES\n";
    return 0;
}

