int N;
list<int> edges [100001];

ll dfs(int curr,int prev,bool& ans,vector<ll>& A)
{
	ll res = 0,children = 0,mx = 0;
	for(const auto& it : edges [curr]) if(it != prev){
		ll t = dfs(it,curr,ans,A);
		res += t;
		chmax(mx,t);
		children++;
	}
	if(children == 0){
		return A [curr];
	}
	if(children == 1){
		ans &= res == A [curr];
		return res;
	}
	if(max(res - res / 2,mx) <= A [curr] && A [curr] <= res && A [curr] * 2 - res >= 0){
		return A [curr] * 2 - res;
	}
	ans = false;
	return 0;
}

