ll solve(vector<ll>& vec)
{
	if(vec.empty()) return 0;
	ll mx = 0;
	ll sum = 0;
	int k = vec.size();
	for(int i = 0; i < k; i++)
	{
		mx=max(mx,vec[i]);
		sum+=vec[i];
	}
	if(mx*2>sum)
	{
		return (sum-mx);
	}
	else
	{
		return sum/2;
	}
}

void prep(int u, int p)
{
	bool leaf=1;
	for(int i = 0; i < adj[u].size(); i++)
	{
		int v = adj[u][i];
		if(v==p) continue;
		leaf=0;
		prep(v,u);
		sumleaf[u]+=sumleaf[v];
	}
	if(leaf)
	{
		sumleaf[u]=a[u];
	}
}

ll dfs1(int u, int p)
{
	ll sum = 0;
	for(int i = 0; i < adj[u].size(); i++)
	{
		int v = adj[u][i];
		if(v==p) continue;
		ll val = dfs1(v,u);
		sum+=val;
		a[u] -= val*2;
	}
	sum+=a[u];
	return sum;
}
bool pos;
ll dfs2(int u, int p)
{
	ll sum = 0;
	vector<ll> vec;
	bool leaf=1;
	for(int i = 0; i < adj[u].size(); i++)
	{
		int v = adj[u][i];
		if(v==p) continue;
		leaf=0;
		ll val = dfs2(v,u);
		sum+=val;
		vec.pb(val);
	}
	if(leaf)
	{
		if(a[u]>0)
		{
			pos=0;
			return 0;
		}
		return sumleaf[u];
	}
	ll cnt = solve(vec);
	if(cnt<a[u])
	{
		pos=0;
		return 0;
	}
	//apply a[u] times;
	return (sum - ll(a[u])*2LL);
}

