const int N = 100000 + 5;

int n, flag, rt;
LL a[N], in[N], f[N];
vector<int> v[N];

void dfs(int x, int p) {
	LL sum = 0, mx = -INF, cnt = 0; f[x] = 0;
	for (int i = 0; i < (int) v[x].size(); i++) {
		int y = v[x][i];
		if (y == p) continue;
		if (in[y] != 1) dfs(y, x);
		//printf("%d %d\n", x, y);
		sum += a[y] - f[y];
		mx = max(mx, a[y] - f[y]);
	}
	LL res = sum - mx;
	if (res <= mx) cnt = res;
	else cnt = sum / 2;
	f[x] = sum - a[x];
	if (f[x] < 0) flag = 0;
	if (f[x] > cnt) flag = 0;
	if (x == rt && a[x] != f[x]) flag = 0;
}

int main() {
	read(n);
	for (int i = 1; i <= n; i++) read(a[i]);
	if (n == 2) {
		if (a[1] == a[2]) printf("YES\n");
		else printf("NO\n");
		return 0;
	}
	for (int i = 1, x, y; i < n; i++) {
		read(x), read(y);
		v[x].push_back(y);
		v[y].push_back(x);
		in[x]++; in[y]++;
	}
	flag = 1;
	for (int i = 1; i <= n; i++) {
		if (in[i] != 1) {
			rt = i;
			dfs(i, 0);
			break;
		}
	}
	if (flag) printf("YES\n");
	else printf("NO\n");
	return 0;
}

