const int maxn = 1e5 + 5;
int n;
int a[maxn];
vector<int> way[maxn];
ll par[maxn];
int bad;
void dfs(int u, int last) {
    int child = 0;
    for(auto v : way[u]) {
        if(v==last) continue;
        dfs(v, u);
        child++;
    }
    if(child==0) par[u] = a[u];
    else {
        par[u] = 2*a[u];
        for(auto v : way[u]) {
            if(v==last) continue;
            if(par[v]>a[u]) bad = 1;
            par[u] -= par[v];
        }
    }
    if(par[u]<0) bad = 1;
//    printf("par %d = %d\n",u,par[u]);
}
int main() {
    scanf("%d",&n);
    for(int i=1;i<=n;i++) scanf("%d",&a[i]);
