        int u,v; scanf("%d%d",&u,&v);
        way[u].push_back(v);
        way[v].push_back(u);
    }
    if(n==2) {
        printf("%s",a[1]==a[2] ? "YES" : "NO");
        return 0;
    }
    int root = -1;
    for(int i=1;i<=n;i++) if(way[i].size()>1) root = i;
    dfs(root,0);
    if(par[root]!=0) bad = 1;
    printf("%s",bad?"NO":"YES");
}

