        if(e==p)continue;
        ll k=dfs(e,i);
        sum+=k;
        ma=max(k,ma);
        cnt++;
    }
    ll res=0;
    //cout<<i<<' '<<sum<<endl;
    if(cnt==1){
        if(d[i]!=sum)f=0;
        else res=d[i];
    }
    else if(cnt==0)res=d[i];
    else if(sum>2*d[i])f=0;
    else if(ma>d[i]){
        f=0;
    }
    else res=2*d[i]-sum;
    //cout<<i<<' '<<res<<endl;
    return res;
}
