using lint = long long;

template <class Cost = int>
struct Edge {
    int from, to;
    Cost cost;
    Edge(int from = -1, int to = -1, Cost cost = 1)
        : from(from), to(to), cost(cost){};

    bool operator<(const Edge<Cost>& e) const { return this->cost < e.cost; }
    bool operator>(const Edge<Cost>& e) const { return this->cost > e.cost; }
};

template <class Cost = int>
class Graph {
public:
    int size;
    std::vector<std::vector<Edge<Cost>>> path;

    explicit Graph(int N = 0) : size(N), path(size) {}
    void span(int from, int to, Cost cost = 1) {
        path[from].push_back(Edge<Cost>(from, to, cost));
    }
    std::vector<Edge<Cost>>& operator[](int v) { return path[v]; }
};

void fail() {
    std::cout << "NO" << std::endl;
    std::exit(0);
}

std::vector<lint> A;
Graph<> tree;

lint dfs(int v, int r) {
    std::vector<lint> ch;
    for (auto e : tree[v]) {
        if (e.to == r) continue;
        ch.push_back(dfs(e.to, v));
    }
    if (ch.empty()) return A[v];

    lint sum = std::accumulate(ch.begin(), ch.end(), 0LL);
    lint max = *std::max_element(ch.begin(), ch.end());

    lint P = std::min(sum / 2, sum - max);  // 作れる最大ペア数
    if (A[v] < sum - P || sum < A[v]) fail();

    // 実際に葉同士でペアにするのは、sum-A[v]組
    // よって親に引き継がれる葉の数は、sum-2(sum-A[v])個
    lint ret = A[v] * 2 - sum;
    return ret;
}

int main() {
    int N;
    std::cin >> N;
    A.resize(N);
    for (auto& a : A) std::cin >> a;

    tree = Graph<>(N);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u, --v;
        tree.span(u, v);
        tree.span(v, u);
    }

    // 例外
    if (N == 2) {
        std::cout << (A[0] == A[1] ? "YES" : "NO") << std::endl;
        return 0;
    }

    // 葉でない頂点からDFS
    int r;
    for (r = 0; tree[r].size() == 1; ++r) {}

    std::cout << (dfs(r, -1) == 0 ? "YES" : "NO") << std::endl;
    return 0;
}

#include <iostream>
