void addEdge(int u,int v){
	e[nume]=edge(v,g[u]);
	g[u]=nume++;
}

bool dfs(int x,int p){
	if(d[x]==1){
		delta[x]=a[x];
		return 1;
	}
	LL temp=0,ts=0,tmax=0;
	for(int i=g[x];~i;i=e[i].next)
		if(e[i].to^p){
			if(!dfs(e[i].to,x)) return 0;
			temp+=delta[e[i].to];
			tmax=max(tmax,delta[e[i].to]);
		}
	ts=temp;
	if(ts-tmax<tmax) ts-=tmax-(ts-tmax);
	ts/=2;
	temp-=a[x];
	if(temp<0) return 0;
	if(temp>ts) return 0;
	delta[x]=a[x]-temp;
	return 1;
}

