Int recur(int node, int prev) {
    Int cnt = 0, child = 0;
    for (auto next : G[node]) if (next != prev) {
        child++;
        cnt += recur(next, node);
    }
    if (child == 0) return A[node];
    if (prev == -1 && A[node] == cnt) {
        return 0;
    } else if ((cnt+1)/2 <= A[node] && A[node] <= cnt) {
        return 2*A[node] - cnt;
    } else {
