int s;

int dfs(int u, int p) {
	priority_queue <int, vector<int>, greater<int> > childw;
	int maxval = 0;
	for (int v : adjList[u]) {
		if (v == p) continue;
		int cur = dfs(v, u);
		maxval += cur;
		if (cur == -1) return -1;
		if (cur != 0) childw.push(cur);
	}
	if (childw.empty()) return a[u];
	int maxinner = 0;
	while (childw.size() > 1) {
		int minus = childw.top(); childw.pop();
		int cur = childw.top(); childw.pop();
		maxinner += minus - cur;
		if (minus - cur != 0) childw.push(minus - cur);
	}
	int minval = (childw.empty() ? 0 : childw.top()) + maxinner;
	if (!(a[u] >= minval && a[u] <= maxval)) return -1;
	int inner = maxval - a[u];
	return maxval - (inner * 2);
}

