ll dfs (int u, int parent = -1)
{
    if(edges[u].size() == 1)
        return a[u];
    ll sum = 0;
    ll mx = 0;
    for(int v : edges[u])
        if(v != parent)
        {
            ll up = dfs(v, u);
            sum += up;
            mx = max(mx, up);
        }
    ll maxPairs = (sum / 2 - max(0LL, mx - ((sum + 1) / 2)));
    if(sum - a[u] < 0)
        ok = false;
    if(sum - a[u] > maxPairs)
        ok = false;
    return a[u] * 2 - sum;
}

