class Solve {
public:
    int N;
    vector<ll> A;
    vector<vector<int>> treeone;
    void input() {
        cin >> N;
        A.resize(N);
        for(int i = 0; i < N; ++i){
            cin >> A[i];
        }
        treeone.resize(N);
        for(int i = 0; i < N - 1; ++i){
            int a,b;
            cin >> a >> b;
            a--,b--;
            treeone[a].push_back(b);
            treeone[b].push_back(a);
        }
    }

    bool flag = true;
    ll dfs(int n, int p){
        if(treeone[n].size() == 1 && p != -1) return A[n];
//        ll par = 2 * A[n];
//        if(treeone[n].size() == 1) par = A[n];

        ll chi = 0;
        ll max_chi = 0;
        for(auto e : treeone[n]){
            if(e != p){
                chi += dfs(e, n);
            }
        }
        if(A[n] > chi) flag = false;
        ll ret = 2 * A[n] - chi;
        if(ret < 0) flag = false;
        if(ret < 2 * max_chi - chi) flag = false;

        return ret;
    }

    void solve() {
        input();
        int leaf;
        for(int i = 0; i < N; ++i){
            if(treeone[i].size() == 1){
                leaf = i;
                break;
            }
