long long DFS(int x, int pred)
{
    bool is_leaf = true;
    long long matched = 0;
    long long alone = 0;
    for (int u : E[x]) {
        if (u == pred) {
            continue;
        }
        is_leaf = false;
        long long new_alone = DFS(u, x);

        // match alones
        long long new_matches = min(new_alone, alone);
        new_alone -= new_matches;
        alone -= new_matches;

        // match with matched
//         //cerr << "a " << new_alone << endl;
        long long use_for_match = min(new_alone / 2, matched);
        new_matches += use_for_match;
        new_alone -= use_for_match * 2;

        matched += new_matches;
        alone += new_alone;

//         //cerr << x << ' ' << u << ' ' << matched << ' ' << alone << endl;
    }

    if (is_leaf) {
        return c[x];
    }

    if (matched + alone != c[x]) {
        //cerr << x << ' ' << matched << ' ' << alone << endl;
        cout << "NO";
        exit(0);
    }

    return alone;
}

