void dfs( int u , int p ){

	Have[u] = 0;

	if ( E[u].size() == 1 ){
		Have[u] = a[u];
		return;
	}

	if ( p == -1 ){
		vector < LL > val;
		for ( int v : E[u] ){
			dfs(v,u);
			val.pb(Have[v]);
		}
		sort(val.begin(),val.end());

		LL sum = 0;
		LL fsum = 0;
		LL target = a[u];
		for ( LL v : val ){
			sum += v;
		}
		for ( int i = 0; i < val.size(); i++ ){
			LL v = val[i];
			if ( fsum <= target && fsum + v >= target ){
				LL l = 0, r = v;
				while ( l < r){
					LL m = ( l + r ) / 2;
					if ( fsum + m >= target ) r = m;
					else l = m + 1;
				}
				fsum += l;
				sum -= l;
				if ( fsum >= target && sum >= target ){
					yes();
				} else {
					no();
				}
			}

			fsum += v;
			sum -= v;
			if ( fsum >= target ){
				if ( sum >= target ){
					yes();
				}
				no();
			}
			if ( sum < target ){
				no();
			}
		}
	} else {
		for ( int v : E[u] ){
			if ( v == p ) continue;
			dfs(v,u);
			Have[u] += Have[v];
		}

		if ( Have[u] < a[u] ){
			no();
		}
		Have[u] = a[u];
	}
}

