  if (c[v].empty()){
    return;
  }
  long long sum = 0;
  long long M = 0;
  for (int w : c[v]){
    dfs(A, c, w, ok);
    sum += A[w];
    M = max(M, A[w]);
  }
  long long tmp = A[v] * 2 - sum;
  long long pair_cnt = max(sum - A[v], 0);
  /*
  cout << "v = " << v << endl;
  cout << "sum = " << sum << endl;
  cout << "pair = " << pair_cnt << endl;
  cout << "max = " << M << endl;
  */
  long long pair_cnt_2 = min(sum - M, sum / 2);
  if (pair_cnt_2 < pair_cnt){
    //cout << "not ok" << endl;
    ok = false;
  }
  A[v] = tmp;
}
