LL ans = 1;//okか
vector<vector<LL>>G;

LL f(LL u, LL p) {
	VL v;
	FOR(i, 0, SZ(G[u])) {
		if (G[u][i] != p)v.push_back(G[u][i]);
	}

	if (SZ(v) == 0)return a[u];//not ch

	LL sum = 0; LL maxv = -1;
	FOR(i, 0, SZ(v)) {
		LL t = f(v[i], u);
		sum += t;
		maxv = max(maxv, t);
	}
	if (sum < a[u]) { ans = 0; return 0; }//普通にしたが多い

	LL up = min(sum / 2, sum - maxv);
	LL res = sum - a[u];
	if (res > up) { ans = 0; return 0; }

	return sum - res * 2;
}

