    LL C2 = s-2*C1 - a;
    LL C3 = a - C2;
    // error(u, C1, C2, C3, s, a, inner[u]);

    if(!(C2 >= 0 && C3 >= 0)) {
        return false;
    }

    inner[u] = C1 + C2;

    return true;
}

bool solve() {

    if(N == 2) {
        return A[0] == A[1];
    }
    if(N == 3) {
        return A[0] == A[1] && A[1] == A[2];
    }
    int root = 0;
    REP(i, N) if(next[i].size() > 1){
        root = i;
        break;
    }

    build(root);

    bool answer = dfs(root);

    return answer;
}

}

