bool dfs(int cur, int parent)
{
  node n = nodes[cur];
  int sum = 0;
  rep(i, n.ns.size()) {
    int next = n.ns[i];
    if(next != parent) {
      if(dfs(next, cur))
	sum += nodes[next].a;
      else
	return false;
    }
  }
  if(parent == -1) {
    node t = nodes[n.ns[0]];
