        que.pop();
        long long tmp2 = que.top();
        cnt += que.top();
        que.pop();
        que.push(tmp-tmp2);
    }

    if(ok <= cnt){
        return a[idx]-ok;
    }else{
        cout << "NO" << endl;
        exit(0);
    }
}

