typedef long long LL;

int N;
int v[100005];
LL up[100005];
int g[100005];
vector <int> edg[100005];

void yes() {printf("YES\n"); exit(0);}
void no() {printf("NO\n"); exit(0);}

bool cmp(int a, int b)
{
    return up[a] > up[b];
}

void DFS(int nod, int fth)
{
    if(edg[nod].size() <= 1)
    {
        up[nod] = v[nod];
        return;
    }
    LL cnt = 0;
    LL mx = 0;
    for(auto nxt: edg[nod])
    {
        if(nxt == fth)  continue;
        DFS(nxt, nod);
        cnt += up[nxt];
        mx = max(mx, up[nxt]);
    }

    up[nod] = 2LL * v[nod] - cnt;
    if( (cnt - up[nod]) % 2 != 0 )  no();
    if(up[nod] < 0) no();

    LL st = 0;
    LL dr = mx;
    LL maxval = mx;
    while(st <= dr)
    {
        LL mij = st + (dr - st) / 2;
        LL rem = up[nod];
        for(auto nxt: edg[nod])
        {
            if(nxt == fth)  continue;
            rem -= max(0LL, up[nxt] - mij);
        }

        if(rem >= 0)
        {
            maxval = mij;
            dr = mij - 1;
        }
        else
            st = mij + 1;
    }

    if(maxval > (cnt - up[nod]) / 2)    no();
}

int main()
{
