    }
    for(int i = 1; i < N; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        edg[x].push_back(y); g[x]++;
        edg[y].push_back(x); g[y]++;
    }

    int root = 1;
    for(int i = 1; i <= N; i++) if(g[i] > 1)    {root = i; break;}

    DFS(root, 0);
    if(up[root] == 0)   yes();
    no();

    return 0;
}

