vector<int> adj[222222];

LL go(int v, int p = -1) {
  if (adj[v].size() == 1 && adj[v].front() == p) return A[v];

  LL all = 0;
  LL maxi = 0;
  for (int u: adj[v]) if (u != p) {
    LL tmp = go(u,v);
    if (tmp == -1) return -1;
    all += tmp;
    maxi = max(maxi, tmp);
  }

  if (all < A[v]) return -1;

  LL max_pairs = min(all - maxi, all / 2);

  LL needed_pairs = all - A[v];
  if (needed_pairs > max_pairs) return -1;
  return all - 2 * needed_pairs;
}

int main() {
  int N;
  scanf("%d", &N);
  REP(i,N) scanf("%lld", &A[i]);
