    ok = A[0] == A[1];
  } else {
    int not_leaf = 0;
    REP(i,N) if (adj[i].size() > 1) not_leaf = i;
    ok = (go(not_leaf) == 0);
  }
  if (ok) {
    printf("YES\n");
  } else {
    printf("NO\n");
  }
}

