long long dfs(int node , int parent){
    dif[node] = arr[node];
    vector < long long > s;
    s.clear();
    long long sum = 0;
    for(int next : v[node]){
        if(next != parent){
            s.push_back(dfs(next , node));
            sum += s.back();
            dif[node] -= arr[next];
        }
