        exit(0);
    }
    long long val = dif[node];
    long long cur = 0;
    long long tot = 0;
    for(auto &it : s){
        long long x = min(it , cur);
        if(val < x){
            val = 0;
            sum -= val * 2;
            tot += val;
            cur -= val;
            it -= val;
            break;
        }
        else{
            val -= x;
            sum -= 2 * x;
            cur -= x;
            it -= x;
            tot += x;
        }
        cur += it;
    }
    if(val > 0){
        printf("NO\n");
        exit(0);
    }
    dif[parent] += tot;
    return cur;
}
