pair<ll, ll> go(vvi& adj, vi& stones, int loc, int par) {
    bool leaf = true;
    ll min_tot = 0, max_tot = 0;

    vector<pair<int, int>> below;
    for (int nbr : adj[loc]) if (nbr != par) {
        leaf = false;

        auto p = go(adj, stones, nbr, loc);
        below.push_back(p);

        min_tot += p.first;
        max_tot += p.second;
    }

    if (loc == par) {
        if (stones[loc] < min_tot) fail();
        if (stones[loc] > max_tot) fail();
        return { 0ll, 0ll };
    }
    if (leaf) return { stones[loc], stones[loc] };

    sort(all(below));

    ll min_out;
    if (2 * below.back().first > min_tot) {
        if (below.back().first > stones[loc]) fail();
        ll max_rest = max_tot - below.back().second;
        min_out = max(0ll, below.back().first - max_rest);
    } else {
        if ((min_tot + 1) / 2 > stones[loc]) fail();
        min_out = (min_tot % 2 == 0 || min_tot < max_tot) ? 0 : 1;
    }

    if (stones[loc] > max_tot) fail();
    ll max_out = min((ll) stones[loc], max_tot);

    return { min_out, max_out };
}

