#include <cstdio>
#include <algorithm>

using namespace std;
typedef long long LL;

const int N=1e5+10;

struct Edge{ int to,next;} way[N<<1];

int n,A[N],num[N],tot,d[N];
LL val[N];

void Build(int a,int b) { way[++tot]=(Edge){b,num[a]}; num[a]=tot; }

void Init()
{
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%d",&A[i]);
	int a,b;
	for (int i=2;i<=n;++i)
	{
		scanf("%d%d",&a,&b);
		Build(a,b); Build(b,a);
		d[a]++; d[b]++;
	}
}

bool Dfs(int x,int fa)
{
	if (d[x]==1) { val[x]=A[x]; return 1; }
	LL sum=0;
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (v==fa) continue;
		if (!Dfs(v,x)) return 0; 
		sum+=val[v];
	}
	if (A[x]>sum) return 0;
	LL need=sum-A[x],last=0,now=0;
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (v==fa) continue;
		if (!last) last=val[v];
		else 
		{
			now+=min(last,val[v]);
			last-=val[v]; if (last<0) last=-last;
		}
	}
	if (now>=need) val[x]=A[x]-need;
	else return 0;
	return 1;
}

void Solve()
{
	if (n==2) 
	{ 
		if (A[1]==A[2]) printf("YES\n");
		else printf("NO\n");
		return ; 
	}
	int root=0;
	for (int i=1;i<=n;++i) if (d[i]>1) { root=i; break; }
	bool fl=Dfs(root,0);
	if (val[root]) fl=0;
	if (fl) printf("YES\n");
	else printf("NO\n");
}

int main()
{
	Init();
	Solve();
	return 0;
}

