const int N = 100000 + 10;
int a[N];

vector<int> g[N];

bool is_leaf(int n)
{
  return g[n].size() == 1;
}

lli f(int curr, int prev)
{
  if (is_leaf(curr)) return a[curr];

  vector<lli> b;
  each (next, g[curr]) {
    if (next == prev) continue;
    b.emplace_back(f(next, curr));
  }

  lli sum = accumulate(b.begin(), b.end(), 0LL);
  if (b.size() == 1) {
    if (a[curr] != b[0]) throw "";
    return b[0];
  }

  lli mx = *max_element(b.begin(), b.end());
  lli paired = min<lli>(sum / 2, mx);
  lli x = a[curr] - paired;
  lli y = a[curr] * 2 - sum;
  if (x < 0 || y < 0 || (curr == prev && y)) throw "";
  return y;
}

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    fill(g, g + N, vector<int>());
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n - 1; ++i) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      g[a].push_back(b);
      g[b].push_back(a);
    }
    int r = 0;
    for (int i = 0; i < n; ++i) {
      if (!is_leaf(i)) { r = i; break; }
    }
    if (n == 1) {
      puts(a[0] ? "NO" : "YES");
    } else if (n == 2) {
      puts(a[0] == a[1] ? "YES" : "NO");
    } else try {
      f(r, r);
      cout << "YES" << endl;
    } catch (const char* e) {
      cout << "NO" << endl;
    }
  }

  return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MAXN = 1e5 + 10;

int n;
long long arr[MAXN];
vector<int> adj[MAXN];
bool CANT = false;

long long dfs(int v, int par = 0) {
	long long all = 0, mx = 0;
	for (auto e : adj[v]) 
		if (e != par) {
			long long g = dfs(e, v);
			all += g;
			mx = max(mx, g);
		}
	if (adj[v].size() == 1)
		return arr[v];
	if (all < arr[v]) {
		CANT = true;
		return 0;
	}
	long long needed = all - arr[v];
	long long nmat = 0;
	if ((all - mx) < mx)
		nmat = all - mx;
	else
		nmat = all / 2;
	if (nmat < needed) {
		CANT = true;
		return 0;
	}
	return all - 2 * needed;
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n;
	for (int i = 1; i <= n; i++)
		cin >> arr[i];
	for (int i = 1; i < n; i++) {
		int u, v; cin >> u >> v;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	if (n == 2) {
		if (arr[1] == arr[2])
			return cout << "YES\n", 0;
		return cout << "NO\n", 0;
	}
	for (int i = 1; i <= n; i++)
		if (adj[i].size() > 1) {
			if (dfs(i) || CANT) 
				return cout << "NO\n", 0;
			return cout << "YES\n", 0;
		}
	return 0;
}

