int dfs(Graph &g, vi &data, int pos, int bef)
{
    if (g[pos].size() == 1) {
        return data[pos];
    }
    int sum = 0;
    vi cnt;
    for (auto i : g[pos]) {
        if (i.d != bef) {
            cnt.pb(dfs(g, data, i.d, pos));
            sum += cnt.back();
        }
    }
    int ret = data[pos] * 2 - sum;
    if (*max_element(all(cnt)) * 2 - sum <= data[pos] && data[pos] <= sum && 
            min(sum - *max_element(all(cnt)), sum/2) >= data[pos] - ret) {
        return ret;
    } else {
        fail = true;
        return -1;
    }
}

