using namespace std;
typedef long long LL;

const int MaxN = 1e5, MaxM = 2e5;
int n, all;
int pre[MaxM + 5], last[MaxN + 5], other[MaxM + 5];
int deg[MaxN + 5];
LL a[MaxN + 5];
bool flag;

void Build(int x, int y)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

void Init()
{
	all = -1; memset(last, -1, sizeof(last));
	memset(deg, 0, sizeof(deg));
	for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
	for (int i = 1; i <= n - 1; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		Build(u, v); Build(v, u);
		deg[u]++; deg[v]++;
	}
}

void Dfs(int x, int fa)
{
	if (deg[x] == 1) return;
	int ed = last[x], dr;
	LL sum = 0, MaX = 0;
	while (ed != -1) {
		dr = other[ed];
		if (dr != fa) {
			Dfs(dr, x);
			sum = sum + a[dr];
			MaX = max(MaX, a[dr]);
		}
		ed = pre[ed];
	}
	if (sum < a[x]) {flag = false; return;}
	if (sum - a[x] > min(sum / 2, sum - MaX)) flag = false;
	else a[x] = 2 * a[x] - sum;
}

void Solve()
{
	flag = true;
	int root = 1;
	for (int i = 1; i <= n; i++) 
		if (deg[i] > 1) root = i;
	Dfs(root, 0);
	if (a[root] != 0) flag = false;
	if (n == 2 && (a[1] != a[2])) flag = false;
	if (!flag) printf("NO\n"); else printf("YES\n");
}

int main()
{
	while (~scanf("%d", &n)) {
		Init();
		Solve();
	}
	return 0;
}

