void dfs(int u, int fa){
    if(du[u] == 1){
        x[u] = a[u];
        return ;
    }
    int sum = 0;
    for(int i = head[u];i;i = nex[i]){
        int v = to[i];
        if(v == fa)continue;
        dfs(v, u);
        sum += x[v];
        G[u].push_back(x[v]);
    }
    sort(G[u].begin(), G[u].end());
    int k = sum - a[u];
    if(k < 0)flag = 0;
    x[u] = sum - 2 * k;
