int solve(int n, int p, bool & flg) {
	if(E[n].size() == 1)
		return A[n];
	ll s = 0;
	ll mx = 0;
	rep(i,E[n].size()) {
		if(E[n][i] == p) continue;
		ll tmp;
		tmp = solve(E[n][i], n, flg);
		s += tmp;
		mx = max(mx,tmp);
	}
	ll I, O;
	I = s - A[n];
	O = A[n] - I;
	if(I < 0 || O < 0 || (I > mx && mx*2 > s)) flg = false;
	return O;
}

