namespace G{
	int rt,cnt,dgr[N],fir[N];
	lint req[N];
	class edge{
		public:
			int to,nx;
	}eg[N<<1];

	inline void add(const int a,const int b){
		++dgr[a],++dgr[b];
		eg[++cnt]=(edge){b,fir[a]};
		fir[a]=cnt;
		eg[++cnt]=(edge){a,fir[b]};
		fir[b]=cnt;
	}

	inline void get_rt(){
		for(; dgr[rt]<2; ++rt);
		assert(rt<=n);
	}

	bool dfs(const int x,const int fa){
		if(dgr[x]==1){
			req[x]=val[x];
			return 1;
		}
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y!=fa&&!dfs(y,x)) return 0;
		}
		lint mx_req=0,req_sum=0;
		for(int i=fir[x]; i; i=eg[i].nx){
			const int y=eg[i].to;
			if(y==fa) continue;
			req_sum+=req[y];
			apx(mx_req,req[y]);
		}
		if(req_sum<val[x]) return 0;
		int link_need=req_sum-val[x];
		int link_able=std::min(req_sum>>1,req_sum-mx_req);
		if(link_need>link_able) return 0;
		req[x]=req_sum-(link_need<<1);
		return 1;
	}
}

