using namespace std;

pair<long long, long long> search(const vector<vector<int>>& g, const vector<int>& A, int pos, int prev){
    long long minSum = 0;
    long long maxSum = 0;
    long long deg = 0;
    vector<pair<long long, long long>> pr;
    for(auto& t : g[pos]){
        if(t == prev) continue;
        auto p = search(g, A, t, pos);
        pr.push_back(p);
        if(p.first < 0 || A[pos] < p.first) return make_pair(-1, -1);
        minSum += p.first;
        maxSum += p.second;
        ++deg;
    }
    if(deg == 0) return make_pair(A[pos], A[pos]);
    if(maxSum < A[pos]) return make_pair(-1, -1);
    long long lower = 0;
    for(auto& p : pr){
        lower = max(lower, 2*A[pos] - min<long long>(A[pos], p.second) - (maxSum - p.second));
    }
    return make_pair(lower, A[pos]);
}

bool solve(const vector<vector<int>>& g, const vector<int>& A){
    auto p = search(g, A, 0, -1);
    if(p.first < 0) return false;
    if(g[0].size() == 1) return p.first <= A[0] && A[0] <= p.second;
    return p.first == 0;
}

