		T[v].c.push_back(c);
		dfs(c,r+1);
	}
}

void tdfs(int v){
	ll sum = 0LL;
	if(T[v].c.empty()){
		T[v].w = A[v];
		return;
	}
	for(int c : T[v].c) if(T[c].w == -1){
		tdfs(c);
		sum += T[c].w;
	}
	T[v].w = 2LL*A[v] - sum;
}

bool C = true;
void cdfs(int v){
	if(T[v].c.empty())return;
	ll sum = 0LL;
	ll maxc = 0LL;
	for(int c : T[v].c){
		cdfs(c);
		sum += T[c].w;
		maxc = max(maxc,T[c].w);
	}
	ll L = (sum-T[v].w)/2LL;
	ll ps = min(sum/2LL,sum-maxc);
	if(ps < L)C = false;
}

int main()
{
	cin >> N;
	rep(i,0,N)cin >> A[i+1];
	rep(i,0,N-1){
		int a,b;
		cin >> a >> b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	//1を根とする木
	dfs(1,1);
	tdfs(1); //経路の使用数
	cdfs(1);
	if(G[1].size() != 1 and T[1].w != 0)C = false;
	if(C){
		cout << "YES" << endl;
	}else{
		cout << "NO" << endl;
	}

	return 0;
}

