#define for_(i,a,b) for(int i=(a);i<(b);++i)
typedef long long lint;
int N;
lint A[100005], B[100005];
vector< set< int > > adj;

void yes() { puts("YES"); exit(0); }
void no() { puts("NO"); exit(0); }

void solve() {
	memset(B, 0, sizeof(B));
	for_(v,0,N) {
		if (adj[v].size() > 1) B[v] = 2 * A[v];
		else B[v] = A[v];
	}

	queue< int > que;
	for_(v,0,N) if (adj[v].size() == 1) que.push(v);

	while (!que.empty()) {
		int v = que.front(); que.pop();
		if (B[v] < 0) no();
		assert(adj[v].size() <= 1);
		for (int u : adj[v]) {
			B[u] -= B[v]; B[v] = 0;
			adj[u].erase(v);
			if (adj[u].size() == 1) que.push(u);
		}
	}

	bool ans = true;
	for_(v,0,N) ans &= (B[v] == 0);
	if (ans) yes();
	else no();
}

int main() {
	cin >> N;
	for_(i,0,N) cin >> A[i];

	adj.assign(N, set< int >());
	for_(i,0,N-1) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		adj[a].insert(b);
		adj[b].insert(a);
	}

	solve();
}

