// 制約fを満たす最大値（最小値）の二分探索
// ok < ng なら最大値，ok > ng なら最小値探索になる
template<class T, typename F> T bsearch(T ok, T ng, int loop, F f) {
	for(int i = 0; i < loop; ++i) {
		T middle = (ok + ng) / 2;
		(f(middle) ? ok : ng) = middle;
	}
	return ok;
}

