void dfs(ll id, ll par, ll gi) {
    ll ct=0;
    for(int i=0;i<G[id].size();i++) {
        if(G[id][i].first==par) continue;
        dfs(G[id][i].first, id, G[id][i].second);
        ct++;
    }
    if(ct==0) {
        MP2[gi] += A[id];
    }
    else {
        if(gi==-1) {
            ll ctt=0;
            for(int i=0;i<G[id].size();i++) {
                if(G[id][i].first==par) continue;
                ctt += MP2[G[id][i].second];
