bool dfs (int x, int las) {
    int cnt = 0;
    ll tmp = 0;
    for (int i = head[x]; i; i = nxt[i]) if (to[i] != las) {
        cnt++;
        if (!dfs(to[i], x)) return false;
        tmp += c[to[i]];
    }
