const int N = 1e5 + 5;

int n;
int arr[N];
vi lst[N];

bool rekt = false;
ll mx[N], total[N];
void dfs(int now, int par){
    // leaf
    if(lst[now].size() == 1){
        mx[now] = total[now] = arr[now];
        return;
    }

    // not leaf
    FOR(i,lst[now].size()){
        int to = lst[now][i];
        if(to == par)continue;
        dfs(to, now);
        mx[now] = max(mx[now], mx[to]);
        total[now] += total[to];
    }

    if(arr[now] > total[now]){ // no way, not enough leaf
        rekt = true;
        return;
    }

    ll reduce = total[now] - arr[now];
    ll maxreduce;
    if(mx[now] > total[now]-mx[now]){ // mx higher than rest
        maxreduce = total[now]-mx[now];
    }else{
        maxreduce = total[now]/2;
    }
    if(reduce > maxreduce){ // too much leaf
        rekt = true;
        return;
    }

    mx[now] = max(0LL, mx[now]-reduce);
    total[now] -= reduce*2;
}

