		}

		long long maximumPair = 0;
		sort(all(v), greater<long long>());
		maximumPair = min(v[0], childSum / 2);
		maximumPair = max(maximumPair, requirePairNumber(v));
		//show(maximumPair)
		if(loot == cur and maximumPair != a[cur]){
			ans = false;
			return 0;
		}

		long long needPair = childSum - a[cur];
		if(maximumPair >= needPair){
			return a[cur] - needPair;
		}else{
			ans = false;
		}

		return 0;
	}
}

