			if(col[p][0]!=node[p]){
				cout << "NO" << endl;
				return 0;
			}
			continue;
		}
		sort(all(col[p]),greater<ll>());
		ll ma = col[p][0];
		ll su = sum(col[p]);
		if((su + 1) / 2 > node[p]){
			cout << "NO" << endl;
			return 0;
		}
		if(su-ma<ma){
			node[p] -= su;
			if(node[p]<ma-su){
				cout << "NO" << endl;
				return 0;
			}
		}else{
			node[p] -= su / 2;
		}
		foreach(i,edges[p]){
			if(edges[i].empty()){
				continue;
			}
			col[i].emplace_back(node[p]);
			node[p] = 0;
			if(col[i].size()==edges[i].size()){
				st.push(i);
			}
		}
		if(node[p]){
			cout << "NO" << endl;
			return 0;
		}
		edges[p].clear();
	}

	cout << "YES" << endl;
	return 0;
}

