bool dfs(int now){
    used[now]=true;
    ll sum=0;
    bool leaf=true;
    vector<int> next;
    for(int i=0;i<g[now].size();i++){
        int u=g[now][i];
        if(used[u]) continue;
        if(!dfs(u)) return false;
        sum+=path[u];
        leaf=false;
        next.push_back(u);
