    ll res=2*A[now]-sum;
    path[now]=res;
    if(res<0) return false;

    ll tmp=res+sum;
    if(tmp%2) return false;
    for(int i=0;i<next.size();i++){
        if(path[next[i]]*2>tmp) return false;
    }
    return true;
}

