long long dfs(int v, int par) {
  vector<long long> ns; long long sum_ns = 0;
  for(auto w : adj[v]) {
    if(w == par) continue;
    ns.push_back(dfs(w, v));
    if(ns.back() < 0) return -1;
    sum_ns += ns.back();
  }
  if(ns.empty()) return A[v];
