	VVI G( N );
	REP( N - 1 )
	{
		int u, v;
		scanf( "%d%d", &u, &v );
		--u, --v;

		G[u].PB( v );
		G[v].PB( u );
	}

	VI degrees( N );
	queue< int > que;
	VT< LL > used( N );

	VT< LL > leaves;
	REP( i, N )
	{
		if ( ( degrees[i] = SZ( G[i] ) ) == 1 )
		{
			used[i] = A[i];
			que.push( i );
			leaves.PB( A[i] );
		}
	}

	if ( accumulate( ALL( leaves ), 0LL ) < 2 * *max_element( ALL( leaves ) ) )
	{
		puts( "NO" );
		fflush( stdout );
		return 0;
	}

	VI vanished( N );
	REP( N - 1 )
	{
		const int u = que.front();
