		const LL rest = 2 * A[u] - used[u];

		if ( rest < 0 )
		{
			puts( "NO" );
			fflush( stdout );
			return 0;
		}

		const int v = *find_if( ALL( G[u] ), [&]( const int v ){ return !vanished[v]; } );

		used[v] += rest;
		vanished[u] = 1;

		if ( --degrees[v] == 1 )
		{
