	for(i=(g[u].l_ength()-1); i>=0; --i){
		v = g[u][i];
		if(done[v]){
			continue;
		}
		++c;
		t = solve(v);
		s += t;
		m = max(m,t);
		if(!ans[v]){
			ans[u] = false;
			return -INFLL;
		}
	}
	if(!c){
		ans[u] = true;
		return a[u];
	}else if(c==1){
		ans[u] = (s==a[u]);
		return a[u];
	}else if(a[u]*2<s || s<a[u] || m>a[u]){
		ans[u] = false;
		return (a[u]*2-s);
	}else{
		ans[u] = true;
		return (a[u]*2-s);
	}
}

