bool valid = true;
int root = 0;

int dfs(int cv, int pv, vector<vector<int>> &G, vector<ll> &a){

    ll sum = 0;
    bool have_child = false;
    for(auto nv : G[cv]){
        if(nv == pv) continue;
        have_child = true;
        ll cost = dfs(nv, cv, G, a);
        if(a[cv] < cost) valid = false;
        if(cost < 0) valid = false;
        sum += cost;
    }

    if(cv == root){
        if(a[root] != sum) valid = false;
    }

    if(!have_child){
        return a[cv];
    }
    else{
        return a[cv] * 2 - sum;
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

