    vector<vector<int>> G(n);
    for(int i=0; i<n-1; i++){
        int a, b; cin>>a>>b;
        a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    while(G[root].size() > 1) root++;

    dfs(root, -1, G, a);

    cout << (valid ? "YES" : "NO") << endl;

    return 0;
}

