lli dfs(lli x,lli prev){
  if(graph[x].size() == 1){
    return a[x];
  }else{
    vll mem;
    for(lli y : graph[x]){
      if(y == prev) continue;
      mem.push_back(dfs(y,x));
    }
    lli b = accumulate(mem.begin(),mem.end(),0ll);
    if(!is_possible(a[x],b)) error(1);
    lli b_pair = (b-a[x])*2;
    lli b_above = 2*a[x]-b;
    lli hoge = 0;
    for(lli m : mem){
      hoge += min(m,b_pair/2);
    }
    if(hoge < b_pair) error(2);
    return b_above;
  }
}

