ll dfs(const vector<vecint>& g, vecint& a, int i, int p=-1) {
  ll csum = 0;
  ll cmax = 0;
  for(auto&& to:g[i]) {
    if (to == p) continue;
    ll child = dfs(g, a, to, i);
    if (child < 0) return -1;
    csum += child;
    cmax = max(cmax, child);
  }
  ll q = g[i].size() == 1 ? a[i] - csum : 2*a[i] - csum;
  if (q < 0) return -1;
  cmax = max(cmax, q);
  if (cmax > a[i]) return -1;
  return q;
}

