//絶対に条件を満たせない場合は, -1を返す.
int dfs(int parent, int v) {
	if (et[v].size() == 1) {
		return a[v];
	}

	int maxi = 0, ssum = 0;
	for (int i = 0; i < et[v].size(); i++) {
		if (et[v][i] == parent) continue;
		int res = dfs(v, et[v][i]);
		if (res == -1) { return -1; }
		maxi  = max(maxi, res);
		ssum += res;
	}

	int x = ssum - a[v];		//折り返す回数
	int y = 2 * a[v] - ssum;	//通る回数

	//条件チェック
	if (0 <= x && x <= min(ssum / 2, ssum - maxi) && 0 <= y) {
		return y;
	}
	return -1;
}

