using P = pair<int,int>;

P merge(P a, P b) {
  int sum = a.second + b.second;
  if (a.second < b.first) return make_pair(b.first - a.second, sum);
  if (b.second < a.first) return make_pair(a.first - b.second, sum);
  return make_pair(a.first & b.first & 1, sum);
}

