using ll = long long;

ll dfs(int v, vector<vector<int>>& g, vector<ll> const& A, int prev) {
    vector<ll> child(g[v].size());
    if(prev != -1 && g[v].size() == 1) {
        return A[v];
    }
    ll sum = 0, ma = -1;
    for(int i=0; i<g[v].size(); ++i) {
        if(g[v][i] == prev) {
            continue;
        }
        child[i] = dfs(g[v][i], g, A, v);
        if(child[i] == -1) {
            return -1;
        }
        sum += child[i];
        ma = max(ma, child[i]);
    }
    ll up = 2*A[v] - sum;
    ll p_cnt = (sum - up) / 2;
    //cout << "v: " << v << " up: " << up << " p_cnt: " << p_cnt << endl;
    if(up < 0 || p_cnt * 2 != sum - up || p_cnt > sum - ma) {
        return -1;
    }
    return up;
}

