#include <bits/stdc++.h>

using namespace std;

//頭の整理のためにコメントを入れてみる
//あってるかは知らない

typedef long long ll;
typedef vector< vector<int> > Graph;

Graph g;
ll a[100010];

//return: nodeとparentを結ぶ辺を通る操作の回数(通る回数)
//全ての石を取り除く事ができないと分かった場合-1を返す
ll dfs(int node, int parent) {
	//nodeが葉の場合通る回数は明らかにa[node]に等しい
	if (g[node].size() == 1) return a[node];

	ll c_sum = 0;  //nodeの子の通る回数の和
	ll c_max = 0;  //nodeの子の通る回数の最大値
	for (int nex : g[node]) {
		if (nex == parent) continue;
		ll c = dfs(nex, node);  //nodeの子の通る回数
		if (c == -1) return -1;  //全ての石を取り除く事ができないと分かった場合
		c_sum += c;
		c_max = max(c_max, c);
	}

	/* 
		T: nodeとparentを結ぶ辺を通る操作の回数
		L: nodeの異なる2つの子がnodeを経由してつながっている辺を通る操作の回数

		1.  nodeを経由するような辺は
			parent-node-children(パターンA)か
			children1-node-children2(パターンB)のどちらかしかなく
			いずれの場合も1回の操作でa[node]は1減る
			よって、a[node]を0にするためには
			T + L == a[node]が成立する必要がある

		2.  パターンAでは1回の操作で子の石は1つ減る
			一方、パターンBでは1回の操作で子の石は2つ減る
			以上よりnodeの子の石を全て0にするためには
			T + 2 * L == c_sumが成立する必要がある

		以上より
		1. T + L == a[node]
		2. T + 2 * L == c_sum
	*/
	ll T = 2 * a[node] - c_sum;
	ll L = c_sum - a[node];
	if (L < 0 || T < 0) return -1;

	/*
		nodeの異なる2つの子がnodeを経由してつながっている辺を通る操作の回数の最大値は

		1.  c_max > c_sum / 2の場合
			通る回数がc_maxとなるnodeの子とそれ以外のnodeの子全てをそれぞれペアとして
			各ペアをつなげた辺に対して操作をすると操作の回数を最大にでき、
			この時、通る回数がc_maxとなるnodeの子以外の石の数が0になることから
			操作の回数の最大値はc_sum - c_maxとなる

		2.  1以外の場合
			nodeの子の中で石の数が多いものを貪欲に2つ選び、
			それらをつなげた辺に対し操作を行うということを繰り返すことで
			操作の回数を最大にでき、
			この時、nodeの子の石の残りの合計はc_sum % 2となることから
			操作の回数の最大値はc_sum / 2となる

		Lが操作の回数の最大値を超えるなら-1を返す
	*/
	if (c_max > c_sum / 2) {
		if (L > c_sum - c_max) return -1;
		else return T;
	} else {
		if (L > c_sum / 2) return -1;
		else return T;
	}
}

