	/*
		YESを出力するのは
		根が葉の場合: dfs(root, -1) == a[root]
		根が葉ではない場合: dfs(root, -1) == 0
		今回は葉ではないノードを根とすることで後者の場合に統一
	*/

	//ノードが全て葉となる場合は例外として処理
	if (n == 2) {
		cout << (a[0] == a[1] ? "YES" : "NO") << endl;
		return 0;
	}

	//葉ではないノードを根とする
	int root;
	for (root = 0; root < n; root++) {
		if (g[root].size() != 1) break;
	}

	cout << (dfs(root, -1) == 0 ? "YES" : "NO") << endl;
	return 0;
}

