void rec(int idx, int par)
{
  if(g[idx].size() == 1) return;
  int64 ret = 0, large = 0;
  for(auto &to : g[idx]) {
    if(to == par) continue;
    rec(to, idx);
    ret += A[to];
    large = max(large, A[to]);
  }
  if(A[idx] > ret || ret > 2 * A[idx]) {
    puts("NO");
    exit(0);
  }
  int64 rest = ret - A[idx];
  if(rest > ret - large) {
    puts("NO");
    exit(0);
  }
  A[idx] -= rest;
}

