ll dfs(int now, int par){
	if(adj[now].size() == 1) return a[now]; /// leaf


    for(int dest:adj[now]){
		if(dest==par) continue;
		ll res = dfs(dest, now);
		v[now].push_back(res);
	}
    if(now==root){
        ll mx=*max_element(v[now].begin(), v[now].end());
        ll sum=0;
        for(ll e:v[now]) sum+=e;
        if(mx > sum-mx) fck(); ///
        if(sum%2==1 || sum/2 != a[now]) fck(); ///
        return 0;
    }
    else{
		ll mx=*max_element(v[now].begin(), v[now].end());
		ll sum=0;
        for(ll e:v[now]) sum+=e;

        ll maxPair=0;
        if(v[now].size() > 1){
			if(mx > sum-mx) maxPair=mx/2;
			else maxPair=sum/2;
		}

		ll LL=sum-maxPair, RR=sum;
		if(a[now] < LL || a[now] > RR) fck(); ///
		ll sP = sum - a[now];
