using namespace std;

vector<vector<int>> graph;
vector<long long> dat;

long long rec(int nod, int par) {
	long long ret = dat[nod] * 2;
	int ccnt = 0;
	vector<long long> subs;
	for (auto next : graph[nod]) {
		if (next == par) continue;
		ccnt++;
		long long sub = rec(next, nod);
		if (sub < 0) return -1;
		subs.push_back(sub);
		ret -= sub;
	}
	if (par == -1) {
		if (ccnt == 1) {
			ret -= dat[nod];
		}
		return ret == 0;
	}
	if (ccnt == 0)
		return dat[nod];
	if (ret > dat[nod])
		return -1;
	sort(subs.begin(), subs.end());
	long long smallsum = 0;
	for (int i = 0; i +1 < subs.size(); i++)
		smallsum+=subs[i];
	if (smallsum < dat[nod] - ret)
		return -1;
	return ret;
}

