	graph.resize(n);
	for (int i = 0; i < n-1; i++) {
		int a,b;
		scanf("%d%d",&a,&b);
		a--,b--;
		graph[a].push_back(b);
		graph[b].push_back(a);
	}
	int ret = rec(0, -1);
	if (ret <= 0) {
		printf("NO\n");
	} else {
		printf("YES\n");
	}
	return 0;
}

