LL up[N];
bool dfs(int u, int fa) {
  LL s = 0;
  for (auto v : adj[u]) {
    if (v == fa)
      continue;
    if (!dfs(v, u))
      return false;
    s += up[v];
  }
  //printf("%d %I64d %d\n", u, s, a[u]);
  if (adj[u].size() == 1) {
    up[u] = a[u];
    return true;
  }
  LL c;
  if (u != rt) {
    if (s < a[u])
      return false;
    c = s-a[u];
  } else {
    if (s != 2ll*a[u])
      return false;
    c = a[u];
  }
  up[u] = a[u] - c;
  if (up[u] < 0)
    return false;
  int maxa = 0;
  for (auto v : adj[u]) {
    if (v == fa)
      continue;
    maxa = max((LL)maxa, up[v]);
  }
  if (s - maxa < c)
    return false;
  return true;
}

