Int recur(int node, int prev) {
    Int maxc = 0, sumc = 0, num = 0;
    for (auto next : G[node]) if (next != prev) {
        num++;
        Int c = recur(next, node);
        maxc = max(maxc, c);
        sumc += c;
    }
    if (num == 0) {
        return A[node];
    }
    Int y = sumc - A[node];
    Int x = A[node] - y;
    if (x >= 0 && y >= 0 && y <= sumc - maxc) {
        return x;
    }
    cout << "NO" << '\n';
    exit(0);
}
