void getAns(int u, int fa)
{
	long long maxLine = -1;
	long long allLine = 0;
	for (int v : adj[u])
	{
		if (v == fa)
			continue;
		getAns(v, u);
		if (ans == false)
			return ;
		maxLine = max(maxLine, f[v]),
		allLine += f[v];
	}

	if (maxLine == -1)
	{
		assert(adj[u].size() == 1);
		f[u] = value[u];
		return ;
	}

	f[u] = 2 * value[u] - allLine;
	long long restLine = allLine - maxLine;

	if (f[u] < 0 || f[u] > value[u] || maxLine - f[u] > restLine)
		return ans = false, void();
}

