ll dfs(int v, int p) {
  vector<ll> edges;
  for (int u : G[v]) {
    if (u != p) {
      ll e = dfs(u, v);
      if (e < 0) {
        return -1;
      }
      edges.push_back(e);
    }
  }
  if (edges.empty()) {
    return A[v];
  }
  ll sum = accumulate(edges.begin(), edges.end(), 0ll);
  ll mx = *max_element(edges.begin(), edges.end());
  ll x = 2 * A[v] - sum;
  sum += x;
  mx = max(mx, x);
  if (x < 0 || sum % 2 != 0 || mx > sum / 2) {
    return -1;
  }
  return x;
}

bool solve() {
  if (N == 2) {
    return A[0] == A[1];
  }
  int r = -1;
  for (int v = 0; v < N; v++) {
    if (G[v].size() > 1) {
      r = v;
      break;
    }
  }
  return dfs(r, -1) == 0;
}

