pair<LL, LL> dfs(int v, int p) {
  int num_ch = 0;
  LL l = 0;
  LL r = 0;
  LL s = 0;
  LL ls = 0;
  LL maxa = -1;
  LL maxb = -1;
  LL maxamina = 0x7fffffffffLL;
  for (int u : es[v]) {
    if (p == u) continue;
    LL x, y;
    tie(x, y) = dfs(u, v);
    s += y;
    ls += x;
    maxa = max(maxa, x);
    if (maxa == x) {
      maxamina = min(maxamina, y);
    }
    maxb = max(maxb, y);
    LL nr = y+r;
    LL nl = max(0LL, max(x, l) - min(y, r));
    l = nl;
    r = nr;
    num_ch++;
  }

  if (ls/2 + ls%2 > A[v]) {
    puts("NO");
    exit(0);
  }

  LL mp = 0;
  if (maxa > s-maxamina) mp = s-maxamina-maxa;

  LL mp2 = s/2;
  if (2*maxb > s) mp2 = s - maxb;
  mp2 = A[v] - mp2;

  if (num_ch == 0) return make_pair(A[v], A[v]);
