		path[i].to = path[i + (n - 1)].from = arr[i].b;
		path[i].cost = path[i + (n - 1)].cost = 1;
	}
	dijk_init((n - 1) * 2, path);
	ull root = 0;
	for (i = 0; i < n; i++) {
		// printf("%llu: %llu\n", i, dist[i]);
		if (dp[root] < dp[i]) root = i;
	}

