		sll pass = a[v] * 2 - sum;
		sll ret = a[v] - pass;
		// printf("return: %lld, pass: %lld\n", ret, pass);
		if (ret < 0 || pass < 0) goto fail;

		sll returnlim = umin(sum / 2, sum - maxval);
		if (ret > returnlim) goto fail;

		dp[v] = pass;
	}

	if (dp[root]) goto fail;

	goto success;

