void addEdge(int u,int v){
	e[nume]=edge(v,g[u]);
	g[u]=nume++;
}

bool gao(LL t){
	while(t){
		LL x1=Q.top(); Q.pop();
		if(Q.empty()) return 0;
		LL x2=Q.top(); Q.pop();
		LL temp=min(x1,x2);
		t-=temp;
		x1-=temp; x2-=temp;
		if(t<=0) return 1;
	}
	return 1;
}

bool dfs(int x,int p){
	if(d[x]==1){
		delta[x]=a[x];
		return 1;
	}
	LL temp=0;
	while(!Q.empty()) Q.pop();
	for(int i=g[x];~i;i=e[i].next)
		if(e[i].to^p){
			if(!dfs(e[i].to,x)) return 0;
			temp+=delta[e[i].to];
			Q.push(delta[e[i].to]);
		}
	temp-=a[x];
	if(temp<0) return 0;
	if(!gao(temp)) return 0;
	delta[x]=a[x]-temp;
	return 1;
}

