#define TAM 100100

ll A[TAM];
vi G[TAM];

bool ok ( int i, int pi = -1 ) {
  if ( G[i].size() == 1 )
    return true;

  ll sum = 0, maxAj = 0;
  for ( int j : G[i] )
    if ( j != pi ) {
      if ( !ok(j, i) )
        return false;
      sum += A[j];
      maxAj = max ( maxAj, A[j] );
    }

  // x + A[i] = sum
  ll x = sum - A[i];

  if ( x < 0 || maxAj > A[i] )
    return false;

  A[i] -= x;
  return A[i] >= 0;
}

