vector<long long int>up;
vector<bool>flag;
bool can = true;

long long int Search(int num) {
	if (up[num] != -1) {
		return up[num];
	}
	if (edge[num].size() == 1) {
		up[num] = box[num];
		return up[num];
	}
	flag[num] = false;
	long long int sum = 0;
	long long int ma = 0;
	for (auto i : edge[num]) {
		if (flag[i]) {
			long long int fig = Search(i);
			sum += fig;
			ma = max(ma, fig);
		}
	}
	R = sum;
	L = max((sum + 1) / 2, ma);
	if (L > box[num] || R < box[num]) {
		can = false;
	}
	up[num] = box[num] * 2 - sum;
	if (up[num] < 0) {
		can = false;
	}
	return up[num];
}

