long long dfs(int id, int from) {
  if (c[id])
    return q[id];
  c[id] = true;
  if (p[id].size() == 1) {
    return q[id] = a[id];
  }
  long long sum = 0;
  for (int i = 0; i < p[id].size(); i++)
    if (p[id][i] != from)
      sum += dfs(p[id][i], id);
  long long b = sum - a[id];
  long long c = a[id] - b;
  if (b < 0 || c < 0) {
    return q[id] = -1000000000000ll;
  }
  long long mm = 0;
  for (int i = 0; i < p[id].size(); i++)
    mm = max(mm, dfs(p[id][i], id));
  if (mm > sum / 2) {
    if (sum - mm < b)
      return q[id] = -1000000000000ll;
  } else {
    if (sum / 2 < b)
      return q[id] = -1000000000000ll;
  }
  return q[id] = c;
}

