int N;
bool flag;
ll A[100000];
vector<int> G[100000];
int used[100000];

map<P, ll> dp;

ll dfs(P n) {
	if (dp[n]) {
		return dp[n] - 1;
	}
	int from = n.first, to = n.second;
	used[to] = 1;
	bool f = true;
	ll res = A[to] * 2;
	for (int v : G[to]) {
		if (used[v] == 0) {
			res -= dfs(P(to, v));
			f = false;
		}
	}
	if (res < 0) {
		flag = false;
	}
	if (f) {
		res /= 2;
	}
	used[to] = 0;
	dp[n] = res + 1;
	return res;
}


int main()
{
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	for (int i = 0, a, b; i < N - 1; i++) {
		cin >> a >> b;
		G[a - 1].push_back(b - 1);
		G[b - 1].push_back(a - 1);
	}
	flag = true;
	for (int i = 0; i < N; i++) {
		if (G[i].size() > 2) {
			ll sum = 0;
			for (int v : G[i]) {
				sum += A[v];
			}
			sum -= A[i] * 2;
			for (int v : G[i]) {
				if (A[v] > A[i]) {
					sum -= A[v] - A[i];
				}
			}
			if (sum < 0) {
				flag = false;
				break;
			}
		}
		else if (G[i].size() == 2 && (A[G[i][0]] < A[i] || A[G[i][1]] < A[i])) {
			flag = false;
			break;
		}
		else if (G[i].size() == 1 && A[G[i][0]] < A[i]) {
			flag = false;
			break;
		}
	}
	for (int i = 0; i < N; i++) {
		used[i] = 1;
		ll val = A[i] * 2;
		for (int v : G[i]) {
			val -= dfs(P(i, v));
		}
		used[i] = 0;
		if ((G[i].size() == 1 && val != A[i]) || (G[i].size() > 1 && val != 0)) {
			flag = false;
		}
	}
	cout << (flag ? "YES" : "NO") << endl;
	return 0;
}

