LL dfs(int u) {
//    DEBUG(u);
    visited[u] = 1;

    if (deg[u] == 1) {  // leaf
        return a[u];
    }
    else {
        LL chains = 0;
        for (auto& v : adj[u]) {
            if (!visited[v]) {
                chains += dfs(v);
            }
        }

        if (chains < 0 || chains < a[u]) ok = false;

        LL combine = 2 * (chains - a[u]);
        LL up = chains - combine;
        if (up < 0) ok = false;
        return up;
    }
}

