int stone[100010];

vector<int> ed[100010];

int par[100010];

void NO(){ puts("NO"); exit(0); }

int dfs(int x){
	if(ed[x].size() == 1u) return stone[x];
	multiset<int> ss;
	ll paths=0;
	for(int y:ed[x]) if(par[x]!=y){
		par[y]=x;
		ll tmp=dfs(y);
		ss.insert(tmp);
		paths += tmp;
	}
	ll pairs = paths-stone[x];
	if(pairs < 0) NO();
	if(paths - 2*pairs < 0) NO();
	ll mm=0;
	while(ss.size() >= 2u){
		ll a=*--ss.end();
		ll b=*--(--ss.end());
		if(b == 0) break;
		if(b > 2){
			ll tmp=b-2;
			a-=tmp; b-=tmp; mm+=tmp;
			ss.erase(--ss.end());
			ss.erase(--ss.end());
			ss.insert(a);
			ss.insert(b);
			continue;
		}
		++mm;
		ss.erase(--ss.end());
		ss.erase(--ss.end());
		ss.insert(a-1);
		ss.insert(b-1);
	}
	if(mm < pairs) NO();
	return paths - 2*pairs;
}

