ll dfs(int v, int f) {
    if (G[v].size() == 1) return a[v];
    ll sum = 0;
    vector<ll> V;
    for (int u : G[v]) if (u ^ f) {
        ll t = dfs(u, v);
        sum += t, V.push_back(t);
    }
    ll ub = sum - a[v];
    for (ll x : V) {
        ll t = min(x, sum - x);
        if (t + (sum - x - t) / 2 < ub &&
            (!t || t - 1 + (sum - x - t + 1) / 2 < ub)) printf("NO\n"), exit(0);
    }
    a[v] -= ub, sum -= ub * 2;
    if (sum < 0) printf("NO\n"), exit(0);
    if (!f && a[v]) printf("NO\n"), exit(0);
    a[v] -= sum;
    if (a[v]) printf("NO\n"), exit(0);
    return sum;
}

