int deg[N];

void DFS(int o, int f){
	if(deg[o] == 1){
		up[o] = val[o];
		return;
	}
	LL mx = 0, sum = 0;
	for(int v : G[o]){
		if(v == f) continue;
		DFS(v, o);
		sum += up[v];
		mx = max(mx, up[v]);
	}
	LL x = sum - val[o];
	//printf("%d: %d %lld %lld %lld\n", o, x, sum, val[o], mx);
	if(x > sum - mx || x < 0){
		puts("NO");
		exit(0);
	}
	up[o] = sum - 2 * x;
}

