		G[u].pb(v), G[v].pb(u);
		++deg[u], ++deg[v];
	}
	if(n == 2){
		puts(val[1] == val[2] ? "YES" : "NO");
		return 0;
	}
	int root = 0;
	For(i, 1, n) if(deg[i] ^ 1){
		root = i;
		break;
	}
	DFS(root, 0);
	puts(up[root] ? "NO" : "YES");
	return 0;
}

