long long dfs(const vector<vector<int>> &G, const vector<long long> &A, int v, int prev){
  //cerr << v << endl;
  if(G[v].size() == 1 and G[v][0] == prev) return A[v];
  vector<long long> B;
  long long s = 0;
  for(auto v_ : G[v]){
    if(v_ == prev) continue;
    long long t = dfs(G,A,v_,v);
    if(t < 0) return -1;
    B.push_back(t);
    s += t;
  }
  sort(B.begin(), B.end());
  long long d = s - A[v];
  if(d >= 0 and s - 2*d >= 0 and s - B.back() >= d) return s - 2*d;
  return -1;
}

