  while(que.size()){
    int p=que.front();que.pop();
    for(int q:edge[p]){
      if(parent[p]==q)continue;
      parent[q]=p;
      que.push(q);
    }
  }
  std::vector<int> son[N];
  for(int i=0;i<N;i++)for(int q:edge[i])if(parent[i]!=q)son[i].push_back(q);
  for(int i=0;i<N;i++)if(son[i].size()==0)que.push(i);
  std::vector<int> in(N,0);
  for(int i=0;i<N;i++)in[i]=son[i].size();
  while(que.size()){
    int p=que.front();que.pop();
    if(son[p].size()==0){
      if(--in[parent[p]]==0)que.push(parent[p]);
      continue;
    }
    if(son[p].size()==1){
      if(a[p]!=a[son[p][0]])fin("NO");
      if(p==0)fin("YES");
      if(--in[parent[p]]==0)que.push(parent[p]);
      continue;
    }
    int mx=0,sum=0;
    for(int q:son[p]){
      sum+=a[q];
      mx=max(mx,a[q]);
    }
    int B=(sum-a[p])*2;
    int A=sum-B/2;
    if(B<0)fin("NO");
    if(A+B<mx)fin("NO");
    a[p]-=B/2;
    if(p==0)fin("YES");
    if(--in[parent[p]]==0)que.push(parent[p]);
  }
}

