LL dfs(int v, int p) {
    if (a[v].size() == 1) return cnt[v];

    LL maxSz = 0, minSz = 0;
    multiset<LL> Set;
    for (int to: a[v]) {
        if (to == p) continue;
        LL s = dfs(to, v);
        Set.insert(s);
        maxSz += s;
    }
    LL curMax = *(--Set.end()), maxCnt = 1;
    LL max2 = 0;
    Set.erase(--Set.end());
    while (Set.size()) {
        while (Set.size() && curMax == *(--Set.end())) {
            maxCnt++;
            Set.erase(--Set.end());
        }
        if (!Set.size()) break;
        LL x = *(--Set.end());
        Set.erase(--Set.end());

        LL k = (maxCnt * (curMax - x) + max2);
        minSz += k / 2;
    //    printf("minSz=%lld maxCnt=%lld curMAx=%lld max2=%lld\n", minSz, maxCnt, curMax, max2);
        if (k % 2) {
            maxCnt = 1 + maxCnt - (max2 == 0);
            max2 = curMax;
        } else {
            maxCnt = 1 + maxCnt + (max2 != 0);
            max2 = 0;
        }
        curMax = x;

    }
//    cerr << v << endl;

    LL k = maxCnt * curMax + max2;
    minSz += k / 2;
    if (k % 2) minSz++;
   // printf("minSz=%lld maxCnt=%lld curMAx=%lld max2=%lld\n", minSz, maxCnt, curMax, max2);

    LL ret = 2 * cnt[v] - maxSz;
    //printf("v=%d minSz=%lld maxSz=%lld ret=%lld\n", v + 1, minSz, maxSz, ret);

    if (ret < 0 || cnt[v] < minSz || cnt[v] > maxSz || (v == p && ret != 0)) {
        puts("NO");
        exit(0);
    }
    return ret;
}

