  rep(i, edges[v].size()) {
    int w = edges[v][i];
    if (w == par) { continue; }
    ll sub = dfs(w, v);
    if (sub < 0) {
      return -1;
    }
    pool.push_back(sub);
    tot += sub;
  }
  ll rest = 0;
  if (par == -1) {
    if (pool.size() >= 2 && tot != 2 * a[v]) {
      return -1;
    }
    if (pool.size() == 1 && tot != a[v]) {
      return -1;
    }
  } else {
    rest = pool.size() >= 1 ? 2 * a[v] - tot : a[v];
    if (rest < 0) {
      return -1;
    }
    pool.push_back(rest);
  }
  sort(pool.rbegin(), pool.rend());
  if (pool.size() >= 2 && pool[0] > a[v]) {
    return -1;
  }
  if (pool.size() == 1) {
    if (pool[0] != a[v]) {
      return -1;
    }
    return a[v];
  }
  return rest;
}

