  rep(i, n) {
    cin >> a[i];
  }
  rep(i, n - 1) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  ll result = dfs(0, -1);
  cout << (result >= 0 ? "YES" : "NO") << endl;
}

