using namespace std;

Graph to_rooted_tree(const Graph &g, int root = 0) {
    int n = g.size();
    Graph res(n);
    constexpr Weight INF = std::numeric_limits<Weight>::max() / 2;
    std::vector<int> dist(n, INF);
    std::deque<std::pair<int, int>> to_visit; // fixme
    dist[root] = 0;
    to_visit.emplace_back(0, root);
    while (to_visit.size()) {
        Weight d; int v;
        std::tie(d, v) = to_visit.back(); // fixme
        to_visit.pop_back(); // fixme
        d = -d;
        for(auto &e : g[v]){
            if (dist[e.dst] > dist[v] + e.weight) {
                dist[e.dst] = dist[v] + e.weight;
                to_visit.emplace_back(dist[e.dst], e.dst); // fixme
                res[e.src].emplace_back(e);
            }
        }
    }
    return res;
}

