int dp[100010];
int dfs(int v) {
    if (g[v].size() == 0) {
        return a[v];
    } else if (g[v].size() == 1) {
        int c = g[v][0].dst;
        return dfs(c) == a[v] ? a[v] : -1;
    } else {
        int sum = 0;
        for (auto &e : g[v]) {
            int x = dfs(e.dst);
            dp[e.dst] = x;
            sum += x;
        }
        bool ok = true;
        for (auto &e : g[v]) {
            int c = e.dst;
            if (dp[c] < 0 || a[v] < dp[c]) {
                ok = false;
                break;
            }
        }
        int res = 2 * a[v] - sum;
        if (res < 0 || a[v] < res) {
            ok = false;
        }
        return ok ? res : -1;
    }
}

