typedef long long ll;

int N;
ll a[100005];
vector<int> g[100005];
vector<int> G[100005];

vector<int> T;
int root=-1;
int parent[100005];
ll dp[100005];

void init(int pos,int prev=-1){
  parent[pos]=prev;
  for(int to:g[pos]){
    if(to==prev)continue;
    G[pos].push_back(to);
    init(to,pos);
  }
  T.push_back(pos);
}

bool solve(){
  if(N==2)return (a[0]==a[1]);

  for(int i=0;i<N;i++)if(g[i].size()>1)root=i;
  init(root);

  for(int v:T){
    if(v==root){
      vector<ll> t;
      ll sum=0;
      for(int child:G[v]){
        sum+=dp[child];
        t.push_back(dp[child]);
      }
      sort(t.begin(),t.end());
      reverse(t.begin(),t.end());

      int match;
      if(t[0] > sum-t[0]){
        match=sum-t[0];
      }else{
        match=sum/2;
      }
      if(match*2==sum&&match==a[v])return true;
      else return false;
      continue;
    }

    if(G[v].size()==0){
      dp[v]=a[v];
      if(a[v]!=dp[v])return false;
      continue;
    }
    if(G[v].size()==1){
      dp[v]=dp[ G[v].back() ];
      if(a[v]!=dp[v])return false;
      continue;
    }

    vector<ll> t;
    ll sum=0;
    for(int child:G[v]){
      sum+=dp[child];
      t.push_back(dp[child]);
    }
    sort(t.begin(),t.end());
    reverse(t.begin(),t.end());

    int match;
    if(t[0] > sum-t[0]){
      match=sum-t[0];
    }else{
      match=sum/2;
    }

    ll M=sum-a[v];
    ll U=a[v]-M;
    if(M>match || U<0 || U>sum || M<0 || M*2>sum)return false;

    dp[v]=U;
  }

  return true;
}

