const int maxn = 1e5 + 5;

int n;
vector<int> e[maxn];
long long a[maxn];
bool dfs(int x, int fa) {
	if(e[x].size() == 1) return true;
	long long sum = 0, mx = 0;
	for(auto &it : e[x]) {
		int v = it;
		if(v == fa) continue;
		if(!dfs(v, x)) return false;
		sum += a[v];
		mx = max(mx, a[v]);
	}
	mx = min(sum - mx, sum / 2);
	long long tmp = sum - a[x];
	if(tmp < 0 || tmp > mx) return false;
	a[x] -= tmp;
	if(x == fa) return a[x] == 0;
	return true;
}
