	REPU(i, 0, n) cin >> a[i];
	MEM(d, 0);
	REPU(i, 1, n) {
		int x, y; cin >> x >> y;
		--x, --y;
		g[x].push_back(y);
		g[y].push_back(x);
		d[x]++; d[y]++;
	}
