typedef long long LL;
typedef long double LD;
#define MAXN 1000005

struct edge {
	int next, to;
} e[MAXN * 2];

int n, ecnt = 0;
int root, d[MAXN], head[MAXN];
void add(int u, int v) {
	d[u]++, d[v]++;
	e[++ecnt].to = v; e[ecnt].next = head[u]; head[u] = ecnt;
	e[++ecnt].to = u; e[ecnt].next = head[v]; head[v] = ecnt;
}
LL a[MAXN], tot[MAXN];


bool dfs(int x, int fa) {
	bool lf = 1;
	for (int now = head[x]; now; now = e[now].next) {
		if (e[now].to != fa) {
			lf = 0;
			if (dfs(e[now].to, x)) return 1;
			tot[x] += a[e[now].to];
		}
	}
	if (!lf) {
		if (tot[x] < a[x]) return 1;
		if (tot[x] > 2 * a[x]) return 1;
		LL ta = 2 * a[x] - tot[x], xx = 0;
		bool flag = 1;
		for (int now = head[x]; now; now = e[now].next) {
			if (e[now].to != fa) {
				LL hh = min (xx, a[e[now].to]);
				xx += a[e[now].to] - 2 * hh;
				ta -= hh;
				if (ta < 1) {flag = 1; break;}
			}
		}
		if (flag) a[x] = 2 * a[x] - tot[x];
		else return 1;
	}
	return 0;
}

