struct node{
	ll stones;
	vector<ll> below;
	set<node *> con;
	bool vis=false;
	void dfs(){
		if(res && con.size()<=1 && !vis){
			vis = true;
			sort(below.begin(), below.end());
			ll below_tot=0;
			for(int i = 0; i<(int)below.size() -1; ++i){
				below_tot += below[i];
			}
			ll min_above=0;
			if(!below.empty()){
				min_above = max(0LL, below.back()-below_tot);
				below_tot += below.back();
			}
			if(stones < below_tot){
				res = false;
				return;
			}
			ll above = 2*stones-below_tot;
			if(above < min_above){
				res = false;
				return;
			}
			if(con.size() == 1){
				(*con.begin())->below.push_back(above);
				(*con.begin())->con.erase(this);
				(*con.begin())->dfs();
			}
			else if(above != 0){
				res = false;
				return;
			}
		}
	}
};


