		scanf("%d", &a[i]);
	}
	forn(i, n - 1) {
		int v, u;
		scanf("%d%d", &v, &u);
		--v;
		--u;
		g[v].pb(u);
		g[u].pb(v);
	}
	return 1;
}

ll dfs(int v, int p) {
	if  (sz(g[v]) == 1) {
		return a[v];
	}

	// printf("in v=%d\n", v + 1);

	vll sons;
	ll sum = 0;
	for (int to : g[v]) {
		if (to == p) {
			continue;
		}

		ll x = dfs(to, v);
		// printf("to=%d, x=%lld\n", to + 1, x);
		if  (x == -1) {
			return -1;
		}
		sum += x;
		sons.pb(x);
	}

	ll up = 2 * a[v] - sum;
	if  (up < 0) {
		return -1;
	}

	sort(all(sons));
	if  (sz(sons) == 1) {
		if  (sons[0] != up) {
			return -1;
		}
		return up;
	}

	ll Up = up;

	ll neg = min(Up, sons.back() - sons[sz(sons) - 2]);
	sons.back() -= neg;
	Up -= neg;

	ll s = accumulate(all(sons), 0ll);

	if  (Up == 0) {
		if  (s & 1) {
			return -1;
		}
		s -= sons.back();
		if  (s < sons.back()) {
			return -1;
		}
		return up;
	}

	if  (s - Up >= 0 && (s - Up) % 2 == 0) {
		return up;
	}

	return -1;
}

bool solve() {
	int r = -1;
	forn(v, n) {
		if  (sz(g[v]) > 1) {
			r = v;
			break;
		}
	}

	// printf("r=%d\n", r + 1);

	if  (r == -1) {
		if  (n == 2) {
			return a[0] == a[1];
		} else {
			assert(0);
		}
	}

	ll up = dfs(r, -1);
	return up == 0;
}

