typedef long long LL;

#define sz 1000000

vector <int> a[sz];
int n, v, u, d[sz];

int dfs(int v, int pr = -1) {
	vector <int> g;
	for (int i = 0; i < a[v].size(); i++) {
		if (a[v][i] == pr) continue;
		g.pb(dfs(a[v][i], v));
	}
	if (a[v].size() == 1) {
		return d[v];
	}
	sort(g.begin(), g.end());
	LL res = 0, s = 0;
	for (int i = 0; i < g.size(); i++) {
		s += g[i];
	}
	LL x = g.back();
	s -= x;
	if (s < x) {
		LL p = (x - s);
		res += p;
		g[g.size() - 1] -= p;
		d[v] -= p;
	}

	if (s & 1) {
		s--;
		res++;
		d[v]--;
	}

	d[v] -= s / 2;
	if (d[v] < 0 || d[v] & 1) {
		cout << "NO";
		exit(0);
	}

	res += (d[v] * 2 - s);

	if (s < 0) {
		cout << "NO";
		exit(0);
	}

	return res;
}

