constexpr int Nmax = 100000;
int N;
vector<lint> A;
vector<int> to[Nmax];

void NO()
{
    puts("NO");
    exit(0);
}

vector<lint> dp;
lint dfs(int now, int prv)
{
    vector<lint> ch;
    for (auto nxt : to[now]) if (nxt != prv) ch.push_back(dfs(nxt, now));

    if (ch.size() == 0)
    {
        dp[now] = A[now];
        return dp[now];
    }
    sort(ch.begin(), ch.end());

    lint chsu = accumulate(ch.begin(), ch.end(), 0LL);
    dp[now] = 2 * A[now] - chsu;
    if (dp[now] < 0 || dp[now] < ch.back() * 2 - chsu) NO();
    return dp[now];
}

