int dfs(int v, int p) {
	vector<int> nex;
	for (int to : g[v]) {
		if (to == p) {
			continue;
		}
		nex.push_back(dfs(to, v));
	}
	if (nex.empty()) {
		return a[v];
	}
	int sum = 0, mx = 0;
	for (int x : nex) {
		sum += x;
		mx = max(mx, x);
	}
	if (sum < a[v]) {
		ANS = false;
		return 0;
	}
	int paired = sum - a[v];
	if (sum - mx < paired) {
		ANS = false;
		return 0;
	}
	return a[v] - paired;
}

