bool solve(int cur)
{
	seen[cur] = true;
	ll sum = 0;
	bool ans = true;
	int mx = 0;
	for (auto &i : g[cur])
	{
		if (!seen[i])
		{
			ans &= solve(i);
			sum += up[i];
			mx = max(mx, up[i]);
		}
	}

	if (!ans)
		return false;

	if (degree[cur] == 1)
	{
		up[cur] = a[cur];
		return true;
	}

	if (sum < a[cur] or 2*a[cur] < sum)
		return false;

	ll x = 2*sum - 2*a[cur];

