int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	int n; cin >> n;
	REPU(i, 0, n) cin >> a[i];
	MEM(d, 0);
	REPU(i, 1, n) {
		int x, y; cin >> x >> y;
		--x, --y;
		g[x].push_back(y);
		g[y].push_back(x);
		d[x]++; d[y]++;
	}
	queue<int> que;
	REPU(i, 0, n) if (d[i] == 1) {
		if (a[i] > 0) que.push(i);
	}
	while (!que.empty()) {
		int v = que.front(); que.pop();
		if (a[v] == -1 || d[v] != 1) continue;
		int nxt = -1;
		for (int u : g[v]) if (d[u] > 1) {
			nxt = u; break;
		}
		if (nxt == -1) continue;
		ll mx = -1, s = 0;
		int cnt = 0;
		for (int u : g[nxt]) if (d[u] == 1 && a[u] > 0) {
			amax(mx, a[u]);
			s += a[u];
			cnt++;
		}
		if (cnt == 1 && s != a[nxt]) {
			puts("NO"); return 0;
		}
		ll go_in = s - a[nxt];
		ll go_out = 2 * a[nxt] - s;
		if (go_in < 0 || go_out < 0 || mx > a[nxt]) {
			puts("NO"); return 0;
		}
		a[nxt] = go_out;
		d[nxt] = 1;
		for (int u : g[nxt]) if (d[u] == 1) {
			a[u] = -1;
			d[u] = 0;
		}
		if (a[nxt] > 0) que.push(nxt);
	}
	vector<ll> rem;
	REPU(i, 0, n) if (a[i] > 0) {
		rem.push_back(a[i]);
	}
	assert(rem.size() == 0 || rem.size() == 2);
	if (rem.size() == 0) {
		puts("YES");
	}
	else {
		if (rem[0] == rem[1]) {
			puts("YES");
		}
		else {
			puts("NO");
		}
	}

	return 0;
}

