map<P, ll> dp;

ll dfs(P n) {
	if (dp[n]) {
		return dp[n] - 1;
	}
	int from = n.first, to = n.second;
	used[to] = 1;
	bool f = true;
	ll res = A[to] * 2;
	for (int v : G[to]) {
		if (used[v] == 0) {
			res -= dfs(P(to, v));
			f = false;
		}
	}
	if (res < 0) {
		flag = false;
	}
	if (f) {
		res /= 2;
	}
	used[to] = 0;
	dp[n] = res + 1;
	return res;
}


