  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    ll tmp = dfs(G[now][i], now);
    s += tmp, m = min(m, tmp);
  }
  ll T, L, K;
  if(now==root) {
    out(s%2==0&&s/2==a[now]);
    return -1;
  }else{
    T = 2*a[now]-s, L = (s - T)/2, K = max(m, s/2);
    if(T<0||L>K) out(0);
  }
  return th[now] = T;
}

int main(int argc, char const *argv[]) {
  ll x, y, n;std::cin >> n;
  rep(i, 1, n+1) std::cin >> a[i];
  re(i, n-1){
    std::cin >> x >> y;
    G[x].push_back(y);
    G[y].push_back(x);
  }
  if(n==2) out(a[1]==a[2]);
  for(int i=1;i<=n;i++) if(G[i].size()!=1) root = i;
  dfs(root, -1);
  out(1);
  return 0;
}

