int vis[N],ds[N],ff;
LL a[N],ct[N];
void addedge(int x,int y)
{
    bs++;v[bs]=y;nxt[bs]=point[x];point[x]=bs;
    bs++;v[bs]=x;nxt[bs]=point[y];point[y]=bs;
}
void dfs(int x)
{
    if (ds[x]==1) {vis[x]=1;ct[x]=a[x];return;}
    int p;LL sum=0,R,mx;vis[x]=1;
    for (p=point[x];p;p=nxt[p])
     if (!vis[v[p]])
     {
            dfs(v[p]);if (ff) return;
            sum+=ct[v[p]];mx=max(mx,ct[v[p]]);
     }
    R=sum-a[x];if (R<0) ff=1;
    ct[x]=sum-2*R;if (ct[x]<0) ff=1;
    if (sum-mx<R) ff=1;
}
