  cin >> n;
  for (int i = 0; i < n; ++i) cin >> p[i];
  for (int i = 1; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  cout << (sub() ? "YES" : "NO") << endl;
  return 0;
}

