int dfs(int now, int pre, vector<int64> const& A, vector<vector<int>> const& edge){
    if(edge[now].size() == 1 and pre!=-1){
        return A[now];
    }

    vector<int64> child;
    for(auto to:edge[now]){
        if(pre==to) continue;
        // debug(now)
        // debug(mp(to,ans));
        child.emplace_back(dfs(to,now,A,edge));
    }

    // debug(mp(now,child))
    int64 max_ = *max_element(ALL(child));
    int64 sum_ = accumulate(ALL(child), 0LL);
    // debug(max_-(sum_-max_))
    // debug(sum_-max_)
    // debug(A[now])
    int64 can = (sum_ - max(0LL, max_-(sum_-max_))) / 2;
    if(sum_< A[now]) ans = false;
    if(A[now] < can) ans=false;
    // debug(mp(sum_,can))
    // debug(ans)
    return A[now] - (sum_ - A[now]);
}

