const int N = 1000010;

struct edge{
	int next, to;
	ll w;
};

edge e[N << 1];
int n, deg[N], first[N], e_cnt = 1;
ll a[N];
__int128 orz[N];

void addedge(int u, int v){
	e[++ e_cnt] = {first[u], v};
	first[u] = e_cnt;
	e[++ e_cnt] = {first[v], u};
	first[v] = e_cnt;
}

void dfs(int i, int fa){
	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		++ deg[i];
		if (x != fa){
			dfs(x, i);
		}
	}
}

void solve(int i, int fa){
	for (int j = first[i]; j; j = e[j].next){
		int x = e[j].to;
		if (x == fa){
			continue;
		}
		solve(x, i);
		if (deg[x] > 1){
			e[j].w = e[j ^ 1].w = 2 * a[x] - orz[x];
		}
		else{
			e[j].w = e[j ^ 1].w = a[x] - orz[x];
		}
		if (e[j].w < 0){
			printf("NO\n");
			exit(0);
		}
		orz[i] += e[j].w;
	}
	if (deg[i] > 1){
		for (int j = first[i]; j; j = e[j].next){
			int x = e[j].to;
			if (e[j].w > a[i]){
				printf("NO\n");
				exit(0);
			}
		}
	}
}

