		scanf("%d%d", &u, &v);
		addedge(u, v);
	}
	if (n == 2){
		return printf(a[1] == a[2] ? "YES\n" : "NO\n"), 0;
	}
	dfs(1, 0);
	for (int i = 1; i <= n; ++ i){
