int solve(int now, int back) {
	if (back != 0&&vertexs[now].size() == 1) return stones[now];
	vector<int> solve_ston;
	for (int i = 0;i < vertexs[now].size();++i) {
		if (vertexs[now][i] != back) {
			solve_ston.push_back(solve(vertexs[now][i], now));
		}
	}
	int nya = 0;
	int wa = 0;
	for (int i = 0;i < solve_ston.size();++i) {
		wa += solve_ston[i];
		for (int q = i + 1;q < solve_ston.size();++q) {
			if (solve_ston[i] < solve_ston[q]) {
				solve_ston[q] -= solve_ston[i];
				solve_ston[i] = 0;
				break;
			}
			else {
				solve_ston[i] -= solve_ston[q];
				solve_ston[q] = 0;
			}
		}
		nya += solve_ston[i];
	}
	wa -= nya;
	wa *= 2;
	wa += nya;
	if (wa != stones[now]) can_do = false;
	if (nya > stones[back]) can_do = false;
	return stones[back];
}
