const int N = 100005;
ll a[N];
int d[N];
vector<int> g[N];

int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	int n; cin >> n;
	REPU(i, 0, n) cin >> a[i];
	MEM(d, 0);
	REPU(i, 1, n) {
		int x, y; cin >> x >> y;
		--x, --y;
		g[x].push_back(y);
		g[y].push_back(x);
		d[x]++; d[y]++;
	}
	queue<int> que;
	REPU(i, 0, n) if (g[i].size() == 1) {
		que.push(i);
	}
	while (!que.empty()) {
		int v = que.front(); que.pop();
		if (a[v] == -1) continue;
		int nxt = -1;
		for (int u : g[v]) if (d[u] > 1) {
			nxt = u; break;
		}
		if (nxt == -1) continue;
		ll mx = -1, s = 0;
		for (int u : g[nxt]) if (d[u] == 1) {
			amax(mx, a[u]);
			s += a[u];
		}
		ll go_in = s - a[nxt];
		ll go_out = 2 * a[nxt] - s;
		if (go_in < 0 || go_out < 0 || mx > a[nxt]) {
			puts("NO"); return 0;
		}
		a[nxt] = go_out;
		d[nxt] = 1;
		for (int u : g[nxt]) if (d[u] == 1) {
			a[u] = -1;
			d[u] = 0;
		}
		que.push(nxt);
	}
	sort(a, a + n);
	reverse(a, a + n);
	if (a[0] <= 0) puts("YES");
	else if (a[0] > 0 && a[1] > 0 && a[0] == a[1]) puts("YES");
	else puts("NO");

	return 0;
}

#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<ll,ll> pii;

int N;
ll A[100010];
ll U[100010];
int par[100010];
vector<pii> mem;
vector<int> G[100010];
bool visit[100010] = {0};
int root;

void DFS(int v,int p,int d)
{
    if(visit[v])return;
    visit[v] = true;
    par[v] = p;
    mem.push_back(make_pair(d,v));
    for(int i = 0; i < G[v].size(); i++)if(G[v][i] != p)DFS(G[v][i],v,d + 1);
    return;
}

int main()
{
    scanf("%d",&N);
    for(int i = 0; i < N; i++)scanf("%lld",A + i + 1);
    for(int i = 0; i < N - 1; i++)
    {
        int a,b;
        scanf("%d%d",&a,&b);
        G[a].push_back(b);
        G[b].push_back(a);
    }
    for(int i = 1; i <= N; i++)
    {
        if(G[i].size() > 1)
        {
            root = i;
            DFS(i,-1,0);
            break;
        }
    }
    sort(mem.begin(),mem.end());
    reverse(mem.begin(),mem.end());
    for(int i = 0; i < N; i++)
    {
        int v = mem[i].second;
        if(G[v].size() == 1)
        {
            U[v] = A[v];
            continue;
        }
        ll sum = 0,MAX = 0;
        for(int i = 0; i < G[v].size(); i++)
        {
            if(par[v] == G[v][i])continue;
            sum += U[G[v][i]];
            MAX = max(MAX,U[G[v][i]]);
        }
        if(A[v] * 2 < sum || min(sum - MAX,sum / 2) < sum - A[v])U[v] = -1;
        else U[v] = A[v] * 2 - sum;
    }
    if(N == 2)
    {
        if(A[1] == A[2])printf("YES\n");
        else printf("NO\n");
    }
    else
    {
        if(U[root] == 0)printf("YES\n");
        else printf("NO\n");
    }
    return 0;
}

