bool DFS(int u,int fa)
{
	LL sum=0;
	bool Enter=false;
	for(int i=0;i<(int)G[u].size();i++)
	{
		int v=G[u][i];
		if(v==fa)
			continue;
		Enter=true;
		if(DFS(v,u)==false)
			return false;
		sum+=a[v];
		maxval[u]=max(maxval[u],a[v]);
	}
	if(Enter==false)
	{
		maxval[u]=a[u];
		return true;
	}
	if(2LL*a[u]<sum||a[u]>sum||a[u]<maxval[u])
		return false;
	a[u]=2*a[u]-sum;
	return true;
}
