#include<bits/stdc++.h>
using namespace std;
typedef long long int ll;
typedef vector<int> vi;
typedef pair<ll,ll> ii;
vector<vi> graph;
vector<ll> val;
vi deg;
vector<ll> sum;
vi check_leaf;
map<ii,ll> edge;
int main()
{
	int n,i;ll x,y;
	scanf("%d",&n);
	graph.assign(n+1,vi());
	val.assign(n+1,0ll);
	deg.assign(n+1,0);
	for(i=1;i<=n;++i)
	{
		scanf("%lld",&val[i]);
	}
	for(i=1;i<n;++i)
	{
		scanf("%d %d",&x,&y);
		graph[x].push_back(y);
		graph[y].push_back(x);
		deg[x]++;deg[y]++;
	}
	if(n==2)
	{
		if(val[1] == val[2])
		{
			printf("YES");
		}
		else	printf("NO");
		return 0;
	}
	check_leaf.assign(n+1,0);
	for(i=1;i<=n;++i)
	{
		if(deg[i]==1)
		check_leaf[i] = 1;
	}
	priority_queue<ii,vector<ii>,greater<ii> > pq;
	for(i=1;i<=n;++i)
	{
		pq.push(ii(deg[i],i));
	}
	sum.assign(n+1,0);
	while(!pq.empty())
	{
		ii l = pq.top();pq.pop();
		x = l.first;
		y = l.second;
		if(x==deg[y])
		{
			for(auto i : graph[y])
			{
				if(deg[i] != 0)
				{
					int up;
					if(check_leaf[y] == 1)
					{
						up = val[y];
					}
					else
					{
						up = 2*val[y] - sum[y];
					}
					edge[ii(min((ll)i,y),max((ll)i,y))] = up;
					deg[i]--;
					deg[y]--;
					if(up<0)
					{
						printf("NO");
						return 0;
					}
					sum[i] += up;
					if(deg[i]!=0)
					{
						pq.push(ii(deg[i],i));
					}
				}
			}
		}
	}
//	for(auto i : edge)
//	{
//		printf("%d %d %d\n",i.first.first,i.first.second,i.second);
//	}
	for(i=1;i<=n;++i)
	{
		if(check_leaf[i] == 0)
		{
			ll s = 0ll;
			for(auto j : graph[i])
			{
				int v = edge[ii(min(i,j),max(i,j))];
				s += v;
				if(v > val[i])
				{
					printf("NO");
					return 0;
				}
			}
			if(s != val[i] *2)	
			{
				printf("NO");
				return 0;
			}
		}
		else
		{
			ll s = 0ll;
			for(auto j:graph[i])
			{
				int v = edge[ii(min(i,j),max(i,j))];
				if(v > val[i])
				{
					printf("NO");
					return 0;
				}
			}	
			if(s != val[i])
			{
				printf("NO");
				return 0;
			}
		}
	}
	printf("YES");
}

