const ll MOD=1e9+7;

int N;
LL A[114514];
vector<int> es[114514];

pair<LL, LL> dfs(int v, int p) {
  int num_ch = 0;
  LL l = 0;
  LL r = 0;
  LL s = 0;
  LL ls = 0;
  LL maxa = -1;
  LL maxb = -1;
  LL maxamina = 0x7fffffffffLL;
  for (int u : es[v]) {
    if (p == u) continue;
    LL x, y;
    tie(x, y) = dfs(u, v);
    s += y;
    ls += x;
    maxa = max(maxa, x);
    if (maxa == x) {
      maxamina = min(maxamina, y);
    }
    maxb = max(maxb, y);
    LL nr = y+r;
    LL nl = max(0LL, max(x, l) - min(y, r));
    l = nl;
    r = nr;
    num_ch++;
  }

  if (ls/2 + ls%2 > A[v]) {
    puts("NO");
    exit(0);
  }

  LL mp = 0;
  if (maxa > s-maxamina) mp = s-maxamina-maxa;

  LL mp2 = s/2;
  if (2*maxb > s) mp2 = s - maxb;
  mp2 = A[v] - mp2;

  if (num_ch == 0) return make_pair(A[v], A[v]);
  if (num_ch == 1) {
    if (l <= A[v] && A[v] <= r) return make_pair(A[v], A[v]);
    puts("NO");
    exit(0);
  }
  return make_pair(max(l, max(mp2, mp)), min(r, A[v]));
}

int main() {
  scanf("%d", &N);
  rep(i, N) {
    scanf("%lld", &A[i]);
  }

  rep(i, N-1) {
    int u, v;
    scanf("%d%d", &u, &v);
    --u;
    --v;
    es[u].eb(v);
    es[v].eb(u);
  }

  int cnt = 0;
  rep(v, N) {
    if (es[v].size() > 1) {
      cnt++;
      if (dfs(v, v).first != 0) {
        puts("NO");
        exit(0);
      }

      if (cnt > 3) {
        puts("YES");
        exit(0);
      }
    }
  }

  if (N > 2) {
    puts("YES");
    exit(0);
  }

  assert(N == 2);
  if (A[0] == A[1]) puts("YES");
  else puts("NO");
}

