const int mod=1000000007,MAX=100005,INF=1<<30;

vector<int> rem(MAX),seen(MAX),G[MAX];

bool ok=true;

void DFS(int u,int p){

    if(G[u].size()==1){
        seen[u]=1;
        return;
    }

    int sum=0,maxi=0;

    for(int i=0;i<G[u].size();i++){
        int a=G[u][i];
        if(a==p) continue;

        if(!seen[a]) DFS(a,u);
        sum+=rem[a];
        maxi=max(rem[a],maxi);
        rem[a]=0;
    }

    int x=sum-rem[u];
    if(x<0) ok=false;
    if(x>sum-maxi) x=sum-maxi;
    rem[u]-=x;
    seen[u]=1;
    return;
}

