        a--;b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    if(N==2){
        if(rem[0]==rem[1]) cout<<"YES"<<endl;
        else cout<<"NO"<<endl;
    }else{

        for(int i=0;i<N;i++){
            if(G[i].size()>=2){
                DFS(i,-1);
                break;
            }
        }
