ll f(int v, int p) {
  if (!ans) return 0;
  ll T = 0;
  if (p != -1 && g[v].size() == 1) {
    T = A[v];
  } else {
    ll L = 0;
    vector<ll> c;
    for (int u : g[v]) if (u != p) {
      ll ci = f(u, v);
      L += ci;
      c.push_back(ci);
    }
    T = 2 * A[v] - L;
    if (T < 0 || T > A[v]) { ans = false; }
