using i64=int64_t;

void solve(){
    i64 n;
    cin >> n;
    vector<i64> a(n);
    rep(i,0,n) cin >> a[i];
    vector<vector<int>> graph(n);
    rep(i,0,n-1){
        i64 a,b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if(n==2){
        if(a[0]==a[1]) cout << "YES" << endl;
        else cout << "NO" << endl;
        return;
    }

    vector<i64> r(n);
    function<bool(int,int)> rec=[&](int u,int p){
        if(graph[u].size()<=2 and p!=-1) return true;
        r[u]=-a[u];
        for(int v:graph[u]){
            if(v==p) continue;
            if(!rec(v,u)) return false;
            r[u]+=a[v]-r[v];
        }
        return (0<=r[u] and r[u]<=a[u]);
    };

    rep(i,0,n){
        if(graph[i].size()<2) continue;
        if(rec(0,-1)) cout << "YES" << endl;
        else cout << "NO" << endl;
        return;
    }
}

