#include <bits/stdc++.h>

using namespace std;

const int N = 1234567;
const int inf = (int) 1e9;

int n;
int a[N];
int f[N];
vector<int> g[N];

bool dfs(int v, int pv, int r) {
  int sum = 0;
  for (int to : g[v]) {
    if (to == pv) {
      continue;
    }
    if (!dfs(to, v, r)) {
      return false;
    }
    sum += f[to];
  }
  if ((int) g[v].size() == 1) {
    f[v] = a[v] - sum;
  } else {
    f[v] = 2 * a[v] - sum;
  }
  if (f[v] < 0 || sum < a[v]) {
    return false;
  }
  return true;
}

bool ok() {
  int sum_a = 0;
  vector<int> all;
  for (int i = 0; i < n; i++) {
    if ((int) g[i].size() == 1) {
      sum_a += f[i];
      all.push_back(f[i]);
    }
  }
  if (sum_a % 2) {
    return false;
  }
  for (auto& x : all) {
    if (x + x > sum_a) {
      return false;
    }
  }
  return true;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);                	
  cin >> n;
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    f[i] = a[i];
  }
  for (int i = 0; i + 1 < n; i++) {
    int x, y;
    cin >> x >> y;
    x--; y--;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  for (int i = 0; i < n; i++) {
    if ((int) g[i].size() > 1) {
      if (dfs(i, -1, i) && ok()) {
        cout << "YES\n";
      } else {
        cout << "NO\n";
      }
      return 0;
    }
  }
  if (n <= 2) {
    if (a[0] == a[1]) {
      cout << "YES\n";
    } else {
      cout << "NO\n";
    }
    return 0;
  }
  assert(false);
  return 0;
}

