using namespace std;
typedef long long ll;

int main(void) {
  ll N;
  cin >> N;
  vector<ll> A(N);
  REP(i, 0, N) cin >> A[i];
  vector< vector<ll> > E(N);
  REP(i, 0, N - 1) {
    ll A, B;
    cin >> A >> B; A--; B--;
    E[A].push_back(B);
    E[B].push_back(A);
  }

  if(N == 2) cout << "YES" << endl;

  bool ok = true;
  function<ll (ll, ll)> dfs = [&](ll v, ll p) {
    if(E[v].size() <= 1 && p != -1) return A[v];
    ll sum = 0;
    for(ll u : E[v]) if(u != p) {
      ll c = dfs(u, v);
      ok = ok && 0 <= c && c <= A[v];
      sum += c;
    }
    ll t = A[v] * 2 - sum;
    ok = ok && (0 <= t && t <= A[v]);
    return t;
  };

  ll v;
  REP(i, 0, N) if(E[i].size() >= 2) v = i;
  cout << (dfs(v, -1) == 0 ? "YES" : "NO") << endl;
}

