const int INF = 1e18 + 239;

int smul(int a, int b) {
	if (a == 0 || b == 0) return 0;
	if (a > INF / b) return INF;
	else return min(INF, a * b);
}

int sadd(int a, int b) {
	return min(a + b, INF);
}

int a[N];
vector<int> g[N];

int dfs(int cur, int p) {
	int sm = 0;
	vector<int> sn;
	for (auto t : g[cur]) {
		if (t != p) {
			int v = dfs(t, cur);
			sm += v;
			sn.push_back(v);
		}
	}
	if (sn.empty()) {
		return a[cur];
	}
	int tot = 0;
	for (auto t : sn) {
		tot = sadd(tot, smul(t, sm - t));
		// tot += t * (sm - t);
	}
	tot /= 2;
	int P = sm - a[cur];
	if (P < 0 || P > tot) {
		cout << "NO\n";
		exit(0);
	}
	return sm - 2 * P;
}

