ll dfs(int s, int p) {

    if(g[s].size() == 1) {
        return A[s];
    }

    ll sum = 0;
    vector<ll> help;
    for(auto &v: g[s]) {
        if(v == p) continue;

        if(not possible) return 0;
        ll temp = dfs(v, s);
        sum += temp;
        help.pb(temp);
    }

    if(help.size() == 1) {
        if(help[0] != A[s]) {
            possible = false;
            return 0;
        }

        return help[0];
    }

    sort(help.begin(), help.end());

    ll maxp = 0;
    // find maximum #of pairs in help
    if(sum/2 < help[help.size()-1]) {
        maxp = sum - help[help.size()-1];
    } else {
        maxp = sum/2;
    }

    int f = 0, l = maxp, mid = (maxp)/2;
    while(f <= l) {
        ll x = mid;
        ll y = sum-2*mid;

        if(x+y == A[s]) {
            return y;
        }

        if(x+y > A[s]) {
            f = mid+1;
        } else {
            l = mid-1;
        }

        mid = (f+l)/2;
    }

    possible = false;
    return 0;
}

