struct res dfs(int n,int parent){
  LL total=0;
  int count=0;
  struct res ans;
  bool ok=true;
  // cout << n << endl;
  list<LL> l;
  for(auto itr=e[n].begin();itr!=e[n].end();itr++){
    if((*itr)!=parent){
      ans=dfs((*itr),n);
      l.push_back(ans.num);
      total+=ans.num;
      ok=ok&&ans.ok;
      count++;
    }
  }
  if(count==0){
    return {a[n],0,true};
  }else if(count==1){
    return {a[n],1,ok&&(total==a[n])};
  }else{
    for(auto itr=l.begin();itr!=l.end();itr++){
      if((*itr)*2>total) ok=false;
    }
    return {2*a[n]-total,2,ok&&(2*a[n]-total>=0&&total-a[n]>=0)};
  }
}

