int64 dfs(int v, int p) {
    if (tree[v].size() == 1) {
        return A[v];
    }
    int64 sum = 0,
          max_c = 0;

    for (int to : tree[v]) {
        if (to == p) continue;
        int64 child = dfs(to, v);
