        int a, b;
        cin >> a >> b;
        a--;
        b--;
        adj[a].push_back(make_pair(b, i));
        adj[b].push_back(make_pair(a, i));
    }

    long long label_0 = make_edge_label(0);
    if(adj[0].size() == 1){
        if(label_0 != A[0]){
            cout << "NO" << endl;
            return 0;
        }
    }else{
        if(label_0 != 2 * A[0]){
