}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn = 100010;
int n; ll a[maxn];
vector<int> G[maxn];

ll dfs(int v, int f) {
    if (G[v].size() == 1) return a[v];
    ll sum = 0;
    vector<ll> V;
    for (int u : G[v]) if (u ^ f) {
        ll t = dfs(u, v);
        assert(t >= 0);
        sum += t, V.push_back(t);
    }
    ll ub = sum - a[v];
    for (ll x : V) {
        ll t = min(x, sum - x);
        if (t + (sum - x - t) / 2 < ub) printf("NO\n"), exit(0);
    }
    a[v] -= ub, sum -= ub * 2;
    if (a[v] < 0 || sum < 0) printf("NO\n"), exit(0);
    if (!f && sum) printf("NO\n"), exit(0);
    if (!f && a[v]) printf("NO\n"), exit(0);
    a[v] -= sum;
    if (a[v]) printf("NO\n"), exit(0);
    return sum;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
    }
    if (n == 2) {
        printf("%s\n", a[1] == a[2] ? "YES" : "NO"), exit(0);
    }
    for (int i = 1, u, v; i < n; i++) {
        scanf("%d %d", &u, &v);
        G[u].push_back(v), G[v].push_back(u);
    }
    for (int i = 1; i <= n; i++) {
        if (G[i].size() > 1) { dfs(i, 0); break; }
    }
    printf("YES\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 1e5 + 7;

ll a[N];
vector<int> adj[N];
bool flag = true;

void dfs(int v, int p)
{
	ll sum = 0;
	int find = 0;
	for (auto u : adj[v])
	{
		if (u == p)
			continue;
		dfs(u, v);
		find++;
		sum += a[u];
	}
	if (find > 1)
	{
		if (sum < a[v] || sum > 2 * a[v])
			flag = false;
		a[v] = 2 * a[v] - sum;
	}
	else if (find == 1)
	{
		if (a[v] != sum)
			flag = false;
	}
	//cout << v << " ~ " <<  a[v] << "\n";
}

int main()
{
	int n;
	cin >> n;
	for (int i=0; i<n; i++)
		cin >> a[i];
	for (int i=1; i<n; i++)
	{
		int u, v;
		cin >> u >> v;
		u--, v--;
		adj[v].push_back(u);
		adj[u].push_back(v);
	}
	if (n == 2)
	{
		cout << (a[0] == a[1] ? "YES\n" : "NO\n") << "\n";
		return 0;
	}
	int v = 0;
	for (int i=0; i<n; i++)
		if ((int)adj[i].size() > 1)
		{
			v = i;
			dfs(i, -1);
			break;
		}
	if (a[v] || !flag)
		cout << "NO\n";
	else
		cout << "YES\n";
}

