#define iter(i, n) for (int i = 1; i <= n; ++i)
#define NR 101000

vector<int> e[NR];
int n, a[NR], d[NR];
bool valid = true;

int dfs(int x, int fa) {
	if (d[x] == 1) {
		return a[x];
	}
	priority_queue<int> q;
	int sum = 0;
	for (int v : e[x]) if (v != fa) {
		int tmp = dfs(v, x);
		if (tmp != 0) q.push(tmp);
		sum += tmp;
	}
	if (a[x] > sum) { valid = false; return 0; }
	int delta = sum - a[x];
	iter(i, delta) {
		if (q.size() < 2) { valid = false; return 0; }
		int i0 = q.top(); q.pop();
		int i1 = q.top(); q.pop();
		--i0, --i1;
		if (i0 != 0) q.push(i0);
		if (i1 != 0) q.push(i1);
		sum -= 2;
	}
	//printf("!%d %d\n", x, sum);
	return sum;
}

int main() {
	scanf("%d", &n);
	iter(i, n) scanf("%d", &a[i]);
	iter(i, n - 1) {
		int x, y;
		scanf("%d%d", &x, &y);
		e[x].push_back(y);
		e[y].push_back(x);
		++d[x], ++d[y];
	}
	int root;	
	iter(i, n) if (d[i] != 1) root = i;
	if (dfs(root, 0) != 0 || !valid) puts("NO");
	else puts("YES");
	return 0;
}

