#include <bits/stdc++.h>
using namespace std;
const int maxn = 100500;
int n = 0, hav[maxn], fir[maxn], nxt[maxn << 1], to[maxn << 1];
int fa[maxn], son[maxn], bro[maxn], rez[maxn];
int dis[maxn], root = 0;
void dfstree(int x)
{
	for(int l = fir[x]; l; l = nxt[l])
	{
		int y = to[l];
		if(y == fa[x]) continue;
		fa[y] = x, bro[y] = son[x], son[x] = y;
		dfstree(y);
	}
}
bool sol(int x)
{
	if(dis[x] == 1)
	{
		rez[x] = hav[x];
		return true;
	}
	int s = 0, w = 0;
	for(int y = son[x]; y; y = bro[y])
	{
		if(not sol(y)) return false;
		s += rez[y], w = max(w, rez[y]);
	}
	if(s < hav[x]) return false;
	if(w <= s - w)
	{
		if((s >> 1) + (s & 1) > hav[x]) return false;
		rez[x] = (hav[x] << 1) - s; return true;
	}
	else
	{
		if(w > hav[x]) return false;
		rez[x] = (hav[x] << 1) - s; return true;
	}
}
signed main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; i++) scanf("%d", hav + i);
	if(n == 2)
	{
		puts(hav[1] == hav[2]? "YES": "NO");
		return 0;
	}
	for(int i = 1, j = 0; i < n; i++)
	{
		int a = 0, b = 0;
		scanf("%d%d", &a, &b);
		j++, nxt[j] = fir[a], fir[a] = j, to[j] = b;
		j++, nxt[j] = fir[b], fir[b] = j, to[j] = a;
		dis[a]++, dis[b]++;
	}
	for(int i = 1; i <= n; i++)
		if(dis[i] > 1) { root = i; break; }
	dfstree(root);
	puts(sol(root) && rez[root] == 0? "YES": "NO");
	return 0;
}

#include <cstdio>
#include <algorithm>

using namespace std;
typedef long long LL;

const int N=1e5+10;

struct Edge{ int to,next;} way[N<<1];

int n,A[N],num[N],tot,d[N];
LL val[N];

void Build(int a,int b) { way[++tot]=(Edge){b,num[a]}; num[a]=tot; }

void Init()
{
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%d",&A[i]);
	int a,b;
	for (int i=2;i<=n;++i)
	{
		scanf("%d%d",&a,&b);
		Build(a,b); Build(b,a);
		d[a]++; d[b]++;
	}
}

bool Dfs(int x,int fa)
{
	if (d[x]==1) { val[x]=A[x]; return 1; }
	LL sum=0,Mx=0;
	for (int i=num[x];i;i=way[i].next)
	{
		int v=way[i].to;
		if (v==fa) continue;
		if (!Dfs(v,x)) return 0; 
		sum+=val[v]; Mx=max(Mx,val[v]);
	}
	if (A[x]>sum) return 0;
	LL need=sum-A[x],now=0;
	if (Mx>sum-Mx) now=sum-Mx;else now=sum/2;
	if (now>=need) val[x]=A[x]-need;
	else return 0;
	return 1;
}

void Solve()
{
	if (n==2) 
	{ 
		if (A[1]==A[2]) printf("YES\n");
		else printf("NO\n");
		return ; 
	}
	int root=0;
	for (int i=1;i<=n;++i) if (d[i]>1) { root=i; break; }
	bool fl=Dfs(root,0);
	if (val[root]) fl=0;
	if (fl) printf("YES\n");
	else printf("NO\n");
}

int main()
{
	Init();
	Solve();
	return 0;
}

