void dfs(int v, int par = -1){
	if (t[v].size() == 1 and par != -1)
		return;
	ll maxb = 0;
	for (auto u : t[v]){
		if (u != par){
			dfs(u, v);
			b[v] += a[u];
			maxb = max(maxb, a[u]);
		}
	}
	if (b[v] < a[v]){
		cout << "NO" << endl;
		exit(0);
	}
	a[v] = 2ll * a[v] - b[v];
	if (a[v] < 0 or a[v] > b[v]){
		cout << "NO" << endl;
		exit(0);
	}
	int maximum_matching = 0;
	if (2ll * maxb >= b[v])
		maximum_matching = b[v] / 2;
	else
