class no_solution: public std::exception
{
public:
	no_solution()
	{
	}

	const char * what() const noexcept
	{
		return "no solution under such constrains";
	}
};

inline void addEdge(int u, int v)
{
	Adj[u].push_back(v);
	Adj[v].push_back(u);
}

int DFS(int cur, int pre)
{
	if(Adj[cur].size() == 1)
		return A[cur];

	i64 sum = 0;
	int tmp, mx = 0;

	for(int to : Adj[cur])
	{
		if(to == pre)
			continue;
		tmp = DFS(to, cur);

		mx = max(mx, tmp);
		sum += tmp;
	}

	if(pre == 0)
	{
		if(sum % 2)
			throw no_solution();
		if(mx > sum / 2)
			throw no_solution();
		if(A[cur] != sum / 2)
			throw no_solution();
		return 0;
	}

	i64 delta = sum - A[cur];
	if(A[cur] < delta || sum < A[cur])
		throw no_solution();
	if(sum - mx < delta)
		throw no_solution();
	return (A[cur] - delta);
}

