	}
    if(now==root){
        ll mx=*max_element(v.begin(), v.end());
        ll sum=0;
        for(int e:v) sum+=e;
        if(mx > sum-mx) fck(); ///
        if(sum/2 != a[now]) fck(); ///
        return 0;
    }
    else{
		ll mx=*max_element(v.begin(), v.end());
		ll sum=0;
        for(int e:v) sum+=e;

        ll maxPair=0;
        if(v.size() > 1){
			if(mx > sum-mx) maxPair=mx/2;
			else maxPair=sum/2;
		}

		ll LL=sum-maxPair, RR=sum;
		if(a[now] < LL || a[now] > RR) fck(); ///
		ll sP = sum - a[now];
		return sum - 2*sP;
    }
}

