using namespace std;
int n,cnt,a[101010];
int up[101010],siz[101010];
int nxt[202020],to[202020],fir[101010];
char S[3][10]={"NO","YES"};
void add(int x,int y)
{
	nxt[++cnt]=fir[x];fir[x]=cnt;
	to[cnt]=y;
}
int dfs(int x,int f)
{
	siz[x]=up[x]=0;
	int c=0;
	for(int i=fir[x];i;i=nxt[i])
	if(to[i]!=f)
	{
		c++;
		int di=dfs(to[i],x);
		if(!di) return 0;
		int k=up[to[i]];
		int f2=min(k,up[x]);
		k-=f2;up[x]-=f2;siz[x]+=f2;
		int fl=min(siz[x],k/2);
		k-=fl*2;siz[x]+=fl;
		up[x]+=k;
	}
	if(x==1&&c==1) return up[x]==a[x];
	else if(up[x]+siz[x]==0) up[x]=a[x];
	else if(up[x]+siz[x]>a[x]) return 0;
	else if(up[x]+siz[x]<=a[x])
	{
		int k=a[x]-up[x]-siz[x];
		if(siz[x]<k) return 0;
		siz[x]-=k;up[x]+=k*2;
	}
	return 1;
}
