const int maxn = 1000*100 + 1000;
int n; 
int s[maxn];

vector <int> a[maxn];

bool mark[maxn];

bool check(int v, int k)
{
	int mx = k;
	int sum = k;

	if( k < 0 ) 
		return false;
	for(int i=0;i< a[v].size() ; i++)
	{
		sum += a[v][i];
		mx = max(mx, a[v][i]);
	}
	if (mx > sum)
		return false;
	else 
		return true;	
}

int dfs(int v)
{
	if( mark[v] ) return 0;
	mark[v] = true;

	if( a[v].size() == 1 && mark[a[v][0]] ) return s[v];

	if( a[v].size() == 1 )
	{
		int ans = s[v] - dfs( a[v][0] );
		if ( ans < 0 ) 
			return -1;
		else
			return ans; 
	}

	int sum = 0;
	for(int i=0; i < a[v].size() ; i++)
	{
		int tmp = dfs(a[v][i]);
		if ( tmp != -1)
			sum += tmp; 
		else 
			return -1;
	}

	int k =  2*s[v] - sum;

	if ( !check(v, k) ) 
		return -1;
	else 
		return k;	
}

