bool Go(int a) {
  done[a] = true;
  vi incoming;
  for (int i = 0; i < G[a].size(); ++i) {
    int other = G[a][i];
    if (done[other]) {
      continue;
    }
    if (!Go(other)) {
      return false;
    }
    incoming.push_back(d[other]);
  }
  ll sum = 0;
  ll mx = 0;
  for (int i = 0; i < incoming.size(); ++i) {
    sum += incoming[i];
    if (incoming[i] > mx) {
      mx = incoming[i];
    }
  }
  if (max(sum / 2, mx) > A[a]) {
    return false;
  }
  if (sum < A[a]) {
    return false;
  }
  if (incoming.size() == 1 && sum != A[a]) {
    return false;
  }
  if (a == 0 && incoming.size() > 1 && 2 * mx > sum) {
    return false;
  }
  if (a == 0 && incoming.size() > 1 && sum / 2 != A[a]) {
    return false;
  }
  if (a == 0 && incoming.size() == 1 && sum != A[a]) {
    return false;
  }
  if (incoming.size() > 1) {
    d[a] = A[a] - min(sum / 2, ll(sum - mx));
  } else {
    d[a] = A[a];
  }
  return true;
}

