	long long sum = 0;
	sum += v[1];
	v[0] -= v[1];

	long long remainder = 0;
	range(i,2,v.size()){
		sum += v[i] / 2;
		if(v[i] % 2){
			if(v[0] > 0){
				v[0]--;
				sum++;
			}else{
				remainder++;
			}
		}
	}

	sum += remainder / 2;
	return sum;
}

long long dfs(int cur){
