void dfs(int u, int p) {
	child[u] = 1;
	for(int i = 0; i < AdjList[u].size(); i++) if(AdjList[u][i] != p) {
		dfs(AdjList[u][i], u);
		child[u] += child[AdjList[u][i]];
	}
}

int findcen(int u, int p, int sz) {
	for(int i = 0; i < AdjList[u].size(); i++) if(AdjList[u][i] != p) {
		if(child[AdjList[u][i]] > sz/2) return findcen(AdjList[u][i], u, sz);
	}
	return u;
}

bool dfs1(int u, int p) {
    if(AdjList[u].size() == 1) return true;
    if(AdjList[u].size() == 2) {
        for(int i = 0; i < 2; i++) {
            if(AdjList[u][i] != p) {
                if(a[AdjList[u][i]] == a[u]) return true;
                else return false;
            }
        }
    }
    int tmp = 0, ma = 0;
    for(int i = 0; i < AdjList[u].size(); i++) {
        if(AdjList[u][i] != p) {
            if(dfs1(AdjList[u][i], u)) {
                tmp += a[AdjList[u][i]];
                if(a[AdjList[u][i]] > ma) ma = a[AdjList[u][i]];
            }
            else return false;
        }
    }
    if(u == root && a[u] >= ma && a[u] * 2 == tmp) return true;
    else if(ma <= a[u] && a[u] > tmp/2) {
        a[u] -= tmp / 2;
        return true;
    }
    else return false;
}

