struct edge { int to, cost; };
const int MAX_V = MAX_N, INF = 10000000;

// Vの初期化を忘れない。
int V;
vector<edge> G[MAX_V];
int d[MAX_V];

void dijkstra(int s) {
  fill(d, d+V, INF);
  priority_queue<Pii, vector<Pii>, greater<Pii> > pque;
  d[s] = 0;
  pque.push(Pii(0, s));


  while (!pque.empty()) {
    Pii p = pque.top(); pque.pop();
    int v = p.second;
    if (d[v] < p.first) continue;
    for (int i = 0; i < (int)G[v].size(); ++i) {
      edge e = G[v][i];
      if (d[e.to] > d[v] + e.cost) {
        d[e.to] = d[v] + e.cost; 
        pque.push(Pii(d[v]+ e.cost, e.to));
      }
    }
  }
}

ll rec(int v) {
  if (G[v].size() == 1) return A[v];

  vector<ll> vec;
  for (int i = 0; i < G[v].size(); ++i) {
    int u = G[v][i].to;
    if (d[v] > d[u]) continue;
    vec.push_back(rec(u));
  }

  ll sum = 0;
  for (int i = 0; i < vec.size(); ++i) {
    if (vec[i] < 0) return -1;
    sum += vec[i];
  }

  ll res = 2*A[v] - sum;
  if (res < 0) return -1;
  vec.push_back(res);

  for (int i = 0; i < vec.size(); ++i) {
    if (vec[i] > A[v]) return -1;
  }

  return res;
}

int main() {
