  V = N;
  for (int i = 0; i < N-1; ++i) {
    G[a[i]].push_back((edge){b[i], 1});
    G[b[i]].push_back((edge){a[i], 1});
  }

  int root = 0;
  for (int i = 0; i < N; ++i) {
    if (G[i].size() != 1) {
      root = i; break;
    }
  }

  dijkstra(root);

  if (rec(root) != 0) {
    cout << "NO" << endl;
  } else {
    cout << "YES" << endl;
  }

  return 0;
}

