int main(void){
  struct node nod[100001];
  int ed[100000][2];
  int i,j,k,N,now;
  int queue[100000],qp=0,qnum=0;

  scanf("%d",&N);
  for(i=1;i<=N;i++){
    scanf("%d",&nod[i].stone);
    nod[i].deg=0;
  }

  for(i=0;i<N-1;i++){
    scanf("%d%d",&ed[i][0],&ed[i][1]);
    nod[ed[i][0]].deg++;
    nod[ed[i][1]].deg++;
  }

  for(i=1;i<=N;i++) nod[i].edge=(int *)calloc(nod[i].deg,sizeof(int));
  for(i=0;i<N-1;i++){
    for(j=0;j<=1;j++){
      for(k=0;k<nod[ed[i][j]].deg;k++){
	if(nod[ed[i][j]].edge[k]!=0) continue;
	nod[ed[i][j]].edge[k]=ed[i][1-j];
	break;
      }
    }
  }

  for(i=1;i<=N;i++){
    nod[i].nowdeg=nod[i].deg;
    if(nod[i].deg!=1) continue;
    queue[qnum++]=i;
  }

  for(qp=0;qp<qnum && qp<N-1;qp++){
    now=queue[qp];
    for(j=0;j<nod[now].deg;j++){
      if(nod[nod[now].edge[j]].nowdeg==0) continue;
      if(nod[nod[now].edge[j]].stone<nod[now].stone){
	puts("NO");
	for(i=1;i<=N;i++) free(nod[i].edge);
	return 0;
      }
      nod[nod[now].edge[j]].stone-=nod[now].stone;
      nod[nod[now].edge[j]].nowdeg--;
      if(nod[nod[now].edge[j]].nowdeg==1) queue[qnum++]=nod[now].edge[j];
    }
    nod[now].nowdeg=0;
  }
  now=queue[qp];
  puts(nod[now].stone!=0?"YES":"NO");
  for(i=1;i<=N;i++) free(nod[i].edge);
  return 0;
}

