      for(j=x[nv].st;j<x[nv].st+x[nv].kz;j++){
        c=llmax(c,b[g[j].fi]);
        if(b[g[j].fi]!=-llinf){
          w+=b[g[j].fi];
        }
      }
      //printf("<%lld %lld %lld>\n",nv,w,c);
      if(c==-llinf){
        b[nv]=a[nv];
      }
      else{
        h=2*a[nv]-w;
        l=w-h;
        if(h<0 || l<0){
          printf("NO\n");
          return 0;
        }
        //printf("[%lld %lld]\n",h,l);
        if(l%2==1){
          printf("NO\n");
          return 0;
        }
        l/=2;
        t=llmin(w/2,w-c);
        if(t<l){
          printf("NO\n");
          return 0;
        }
        b[nv]=h;
      }
    }
    if(b[v]!=0){
      printf("NO\n");
      return 0;
    }
    printf("YES\n");
    return 0;
}

