typedef long long int int64;

#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
#define ABS(a) ((a)>(0)?(a):-(a))

void run(void){
  int n;
  scanf("%d",&n);
  int *a=(int *)calloc(n,sizeof(int));
  int i;
  for(i=0;i<n;i++) scanf("%d",a+i);
  graph *g=newGraph(n,2*n);
  for(i=1;i<n;i++){
    int v,u;
    scanf("%d%d",&v,&u);
    v--;u--;
    addEdge(g,v,u);
    addEdge(g,u,v);
  }
  int *q=(int *)calloc(n,sizeof(int));
  int *parent=(int *)calloc(n,sizeof(int));
  int front=0,last=0;
  q[last++]=0;
  while(last<n){
    int v=q[front++];
    for(int p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      if(u==parent[v]) continue;
      parent[u]=v;
      q[last++]=u;
    }
  }
  int *dp=(int *)calloc(n,sizeof(int));
  for(i=n-1;i>=0;i--){
    int v=q[i];
    int max=0;
    int64 sum=0;
    int d=0;
    for(int p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      if(u==parent[v]) continue;
      d++;
      sum+=dp[u];
      max=MAX(dp[u],max);
    }
    if(d==0){
      dp[v]=a[v];
      continue;
    }
    if(d==1){
      if(sum!=a[v]){
	exit(1);
	puts("NO");
	return;
      }
      dp[v]=sum;
      continue;
    }
    if(2*max-sum>0){
      int k=2*max-sum;
      if(!(k+(sum-k)/2<=a[v] && a[v]<=sum)){
	puts("NO");
	return;
      }
      dp[v]=a[v]-(sum-k)/2;
    } else {
      if(!((sum+1)/2<=a[v] && a[v]<=sum)){
	puts("NO");
	return;
      }
      dp[v]=a[v]-sum/2;
    }
  }
  int d=0;
  for(i=1;i<n;i++) if(parent[i]==0) d++;
  if((d==1 && dp[0]==a[0]) || dp[0]==0){
    puts("YES");
  } else {
    puts("NO");
  }
}

int main(void){
  run();
  return 0;
}

