    return;
  }
  graph *g=newGraph(n,2*n);
  for(i=1;i<n;i++){
    int v,u;
    scanf("%d%d",&v,&u);
    v--;u--;
    addEdge(g,v,u);
    addEdge(g,u,v);
  }
  int *q=(int *)calloc(n,sizeof(int));
  int *parent=(int *)calloc(n,sizeof(int));
  int front=0,last=0;
  for(i=0;i<n;i++){
    int d=0;
    for(int p=g->start[i];p!=-1;p=g->next[p]) d++;
    if(d>1){
      q[last++]=i;
      parent[i]=i;
      break;
    }
  }
  while(last<n){
    int v=q[front++];
    for(int p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      if(u==parent[v]) continue;
      parent[u]=v;
      q[last++]=u;
    }
  }
  int *min=(int *)calloc(n,sizeof(int));
  int *max=(int *)calloc(n,sizeof(int));
  for(i=n-1;i>0;i--){
    int v=q[i];
    int d=0;
    for(int p=g->start[v];p!=-1;p=g->next[p]) d++;
    if(d==1){
      max[v]=min[v]=a[v];
      continue;
    }
    int64 sumMax=0;
    int64 sumMin=0;
    int minMax=-1;
    for(int p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      if(u==parent[v]) continue;
      sumMin+=min[u];
      sumMax+=max[u];
      if(minMax==-1 || min[u]>min[minMax]){
	minMax=u;
      }
    }
    int val=MAX(0,min[minMax]-(sumMax-max[minMax]));
    COND(a[v]<=sumMax);
    COND((sumMin-val+1)/2+val<=a[v]);
    min[v]=val;
    max[v]=a[v];
  }
  exit(1);
  puts("YES");
}

