int check[100010];
ll a[100010];

ll f(int n){
	//nから上に行く本数を返す
	check[n]=1;

	//子のsumとmaxを覚えておく
	ll s=0,M=0,flag=0;
	rep(i,id[n],id[n+1])if(!check[e[i].g]){
		ll temp=f(e[i].g);
		s+=temp;
		M=max(M,temp);
		flag=1;
	}

	//葉ならa[n]本上にいく
	if(!flag)return a[n];

	//そうでないなら上にはsum-(sum-a[n])*2即ちa[n]*2-sum本行く
	//これが0未満ならダメ
	if(a[n]*2-s<0){
		puts("NO");
		exit(0);
	}

	//そもそも数が足りなければダメ
	if(a[n]>s){
		puts("NO");
		exit(0);
	}

	//M-(a[n]*2-sum)がsum-(a[n]*2-sum)の1/2より真に大きいとだめ
	if((M-(a[n]*2-s))*2>s-(a[n]*2-s)){
		puts("NO");
		exit(0);
	}

	return a[n]*2-s;
}

