#define ll long long
#define rep(i,l,r)for(ll i=(l);i<(r);i++)
#define max(p,q)((p)>(q)?(p):(q))

typedef struct edge{ll s,g;}E;
int edgehikaku(const void*a,const void*b){
	E*p=(E*)a,*q=(E*)b;
	if((*p).s<(*q).s)return -1;
	if((*p).s>(*q).s)return  1;
	if((*p).g<(*q).g)return -1;
	return 1;
}

E e[200010];
int id[100010];
int check[100010];
ll a[100010];

ll f(int n){
	//nから上に行く本数を返す
	check[n]=1;

	//子のsumとmaxを覚えておく
	ll s=0,M=0,flag=0;
	rep(i,id[n],id[n+1])if(!check[e[i].g]){
		ll temp=f(e[i].g);
		s+=temp;
		M=max(M,temp);
		flag=1;
	}

	//葉ならa[n]本上にいく
	if(!flag)return a[n];

	//そうでないなら上にはsum-(sum-a[n])*2即ちa[n]*2-sum本行く
	//M-(a[n]*2-sum)がsum-(a[n]*2-sum)の1/2より真に大きいとだめ
	if((M-(a[n]*2-s))*2>s-(a[n]*2-s)){
		puts("NO");
		exit(0);
	}

	return a[n]*2-s;
}

int main(){
	int n;
	scanf("%d",&n);
	rep(i,0,n)scanf("%lld",a+i);
	rep(i,0,n-1){
		ll x,y;
		scanf("%lld %lld",&x,&y);
		x--,y--;
		e[2*i].s=x;
		e[2*i].g=y;
		e[2*i+1].s=y;
		e[2*i+1].g=x;
	}
	qsort(e,2*n-2,sizeof(E),edgehikaku);

	int p=0;
	rep(i,1,n){
		while(e[p].s!=i)p++;
		id[i]=p;
	}
	id[n]=2*n-2;

	//葉でない頂点を親とする
	p=0;
	while(id[p+1]-id[p]==1)p++;
	puts(f(p)?"NO":"YES");
}

