	ll s=0,M=0,flag=0;
	rep(i,id[n],id[n+1])if(!check[e[i].g]){
		ll temp=f(e[i].g);
		s+=temp;
		M=max(M,temp);
		flag=1;
	}

	//葉ならa[n]本上にいく
	if(!flag)return a[n];

	//そうでないなら上にはsum-(sum-a[n])*2即ちa[n]*2-sum本行く
