    static class agc010c {
        List[] g;
        int[] a;
        boolean isp = true;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            a = new int[n];

            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList();
            }

            for (int i = 0; i < n - 1; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;

                g[u].add(v);
                g[v].add(u);
            }

            long val = dfs(0, -1);

            if ((g[0].size() == 1 || val == 0) && isp) {
                out.print("YES");
            } else {
                out.print("NO");
            }
        }

        long dfs(int u, int p) {

            long sum = 0;
            int tot = 0;
            for (int v : (List<Integer>) g[u]) {
                if (v != p) {
                    tot++;
                    sum += dfs(v, u);
                }
            }

            if (tot == 0) {
                return a[u];
            }

            if (tot == 1) {
                if (sum != a[u]) {
                    isp = false;
                    return -1;
                } else {
                    return sum;
                }
            }

            if (sum < a[u]) {
                isp = false;
                return -1;
            }

            if (sum == a[u]) {
                return sum;
            }

            if (sum > a[u]) {
                long rem = sum - a[u];
                if (rem <= a[u] && 2 * rem <= sum) {
                    return a[u] - rem;
                } else {
                    isp = false;
                    return -1;
                }
            }

            return -1;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

