import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;


public class Main {
  private static int N;
  private static int[][] g;
  private static long[] A;

  private static long[] last;

  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    N = sc.nextInt();
    A = sc.nextLongList(N);

    int[] from = new int[N - 1];
    int[] to = new int[N - 1];
    for (int i = 0; i < N - 1; i ++) {
      from[i] = sc.nextInt() - 1;
      to[i] = sc.nextInt() - 1;
    }
    g = packU(N, from, to);

    last = new long[N];

    int s = -1;
    for (int i = 0; i < N; i ++) {
      if (g[i].length > 1) {
        s = i;
        break;
      }
    }
    if (s >= 0) {
      boolean ret = dfs(s, -1);
      if (ret && last[s] == 0) { 
        System.out.println("YES");
      } else {
        System.out.println("NO");
      }
    } else {
      System.out.println(A[0] == A[1] ? "YES" : "NO");
    }
  }

  private static boolean dfs(int now, int pre) {
    if (pre >= 0 && g[now].length == 1) {
      last[now] = A[now];
      return true;
    }

    long a = 0;
    long max = 0;
    for (int v : g[now]) {
      if (v != pre) {
        boolean ret = dfs(v, now);
        if (!ret) {
          return false;
        }
        a += last[v];
        max = Math.max(max, a);
      }
    }

    if (pre >= 0 && g[now].length == 2) {
      last[now] = A[now];
      return a == A[now];
    } else {
      if (a <= A[now] * 2 && A[now] <= a) {
        last[now] = A[now] * 2 - a;

        if (A[now] > max) {
          return false;
        }
        return true;
      } else {
        return false;
      }
    }
  }

  public static int[][] packU(int n, int[] from, int[] to)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int f : from)p[f]++;
      for(int t : to)p[t]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < from.length;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }
}


class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskC {
		boolean ok;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			List<Integer>[] adj = new List[n];
			for (int i = 0; i < n; i++) {
				adj[i] = new ArrayList<>();
			}
			int[] a = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
			}
			for (int i = 0; i < n - 1; i++) {
				int u = in.nextInt() - 1;
				int v = in.nextInt() - 1;
				adj[u].add(v);
				adj[v].add(u);
			}
			if (n == 2) {
				out.println(a[0] == a[1] ? "YES" : "NO");
				return;
			}
			int root = -1;
			for (int i = 0; i < n; i++) {
				if (adj[i].size() > 1) {
					root = i;
					break;
				}
			}
			if (root < 0) {
				throw new AssertionError();
			}
			ok = true;
			// System.out.println("root = " + root);
			long excess = dfs(root, -1, adj, a);
			out.println(ok && excess == 0 ? "YES" : "NO");
		}

		private long dfs(int v, int parent, List<Integer>[] adj, int[] a) {
			List<Long> e = new ArrayList<>();
			long sum = 0;
			for (int u : adj[v]) {
				if (u == parent) {
					continue;
				}
				long cur = dfs(u, v, adj, a);
				e.add(cur);
				sum += cur;
			}
			if (e.size() == 0) {
				return a[v];
			}
			long p = sum - a[v]; // pairs
			long s = a[v] - p; // singles
			if (p < 0 || s < 0) {
				ok = false;
				return 0;
			}
			if (p > maxPairs(e)) {
				ok = false;
				return 0;
			}
			return s;
		}

		private long maxPairs(List<Long> a) {
			long free = 0;
			long pairs = 0;
			for (long x : a) {
				long s = Math.min(x, free);
				x -= s;
				free -= s;
				if (x % 2 != 0) {
					++free;
					--x;
				}
				long d = Math.min(x, 2 * pairs);
				x -= d;

				pairs += s;
				pairs += d / 2;
				free += x;
			}
			return pairs;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable{

	public static void main(String[] args) {
		Thread.setDefaultUncaughtExceptionHandler((t,e) -> System.exit(1));
		new Thread(null, new Main(), "", 1024L * 1024L * 16).start();
	}

	@Override
	public void run() {
		System.out.println(solve() ? "YES" : "NO");
	}

	public boolean solve() {
		IO io = new IO();
		int n = io.nextInt();
		long[] a = io.nextLongArray(n);
		if (n == 2) {
			return a[0] == a[1];
		}
		ArrayList<Integer>[] t = new ArrayList[n];
		for(int i=0;i<n;i++) {
			t[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int u = io.nextInt() - 1;
			int v = io.nextInt() - 1;
			t[u].add(v);
			t[v].add(u);
		}
		for(int i=0;i<n;i++) {
			if (t[i].size() >= 2) {
				try {
					return dfs(-1,i,t,a) == 0;
				} catch(FailedException e) {
					return false;
				}
			}
		}
		throw new RuntimeException("unreachable");
	}

	public long dfs(int p,int v,ArrayList<Integer>[] t,long[] a) {
		if (t[v].size() == 1 && t[v].get(0) == p) {
			return a[v];
		}
		long sum = 0;
		long max = 0;
		for(int u:t[v]) {
			if (u == p) continue;
			long x = dfs(v,u,t,a);
			sum += x; 
			max = Math.max(max, x);
		}
		long nGamma = sum - a[v];
		if (nGamma < 0) {
			throw new FailedException();
		}
		long nI = a[v] - nGamma;
		if (nI < 0) {
			throw new FailedException();
		}
		if ((max - nI) * 2 > sum) {
			throw new FailedException();
		}
		return nI;
	}
}
class FailedException extends RuntimeException {

}
class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.max;



public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = In.nl(n);
        if (n == 2) {
            out.append(a[0] == a[1] ? "YES" : "NO");
            return;
        }
        int[][] uv = new int[n - 1][2];
        int[] c = new int[n];
        int r = 0;
        for (int i = 0; i < n - 1; i++) {
            uv[i][0] = In.ni() - 1;
            uv[i][1] = In.ni() - 1;
            c[uv[i][0]]++;
            c[uv[i][1]]++;
        }
        long l = 0;
        for (int i = 0; i < n; i++) {
            if (c[i] > 1) {
                r = i;
            } else {
                l ^= a[i];
            }
        }
        if ((l & 1) == 1) {
            out.append("NO");
            return;
        }
        Tree t = new Tree(n, r);
        for (int i = 0; i < n - 1; i++) {
            t.addEdge(uv[i][0], uv[i][1]);
        }
        t.build();
        try {
            dfs(t, t.root, a);
            out.append("YES");
        } catch (Exception e) {
            out.append("NO");
        }
    }

    public static long dfs(Tree t, int u, long[] a) throws Exception {
        long minSum = 0;
        long sumA = 0;
        long maxA = 0;
        PrimitiveIterator.OfInt iter = t.getEdges(u).iterator();
        while (iter.hasNext()) {
            int v = iter.nextInt();
            if (v == t.parent(u)) continue;
            minSum += dfs(t, v, a);
            sumA += a[v];
            maxA = max(maxA, a[v]);
        }
        if (sumA == 0) return a[u];
        long ret = max(2 * maxA - sumA, sumA & 1);
        if (u != t.root && (2 * a[u] < minSum || a[u] > sumA)) {
            throw new Exception();
        } else if (u == t.root && (2 * a[u] < minSum || 2 * a[u] > sumA)) {
            throw new Exception();
        }
        return ret;
    }
}


