/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        agc010c solver = new agc010c();
        solver.solve(1, in, out);
        out.close();
    }

    static class agc010c {
        List[] g;
        int[] a;
        boolean isp = true;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            a = new int[n];

            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            g = new List[n];

            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList();
            }

            for (int i = 0; i < n - 1; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;

                g[u].add(v);
                g[v].add(u);
            }

            long val = dfs(0, -1);

            if ((g[0].size() == 1 || val == 0) && isp) {
                out.print("YES");
            } else {
                out.print("NO");
            }
        }

        long dfs(int u, int p) {

            long sum = 0;
            int tot = 0;
            List<Long> rl = new ArrayList<>();

            for (int v : (List<Integer>) g[u]) {
                if (v != p) {
                    tot++;
                    long val = dfs(v, u);
                    sum += val;
                    rl.add(val);
                }
            }

            rl.sort((x, y) -> (int) Math.signum(x - y));

            long minsum = 0;

            if (tot == 0) {
                return a[u];
            }

            if (tot == 1) {
                if (sum != a[u]) {
                    isp = false;
                    return -1;
                } else {
                    return sum;
                }
            }

            for (int i = 0; i < rl.size() - 1; i++) {
                minsum += rl.get(i);
            }

            if (sum < a[u]) {
                isp = false;
                return -1;
            }

            if (sum == a[u]) {
                return sum;
            }

            if (sum > a[u]) {
                long rem = sum - a[u];
                if (rem <= a[u] && 2 * rem <= sum && minsum >= rem) {
                    return a[u] - rem;
                } else {
                    isp = false;
                    return -1;
                }
            }

            return -1;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;
import static java.lang.Math.max;



public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = In.nl(n);
        if (n == 2) {
            out.append(a[0] == a[1] ? "YES" : "NO");
            return;
        }
        int[][] uv = new int[n - 1][2];
        int[] c = new int[n];
        int r = 0;
        for (int i = 0; i < n - 1; i++) {
            uv[i][0] = In.ni() - 1;
            uv[i][1] = In.ni() - 1;
            c[uv[i][0]]++;
            c[uv[i][1]]++;
        }
        long l = 0;
        for (int i = 0; i < n; i++) {
            if (c[i] > 1) {
                r = i;
            } else {
                l ^= a[i];
            }
        }
        if ((l & 1) == 1) {
            out.append("NO");
            return;
        }
        Tree t = new Tree(n, r);
        for (int i = 0; i < n - 1; i++) {
            t.addEdge(uv[i][0], uv[i][1]);
        }
        t.build();
        try {
            dfs(t, t.root, a);
            out.append("YES");
        } catch (Exception e) {
            out.append("NO");
        }
    }

    public static long dfs(Tree t, int u, long[] a) throws Exception {
        if (t.getEdges(u).size() == 1) return a[u];
        long sum = 0;
        long max = 0;
        PrimitiveIterator.OfInt iter = t.getEdges(u).iterator();
        while (iter.hasNext()) {
            int v = iter.nextInt();
            if (v == t.parent(u)) continue;
            long c = dfs(t, v, a);
            sum += c;
            max = max(max, c);
        }
        if (u == t.root && 2 * a[u] != sum) {
            throw new Exception();
        }
        long ret = 2 * a[u] - sum;
        long r = max(2 * max - sum, sum & 1);
        long p = (sum - r) / 2;
        if (ret < 0 || a[u] - ret > p) {
            throw new Exception();
        }
        return ret;
    }
}


