import static java.lang.Math.max;

public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        long[] a = In.nl(n);
        if (n == 2) {
            out.append(a[0] == a[1] ? "YES" : "NO");
            return;
        }
        Tree t = new Tree(n);
        for (int i = 0; i < n - 1; i++) {
            int u = In.ni() - 1;
            int v = In.ni() - 1;
            t.addEdge(u, v);
        }
        t.build();
        try {
            dfs(t, 0, a);
            out.append("YES");
        } catch (Exception e) {
            out.append("NO");
        }
    }

    public static long dfs(Tree t, int u, long[] a) throws Exception {
        if (u != 0 && t.getEdges(u).size() == 1) return a[u];
        long sum = 0;
        long max = 0;
        PrimitiveIterator.OfInt iter = t.getEdges(u).iterator();
        while (iter.hasNext()) {
            int v = iter.nextInt();
            if (v == t.parent(u)) continue;
            long c = dfs(t, v, a);
            sum += c;
            max = max(max, c);
        }
        long ret = a[u] * 2 - sum;
        long p = sum - max < max ? sum - max : sum / 2;
        if (ret < 0 || sum - a[u] > p) throw new Exception();
        return ret;
    }
}


