import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable{

	public static void main(String[] args) {
		Thread.setDefaultUncaughtExceptionHandler((t,e) -> System.exit(1));
		new Thread(null, new Main(), "", 1024L * 1024L * 16).start();
	}

	@Override
	public void run() {
		System.out.println(solve() ? "YES" : "NO");
	}

	public boolean solve() {
		IO io = new IO();
		int n = io.nextInt();
		long[] a = io.nextLongArray(n);
		if (n == 2) {
			return a[0] == a[1];
		}
		ArrayList<Integer>[] t = new ArrayList[n];
		for(int i=0;i<n;i++) {
			t[i] = new ArrayList<>();
		}
		for(int i=0;i<n-1;i++) {
			int u = io.nextInt() - 1;
			int v = io.nextInt() - 1;
			t[u].add(v);
			t[v].add(u);
		}
		for(int i=0;i<n;i++) {
			if (t[i].size() >= 2) {
				try {
					return dfs(-1,i,t,a) == 0;
				} catch(FailedException e) {
					return false;
				}
			}
		}
		return true;
		//throw new RuntimeException("unreachable");
	}

	public long dfs(int p,int v,ArrayList<Integer>[] t,long[] a) {
		if (t[v].size() == 1) {
			return a[v];
		}
		long sum = 0;
		long max = 0;

		for(int u:t[v]) {
			if (u == p) continue;
			long x = dfs(v,u,t,a);
			sum += x; 
			max = Math.max(max, x);
		}
		long nGamma = sum - a[v];
		if (nGamma < 0) {
			throw new FailedException();
		}
		long nI = a[v] - nGamma;
		if (nI < 0) {
			throw new FailedException();
		}
		if (max - nI > sum - max) {
			throw new FailedException();
		}
		return nI;
	}
}
class FailedException extends RuntimeException {

}
class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A;
    static int[] U, V;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        U = new int[N-1];
        V = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            U[i] = sc.nextInt()-1;
            V[i] = sc.nextInt()-1;
        }

        System.out.println(solve() ? "YES" : "NO");
    }

    static boolean solve() {
        int[][] G = adjB(N, U, V);
        int root = 0;
        Node[] nodes = orderFromLeaf(N, G, root);

        for (int i = 0; i < N; i++) {
            Node node = nodes[i];

            if( G[node.a].length == 1 ) continue;

            long sum = 0;
            int max = -1;
            for (int next : G[node.a]) {
                if( next == node.parent ) continue;

                sum += A[next];
                max = Math.max(A[next], max);
            }

            long remain = sum - max;
            long pair;
            if( max > remain ) {
                pair = remain;
            } else {
                pair = sum / 2;
            }

            long top = sum;
            long bot = sum - pair;

            // debug(node.a, bot, top, A[node.a], pair);
            if( A[node.a] < bot || top < A[node.a] ) return false;

            A[node.a] = A[node.a] - (int)pair;
        }

        if( G[root].length == 1 ) {
            return A[G[root][0]] == A[root];
        } else {
            return A[root] == 0;
        }

    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
  static Scanner sc = new Scanner(System.in);
  static long startTime = System.currentTimeMillis();
  static int N;
  static int[] A;
  static Node[] nodes;

  public static void main(String[] args) {
    N = sc.nextInt();
    A = new int[N];
    for (int i = 0; i < N; i++) {
      A[i] = Integer.parseInt(sc.next());
    }
    if (N == 2) {
      System.out.println(A[0] == A[1] ? "YES" : "NO");
      return;
    }
    nodes = new Node[N];
    for (int i = 0; i < N; i++) {
      nodes[i] = new Node(i);
    }
    for (int i = 0; i < N - 1; i++) {
      int a = Integer.parseInt(sc.next()) - 1;
      int b = Integer.parseInt(sc.next()) - 1;
      nodes[a].next.add(nodes[b]);
      nodes[b].next.add(nodes[a]);
    }
    boolean ans = false;
    for (int i = 0; i < N && !ans && System.currentTimeMillis() - startTime < 1600; i++) {
      if (nodes[i].next.size() > 1) {
        ans |= solve(i);
      }
    }
    System.out.println(ans ? "YES" : "NO");
  }

  static boolean solve( int root) {
    int[] order = new int[N];
    order[0] = root;
    int pos = 1;
    for (int i = 0; i < N; i++) {
      Node cur = nodes[order[i]];
      for (Node c : cur.next) {
        if (c.idx == cur.parent) continue;
        c.parent = cur.idx;
        order[pos++] = c.idx;
      }
    }
    for (int i = N - 1; i >= 0; i--) {
      long sum = 0;
      long max = 0;
      Node n = nodes[order[i]];
      boolean hasChild = false;
      for (Node c : n.next) {
        if (c.idx == n.parent) continue;
        sum += c.v;
        max = Math.max(max, c.v);
        hasChild = true;
      }
      if (!hasChild) continue;
      if (sum < A[n.idx]) {
        return false;
      }
      long dec = sum - A[n.idx];
//      System.out.println(order[i] + " " + sum + " " + max + " " + dec);
      if (max > sum - max) {
        long c = max - (sum - max);
        if (c < dec) {
          return false;
        }
      }
      n.v = sum - dec * 2;
      if (n.v < 0) {
        return false;
      }
    }
    return nodes[root].v == 0;
  }


  static class Node {
    int idx;
    long v;
    int parent = -1;
    ArrayList<Node> next = new ArrayList<>();

    public Node(int idx) {
      this.idx = idx;
      this.v = A[idx];
    }
  }
}

