import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        a = new long[n];
        for (int i = 0; i < n ; i++) {
            a[i] = in.nextLong();
        }
        graph = buildGraph(in, n, n-1);

        out.println(isOK(n) ? "YES" : "NO");
        out.flush();
    }

    static boolean isOK(int n) {
        isOK = true;
        if (n == 2) {
            return a[0] == a[1];
        }
        for (int i = 0; i < n ; i++) {
            if (graph[i].length >= 2) {
                isOK &= dfs(i, -1) == 0;
                break;
            }
        }
        return isOK;
    }

    static long[] a;
    static int[][] graph;
    static boolean isOK;

    static long dfs(int now, int par) {
        boolean has = false;
        long upsum = 0;
        long max = 0;
        for (int to : graph[now]) {
            if (to == par) {
                continue;
            }
            has = true;
            long l = dfs(to, now);
            max = Math.max(max, l);
            upsum += l;
        }
        if (!has) {
            return a[now];
        }

        isOK &= a[now] <= upsum;
        long pair = upsum - a[now];
        long maxpair = max * 2 <= upsum ? upsum / 2 : (upsum - max);
        isOK &= pair >= 0;
        isOK &= pair <= maxpair;

        long up = a[now] * 2 - upsum;
        isOK &= up >= 0;

        // debug(now, a[now], pair, upsum, up);

        return up;
    }

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }


    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
	static int gen = 0;

	static class Vertex {
		List<Vertex> adj = new ArrayList<>();
		long stones;
		int id = gen++;

		public Vertex(long stones) {
			this.stones = stones;
		}

		long dfs(Vertex parent) {
			if (adj.size() == 1)
				return stones;
			long sum = 0;
			long max = 0;
			for (Vertex v : adj) {
				if (v == parent)
					continue;
				long got = v.dfs(this);
				sum += got;
				max = Math.max(max, got);
			}
			long nextPathNum = 2 * stones - sum;
			max = Math.max(max, nextPathNum);
			if (nextPathNum < 0) {
				return -1;
			}
			if (2 * max > 2 * stones) {
				return -1;
			}
			return nextPathNum;
		}
	}

	static int N;
	static int[] a, b;
	static Vertex[] vs;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		vs = new Vertex[N];
		for (int i = 0; i < N; ++i)
			vs[i] = new Vertex(sc.nextInt());
		a = new int[N - 1];
		b = new int[N - 1];
		for (int i = 0; i < N - 1; ++i) {
			Vertex a = vs[sc.nextInt() - 1];
			Vertex b = vs[sc.nextInt() - 1];
			a.adj.add(b);
			b.adj.add(a);
		}

		if (N == 2) {
			if (vs[0].stones == vs[1].stones) {
				System.out.println("YES");
			} else {
				System.out.println("NO");
			}
			return;
		}

		Vertex root = null;
		for (Vertex v : vs) {
			if (v.adj.size() > 1) {
				root = v;
				break;
			}
		}

		long pathNum = root.dfs(null);
		if (pathNum == 0) {
			System.out.println("YES");
		} else {
			System.out.println("NO");
		}
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}

}

import java.util.*;

public class Main {
	static class Tree {
		public class Edge {
			int to, rev;

			public Edge(int to, int rev) {
				this.to = to;
				this.rev = rev;
			}
		}

		int V;
		ArrayList<ArrayList<Edge>> G;
		int root;
		int[] p;
		int[] path;
		int[] A;

		public Tree(int[] a, int[] b, int[] A) {
			this.V = a.length+1;
			p = new int[V];
			path = new int[V];
			this.A = A;

			G = new ArrayList<ArrayList<Edge>>();
			for(int i=0; i<V; i++) {
				G.add(new ArrayList<Edge>());
			}

			for(int i=0; i<V-1; i++) {
				G.get(a[i]).add(new Edge(b[i], G.get(b[i]).size()));
				G.get(b[i]).add(new Edge(a[i], G.get(a[i]).size()-1));
			}
			int root = 0;
			for(int i=0; i<V; i++)
				if(G.get(i).size()>1) {
					root=i;
					break;
				}
			setRoot(root);
		}

		public void setRoot(int root) {
			this.root = root;
			setRoot(root, -1);
		}
		public void setRoot(int cur, int parent) {
			p[cur] = parent; 
			for(int i=0; i<G.get(cur).size(); i++) {
				int next = G.get(cur).get(i).to;
				if(next!=parent) {
					setRoot(next, cur);
				}
			}
		}

		public boolean check(int cur) {
			if(G.get(cur).size()==1) {
				path[cur] = A[cur];
				return true;
			}

			long sum = 0;
			long max = -1;
			for(int i=0; i<G.get(cur).size(); i++) {
				int next = G.get(cur).get(i).to;
				if(next!=p[cur]) {
					if(!check(next))
						return false;
					sum += path[next];
					max = Math.max(max, path[next]);
				}
			}
			long pair = Math.max(0, sum-A[cur]);
			if(pair>A[cur] || sum-max<pair)
				return false;

			path[cur] = A[cur] - (int)pair;
			return true;
		}
	}


	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int[] A = new int[N];
		for(int i=0; i<N; i++)
			A[i] = sc.nextInt();
		int[] a = new int[N-1];
		int[] b = new int[N-1];
		for(int i=0; i<N-1; i++) {
			a[i] = sc.nextInt()-1;
			b[i] = sc.nextInt()-1;
		}
		if(N==2) {
			System.out.println(A[0]==A[1] ? "YES" : "NO");
		} else {
			Tree tree = new Tree(a, b, A);
			System.out.println(tree.check(tree.root) && tree.path[tree.root]==0 ? "YES" : "NO");
		}
		sc.close();
	}
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A;
    static int[] U, V;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        U = new int[N-1];
        V = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            U[i] = sc.nextInt()-1;
            V[i] = sc.nextInt()-1;
        }

        System.out.println(solve() ? "YES" : "NO");
    }

    static boolean solve() {
        int[][] G = adjB(N, U, V);
        int root = 0;
        Node[] nodes = orderFromLeaf(N, G, root);

        for (int i = 0; i < N; i++) {
            Node node = nodes[i];

            if( G[node.a].length == 1 ) continue;

            long sum = 0;
            int maxNode = -1;
            for (int next : G[node.a]) {
                if( next == node.parent ) continue;

                sum += A[next];
                maxNode = Math.max(A[next], maxNode);
            }

            long maxPair;
            if( maxNode > sum - maxNode ) {
                maxPair = sum - maxNode;
            } else {
                maxPair = sum / 2;
            }

            long top = sum;
            long bot = sum - maxPair;

            if( A[node.a] < bot || top < A[node.a] ) return false;

            long pair = top - A[node.a];

            A[node.a] = (int)(A[node.a] - pair);
        }

        if( G[root].length == 1 ) {
            return A[G[root][0]] == A[root];
        } else {
            return A[root] == 0;
        }

    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

