    private static boolean solve(long[] ai, int[][] g) {
        a = ai;
        n = a.length;
        graph = g;
        if (n == 2) {
            return a[0] == a[1];
        }

        int root = -1;
        for (int i = 0; i < n ; i++) {
            if (g[i].length >= 2) {
                root = i;
                break;
            }
        }
        lnln = new long[n+10];
        cnt = new long[n];
        up = new long[n];
