class TaskC {
    long[] A;
    public void solve(int testNumber, MyScanner in, MyPrintWriter out) {
        int N = in.nextInt();
        A = new long[N];
        for (int i = 0; i < N; i++) A[i] = in.nextInt();
        Graph G = new Graph(N);
        for (int i = 0; i < N - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            G.add(a,b);
            G.add(b,a);
        }
        long res = dfs(G, 0, -1);
        out.println(res == (lastDeg <= 1 ? A[0] : 0) ? "YES" : "NO");
    }

    int lastDeg;

    private long dfs(Graph g, int root, int prev) {
        debug("root,prev", root+1, prev+1);
        long S = 0;
        long max = 0;
        int deg = 0;
        for(Edge e : g.edges(root)) {
            if (e.to() != prev) {
                deg++;
                long v = dfs(g, e.to(), root);
                if (v < 0) return -1;
                S += v;
                max = Math.max(max, v);
            }
        }
        if (A[root] < max) return -1;
        long res = deg == 0 ? A[root] : S - 2 * (S - A[root]);
        if (res < 0) return -1;
        debug(root+1, res);
        lastDeg = deg;
        return res;
    }
    void debug(Object...os){
}
}

class MyScanner {
    private final InputStream in;

    public MyScanner(InputStream in) {
        this.in = in;
    }

    private static final int BUFSIZE = 65536;
    int bufLen;
    int bufPtr;
    byte[] buf = new byte[BUFSIZE];

    public int read() {
        if (bufLen == -1)
            throw new InputMismatchException();
        if (bufPtr >= bufLen) {
            bufPtr = 0;
            try {
                bufLen = in.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bufLen <= 0)
                return -1;
        }
        return buf[bufPtr++];
    }

    public int nextInt() {
        int c = read();
        if (c == -1) throw new NoSuchElementException();
        while (c != '-' && (c < '0' || '9' < c)) {
            c = read();
            if (c == -1) throw new NoSuchElementException();
        }
        if (c == '-') return -nextInt();
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while ('0' <= c && c <= '9');
        return res;
    }

}

