public class Main {
	static int gen = 0;

	static class Vertex {
		List<Vertex> adj = new ArrayList<>();
		long stones;
		int id = gen++;

		public Vertex(long stones) {
			this.stones = stones;
		}

		long dfs(Vertex parent) {
			if (adj.size() == 1)
				return stones;
			long sum = 0;
			long max = 0;
			for (Vertex v : adj) {
				if (v == parent)
					continue;
				long got = v.dfs(this);
				sum += got;
				max = Math.max(max, got);
			}
			long nextPathNum = 2 * stones - sum;
			max = Math.max(max, nextPathNum);
			if (nextPathNum < 0) {
				return -1;
			}
			if (2 * max > 2 * stones) {
				return -1;
			}
			return nextPathNum;
		}
	}

	static int N;
	static int[] a, b;
	static Vertex[] vs;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
