import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;


public class Main {
  private static int N;
  private static int[][] g;
  private static long[] A;

  private static long[] last;

  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    N = sc.nextInt();
    A = sc.nextLongList(N);

    int[] from = new int[N - 1];
    int[] to = new int[N - 1];
    for (int i = 0; i < N - 1; i ++) {
      from[i] = sc.nextInt() - 1;
      to[i] = sc.nextInt() - 1;
    }
    g = packU(N, from, to);

    last = new long[N];

    int s = -1;
    for (int i = 0; i < N; i ++) {
      if (g[i].length > 1) {
        s = i;
        break;
      }
    }
    if (s >= 0) {
      boolean ret = dfs(s, -1);
      if (ret && last[s] == 0) { 
        System.out.println("YES");
      } else {
        System.out.println("NO");
      }
    } else {
      System.out.println(A[0] == A[1] ? "YES" : "NO");
    }
  }

  private static boolean dfs(int now, int pre) {
    if (pre >= 0 && g[now].length == 1) {
      last[now] = A[now];
      return true;
    }

    long a = 0;
    for (int v : g[now]) {
      if (v != pre) {
        boolean ret = dfs(v, now);
        if (!ret) {
          return false;
        }
        a += last[v];
      }
    }

    if (pre >= 0 && g[now].length == 2) {
      last[now] = A[now];
      return a == A[now];
    } else {
      if ((a + 1) / 2 <= A[now] && A[now] <= a) {
        last[now] = A[now] * 2 - a;
        return true;
      } else {
        return false;
      }
    }
  }

  public static int[][] packU(int n, int[] from, int[] to)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int f : from)p[f]++;
      for(int t : to)p[t]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < from.length;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }
}


class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.BufferedWriter;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author ilyakor
 */
public class Main {

  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    OutputWriter out = new OutputWriter(outputStream);
    TaskC solver = new TaskC();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskC {

    ArrayList<Integer>[] g;
    int[] need;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      g = new ArrayList[n];
      for (int i = 0; i < n; ++i) {
        g[i] = new ArrayList<>();
      }
      need = new int[n];
      for (int i = 0; i < n; ++i) {
        need[i] = in.nextInt();
      }
      for (int i = 0; i < n - 1; ++i) {
        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;
        g[x].add(y);
        g[y].add(x);
      }
      if (n == 2) {
        if (need[0] == need[1]) {
          out.printLine("YES");
        } else {
          out.printLine("NO");
        }
        return;
      }
      int root = 0;
      while (g[root].size() <= 1) {
        ++root;
      }
      TaskC.Seg res = dfs(root, -1);
      out.printLine((res.l <= 0 && res.r >= 0 && res.l % 2 == 0) ? "YES" : "NO");
    }

    private TaskC.Seg dfs(int x, int par) {
      if (g[x].size() == 1) {
        return new TaskC.Seg(need[x], need[x]);
      }
      long sl = 0, sr = 0, ml = 0, mr = 0;
      for (int y : g[x]) {
        if (y != par) {
          TaskC.Seg s = dfs(y, x);
          if (s.l > s.r) {
            return new TaskC.Seg(0, -2);
          }
          sl += s.l;
          sr += s.r;
          if (ml < s.l) {
            ml = s.l;
          }
          if (mr < s.r) {
            mr = s.r;
          }
        }
      }
      long maxConn = (sr - mr + Math.min(mr, sr - mr)) / 2L;
      if (sl < need[x]) {
        sl = need[x] + (sl % 2 == need[x] % 2 ? 0 : 1);
      }
      if (sr > maxConn + need[x]) {
        sr = maxConn + need[x] - (sr % 2 == (maxConn + need[x]) % 2 ? 0 : 1);
      }
      if (sl > sr) {
        return new TaskC.Seg(0, -2);
      }
      sl = 2 * need[x] - sl;
      sr = 2 * need[x] - sr;
      {
        long t = sl;
        sl = sr;
        sr = t;
      }
      if (sl < 0) {
        sl = Math.abs(sl) % 2;
      }
      if (sl > sr) {
        return new TaskC.Seg(0, -2);
      }

      return new TaskC.Seg(sl, sr);
    }

    static class Seg {

      long l;
      long r;

      public Seg(long l, long r) {
        this.l = l;
        this.r = r;
      }

    }

  }

  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }

  static class OutputWriter {

    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
      writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public OutputWriter(Writer writer) {
      this.writer = new PrintWriter(writer);
    }

    public void print(Object... objects) {
      for (int i = 0; i < objects.length; i++) {
        if (i != 0) {
          writer.print(' ');
        }
        writer.print(objects[i]);
      }
    }

    public void printLine(Object... objects) {
      print(objects);
      writer.println();
    }

    public void close() {
      writer.close();
    }

  }
}

