import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        long[] a = in.nextLongs(n);
        int[][] graph = buildGraph(in, n, n-1);

        out.println(solve(a, graph) ? "YES" : "NO");
        out.flush();
    }

    private static boolean solve(long[] ai, int[][] g) {
        a = ai;
        n = a.length;
        graph = g;
        if (n == 2) {
            return a[0] == a[1];
        }

        int root = -1;
        for (int i = 0; i < n ; i++) {
            if (g[i].length >= 2) {
                root = i;
                break;
            }
        }
        lnln = new long[n+10];
        cnt = new long[n];
        up = new long[n];
        ok = true;
        dfs(root, -1);

        // debug(root,up);

        return ok && up[root] == 0 && leafSum % 2 == 0;
    }

    static boolean ok = true;

    static long leafSum = 0;

    static int n;
    static long[] a;
    static int[][] graph;
    static long[] cnt;

    static long[] up;

    static long[] lnln;

    static void dfs(int now, int par) {
        boolean leaf = true;
        long dup = 0;

        int ln = 0;
        for (int to : graph[now]) {
            if (to == par) {
                continue;
            }
            leaf = false;
            dfs(to, now);
            lnln[ln++] = up[to];
            dup += up[to];
        }

        if (leaf) {
            leafSum += a[now];
            up[now] = a[now];
        } else {
            long inner = dup - a[now];
            if (inner < 0) {
                ok = false;
            }
            up[now] = dup - inner * 2;
            if (up[now] < 0) {
                ok = false;
            }

            if (ln >= 2) {
                Arrays.sort(lnln, 0, ln);

//                int j = ln-1;
//                long totalDec = 0;
//                for (int i = 0 ; i < ln ; i++) {
//                    while (lnln[i] >= 1) {
//                        long lft = lnln[j];
//                        long dec = Math.min(lnln[i], lnln[j]);
//                        lnln[i] -= dec;
//                        lnln[j] -= dec;
//                        totalDec += lft;
//                    }
//                }
//

                long pre = 0;
                boolean canMake = false;
                for (int i = 0; i < ln ; i++) {
                    pre += lnln[i];
                    long suf = dup - pre;
                    if (inner <= Math.min(pre, suf)) {
                        canMake = true;
                    }
                    if (i+2 < ln) {
                        long pre2 = pre;
                        long suf2 = suf - lnln[i+1];
                        long z = lnln[i+1];
                        long diff = Math.abs(pre2-suf2);
                        long canapp = Math.min(diff, z);
                        if (pre2 < suf2) {
                            pre2 += canapp;
                        } else {
                            suf2 -= canapp;
                        }
                        z -= canapp;
                        long canaddBoth = z / 2;
                        pre2 += canaddBoth;
                        suf2 += canaddBoth;
                        if (inner <= Math.min(pre2, suf2)) {
                            canMake = true;
                        }
                    }
                }
                ok &= canMake;
            }

        }
    }

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int[] nextInts(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }

        private int[][] nextIntTable(int n, int m) {
            int[][] ret = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextInt();
                }
            }
            return ret;
        }

        private long[] nextLongs(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        private long[][] nextLongTable(int n, int m) {
            long[][] ret = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextLong();
                }
            }
            return ret;
        }

        private double[] nextDoubles(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c-'0';
                c = next();
            } while (!isSpaceChar(c));
            return res*sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {
  static Scanner sc = new Scanner(System.in);
  static int N;
  static int[] A;
  static Node[] nodes;

  public static void main(String[] args) {
    N = sc.nextInt();
    A = new int[N];
    for (int i = 0; i < N; i++) {
      A[i] = sc.nextInt();
    }
    if (N == 2) {
      System.out.println(A[0] == A[1] ? "YES" : "NO");
      return;
    }
    nodes = new Node[N];
    for (int i = 0; i < N; i++) {
      nodes[i] = new Node(i);
    }
    for (int i = 0; i < N - 1; i++) {
      int a = sc.nextInt() - 1;
      int b = sc.nextInt() - 1;
      nodes[a].next.add(nodes[b]);
      nodes[b].next.add(nodes[a]);
    }
    int root = 0;
    for (int i = 0; i < N; i++) {
      if (nodes[i].next.size() > 1) {
        root = i;
        break;
      }
    }
    int[] order = new int[N];
    order[0] = root;
    int pos = 1;
    for (int i = 0; i < N; i++) {
      Node cur = nodes[order[i]];
      for (Node c : cur.next) {
        if (c.idx == cur.parent) continue;
        c.parent = cur.idx;
        order[pos++] = c.idx;
      }
    }
    boolean ok = true;
    for (int i = N - 1; i >= 0; i--) {
      long sum = 0;
      long max = 0;
      Node n = nodes[order[i]];
      boolean hasChild = false;
      for (Node c : n.next) {
        if (c.idx == n.parent) continue;
        sum += c.v;
        max = Math.max(max, c.v);
        hasChild = true;
      }
      if (!hasChild) continue;
      if (sum < A[n.idx]) {
        ok = false;
        break;
      }
      long dec = sum - A[n.idx];
//      System.out.println(order[i] + " " + sum + " " + max + " " + dec);
      if (max > sum - max) {
        long c = max - (sum - max);
        if (c < dec) {
          ok = false;
          break;
        }
      }
      n.v = sum - dec * 2;
