		for (int i = 0; i < n; i++) {
			edges.add(new ArrayList<>());
		}

		for (int i = 0; i < n - 1; i++) {
			int aa = sc.nextInt() - 1;
			int bb = sc.nextInt() - 1;

			edges.get(aa).add(bb);
			edges.get(bb).add(aa);
		}

		boolean[] used = new boolean[n];
		int[] p = new int[n];

		int root = 0;
		for (int i = 0; i < n; i++) {
			if (edges.get(i).size() > 1) {
				root = i;
				break;
			}
		}

		List<Integer> vl = new ArrayList<>();
		Deque<Integer> st = new ArrayDeque<>();
		st.push(root);
		p[root] = root;
		while (!st.isEmpty()) {
			int e = st.peek();

			if (used[e]) {
				vl.add(e);
				st.pop();
			} else {
				for (int next : edges.get(e)) {
					if (used[next]) {
						continue;
					}

					st.push(next);
					p[next] = e;
				}
				used[e] = true;
			}
		}

		for (int v : vl) {
			long sum = 0;
			long max = 0;
			for (int e : edges.get(v)) {
				if (e == p[v]) {
					continue;
				}

				sum += a[e];
				max = Math.max(max, a[e]);
			}

			long pair = Math.min(sum / 2, sum - max);
			long tmp = sum - pair * 2;

			if (p[v] == v) {
				if (edges.get(v).size() == 1 && sum == a[v]) {
					pr.println("YES");
