    long f(int c, int p){
        long sum = 0;
        long ma = 0;

        boolean seen = false;
        for(int e : edge[c]){
            if(e==p) continue;
            long tmp = f(e, c);
            ma = Math.max(ma, tmp);
            sum += tmp;
            seen = true;
        }

        if(!seen) return a[c];

        long t = 2*a[c] - sum;
        long d = a[c]-t;
        ma -= t;
        sum -= t;

        long q = 0;
        if(ma>=sum/2) q = sum-ma;
        else q = sum/2;

        // System.out.println(c+" "+t+" "+ma+" "+sum);
        if(d!=sum/2 || sum%2==1 || t < 0){
