    class Graph {
        int n;
        ArrayList<Integer>[] graph;
        int[] a;
        boolean[] visited;

        Graph(int n, int[] a) {
            this.n = n;
            graph = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                graph[i] = new ArrayList<>();
            }
            this.a = a;
            visited = new boolean[n];
        }

        void addEdge(int from, int to) {
            graph[from].add(to);
            graph[to].add(from);
        }

        int dfs(int x) {
            visited[x] = true;

            if (x == 0 && graph[x].size() == 1) {
                return a[x] - dfs(graph[x].get(0));
