            if (graph[x].size() == 1) {
                return a[x];
            }

            int sum = 0;
            int max = 0;
            for (int y : graph[x]) {
                if (visited[y]) continue;

                int t = dfs(y);

                if (t == -1) return -1;

                sum += t;
                max = Math.max(max, t);
