	long dfs(int u, int par) {
		long res = 0;
		long max = -1, sum = 0;
		int cnt = 0;
		for (int v : g[u]) {
			if (v == par) continue;

			long next = dfs(v, u);
			if (next == -1) {
				res = -1;
				break;
			}
			max = Math.max(max, next);
			sum += next;
			cnt++;
		}

		if (cnt == 0) {
			res = a[u];
		} else {
			if (max > a[u] || sum < a[u] || sum > a[u] * 2) 
				res = -1;
			else 
				res = a[u] * 2 - sum;
		}
		// System.out.println(u + " " + par + " : " + res);
		return res;
	}

