using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N;
    private long[] A;
    private List<int>[] E;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.LongArray();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }

        // 0根

        // 葉 繋がってる頂点以下

        // 葉以外 連結頂点の和/2 以下

        long o;
        if (!Go(0, -1, out o))
        {
            Console.WriteLine("NO");
            return;
        }

        Console.WriteLine(o == 0 ? "YES" : "NO");
    }

    bool Go(int cur, int par, out long t)
    {
        long sum = 0;
        long max = long.MinValue;
        foreach (int to in E[cur])
        {
            if (to == par) continue;
            long c;
            if (!Go(to, cur, out c))
            {
                t = -1;
                return false;
            }

            // if(cur == 0)Console.WriteLine(c);
            max = Math.Max(max, c);
            sum += c;
        }

        if (E[cur].Count == 1)
        {
            if (par != -1)
            {
                t = A[cur];
                return true;
            }
            else
            {
                if (A[cur] == sum)
                {
                    t = 0;
                    return true;
                }
                else
                {
                    t = -1;
                    return false;
                }
            }
        }
        else
        {
            // 子を通る回数合計 sum

            // 子同士通る = L
            // 親と子を通る = T

            // T + L = A
            // 2L + T = sum
            // 2A - sum = T
            t = 2 * A[cur] - sum;
            if (t < 0)
            {
                return false;
            }

            long l = A[cur] - t;

            // 子同士通るペアがL個作れるか
            // 子iはc_i回まで使える

            // maxとその他ペア

            // まんべんなくペア
            long r = Math.Min(sum - max, sum / 2);
            if (l > r)
            {
                // Console.WriteLine($"a {cur} {sum} {l} {r} {t}");
                return false;
            }

            return true;
        }
    }

    public static void Main(string[] args) => new Program().Solve();
}

