        public void Solve()
        {
            var n = sc.Integer();
            var a = sc.Long(n);
            var G = Enumerate(n, x => new List<int>());
            for (int i = 0; i < n - 1; i++)
            {
                var f = sc.Integer() - 1;
                var t = sc.Integer() - 1;
                G[f].Add(t);
                G[t].Add(f);
            }
            if (n == 2)
            {
                if (a[0] == a[1])
                {
                    IO.Printer.Out.WriteLine("YES");
                }
                else IO.Printer.Out.WriteLine("NO");
                return;
            }

            Func<int, int, long> dfs = null;
            dfs = (prev, cur) =>
              {
                  if (G[cur].Count == 1) return a[cur];
                  var rem = a[cur];
                  var max = 0L;
                  var cnt = 0;
                  foreach (var to in G[cur])
                  {
                      if (to == prev) continue;
                      cnt++;
                      var y = dfs(cur, to);
                      if (y > rem) throw new Exception();

                      max += y;
                  }
                  if (cnt == 1)
                  {
                      if (max != rem) throw new Exception();
                      return rem;
                  }
                  if (max < rem) throw new Exception();

                  return max - rem;
              };
            try
            {
                for (int i = 0; i < n; i++)
                    if (G[i].Count > 1)
                    {
                        var res = dfs(-1, i);
                        if (res == a[i]) IO.Printer.Out.WriteLine("YES");
                        else IO.Printer.Out.WriteLine("NO");
                        return;
                    }
            }
            catch
