        A = sc.IntArray();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            E[a].Add(b);
            E[b].Add(a);
        }

        // 0根

        // 葉 繋がってる頂点以下

        // 葉以外 連結頂点の和/2 以下

        Console.WriteLine(Go(0, -1, out _) ? "YES" : "NO");
    }

    bool Go(int cur, int par, out long c)
    {
        long sum = 0;
        c = -1;
        foreach (int to in E[cur])
        {
            if (to == par) continue;
            long o;
            if (!Go(to, cur, out o))
            {
                return false;
            }

            sum += o;
        }

        if (par != -1)
        {
            if (E[cur].Count == 1)
            {
                c = A[cur];
                return true;
            }
            else
            {
                // (t + c) /2 = a
                // t + c = 2a
                // t = 2a - c
                long t = 2 * A[cur] - sum;
                if (t < 0)
                {
                    Console.WriteLine($"{cur} {par}");
                    return false;
                }

                c = t;
                return true;
            }
        }
        else
        {
            if (E[cur].Count == 1)
            {
                if (sum != A[cur])
                {
                    // Console.WriteLine($"{cur} {par}");
                    return false;
                }

                return true;
            }
            else
            {
                long t = 2 * A[cur] - sum;
                return t == 0;
            }
        }
    }

