namespace AtTest.AGC_Challenge
{
    class _010_C
    {
        static void Main(string[] args)
        {
            Method(args);
            ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] cnts = ReadInts();
            List<int>[] graph = new List<int>[n];
            for (int i = 0; i < n; i++) graph[i] = new List<int>();
            for(int i = 0; i < n - 1; i++)
            {
                int[] ab = ReadInts();
                int a = ab[0] - 1;
                int b = ab[1] - 1;
                graph[a].Add(b);
                graph[b].Add(a);
            }
            bool[] visited = new bool[n];
            Stack<int> stack = new Stack<int>();
            bool ok = true;
            DFS(graph, cnts, ref visited, ref ok, 0);
            WriteLine(ok ? "YES" : "NO");
        }

        static int DFS(List<int>[] graph,int[] cnts,
            ref bool[] visited, ref bool ok, int now)
        {
            if (!ok) return 0;

            visited[now] = true;
            int cnt = 0;
            int nodes = 0;
            for(int i = 0; i < graph[now].Count; i++)
            {
                if (visited[graph[now][i]]) continue;
                nodes++;
                int tmp = DFS(graph, cnts,
                    ref visited, ref ok, graph[now][i]);
                if (cnts[now] < tmp)
                {
                    ok = false;
                    return 0;
                }
                cnt += tmp;
            }
            if (nodes == 0) return cnts[now];
            if (cnt < cnts[now] || cnt > cnts[now] * 2)
            {
                ok = false;
                return 0;
            }
            return cnts[now] * 2 - cnt;
        }

