	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int N;
		int[] A;
		Tuple<int, int>[] rs;
		void Read()
		{
			sc.Read(out N);
			A = sc.ReadMany<int>();
			rs = sc.ReadManyLines<int, int>(N - 1);
		}
		HashSet<int>[] es;
		int root;
		void SolveOne()
		{
			es = new HashSet<int>[N];
			for (var i = 0; i < N; i++) es[i] = new HashSet<int>();
			foreach (var r in rs)
			{
				es[r.Item1 - 1].Add(r.Item2 - 1);
				es[r.Item2 - 1].Add(r.Item1 - 1);
			}
			for (var i = 0; i < N; i++) if (es[i].Count == 1) root = i;
			pr.WriteLine(OK() ? "YES" : "NO");
		}
		bool OK()
		{
			foreach (var c in es[root]) return DFS(c, root) == A[root];
			return true;
		}
		long DFS(int u, int r)
		{
			es[u].Remove(r);
			var y = new List<long>();
			foreach (var v in es[u]) y.Add(DFS(v, u));
			if (y.Count == 0) return A[u];
			else if (y.Count == 1) return A[u] != y[0] ? -1 : A[u];
			else
			{
				foreach (var z in y) if (z < 0) return -1;
				var s = y.Sum();
				if (A[u] > s || A[u] < y.Max()) return -1;
				return 2L * A[u] - s;
			}
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			  {
				  if (r[i] != r[j]) return r[i] - r[j];
				  var a = i + k <= N ? r[i + k] : -1;
				  var b = j + k <= N ? r[j + k] : -1;
				  return a - b;
			  };
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
