	public void Solve(){


		int[] depth = new int[N];
		int[] parent = new int[N];
		var Q = new Queue<int>();
		Q.Enqueue(0);
		parent[0] = -1;
		while(Q.Count > 0){
			var now = Q.Dequeue();
			foreach(var nxt in E[now]){
				if(nxt == parent[now]) continue;
				parent[nxt] = now;
				depth[nxt] = depth[now] + 1;
				Q.Enqueue(nxt);
			}
		}

		Pair[] P = new Pair[N];
		for(int i=0;i<N;i++) P[i] = new Pair(i, depth[i]);
		Array.Sort(P, (p,q) => p.Depth.CompareTo(q.Depth));
		Array.Reverse(P);

		long[] sum = new long[N];
		for(int i=1;i<N;i++){
			if(E[i].Count == 1) sum[i] = A[i];
		}


		foreach(var p in P){
			var now = p.Idx;
			if(now == 0) break;

			long v = sum[now] - A[now];
			if(v < 0){
				Console.WriteLine("NO");
				return;
			}
			if(now != 0 && E[now].Count == 2){
				if(v != 0){
					Console.WriteLine("NO");
					return;
				}
			}
