class Solver
{
    public Scanner sc;
    int[] A;
    List<int>[] G;
    public void Solve()
    {
        var N = sc.Int;
        A = sc.ArrInt;
        if (N == 2) { Console.WriteLine(A[0]==A[1]?"YES":"NO");return; }
        G = Create(N, () => new List<int>());
        for (var i = 0; i < N - 1; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            a--; b--;
            G[a].Add(b);
            G[b].Add(a);
        }
        res = new long[N];
        int j;
        for (j = 0; j < N; j++) if (G[j].Count > 1) { dfs(j, -1); break; }
        if (leaf % 2 == 1) Fail("NO");
        Console.WriteLine(res[j]==0?"YES":"NO");
    }
    long leaf = 0;
    long[] res;
    void dfs(int i, int p)
    {
        if (G[i].Count == 1)
        {
            res[i] = A[i]; leaf += A[i]; return;
        }
        long min = 0, max = 0, mx = 0, ok = 0;
        foreach (var e in G[i])
        {
            if (e == p) continue;
            dfs(e, i);
            min += res[e];
            max += A[e];
            chmax(ref mx, A[e]);
        }
        if (mx * 2 > max) ok = max - mx;
        else ok = max/2;
        if (2*A[i]<min||max < A[i]) Fail("NO");
        res[i] = Max(A[i] - ok, 0);
    }
}

