func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  n := input.NextInt()
  a := input.NextIntArray()
  tree := make([][]int,n)
  for i:=0;i<n-1;i++ {
    x,y := input.NextInts()
    tree[x-1] = append(tree[x-1],y-1)
    tree[y-1] = append(tree[y-1],x-1)
  }
  order := order_from_leaf(tree)
  for _,node := range order {
    if len(tree[node.id]) == 1 { continue }
    s := int64(0)
    m := int64(-1)
    for _,nxt := range tree[node.id] {
      if nxt == node.par { continue }
      s += a[nxt]
      if m < a[nxt] { m = a[nxt] }
    }
    p := s/2
    if m > s-m { p = s-m }
    if a[node.id] < s-p || s < a[node.id] { fmt.Println("NO");return }
    a[node.id] = 2*a[node.id]-s
  }
  if len(tree[0]) == 1 && a[0] == a[tree[0][0]] ||
  len(tree[0]) > 1 && a[0] == 0 {
    fmt.Println("YES");return
  }
  fmt.Println("NO")
}

type Node struct { par,id int }
func order_from_leaf(tree [][]int) []Node {
  n := len(tree)
  order := make([]Node,n)
  q := list.New()
  q.PushBack(Node{-1,0})
  i := n-1
  for q.Len() > 0 {
    p := q.Remove(q.Front()).(Node)
    order[i] = p
    i--
    for _,e := range tree[p.id] {
      if e == p.par { continue }
      q.PushBack(Node{p.id,e})
    }
  }
  return order
}

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInt() int {
  n,_ := strconv.Atoi(i.NextLine())
  return n
}
func(i *Input) NextInts() (int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}
func(i *Input) NextIntArray() []int64 {
  s := strings.Fields(i.NextLine())
  a := make([]int64,len(s))
  for i:=0;i<len(s);i++ { a[i],_ = strconv.ParseInt(s[i],10,64) }
  return a
}

