void main() {
    auto N = readln.chomp.to!int;
    auto A = readln.split.map!(to!long).array;
    auto G = new int[][](N);
    foreach (_; 0..N-1) {
        auto s = readln.split.map!(to!int);
        G[s[0]-1] ~= s[1]-1;
        G[s[1]-1] ~= s[0]-1;
    }

    if (N == 2) {
        writeln(A[0] == A[1] ? "YES" : "NO");
        return;
    }

    int root;
    foreach (i; 0..N) {
        if (G[i].length >= 2) {
            root = i;
            break;
        }
    }


    bool dfs(int n, int p) {
        if (G[n].length == 1) {
            return true;
        }

        long sm = 0;
        long mx = 0;
        foreach (m; G[n]) {
            if (m != p) {
                if (!dfs(m, n)) return false;
                sm += A[m];
                mx = max(mx, A[m]);
            }
        }

        sm -= mx;
        long y = max(0, mx - sm);
        mx -= y;
        sm += mx;
        y += sm % 2;
        sm -= sm % 2;

        if (n == root) return sm/2 == A[n];

        long z = y + sm - A[n];
        A[n] = y + (sm - z);

        if (A[n] < 0) writeln([n, y, sm, z]);
        return A[n] >= 0;
    }

    writeln(dfs(root, -1) ? "YES" : "NO");
}

