void main() {
    auto N = readln.chomp.to!int;
    auto A = readln.split.map!(to!long).array;
    auto G = new int[][](N);
    foreach (_; 0..N-1) {
        auto s = readln.split.map!(to!int);
        G[s[0]-1] ~= s[1]-1;
        G[s[1]-1] ~= s[0]-1;
    }

    if (N == 2) {
        writeln(A[0] == A[1] ? "YES" : "NO");
        return;
    }

    int root;
    foreach (i; 0..N) {
        if (G[i].length >= 2) {
            root = i;
            break;
        }
    }


    bool dfs(int n, int p) {
