	sl=0
	if me in ones and parent==0:
		for a in lines:
			if a[0]==me:
				sl+=TT(A,lines,ones,a[1],me)
			elif a[1]==me:
				sl+=TT(A,lines,ones,a[0],me)
		if sl==0:
			return(A[me])
		else:
			return(A[me]*2-sl)

#	elif [me,parent] not in lines and [parent,me] not in lines:
