	else:
		for a in lines:
			if a[0]==me and a[1]!=parent:
				sl+=TT(A,lines,ones,a[1],me)
			elif a[1]==me and a[0]!=parent:
				sl+=TT(A,lines,ones,a[0],me)

		if sl==0:
			return(A[me])
		else:
			return(A[me]*2-sl)


