fn dfs(v: usize, p: usize, t: &Vec<Vec<usize>>, num: &Vec<usize>, mem: &mut Vec<usize>) -> bool {
    if t[v].len() == 1 && v != p {
        mem[v] = num[v];
        return true;
    }
    let mut m1 = 0;
    let mut m2 = 0;
    let mut mt = 0;
    let mut n_max = 0;
    for &c in &t[v] {
        if c == p {
            continue;
        }
        if !dfs(c, v, t, num, mem) {
            return false;
        }
        if m1 < num[c] {
            m1 = num[c];
        }
        if m2 < mem[c] {
            m2 = mem[c];
        }
        n_max += num[c];
        mt += mem[c];
    }
    if !(num[v] >= m2 && (mt + 1) / 2 <= num[v] && num[v] <= n_max) {
        return false;
    }
    let n_min;
    if n_max - m1 < num[v] {
        n_min = num[v] - (n_max - m1);
    } else if mt == n_max && mt % 2 == 1 {
        n_min = 1;
    } else {
        n_min = 0;
    }
    mem[v] = n_min;
    true
}

