    if graph[v].len() == 1 {
        return Some(a[v]);
    }
    let mut children = 0;
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }
        match dfs(next, v, graph, a) {
            Some(up) => {
                children += up;
            }
            None => {
