fn dfs(v: usize, parent: Option<usize>, adj: &[Vec<usize>], aa: &[u64]) -> Option<u64> {
    let children = adj[v].iter().cloned().filter(|&u| Some(u) != parent).collect::<Vec<_>>();
    let ans = if children.is_empty() {
        Some(aa[v])
    } else {
        let xs: Vec<Option<u64>> = children.iter().map(|&u| dfs(u, Some(v), adj, aa)).collect();
        if xs.contains(&None) {
            return None;
        }
        let mut xs: Vec<u64> = xs.into_iter().map(|x| x.unwrap()).filter(|&x| x > 0).collect();
        dbg!(&xs);
        let s: u64 = xs.iter().sum();
        // let pass = (2*aa[v]).checked_sub(s)?;
        let pass = match (2*aa[v]).checked_sub(s) {
            None => return None,
            Some(x) => x
        };
        if aa[v] < pass || s < pass || (s - pass) % 2 == 1 {
            None
        } else {
            xs.push(pass);
            let s = s + pass;
            if xs.into_iter().any(|x| x > s/2) {
                None
            } else {
                Some(pass)
            }
        }
    };
    dbg!((v, ans));
    ans
}

