fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>, a: &Vec<u64>) -> Option<u64> {
    if graph[v].len() == 1 {
        return Some(a[v]);
    }

    let mut children = vec![];
    for &next in graph[v].iter() {
        if p == next {
            continue;
        }
        match dfs(next, v, graph, a) {
            Some(c) => {
                children.push(c);
            }
            None => {
                return None;
            }
        }
    }

    let v = a[v];
    let sum = children.iter().sum::<u64>();
    if sum > 2 * v {
        return None;
    }

    let upload = 2 * v - sum;
    if sum < upload || (sum - upload) % 2 != 0 {
        return None;
    }
    let matching = (sum - upload) / 2;
    children.sort();
    children.reverse();
    if children.len() > 0 && children[0] > matching + upload {
        return None;
    }
    Some(upload)
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::cmp;

fn main() {
    let mut sc = Scanner::new();
    let n = sc.read();
    let a: Vec<usize> = sc.read_vec(n);
    if n == 2 {
        println!("{}", if a[0] == a[1] { "YES" } else { "NO" });
        return;
    }

    let mut graph = vec![vec![]; n];
    for _ in 0..(n - 1) {
        let a = sc.usize_read() - 1;
        let b = sc.usize_read() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut root = 0;
    for i in 0..n {
        if graph[root].len() < graph[i].len() {
            root = i;
        }
    }
    assert!(graph[root].len() > 1);

    let mut up = vec![0; n];
    if !dfs(&graph, root, root, &mut up, &a) || up[root] != 0 {
        println!("NO");
    } else {
        println!("YES");
    }
}

fn dfs(graph: &Vec<Vec<usize>>, v: usize, p: usize, up: &mut Vec<usize>, a: &Vec<usize>) -> bool {
    if graph[v].len() == 1 && graph[v][0] == p {
        up[v] = a[v];
        return true;
    }

    let mut sum = 0;
    let mut max = 0;
    for &next in &graph[v] {
        if next == p {
            continue;
        }
        if !dfs(graph, next, v, up, a) {
            return false;
        }
        sum += up[next];
        max = cmp::max(max, up[next]);
    }
    if 2 * a[v] < sum {
        return false;
    }
    up[v] = 2 * a[v] - sum;
    if sum < up[v] || (sum - up[v]) % 2 == 1 {
        return false;
    }
    let rest = sum - max;
    (sum - up[v]) / 2 <= cmp::min(rest, sum / 2)
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read_vec<T>(&mut self, n: usize) -> Vec<T>
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        (0..n).map(|_| self.read()).collect()
    }

    fn usize_read(&mut self) -> usize {
        self.read()
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use std::cmp;
use std::io::*;
use std::str::FromStr;

fn func(v: usize, ai: &Vec<i64>, graph: &Vec<Vec<usize>>, used: &mut Vec<bool>) -> (bool, i64) {
    used[v] = true;
    if graph[v].len() == 1 {
        return (true, ai[v]);
    }
    if graph[v].len() == 2 {
        for i in &graph[v] {
            if used[*i] {
                continue;
            }
            let (ok, po) = func(*i, ai, graph, used);
            if po == ai[v] {
                return (ok, po);
            } else {
                return (false, 0);
            }
        }
    }
    let mut max: i64 = 0;
    let mut sum: i64 = 0;
    for i in &graph[v] {
        if used[*i] {
            continue;
        }
        let (po, aii) = func(*i, &ai, &graph, used);
        if !po {
            return (false, 0);
        }
        max = cmp::max(max, aii);
        sum += aii;
    }
    return (cmp::min(max, sum / 2) >= (sum - ai[v]), 2 * ai[v] - sum);
}

fn main() {
    let n: usize = read();
    let ai: Vec<i64> = (0..n).map(|_| read::<i64>()).collect();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut root: usize = 0;
    for i in 0..n {
        if graph[i].len() > 1 {
            root = i;
            break;
        }
    }
    let mut used = vec![false; n];
    used[root] = true;
    let mut ok = true;
    let mut sum: i64 = 0;
    for i in &graph[root] {
        let (po, aii) = func(*i, &ai, &graph, &mut used);
        if !po {
            ok = false;
            break;
        }
        sum += aii;
    }
    if ai[root] != sum / 2 {
        ok = false;
    }
    println!("{}", if ok { "YES" } else { "NO" });
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

