    let mut ai: Vec<i64> = (0..n).map(|_| read::<i64>()).collect();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut que: VecDeque<usize> = VecDeque::new();
    for i in 0..n {
        if graph[i].len() == 1 {
            que.push_back(i);
        }
    }
    let mut count: Vec<i64> = (0..n).map(|i| graph[i].len() as i64).collect();
    let mut used = vec![false; n];
    let mut check = true;
    while !que.is_empty() {
        let now = que.pop_front().unwrap();
        used[now] = true;
        for i in &graph[now] {
            if count[*i] <= 2 {
                if !used[*i] {
                    if ai[now] != ai[*i] {
                        check = false;
                    }
                    que.push_front(*i);
                }
            } else {
                if !used[*i] {
                    ai[*i] *= 2;
                    used[*i] = true;
                }
                ai[*i] -= ai[now];
            }
        }
    }
    for i in 0..n {
        if !used[i] {
            ai[i] *= 2;
        }
    }
    while !que.is_empty() {
        let now = que.pop_front().unwrap();
        used[now] = true;
        for i in &graph[now] {
            if count[*i] <= 2 {
                if !used[*i] {
                    if ai[now] != ai[*i] {
                        check = false;
                    }
                    que.push_front(*i);
                }
            } else {
                count[*i] -= 1;
                ai[*i] -= ai[now];
                if ai[*i] < 0 {
                    check = false;
                    break;
                }
                if !used[*i] && count[*i] == 1 {
                    que.push_back(*i);
                }
            }
        }
    }
    println!("{}", if check { "YES" } else { "NO" });
}

fn read<T: FromStr>() -> T {
