use std::io::*;
use std::str::FromStr;

fn func(v: usize, ai: &Vec<i64>, graph: &Vec<Vec<usize>>, used: &mut Vec<bool>) -> (bool, i64) {
    used[v] = true;
    if graph[v].len() == 1 {
        return (true, ai[v]);
    }
    if graph[v].len() == 2 {
        for i in &graph[v] {
            if used[*i] {
                continue;
            }
            let (ok, po) = func(*i, ai, graph, used);
            if po == ai[v] {
                return (ok, po);
            } else {
                return (false, 0);
            }
        }
    }
    let mut max: i64 = 0;
    let mut sum: i64 = 0;
    for i in &graph[v] {
        if used[*i] {
            continue;
        }
        let (po, aii) = func(*i, &ai, &graph, used);
        if !po {
            return (false, 0);
        }
        max = cmp::max(max, aii);
        sum += aii;
    }
    if sum < ai[v] {
        return (false, 0);
    }
    return (
        cmp::min(sum - max, sum / 2) >= (sum - ai[v]),
        2 * ai[v] - sum,
    );
}

