#[derive(Clone, Debug, Default)]
pub struct Graph {
    pub vsize: usize,
    pub esize: usize,
    pub graph: Vec<Vec<Adjacent>>,
}
impl Graph {
    pub fn new(vsize: usize) -> Graph {
        Graph {
            vsize: vsize,
            esize: 0,
            graph: vec![vec![]; vsize],
        }
    }
    pub fn add_edge(&mut self, from: usize, to: usize) {
        self.graph[from].push(Adjacent::new(to, self.esize));
        self.esize += 1;
    }
    pub fn add_undirected_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(Adjacent::new(v, self.esize));
        self.graph[v].push(Adjacent::new(u, self.esize));
        self.esize += 1;
    }
    pub fn vertices(&self) -> std::ops::Range<usize> {
        0..self.vsize
    }
    pub fn adjacency(&self, from: usize) -> &Vec<Adjacent> {
        &self.graph[from]
    }
}
#[derive(Debug, Default)]
pub struct TreeRec {
    n: usize,
    a: Vec<i64>,
    dp: Vec<i64>,
    ans: bool,
}
impl TreeRec {
    pub fn new(n: usize, a: Vec<i64>) -> TreeRec {
        TreeRec {
            n: n,
            dp: a.clone(),
            a: a,
            ans: true,
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        if p < self.n && graph.adjacency(u).len() == 1 {
            return;
        }
        let mut tot = 0;
        let mut mx = 0;
        for a in graph.adjacency(u) {
            if a.to != p {
                self.dfs(a.to, u, graph);
                tot += self.dp[a.to];
                mx = std::cmp::max(mx, self.dp[a.to]);
            }
        }
        let aa = self.a[u];
        let y = tot - aa;
        let x = 2 * aa - tot;
        if y < 0 || x < 0 || tot - mx < y {
            self.ans = false;
        }
        self.dp[u] = x;
    }
}
