fn dfs(v: usize, p: usize, t: &Vec<Vec<usize>>, num: &Vec<usize>, mem: &mut Vec<usize>) -> bool {
    if t[v].len() == 1 && v != p {
        mem[v] = num[v];
        return true;
    }
    let mut m = 0;
    let mut mt = 0;
    for &c in &t[v] {
        if c == p {
            continue;
        }
        if !dfs(c, v, t, num, mem) {
            return false;
        }
        if m < mem[c] {
            m = mem[c];
        }
        mt += mem[c];
    }
    if mt < num[v] || 2 * num[v] < mt || min(mt - m, mt / 2) < mt - num[v] {
        return false;
    }
    mem[v] = 2 * num[v] - mt;
    true
}

