    for _ in 0..n - 1 {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut root: usize = 0;
    for i in 0..n {
        if graph[i].len() > 1 {
            root = i;
            break;
        }
    }
    let mut used = vec![false; n];
    used[root] = true;
    let mut ok = true;
    let mut sum: i64 = 0;
    for i in &graph[root] {
        let (po, aii) = func(*i, &ai, &graph, &mut used);
        if !po {
            ok = false;
            break;
        }
        sum += aii;
    }
    if ai[root] != sum / 2 {
        ok = false;
    }
