fn solve(adj: &[Vec<usize>], mut aa: Vec<u32>, mut degs: Vec<u32>) -> bool {
    let mut n = adj.len();
    let mut visited = vec![false; n];
    let mut deg1_vs: Vec<usize> = degs.iter().enumerate()
        .filter(|&(_, &d)| d == 1).map(|(i, _)| i).collect();
    while n > 2 {
        let v = deg1_vs.pop().unwrap();
        visited[v] = true;
        for &next in &adj[v] {
            if !visited[next] {
                degs[next] -= 1;
                if degs[next] == 1 {
                    deg1_vs.push(next);
                }
                if aa[next] < aa[v] {
                    return false;
                }
                aa[next] -= aa[v];
                break;
            }
        }
        n -= 1;
    }
    aa[deg1_vs[0]] == aa[deg1_vs[1]]
}

fn main() {
    read!(n = usize);
    read!(mut aa = Vec<u32>);
    let mut adj = vec![Vec::new(); n];
    let mut degs = vec![0; n];
    readx_loop!(|a = usize_, b = usize_| {
        degs[a] += 1;
        adj[a].push(b);
        degs[b] += 1;
        adj[b].push(a);
    });
    for i in 0..n {
        if degs[i] > 1 {
            aa[i] *= 2;
        }
    }
    YN(solve(&adj, aa, degs));
}

