        children_a[ti] = 2 * children_a[ti] - a_sum;
        let inner = a[ti] - children_a[ti];

        if !tree[ti].is_empty() {
            let a_max = tree[ti].iter().map(|&x| children_a[x]).max().unwrap();
            if a_max - children_a[ti] > inner {
                debug!(ti, a_max - children_a[ti], inner);
                println!("NO");
                return;
            }
        }
        if ti == root {
            if tree[ti].len() >= 2 {
                if children_a[ti] > 0 {
                    debug!(ti, children_a[ti]);
                    println!("NO");
                    return;
                }
            } else {
                if a_sum != a[ti] {
                    debug!(ti, children_a[ti]);
                    println!("NO");
