}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn make_tree(
    cur_idx: usize,
    parent_idx: usize,
    edges: &Vec<Vec<usize>>,
    tree: &mut Vec<Vec<usize>>,
    parent_dict: &mut HashMap<usize, usize>,
) {
    for child_idx in edges[cur_idx].iter() {
        if *child_idx == parent_idx {
            continue;
        }
        tree[cur_idx].push(*child_idx);
        parent_dict.insert(*child_idx, cur_idx);
        make_tree(*child_idx, cur_idx, edges, tree, parent_dict);
    }
}

fn topological_dfs(cur_idx: usize, tree: &Vec<Vec<usize>>, result: &mut Vec<usize>) {
    for child_idx in tree[cur_idx].iter() {
        result.push(*child_idx);
        topological_dfs(*child_idx, tree, result);
    }
}

use std::collections::VecDeque;
use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let mut ai: Vec<i64> = (0..n).map(|_| read::<i64>()).collect();
    let mut graph: Vec<Vec<usize>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut que: VecDeque<usize> = VecDeque::new();
    for i in 0..n {
        if graph[i].len() == 1 {
            que.push_back(i);
        }
    }
    let mut count: Vec<i64> = (0..n).map(|i| graph[i].len() as i64).collect();
    let mut used = vec![false; n];
    let mut check = true;
    let mut bai = vec![false; n];
    while !que.is_empty() {
        let now = que.pop_front().unwrap();
        used[now] = true;
        for i in &graph[now] {
            if count[*i] <= 2 {
                if !used[*i] {
                    if ai[now] != ai[*i] {
                        check = false;
                    }
                    que.push_front(*i);
                }
            } else {
                if !bai[*i] {
                    ai[*i] *= 2;
                    bai[*i] = true;
                }
                ai[*i] -= ai[now];
            }
        }
    }
    for i in 0..n {
        if !used[i] && !bai[i] {
            ai[i] *= 2;
        }
    }
    while !que.is_empty() {
        let now = que.pop_front().unwrap();
        used[now] = true;
        for i in &graph[now] {
            if count[*i] <= 2 {
                if !used[*i] {
                    if ai[now] != ai[*i] {
                        check = false;
                    }
                    que.push_front(*i);
                }
            } else {
                count[*i] -= 1;
                ai[*i] -= ai[now];
                if ai[*i] < 0 {
                    check = false;
                    break;
                }
                if !used[*i] && count[*i] == 1 {
                    que.push_back(*i);
                }
            }
        }
    }
    println!("{}", if check { "YES" } else { "NO" });
}

fn read<T: FromStr>() -> T {
