    let va = a[v];
    let mut sum_children = 0;
    let mut max_child = 0;
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }

        match dfs(next, v, graph, a) {
            Some(child) => {
                sum_children += child;
                if max_child < child {
                    max_child = child;
                }
            }
            None => {
                return None;
            }
        }
    }

    if max_child > va {
        return None;
    }
    if sum_children > va * 2 {
        return None;
    }

    let out = va * 2 - sum_children;
    if out > va {
        return None;
    }
    Some(out)
}

