pub struct TreeRec {
    n: usize,
    a: Vec<i64>,
    dp: Vec<i64>,
    ans: bool,
}
impl TreeRec {
    pub fn new(n: usize, a: Vec<i64>) -> TreeRec {
        TreeRec {
            n: n,
            dp: a.clone(),
            a: a,
            ans: true,
        }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) {
        if p < self.n && graph.adjacency(u).len() == 1 {
            return;
        }
        let mut tot = 0;
        let mut mx = 0;
        for a in graph.adjacency(u) {
            if a.to != p {
                self.dfs(a.to, u, graph);
                tot += self.dp[a.to];
                mx = std::cmp::max(mx, self.dp[a.to]);
            }
        }
        let aa = self.a[u];
        let y = tot - aa;
        let x = 2 * aa - tot;
        if y < 0 || x < 0 || tot - mx < y {
            self.ans = false;
        }
        if p == self.n && graph.adjacency(u).len() == 1 && x != aa {
            self.ans = false;
        }
        self.dp[u] = x;
    }
}
