fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>, a: &Vec<u64>) -> Option<u64> {
    if graph[v].len() == 1 {
        return Some(a[v]);
    }
    let mut children = 0;
    let mut max = 0;
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }
        match dfs(next, v, graph, a) {
            Some(up) => {
                children += up;
                max = cmp::max(max, up);
            }
            None => {
                return None;
            }
        }
    }

    if 2 * a[v] < children || children < a[v] {
        return None;
    }

    let up = 2 * a[v] - children;
    let pairs = children - a[v];

    if children - max < pairs {
        return None;
    } else {
        Some(up)
    }
}

