fn dfs(v: usize, p: usize, tree: &Vec<Vec<usize>>, a: &Vec<u64>) -> Option<u64> {
    if tree[v].len() == 1 && tree[v][0] == p {
        return Some(a[v]);
    }
    let mut sum = 0;
    for &next in tree[v].iter() {
        if p == next {
            continue;
        }
        match dfs(next, v, tree, a) {
            Some(next) => {
                sum += next;
            }
            None => {
                return None;
            }
        }
    }
    if 2 * a[v] >= sum {
        Some(2 * a[v] - sum)
    } else {
        None
    }
}

