fn dfs(gr: &Vec<Vec<usize>>, v: usize, parent: usize, cs: &Vec<i64>) -> Option<i64> {
    let len = gr[v].len() - 1;
    if len == 0 {
        return Some(cs[v]);
    } else if len == 1 {
        let nv = if gr[v][0] == parent {
            gr[v][1]
        } else {
            gr[v][0]
        };
        if let Some(csv) = dfs(gr, nv, v, cs) {
            if csv == cs[v] {
                return Some(csv);
            } else {
                return None;
            }
        } else {
            return None;
        }
    }
    let mut children: Vec<i64> = Vec::with_capacity(len);
    for &nv in &gr[v] {
        if nv == parent {
            continue;
        }
        if let Some(c) = dfs(gr, nv, v, cs) {
            children.push(c)
        } else {
            return None;
        }
    }
    children.sort();

    let s: i64 = children.iter().fold(0, |acc, &x| acc + x);
    let m: i64 = children.iter().fold(0, |acc, &x| max(acc, x));
    let lim = if s < 2 * m { s - m } else { s / 2 };

    let t = 2 * cs[v] - s;

    if t + lim >= cs[v] { Some(t) } else { None }

}

