fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>, a: &Vec<usize>) -> Option<usize> {
    if graph[v].len() == 1 {
        return Some(a[v]);
    }
    let va = a[v];
    let mut sum_childern = 0;
    let mut max_child = 0;
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }

        match dfs(next, v, graph, a) {
            Some(child) => {
                sum_childern += child;
                if max_child < child {
                    max_child = child;
                }
            }
            None => {
                return None;
            }
        }
    }

    if max_child > va {
        return None;
    }
    if sum_childern > va * 2 {
        return None;
    }

    let out = va * 2 - sum_childern;
    Some(out)
}

