fn run<I: Input, O: Write>(mut kin: I, mut out: O) {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let n: usize = kin.input();
    let mut a: Vec<i64> = iter::once(0).chain(kin.iter::<i64>().take(n)).collect();
    let mut g = vec![Vec::new(); n + 1];
    for (a, b) in kin.iter::<(usize, usize)>().take(n - 1) {
        g[a].push(b);
        g[b].push(a);
    }

    if dfs(&g, &mut a, 1, 0) {
        outputln!("YES");
    } else {
        outputln!("NO");
    }
}

fn dfs(g: &[Vec<usize>], a: &mut [i64], u: usize, p: usize) -> bool {
    if g[u].len() == 1 && p != 0 {
        return true;
    }
    let mut sum = 0;
    let mut max = 0;
    for &v in g[u].iter().filter(|&&v| v != p) {
        if !dfs(g, a, v, u) {
            return false;
        }
        sum += a[v];
        max = max.max(a[v]);
    }
    let rem = (sum & 1).max(2 * max - sum);
    let new = 2 * a[u] - sum;
    kdbg!(u, a[u], new, sum, rem, ());
    if p == 0 && g[u].len() >= 2 && new != 0 {
        return false;
    }
    if new >= rem && new <= a[u] {
        a[u] = new;
        true
    } else {
        false
    }
}

