type Graph = Vec<Vec<usize>>;

fn dfs_cpo(g: &Graph, root: usize) -> (Vec<usize>, Vec<Option<usize>>, Vec<usize>) {
    let n = g.len();
    struct Cpo {
        count: Vec<usize>,
        parent: Vec<Option<usize>>,
        order: Vec<usize>,
        oidx: usize
    };
    let mut cpo = Cpo {
        count: vec![0; n],
        parent: vec![None; n],
        order: vec![0; n],
        oidx: 0
    };

    fn dfs(g: &Graph, now: usize, par: Option<usize>, cpo: &mut Cpo) {
        for &to in &g[now] {
            if Some(to) != par {
                dfs(g, to, Some(now), cpo);
            }
        }
        cpo.count[now] = 1;
        for &to in &g[now] {
            if Some(to) != par {
                cpo.count[now] += cpo.count[to];
            }
        }
        cpo.parent[now] = par;
        cpo.order[cpo.oidx] = now;
        cpo.oidx += 1;

    }
    dfs(&g, root, None, &mut cpo);
    (cpo.count, cpo.parent, cpo.order)
}
//===

fn solve(g: Vec<Vec<usize>>, a: Vec<i64>) -> bool {
    let n = g.len();
    if n == 2 {
        return a[0] == a[1];
    }

    let mut root = 0;
    for i in 0..n {
        if g[i].len() >= 2 {
            root = i;
            break;
        }
    }
    let (count, parent, order) = dfs_cpo(&g, root);


    let mut isvalid = true;
    let mut up = vec![0; n];
    for i in 0..n {
        let v = order[i];
        let mut total = 0;
        let mut upmax = 0;
        let mut cn = 0;
        for &to in &g[v] {
            if Some(to) == parent[v] {
                continue;
            }
            total += up[to];
            upmax = max(upmax, up[to]);
            cn += 1;
        }
        if cn == 0 {
            up[v] = a[v];
        } else {
            let maxtie = min(total-upmax, total/2);
            let needtie = total-a[v];
            if needtie < 0 || needtie > maxtie {
                return false;
            } else {
                up[v] = total - needtie * 2;
                if v == root {
                    isvalid &= up[v] == 0;
                }
            }
        }
    }
    isvalid
}

fn main() {
    input! {
        n: usize,
        a: [i64; n],
        edges: [(usize1, usize1); n-1]
    };


    let mut g = vec![vec![]; n];
    for (u, v) in edges {
        g[u].push(v);
        g[v].push(u);
    }
    println!("{}", ifv!(solve(g, a), "YES", "NO"));
}
